        &self,
        scene: ActorScene,
        frame_clock: [f32; 2],
    ) -> Option<Vec<crate::SongLuaOverlayState>> {
        let snapshots = self.snapshot(scene)?;
        retirement::sweep(&self.store);
        let store = self.store.lock().unwrap();
        if store.retired_scenes.contains_key(&scene.id) {
            return None;
        }
        let scene = store.scenes.get(&scene.id)?;
        Some(
            snapshots
                .into_iter()
                .zip(&scene.actors)
                .map(|(snapshot, id)| {
                    let mut render = snapshot.render;
                    effects::render_time(&store.actors[id], frame_clock, &mut render);
                    render
                })
                .collect(),
        )
    }

    pub(super) fn host_messages(&self, vm: &Vm) -> Result<Value, Error> {
        vm.rooted(self.broadcast)
    }

    pub(super) fn host_template(&self, vm: &Vm) -> Result<Value, Error> {
        vm.rooted(self.template)
    }

    pub(super) fn broadcast(
        &self,
        vm: &mut Vm,
        name: &str,
        params: Option<Value>,
        normalize: bool,
    ) -> Result<(), Error> {
        let name = vm.try_intern(name.as_bytes())?;
        vm.call(
            vm.rooted(self.broadcast)?,
            &[
                name,
                Value::Boolean(params.is_some()),
                params.unwrap_or(Value::Nil),
                Value::Boolean(normalize),
            ],
        )?;
        Ok(())
    }

    #[cfg(feature = "test-support")]
    pub(super) fn ownership_counts(&self) -> [usize; 3] {
        retirement::sweep(&self.store);
        let guard = self.store.lock().unwrap();
        [
            guard.actors.len(),
            guard.scenes.len(),
            guard.retired_scenes.len(),
        ]
    }

    #[cfg(feature = "test-support")]
    pub(super) fn set_message_ranks(&self, scene: ActorScene, ranks: &[usize]) -> bool {
        if scene.owner != self.instantiate {
            return false;
        }
        let mut store = self.store.lock().unwrap();
        let Some(scene) = store.scenes.get(&scene.id) else {
            return false;
        };
        if ranks.len() != scene.actors.len()
            || ranks.contains(&0)
            || ranks.iter().copied().collect::<HashSet<_>>().len() != ranks.len()
        {
            return false;
        }
        let actors = scene.actors.clone();
        store
            .message_ranks
            .extend(actors.into_iter().zip(ranks.iter().copied()));
        true
    }

    #[cfg(feature = "test-support")]
    pub(super) fn set_message_identity(&self, actor: Value, rank: usize) -> bool {
        let Value::Table(actor) = actor else {
            return false;
        };
        let mut store = self.store.lock().unwrap();
        if rank == 0 || !store.actors.contains_key(&actor) {
            return false;
        }
        store.message_ranks.insert(actor, rank);
        true
    }
}
fn install_method(
    vm: &mut Vm,
    table: TableId,
    name: &str,
    op: Op,
    store: &Shared,
    captures: &[Value],
) -> Result<(), Error> {
    let function = vm.new_host_function_with_data(
        callback,
        captures,
        Binding {
            store: store.clone(),
            op,
        },
    )?;
    super::put(vm, table, name, function)
}
fn table(call: &HostCall<'_>, value: Value) -> Result<TableId, Error> {
    if let Value::Table(id) = value {
        Ok(id)
    } else {
        Err(call.error(b"actor table expected"))
    }
}
fn get(call: &mut HostCall<'_>, t: TableId, key: &[u8]) -> Result<Value, Error> {
    let key = call.try_intern(key)?;
    call.raw_table_get(t, key)
}
fn bytes(call: &mut HostCall<'_>, value: Value) -> Result<Vec<u8>, Error> {
    let id = call
        .coerce_string(value)?
        .ok_or_else(|| call.error(b"string expected"))?;
    Ok(call.string_bytes(id).unwrap().to_vec())
}
fn arg(call: &HostCall<'_>, i: usize) -> Value {
    call.arguments().get(i).copied().unwrap_or(Value::Nil)
}
fn helper(call: &HostCall<'_>, index: usize) -> Result<Value, Error> {
    let Value::Table(helpers) = call.captures()[1] else {
        unreachable!()
    };
    call.raw_table_get(helpers, Value::Number(index as f64))
}
fn declared_children(store: &Shared, actor: TableId) -> Vec<TableId> {
    store.lock().unwrap().actors[&actor].children.clone()
}
fn children(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<Vec<TableId>, Error> {
    if has_native_children(store, actor) {
        native_children::children(call, store, actor)
    } else {
        Ok(declared_children(store, actor))
    }
}
fn has_native_children(store: &Shared, actor: TableId) -> bool {
    let store = store.lock().unwrap();
    let actor = &store.actors[&actor];
    actor.native_children
        || matches!(
            actor.state.class,
            "GraphDisplay"
                | "SongMeterDisplay"
                | "CourseContentsList"
                | "Model"
                | "PlayerActor"
                | "HoldJudgment"
                | "NoteField"
        )
}
fn is_frame(store: &Shared, actor: TableId) -> bool {
    matches!(
        store.lock().unwrap().actors[&actor].state.class,
        "ActorFrame"
            | "PlayerActor"
            | "HoldJudgment"
            | "PercentageDisplay"
            | "StepsDisplay"
            | "TopScreen"
            | "NoteField"
            | "ActorFrameTexture"
            | "WrapperState"
            | "GraphDisplay"
            | "SongMeterDisplay"
            | "CourseContentsList"
    )
}
fn sort(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    for child in declared_children(store, actor) {
        if store.lock().unwrap().actors[&child].raw_instance {
            let value = get(call, child, b"__songlua_state_draw_order")?;
            let n = sprites::number(call, value).unwrap_or(0.);
            let order = if n > -2147483649. && n < 2147483648. {
                n as i32
            } else {
                0
            };
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&child)
                .unwrap()
                .state
                .draw_order = order;
        }
    }
    let list = {
        let mut store = store.lock().unwrap();
        let mut list = store.actors[&actor].children.clone();
        list.sort_by_key(|id| store.actors[id].state.draw_order);
        store.actors.get_mut(&actor).unwrap().children = list.clone();
        list
    };
    for (index, child) in list.into_iter().enumerate() {
        call.raw_table_set(
            actor,
            Value::Number((index + 1) as f64),
            Value::Table(child),
        )?;
    }
    Ok(())
}
fn command(
    call: &mut HostCall<'_>,
    actor: TableId,
    name: &[u8],
) -> Result<Option<(Value, Vec<u8>)>, Error> {
    let mut field = [name, b"Command"].concat();
    for fallback in [false, true] {
        if fallback {
            if name.ends_with(b"Message") {
                break;
            }
            field = [name, b"MessageCommand"].concat();
        }
        let key = call.try_intern(&field)?;
        let value = call.table_get(Value::Table(actor), key)?;
        match value {
            Value::Function(_) | Value::Native(_) => return Ok(Some((value, field))),
            Value::Nil => {}
            _ => return Err(call.error(b"actor command must be a function")),
        }
    }
    Ok(None)
}
fn run(
    call: &mut HostCall<'_>,
    actor: TableId,
    function: Value,
    params: Option<Value>,
) -> Result<(), Error> {
    match params {
        Some(params) => call.call(function, &[Value::Table(actor), params])?,
        None => call.call(function, &[Value::Table(actor)])?,
    };
    Ok(())
}
fn run_actor_function(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    function: Value,
    params: Option<Value>,
) -> Result<(), Error> {
    command_locals::capture(call, store, function)?;
    run_scoped(call, actor, function, params)
}
fn run_scoped(
    call: &mut HostCall<'_>,
    actor: TableId,
    function: Value,
    params: Option<Value>,
) -> Result<(), Error> {
    let key = call.try_intern(b"__songlua_script_dir")?;
    let directory = call.table_get(Value::Table(actor), key)?;
    if directory == Value::Nil {
        return run(call, actor, function, params);
    }
    let directory = bytes(call, directory)?;
    let text = std::str::from_utf8(&directory)
        .map_err(|_| call.error(b"actor script directory must be UTF-8"))?;
    if text.trim().is_empty() {
        return run(call, actor, function, params);
    }
    let directory = call.try_intern(&directory)?;
    call.with_roots(&[directory, key], |call| {
        let globals = helper(call, 5)?;
        let previous = call.table_get(globals, key)?;
        call.with_roots(&[previous], |call| {
            call.table_set(globals, key, directory)?;
            let result = run(call, actor, function, params);
            // Restore the caller's directory even when a callback errors or
            // exhausts its instruction budget. This runs outside authored Lua.
            let globals_table = table(call, globals)?;
            if call.raw_table_get(globals_table, key)? != Value::Nil {
                // An existing field bypasses __newindex. Restore it without
                // entering the VM again after an exhausted instruction budget.
                call.raw_table_set(globals_table, key, previous)?;
            } else {
                call.table_set(globals, key, previous)?;
            }
            result
        })
    })
}
fn run_named(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Option<Value>,
) -> Result<(), Error> {
    run_named_with_drain(call, store, actor, name, params, true)
}
fn run_named_with_drain(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Option<Value>,
    drain: bool,
) -> Result<(), Error> {
    let Some((function, field)) = command(call, actor, name)? else {
        return Ok(());
    };
    run_guarded_command(call, store, actor, field, function, params, drain)
}
fn run_guarded_command(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    field: Vec<u8>,
    function: Value,
    params: Option<Value>,
    drain: bool,
) -> Result<(), Error> {
    let inserted = store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .active_commands
        .insert(field.clone());
    if !inserted {
        return Ok(());
    }
    let previous_capture_start = capture::command_start(store, actor);
    // Keep the selected function alive if a callback replaces its own field or
    // forces GC. Never retain the store lock while entering authored Lua.
    let result = call.with_roots(&[function, params.unwrap_or(Value::Nil)], |call| {
        let theme = call.call(helper(call, 4)?, &[function])?[0] == Value::Boolean(true);
        match run_actor_function(call, store, actor, function, params) {
            Err(error) if theme && error.kind() == ErrorKind::Runtime => {
                store.lock().unwrap().diagnostics.push(error.to_string());
                Ok(())
            }
            result => result,
        }
    });
    let result = result.and_then(|()| {
        if drain && previous_capture_start.is_some() {
            capture::drain_commands(call, store, actor)?;
        }
        Ok(())
    });
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .active_commands
        .remove(&field);
    capture::command_end(store, actor, previous_capture_start);
    result
}
fn play(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Option<Value>,
    recurse: bool,
) -> Result<(), Error> {
    run_named(call, store, actor, name, params)?;
    if recurse {
        for child in children(call, store, actor)? {
            play(call, store, child, name, params, true)?;
        }
    }
    Ok(())
}
fn leaves(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    action: &mut impl FnMut(&mut HostCall<'_>, TableId) -> Result<(), Error>,
) -> Result<(), Error> {
    let children = children(call, store, actor)?;
    if children.is_empty() {
        action(call, actor)?;
    } else {
        for child in children {
            leaves(call, store, child, action)?;
        }
    }
    Ok(())
}
fn release(call: &mut HostCall<'_>, store: &Shared, id: u64) -> Result<bool, Error> {
    if store.lock().unwrap().retired_scenes.contains_key(&id) {
        return Ok(false);
    }
    store.lock().unwrap().constructor_scenes.remove(&id);
    let scene = store.lock().unwrap().scenes.remove(&id);
    let Some(scene) = scene else { return Ok(false) };
    lifecycle::invalidate_plans(call, store)?;
    // Course displays can be shared tables. A scene retires only its last
    // ownership of those actors, including their callbacks and registry roots.
    let mut retired = HashSet::new();
    let mut transferred = Vec::new();
    {
        let mut guard = store.lock().unwrap();
        for &actor in &scene.actors {
            let other = guard
                .scenes
                .iter()
                .filter(|(_, scene)| scene.actors.contains(&actor))
                .min_by_key(|(id, _)| guard.retired_scenes.contains_key(id))
                .map(|(id, _)| *id);
            if let Some(other) = other {
                if guard.retired_scenes.contains_key(&other) {
                    transferred.push((actor, other));
                }
                if let Some(instance) = guard.actors.get_mut(&actor)
                    && instance.scene == id
                {
                    instance.scene = other;
                }
            } else {
                retired.insert(actor);
            }
        }
    }
    store
        .lock()
        .unwrap()
        .actor_order
        .retain(|actor| !retired.contains(actor));
    if let Some(queued) = &mut store.lock().unwrap().startup_queues {
        queued.retain(|actor| !retired.contains(actor));
    }
    let registry = table(call, call.captures()[0])?;
    for (actor, other) in transferred {
        retirement::retain(call, store, other, actor, registry)?;
        call.raw_table_set(registry, Value::Table(actor), Value::Nil)?;
        store.lock().unwrap().retired_subscriptions.remove(&actor);
        store
            .lock()
            .unwrap()
            .actor_order
            .retain(|value| *value != actor);
    }
    for actor in scene.actors {
        if !retired.contains(&actor) {
            continue;
        }
        if !scene.sounds_retired {
            sound::retire(call, store, actor);
        }
        call.raw_table_set(registry, Value::Table(actor), Value::Nil)?;
        let mut store = store.lock().unwrap();
        store.actors.remove(&actor);
        store.retired_subscriptions.remove(&actor);
        #[cfg(feature = "test-support")]
        store.message_ranks.remove(&actor);
    }
    Ok(true)
}
fn build(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    node: TableId,
    parent: Option<TableId>,
    check_condition: bool,
    internal: bool,
) -> Result<Option<TableId>, Error> {
    let attrs = table(call, call.raw_table_get(node, Value::Number(1.0))?)?;
    if check_condition && get(call, attrs, b"Condition")? == Value::Boolean(false) {
        return Ok(None);
    }
    let template = match call.raw_table_get(node, Value::Number(3.0))? {
        Value::Table(source) => store
            .lock()
            .unwrap()
            .actors
            .get(&source)
            .map(TemplateState::from),
        _ => None,
    };
    let class = if let Some(template) = &template {
        template.state.class.as_bytes().to_vec()
    } else {
        let mut kind = get(call, attrs, b"Class")?;
        if kind == Value::Nil {
            kind = get(call, attrs, b"Type")?;
        }
        if kind == Value::Nil {
            Vec::new()
        } else {
            bytes(call, kind)?
        }
    };
    let dummy = class.is_empty();
    let class = match class.as_slice() {
        b"" | b"Actor" => "Actor",
        b"ActorFrame" => "ActorFrame",
        b"ActorFrameTexture" => "ActorFrameTexture",
        b"WrapperState" => "WrapperState",
        b"Quad" => "Quad",
        b"Sprite" => "Sprite",
        b"Banner" => "Banner",
        b"GraphDisplay" => "GraphDisplay",
        b"SongMeterDisplay" => "SongMeterDisplay",
        b"CourseContentsList" => "CourseContentsList",
        b"Model" => "Model",
        b"PlayerActor" if internal => "PlayerActor",
        b"HoldJudgment" if internal => "HoldJudgment",
        b"PercentageDisplay" if internal => "PercentageDisplay",
        b"StepsDisplay" if internal => "StepsDisplay",
        b"TopScreen" if internal => "TopScreen",
        b"ChildActor" if internal => "ChildActor",
        b"OptionRow" if internal => "OptionRow",
        b"OptionRowFrame" if internal => "OptionRowFrame",
        b"Timer" if internal => "Timer",
        b"NoteField" if internal => "NoteField",
        b"NoteColumnRenderer" if internal => "NoteColumnRenderer",
        b"LifeMeter" if internal => "LifeMeter",
        b"GraphDisplayBody" if internal => "GraphDisplayBody",
        b"GraphDisplayLine" if internal => "GraphDisplayLine",
        b"BitmapText" => "BitmapText",
        b"RollingNumbers" => "RollingNumbers",
        b"BPMDisplay" => "BPMDisplay",
        b"DeviceList" => "DeviceList",
        b"InputList" => "InputList",
        b"ActorMultiVertex" => "ActorMultiVertex",
        b"ActorProxy" => "ActorProxy",
        b"Sound" => "Sound",
        _ => {
            return Err(call.error(
                format!(
                    "actor class '{}' has no Rust instance implementation yet",
                    String::from_utf8_lossy(&class)
                )
                .as_bytes(),
            ));
        }
    };
    let create = helper(call, 1)?;
    let kind = call.try_intern(class.as_bytes())?;
    let empty_attrs = if dummy {
        Value::Table(call.try_new_table()?)
    } else {
        Value::Table(attrs)
    };
    let actor = call.call(
        create,
        &[
            kind,
            parent.map_or(Value::Nil, Value::Table),
            empty_attrs,
            Value::Boolean(template.is_some()),
        ],
    )?[0];
    let actor = table(call, actor)?;
    if matches!(class, "Quad" | "ActorMultiVertex") && template.is_none() {
        let key = call.try_intern(b"__songlua_default_texture")?;
        call.raw_table_set(actor, key, Value::Boolean(true))?;
    }
    let mut name = get(call, attrs, b"Name")?;
    // Constructors can name a raw CourseContentsList Display before the same
    // declaration is materialized as an ordinary child.
    if name == Value::Nil
        && let Value::Table(source) = call.raw_table_get(node, Value::Number(3.))?
    {
        name = get(call, source, b"Name")?;
        if name != Value::Nil {
            sprites::set(call, actor, "Name", name)?;
        }
    }
    let load_name = if dummy || name == Value::Nil {
        None
    } else {
        Some(bytes(call, name)?)
    };
    let registry = table(call, call.captures()[0])?;
    retirement::retain(call, store, scene, actor, registry)?;
    {
        let mut store = store.lock().unwrap();
        store.scenes.get_mut(&scene).unwrap().actors.push(actor);
        let deferred = store.defer_registration && !internal && !dummy;
        let mut instance = Actor::new(
            scene,
            class,
            if deferred { None } else { parent },
            load_name,
        );
        instance.pending_init = deferred;
        instance.registered = !deferred;
        if deferred {
            instance.state.name = instance.load_name.clone().unwrap_or_default();
        } else {
            store.actor_order.push(actor);
        }
        if store.constructing_capture {
            instance.capture = Some(capture::Capture::default());
        }
        if let Some(template) = &template {
            // Production clones native fields into a fresh actor at its last
            // destination. Its existing tween queue does not advance or become
            // the clone's queue; independent hibernation and immediate fields
            // are retained. Init still runs normally on the new instance.
            instance.current = template.pose;
            instance.hibernate = template.hibernate;
            instance.update_rate = template.update_rate;
            instance.propagate = template.propagate;
            instance.update_error_reported = template.update_error_reported;
            instance.state.size = template.state.size;
            instance.state.visible = template.state.visible;
            instance.state.draw_order = template.state.draw_order;
            instance.state.render = template.state.render;
            instance.state.rotation = template.state.rotation;
            instance.effects = template.effects;
            if store.preparing {
                instance.capture = template.capture.clone().or(instance.capture);
                instance.preparation_getters = template.preparation_getters;
                instance.offline_instance = true;
            }
        }
        store.actors.insert(actor, instance);
    }
    initialize_resources(
        call,
        store,
        scene,
        actor,
        class,
        if template.is_some() {
            ResourceMode::Template
        } else {
            ResourceMode::Constructor
        },
    )?;
    if dummy {
        return Ok(Some(actor));
    }
    if matches!(
        class,
        "ActorFrame"
            | "PlayerActor"
            | "HoldJudgment"
            | "PercentageDisplay"
            | "StepsDisplay"
            | "TopScreen"
            | "NoteField"
            | "ActorFrameTexture"
            | "GraphDisplay"
            | "SongMeterDisplay"
            | "CourseContentsList"
            | "Model"
    ) {
        let nodes = table(call, call.raw_table_get(node, Value::Number(2.))?)?;
        let mut selected = nodes;
        let mut array_only = true;
        for i in 1..=call.raw_table_len(nodes)? {
            let entry = table(call, call.raw_table_get(nodes, Value::Number(i as f64))?)?;
            let key = call.raw_table_get(entry, Value::Number(1.))?;
            if bytes(call, key)? == b"children" {
                let node = table(call, call.raw_table_get(entry, Value::Number(2.))?)?;
                selected = table(call, call.raw_table_get(node, Value::Number(2.))?)?;
                array_only = false;
                break;
            }
        }
        for i in 1..=call.raw_table_len(selected)? {
            let entry = table(call, call.raw_table_get(selected, Value::Number(i as f64))?)?;
            let name = call.raw_table_get(entry, Value::Number(1.))?;
            let name = bytes(call, name)?;
            if array_only && (name.is_empty() || !name.iter().all(u8::is_ascii_digit)) {
                continue;
            }
            let child = table(call, call.raw_table_get(entry, Value::Number(2.))?)?;
            if let Some(child) = build(call, store, scene, child, Some(actor), true, false)? {
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .children
                    .push(child);
                let index = store.lock().unwrap().actors[&actor].children.len();
                call.raw_table_set(actor, Value::Number(index as f64), Value::Table(child))?;
            }
        }
    }
    Ok(Some(actor))
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ResourceMode {
    Constructor,
    Template,
    OfflineClone,
    Dummy,
}

fn initialize_resources(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
    class: &'static str,
    mode: ResourceMode,
) -> Result<(), Error> {
    let template = mode != ResourceMode::Constructor;
    let bind_only = matches!(mode, ResourceMode::OfflineClone | ResourceMode::Dummy);
    if class == "Sound" {
        sound::install(call, store, actor)?;
    }
    proxies::install(call, actor, class == "ActorProxy")?;
    textures::install_getter(call, store, actor)?;
    if !template {
        render::initialize(call, store, actor)?;
    }
    if class == "Model" {
        models::initialize(call, store, actor, template)?;
    }
    if text_displays::is_display(class) {
        text_displays::install(call, actor)?;
        if !bind_only && let Some(text) = crate::input_status_actor_text(class) {
            let value = call.try_intern(text.as_bytes())?;
            sprites::set(call, actor, "Text", value)?;
        }
    }
    if matches!(
        class,
        "GraphDisplay" | "GraphDisplayBody" | "GraphDisplayLine"
    ) {
        graphs::install(call, actor)?;
    }
    if class == "GraphDisplay" && !bind_only {
        graphs::initialize(call, store, scene, actor)?;
    }
    if class == "CourseContentsList" {
        courses::install(call, actor)?;
        if !bind_only {
            courses::initialize(call, store, scene, actor)?;
        }
    }
    if class == "SongMeterDisplay" {
        song_meters::install(call, actor)?;
        if !bind_only {
            song_meters::initialize(call, store, scene, actor)?;
        }
    }
    if class == "ActorFrameTexture" && !bind_only {
        framebuffers::initialize(call, actor)?;
    }
    if matches!(class, "Sprite" | "Banner") && !bind_only {
        sprites::initialize(call, store, actor, template)?;
    }
    Ok(())
}

fn new_scene(call: &HostCall<'_>, store: &Shared) -> Result<u64, Error> {
    let mut guard = store.lock().unwrap();
    if guard.next >= (1u64 << 53) - 1 {
        return Err(call.error(b"actor scene identity exhausted"));
    }
    guard.next += 1;
    let id = guard.next;
    guard.scenes.insert(
        id,
        Scene {
            actors: Vec::new(),
            root: None,
            ended: false,
            sounds_retired: false,
            initial_states: None,
            song_session: None,
        },
    );
    Ok(id)
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Materialization {
    Template,
    Construct,
    Initialize,
}

// Declaration construction and template cloning share scene ownership. A
// compiler can retain the constructed graph across initial-state capture/Init.
fn materialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    declaration: TableId,
    mode: Materialization,
) -> Result<u64, Error> {
    let offline = {
        let guard = store.lock().unwrap();
        matches!(
            mode,
            Materialization::Construct | Materialization::Initialize
        ) && guard.preparing
            && guard.actors.contains_key(&declaration)
    };
    if offline {
        return offline::own_root(
            call,
            store,
            declaration,
            mode == Materialization::Initialize,
        );
    }
    let node = call.call(helper(call, 2)?, &[Value::Table(declaration)])?[0];
    call.with_roots(&[node], |call| {
        let id = new_scene(call, store)?;
        let previous = {
            let mut guard = store.lock().unwrap();
            std::mem::replace(
                &mut guard.defer_registration,
                mode != Materialization::Template,
            )
        };
        // MakeActor ignores Condition on the root. Only the child loader tests it.
        let result = build(call, store, id, table(call, node)?, None, false, false);
        store.lock().unwrap().defer_registration = previous;
        let result = result.and_then(|root| {
            if mode == Materialization::Initialize
                && let Some(actor) = root
            {
                prepare_init(store);
                initialize(call, store, actor)?;
            }
            Ok(root)
        });
        match result {
            Ok(root) => {
                let mut guard = store.lock().unwrap();
                guard.scenes.get_mut(&id).unwrap().root = root;
                if mode == Materialization::Template
                    && let Some(actor) = root
                {
                    let offline = !guard.clock.live.load(std::sync::atomic::Ordering::Relaxed)
                        && !guard.playback;
                    guard.actors.get_mut(&actor).unwrap().offline_template = offline;
                }
                Ok(id)
            }
            Err(error) => {
                release(call, store, id)?;
                Err(error)
            }
        }
    })
}

fn prepare_init(store: &Shared) {
    let mut guard = store.lock().unwrap();
    if guard.preparing {
        guard.startup_queues.get_or_insert_with(Vec::new);
    }
}

fn initialize(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    if !store.lock().unwrap().actors.contains_key(&actor) {
        return native_children::group_lifecycle(call, store, actor, false);
    }
    if store.lock().unwrap().actors[&actor].offline_instance {
        offline::prepare_init(call, store, actor)?;
    }
    courses::prepare_raw_init(call, store, actor)?;
    if store.lock().unwrap().actors[&actor].initialized {
        return Ok(());
    }
    let original = get(call, actor, b"Name")?;
    call.with_roots(&[original], |call| {
        initialize_body(call, store, actor, original)
    })
}
fn initialize_body(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    original: Value,
) -> Result<(), Error> {
    let raw = {
        let guard = store.lock().unwrap();
        let a = &guard.actors[&actor];
        a.raw_instance || a.offline_instance
    };
    let name = if raw {
        // Raw CourseContentsList displays preserve malformed attributes until
        // a typed getter reads them. prepare_raw_init already applies that rule.
        store.lock().unwrap().actors[&actor].load_name.clone()
    } else if original == Value::Nil {
        None
    } else {
        Some(bytes(call, original)?)
    };
    {
        let mut store = store.lock().unwrap();
        if !store.actor_order.contains(&actor) {
            store.actor_order.push(actor);
        }
        let actor = store.actors.get_mut(&actor).unwrap();
        actor.state.name.clear();
        actor.load_name = name;
        actor.pending_init = false;
        actor.registered = true;
    }
    // The production host materializes the complete tree before Init. Every
    // child is observable while child-first Init applies names and draw order.
    for child in declared_children(store, actor) {
        native_children::adopt_declared(call, store, child, actor)?;
        initialize(call, store, child)?;
    }
    sort(call, store, actor)?;
    {
        let mut store = store.lock().unwrap();
        let actor = store.actors.get_mut(&actor).unwrap();
        if let Some(name) = actor.load_name.take() {
            actor.state.name = name;
        }
    }
    if original != Value::Nil {
        let key = call.try_intern(b"Name")?;
        call.raw_table_set(actor, key, original)?;
    }
    courses::publish_raw_name(call, store, actor, original)?;
    play(call, store, actor, b"Init", None, false)?;
    if let Some(stream) = song_meters::stream(call, store, actor)? {
        if store
            .lock()
            .unwrap()
            .actors
            .get(&stream)
            .is_some_and(|a| !a.initialized)
        {
            let name = get(call, stream, b"Name")?;
            if name != Value::Nil {
                let name = bytes(call, name)?;
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&stream)
                    .unwrap()
                    .load_name = Some(name);
            }
        }
        initialize(call, store, stream)?;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .initialized = true;
    courses::publish_raw_flag(call, store, actor, "__songlua_init_commands_ran")?;
    Ok(())
}
fn group(call: &mut HostCall<'_>, ids: &[TableId]) -> Result<Value, Error> {
    match ids {
        [] => Ok(Value::Nil),
        [actor] => Ok(Value::Table(*actor)),
        _ => {
            let list = call.try_new_table()?;
            for (i, id) in ids.iter().enumerate() {
                call.raw_table_set(list, Value::Number((i + 1) as f64), Value::Table(*id))?;
            }
            Ok(call.call(helper(call, 3)?, &[Value::Table(list)])?[0])
        }
    }
}
fn invoke_bound(call: &mut HostCall<'_>) -> Result<(), Error> {
    let name = *call.function_data::<&'static str>().unwrap();
    // Production's own adapters close over the receiver. Both colon and dot
    // invocation therefore address this actor, including calls with another
    // table in the receiver slot. settext uniquely always reads argument two.
    let skip = if name == "settext" {
        1
    } else {
        usize::from(matches!(call.arguments().first(), Some(Value::Table(_))))
    };
    let mut args = Vec::with_capacity(call.arguments().len() + 1);
    args.push(call.captures()[2]);
    args.extend(call.arguments().iter().skip(skip).copied());
    call.call_and_return(call.captures()[3], &args)
}

fn actor_name(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<Vec<u8>, Error> {
    let (raw, name) = {
        let guard = store.lock().unwrap();
        let actor = &guard.actors[&actor];
        (
            actor.raw_instance || actor.pending_init || actor.offline_instance,
            actor.state.name.clone(),
        )
    };
    if raw {
        for key in [
            b"__songlua_load_name".as_slice(),
            b"__songlua_native_name",
            b"Name",
        ] {
            let value = get(call, actor, key)?;
            if value != Value::Nil {
                return Ok(assets::text(call, value)?.into_bytes());
            }
        }
        return Ok(Vec::new());
    }
    Ok(name)
}

fn parent_scene(
    call: &mut HostCall<'_>,
    store: &Shared,
    root: TableId,
    parent: Value,
    append: bool,
) -> Result<(), Error> {
    let parent = match parent {
        Value::Nil if !append => None,
        Value::Table(parent) if store.lock().unwrap().actors.contains_key(&parent) => Some(parent),
        _ => return Err(call.error(b"parent must be an actor owned by this runtime")),
    };
    if let Some(parent) = parent {
        {
            let guard = store.lock().unwrap();
            let mut ancestor = Some(parent);
            let mut visited = HashSet::new();
            while let Some(id) = ancestor {
                if id == root || !visited.insert(id) {
                    return Err(call.error(b"actor parent would create a cycle"));
                }
                ancestor = guard.actors.get(&id).and_then(|actor| actor.parent);
            }
            // Before Init, child links exist even though GetParent is still nil.
            let mut descendants = guard.actors[&root].children.clone();
            let mut visited = HashSet::new();
            while let Some(id) = descendants.pop() {
                if id == parent {
                    return Err(call.error(b"actor parent would create a cycle"));
                }
                if visited.insert(id)
                    && let Some(actor) = guard.actors.get(&id)
                {
                    descendants.extend_from_slice(&actor.children);
                }
            }
        }
        if append {
            if !is_frame(store, parent) {
                return Err(call.error(b"ActorFrame parent expected"));
            }
            courses::share_child(call, store, parent, root)?;
            if !store.lock().unwrap().actors[&parent]
                .children
                .contains(&root)
            {
                screen_parts::append(call, store, parent, root)?;
                lifecycle::invalidate_plans(call, store)?;
                return Ok(());
            }
        }
        native_children::adopt(call, store, root, parent)?;
    } else {
        sprites::set(call, root, "__songlua_parent", Value::Nil)?;
        store.lock().unwrap().actors.get_mut(&root).unwrap().parent = None;
    }
    Ok(())
}

fn callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let Binding { store, op } = call.function_data::<Binding>().unwrap().clone();
    retirement::sweep(&store);
    if matches!(op, Op::Retire) {
        let id = call.number(0)? as u64;
        let retired = retirement::retire(call, &store, id)?;
        return call.push(Value::Boolean(retired));
    }
    if matches!(op, Op::PrepareDefinitions) {
        return offline::install(call, &store);
    }
    if matches!(op, Op::LoadPreparationActor) {
        return loading::load_actor(call, &store);
    }
    if let Op::OfflineConstructor(class) = op {
        return offline::construct(call, &store, class);
    }

    if matches!(op, Op::DiscoverStartup) {
        return capture::discover_startup(call, &store);
    }
    if let Op::Message(op) = op {
        return messages::callback(call, &store, op);
    }
    if matches!(op, Op::End) {
        let id = call.number(0)? as u64;
        if store.lock().unwrap().retired_scenes.contains_key(&id) {
            return call.push(Value::Boolean(false));
        }
        let root = {
            let mut store = store.lock().unwrap();
            let Some(scene) = store.scenes.get_mut(&id) else {
                return call.push(Value::Boolean(false));
            };
            if scene.ended {
                return call.push(Value::Boolean(false));
            }
            // An errored End is still final. The caller observes its partial
            // effects; it must not retry callbacks or advance the outgoing tree.
            scene.ended = true;
            scene.root
        };
        if let Some(root) = root {
            lifecycle::end(call, &store, root)?;
        }
        let actors = store.lock().unwrap().scenes[&id].actors.clone();
        for actor in actors {
            sound::retire(call, &store, actor);
        }
        store
            .lock()
            .unwrap()
            .scenes
            .get_mut(&id)
            .unwrap()
            .sounds_retired = true;
        return call.push(Value::Boolean(true));
    }
    if matches!(
        op,
        Op::Start | Op::Advance | Op::DrawScene | Op::Initialize | Op::SetParent | Op::Append
    ) {
        let id = call.number(0)? as u64;
        if store.lock().unwrap().retired_scenes.contains_key(&id) {
            return call.push(Value::Boolean(false));
        }
        let root = store
            .lock()
            .unwrap()
            .scenes
            .get(&id)
            .map(|scene| (scene.root, scene.ended));
        let Some((root, ended)) = root else {
            return call.push(Value::Boolean(false));
        };
        if ended {
            return Err(call.error(b"cannot advance an ended song Lua scene"));
        }
        if let Some(root) = root {
            if matches!(op, Op::Initialize) {
                prepare_init(&store);
                initialize(call, &store, root)?;
            } else if matches!(op, Op::SetParent | Op::Append) {
                parent_scene(call, &store, root, arg(call, 1), matches!(op, Op::Append))?;
            } else if matches!(op, Op::Start) {
                lifecycle::start(call, &store, root)?;
            } else if matches!(op, Op::DrawScene) {
                draw::scene(call, &store, root)?;
            } else {
                let delta = call.number(1)? as f32;
                lifecycle::advance(call, &store, root, delta)?;
            }
        }
        return call.push(Value::Boolean(true));
    }
    if matches!(op, Op::LoadFont) {
        return text::load_font(call, &store);
    }
    if matches!(op, Op::Template) {
        let declaration = table(call, arg(call, 0))?;
        let globals = table(call, helper(call, 5)?)?;
        for key in ["__songlua_script_dir", "__songlua_song_dir"] {
            if let Some(directory) = assets::field(call, globals, key.as_bytes())? {
                let value = call.try_intern(directory.as_bytes())?;
                sprites::set(call, declaration, key, value)?;
            }
        }
        let id = materialize(call, &store, declaration, Materialization::Template)?;
        let actor = store.lock().unwrap().scenes[&id]
            .root
            .expect("actor template");
        let key = call.try_intern(b"Class")?;
        call.raw_table_set(actor, key, Value::Nil)?;
        return call.push(Value::Table(actor));
    }
    if matches!(op, Op::Instantiate | Op::Construct) {
        let declaration = table(call, arg(call, 0))?;
        let mode = if matches!(op, Op::Instantiate) {
            Materialization::Initialize
        } else {
            Materialization::Construct
        };
        let id = materialize(call, &store, declaration, mode)?;
        return call.push(Value::Number(id as f64));
    }
    if matches!(op, Op::Release) {
        let id = call.number(0)? as u64;
        let removed = release(call, &store, id)?;
        return call.push(Value::Boolean(removed));
    }
    let actor = table(call, arg(call, 0))?;
    if !store.lock().unwrap().actors.contains_key(&actor) {
        return Err(call.error(b"actor instance is not owned by this runtime or has been released"));
    }
    let frame_method = matches!(
        op,
        Op::GetChildren
            | Op::GetChild
            | Op::GetNumChildren
            | Op::Sort
            | Op::OnChildren
            | Op::OnLeaves
            | Op::NamedChildren
            | Op::NamedLeaves
            | Op::Propagate
            | Op::PropagateCommand
    ) || matches!(op, Op::Render(name) if render::FRAME_METHODS.contains(&name))
        || matches!(op, Op::Draw("SetDrawFunction" | "GetDrawFunction"));
    let actor_class = store.lock().unwrap().actors[&actor].state.class;
    let private_child_query = matches!(op, Op::GetChild | Op::GetChildren | Op::GetNumChildren)
        && matches!(
            actor_class,
            "Model" | "OptionRow" | "OptionRowFrame" | "LifeMeter"
        );
    if frame_method && !is_frame(&store, actor) && !private_child_query {
        return Err(call.error(b"ActorFrame expected"));
    }
    match op {
        Op::Lifecycle(operation) => return lifecycle::method(call, &store, actor, operation),
        Op::Render(name) => return render::method(call, &store, actor, name),
        Op::Effect(name) => return effects::method(call, &store, actor, name),
        Op::Wrapper(name) => return wrappers::method(call, &store, actor, name),
        Op::Sound(name) => return sound::method(call, &store, actor, name),
        Op::Sprite(name) => return sprites::method(call, &store, actor, name),
        Op::Banner(name) => return banners::method(call, &store, actor, name),
        Op::Mesh(name) => return meshes::method(call, &store, actor, name),
        Op::CloneTemplate => {
            if store.lock().unwrap().actors[&actor].offline_instance {
                let clone = offline::clone_actor(call, &store, actor, false)?;
                return call.push(Value::Table(clone));
            }
            let id = materialize(call, &store, actor, Materialization::Template)?;
            let root = store.lock().unwrap().scenes[&id].root;
            return call.push(root.map_or(Value::Nil, Value::Table));
        }
        Op::Text(name) => return text::method(call, &store, actor, name),
        Op::Graph(name) => return graphs::method(call, &store, actor, name),
        Op::SongMeter(name) => return song_meters::method(call, &store, actor, name),
        Op::Course(name) => return courses::method(call, &store, actor, name),
        Op::ReadModelPaths => {
            let paths = models::paths(call, actor)?;
            store.lock().unwrap().model_paths_output = paths;
            return Ok(());
        }
        Op::ReadSongMeter => {
            let meter = song_meters::read(call, &store, actor)?;
            store.lock().unwrap().meter_output = meter;
            return Ok(());
        }
        Op::ReadGraph => {
            let graph = graphs::read(call, &store, actor)?;
            store.lock().unwrap().graph_output = Some(graph);
            return Ok(());
        }
        Op::TextDisplay(name) => return text_displays::method(call, &store, actor, name),
        Op::ReadText => {
            let output = text::read(call, actor)?;
            store.lock().unwrap().text_output = Some(output);
            return Ok(());
        }
        Op::Framebuffer(name) => return framebuffers::method(call, &store, actor, name),
        Op::ReadFramebuffer => {
            let framebuffer = framebuffers::read(call, actor)?;
            store.lock().unwrap().framebuffer_output = Some(framebuffer);
            return Ok(());
        }
        Op::Draw(name) => return draw::method(call, &store, actor, name),
        Op::ReadMesh => {
            let mesh = meshes::read(call, actor)?;
            store.lock().unwrap().mesh_output = mesh;
            return Ok(());
        }
        Op::ReadProxy => {
            let target = proxies::read(call, actor)?;
            store.lock().unwrap().proxy_output = target;
            return Ok(());
        }
        Op::GetName if actor_class == "OptionRow" => {
            let bound = get(call, actor, b"__songlua_bound_methods")?;
            let function = get(call, table(call, bound)?, b"GetName")?;
            let args = call.arguments().to_vec();
            return call.call_and_return(function, &args);
        }
        Op::GetName => {
            let name = actor_name(call, &store, actor)?;
            let name = call.try_intern(&name)?;
            return call.push(name);
        }
        Op::Name => {
            let name = bytes(call, arg(call, 1))?;
            let publish = {
                let guard = store.lock().unwrap();
                let actor = &guard.actors[&actor];
                actor.raw_instance || actor.pending_init || actor.offline_instance
            };
            if publish {
                let value = call.try_intern(&name)?;
                let key = call.try_intern(b"__songlua_load_name")?;
                if call.raw_table_get(actor, key)? != Value::Nil {
                    call.raw_table_set(actor, key, value)?;
                }
                let key = call.try_intern(b"__songlua_native_name")?;
                call.raw_table_set(actor, key, value)?;
            }
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .name = name;
        }
        Op::GetParent => {
            let parent = store.lock().unwrap().actors[&actor].parent;
            return call.push(parent.map_or(Value::Nil, Value::Table));
        }
        Op::GetNumChildren => {
            let count = children(call, &store, actor)?.len();
            return call.push(Value::Number(count as f64));
        }
        Op::GetChild if actor_class == "TopScreen" => {
            let bound = get(call, actor, b"__songlua_bound_methods")?;
            let function = get(call, table(call, bound)?, b"GetChild")?;
            if function != Value::Nil {
                let args = call.arguments().to_vec();
                return call.call_and_return(function, &args);
            }
            let key = bytes(call, arg(call, 1))?;
            let map = native_children::named_children(call, actor)?;
            let value = call.with_roots(&[map], |call| {
                let key = call.try_intern(&key)?;
                call.table_get(map, key)
            })?;
            return call.push(value);
        }
        Op::GetChild if has_native_children(&store, actor) => {
            let key = arg(call, 1);
            let key = bytes(call, key)?;
            let map = native_children::named_children(call, actor)?;
            let value = call.with_roots(&[map], |call| {
                let key = call.try_intern(&key)?;
                call.table_get(map, key)
            })?;
            return call.push(value);
        }
        Op::GetChildren if has_native_children(&store, actor) => {
            let result = native_children::named_children(call, actor)?;
            return call.push(result);
        }
        Op::GetChild => {
            let name = bytes(call, arg(call, 1))?;
            let mut ids = Vec::new();
            for id in children(call, &store, actor)? {
                if actor_name(call, &store, id)? == name {
                    ids.push(id);
                }
            }
            let value = group(call, &ids)?;
            return call.push(value);
        }
        Op::GetChildren => {
            let result = Value::Table(call.try_new_table()?);
            return call.with_roots(&[result], |call| {
                let mut names: Vec<(Vec<u8>, Vec<TableId>)> = Vec::new();
                for id in children(call, &store, actor)? {
                    let name = actor_name(call, &store, id)?;
                    if let Some((_, ids)) = names.iter_mut().find(|(n, _)| *n == name) {
                        ids.push(id)
                    } else {
                        names.push((name, vec![id]));
                    }
                }
                for (name, ids) in names {
                    let value = group(call, &ids)?;
                    let key = call.try_intern(&name)?;
                    call.raw_table_set(table(call, result)?, key, value)?;
                }
                call.push(result)
            });
        }
        Op::Sort => sort(call, &store, actor)?,
        Op::Propagate => {
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .propagate = !matches!(arg(call, 1), Value::Nil | Value::Boolean(false));
        }
        Op::AddCommand | Op::GetCommand => {
            let name = arg(call, 1);
            if matches!(op, Op::GetCommand) {
                let Some(name) = command_name(call, name) else {
                    return call.push(Value::Nil);
                };
                let value = command(call, actor, &name)?;
                return call.push(value.map_or(Value::Nil, |(function, _)| function));
            }
            let name = bytes(call, name)?;
            std::str::from_utf8(&name).map_err(|_| call.error(b"command name must be UTF-8"))?;
            let value = arg(call, 2);
            if !matches!(value, Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"function expected"));
            }
            let key = call.try_intern(&[name.as_slice(), b"Command"].concat())?;
            call.table_set(Value::Table(actor), key, value)?;
        }
        Op::PlayCommand | Op::PropagateCommand | Op::NamedChildren | Op::NamedLeaves => {
            let Some(name) = command_name(call, arg(call, 1)) else {
                return call.push(Value::Table(actor));
            };
            let params = call.arguments().get(2).copied();
            match op {
                Op::NamedLeaves => leaves(call, &store, actor, &mut |call, actor| {
                    run_named(call, &store, actor, &name, params)
                })?,
                Op::NamedChildren | Op::PropagateCommand => {
                    for child in children(call, &store, actor)? {
                        play(
                            call,
                            &store,
                            child,
                            &name,
                            params,
                            matches!(op, Op::PropagateCommand),
                        )?;
                    }
                }
                _ => {
                    let propagate = store.lock().unwrap().actors[&actor].propagate;
                    if !propagate {
                        run_named(call, &store, actor, &name, params)?;
                    }
                    for child in children(call, &store, actor)? {
                        play(call, &store, child, &name, params, true)?;
                    }
                }
            }
        }
        Op::Recursive => {
            // The existing production class exposes this name but has no
            // semantic implementation. Migration must preserve that error.
            return Err(call.error(
                b"native actor method RunCommandsRecursively has no semantic implementation",
            ));
        }
        Op::OnChildren | Op::OnLeaves => {
            let function = arg(call, 1);
            if matches!(function, Value::Function(_) | Value::Native(_)) {
                let params = call.arguments().get(2).copied();
                match op {
                    Op::OnLeaves => leaves(call, &store, actor, &mut |call, actor| {
                        run(call, actor, function, None)
                    })?,
                    _ => {
                        for child in children(call, &store, actor)? {
                            run(call, child, function, params)?;
                        }
                    }
                }
            }
        }
        Op::Set(name) => set_scalar(call, &store, actor, name)?,
        Op::Get(name) => return get_scalar(call, &store, actor, name),
        Op::PrepareDefinitions
        | Op::LoadPreparationActor
        | Op::OfflineConstructor(_)
        | Op::Instantiate
        | Op::Construct
        | Op::Initialize
        | Op::SetParent
        | Op::Append
        | Op::DiscoverStartup
        | Op::Template
        | Op::LoadFont
        | Op::Release
        | Op::Retire
        | Op::Start
        | Op::Advance
        | Op::End
        | Op::DrawScene
        | Op::Message(_) => {
            unreachable!()
        }
    }
    call.push(Value::Table(actor))
}
fn command_name(call: &HostCall<'_>, value: Value) -> Option<Vec<u8>> {
    let Value::String(id) = value else {
        return None;
    };
    std::str::from_utf8(call.string_bytes(id)?)
        .ok()
        .map(|name| name.as_bytes().to_vec())
}
fn set_scalar(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    if name == "draworder" {
        if let Some(value) = integer_scalar(call, arg(call, 1)) {
            action_capture::prepare(call, store, actor)?;
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .draw_order = value;
            let key = call.try_intern(b"__songlua_state_draw_order")?;
            call.raw_table_set(actor, key, Value::Number(value as f64))?;
            capture::property(call, store, actor, name);
            song_properties::record(
                call,
                store,
                actor,
                crate::SongLuaOverlayUpdateTarget::DrawOrder,
                crate::SongLuaOverlayUpdateValue::I32(value),
            );
        }
        return Ok(());
    }
    let allows_nonfinite = matches!(
        name,
        "x" | "y" | "zoom" | "zoomx" | "zoomy" | "zoomz" | "rotationx" | "rotationy" | "rotationz"
    );
    if name == "xy" {
        let store_ref = store;
        let x = float_scalar(call, arg(call, 1), false);
        let y = float_scalar(call, arg(call, 2), false);
        if x.is_some() || y.is_some() {
            action_capture::prepare(call, store, actor)?;
        }
        let mut store = store.lock().unwrap();
        let position = store.actors.get_mut(&actor).unwrap().destination_mut();
        if let Some(x) = x {
            position.x = x;
        }
        if let Some(y) = y {
            position.y = y;
        }
        drop(store);
        capture::write(
            call,
            store_ref,
            actor,
            crate::SongLuaOverlayStateDelta {
                x,
                y,
                ..Default::default()
            },
            false,
        );
        song_replay::publish_scalar(call, store_ref, actor, name)?;
        return Ok(());
    }
    let first = if name == "visible" {
        let Some(value) = boolish(call, arg(call, 1)) else {
            return Ok(());
        };
        value as u8 as f32
    } else {
        let Some(value) = float_scalar(call, arg(call, 1), allows_nonfinite) else {
            return Ok(());
        };
        value
    };
    let second = if name == "setsize" {
        let Some(value) = float_scalar(call, arg(call, 2), false) else {
            return Ok(());
        };
        value
    } else {
        0.
    };
    if matches!(name, "SetWidth" | "SetHeight") {
        sprites::refresh_size(call, store, actor)?;
    }
    if matches!(name, "SetWidth" | "SetHeight" | "setsize" | "visible") {
        action_capture::prepare(call, store, actor)?;
    }
    if matches!(name, "SetWidth" | "SetHeight" | "setsize") {
        let size = {
            let store = store.lock().unwrap();
            let actor = &store.actors[&actor];
            (actor.state.class == "ActorFrameTexture").then(|| match name {
                "SetWidth" => [first, actor.state.size[1].abs()],
                "SetHeight" => [actor.state.size[0].abs(), first],
                _ => [first, second],
            })
        };
        if let Some(size) = size {
            let value = sprites::vector_value(call, &size)?;
            let key = call.try_intern(b"__songlua_state_size")?;
            call.raw_table_set(actor, key, value)?;
        }
    }
    if name == "visible" {
        sprites::set(
            call,
            actor,
            "__songlua_visible",
            Value::Boolean(first != 0.),
        )?;
    }
    let preparation = {
        let store = store.lock().unwrap();
        !store.playback || store.actors[&actor].replay.is_some()
    };
    let captured_position = if preparation && matches!(name, "addx" | "addy" | "addz") {
        text::captured_position(call, actor, &name[3..])?
    } else {
        None
    };
    action_capture::prepare(call, store, actor)?;
    let id = actor;
    let mut guard = store.lock().unwrap();
    let actor = guard.actors.get_mut(&id).unwrap();
    let captured_position = captured_position.or_else(|| {
        actor.replay.as_ref().and_then(|_| {
            let pose = actor.getter_destination();
            match name {
                "addx" => Some(pose.x),
                "addy" => Some(pose.y),
                "addz" => Some(pose.z),
                _ => None,
            }
        })
    });
    let immediate = &mut actor.state;
    match name {
        "SetWidth" => immediate.size = [first, immediate.size[1].abs()],
        "SetHeight" => immediate.size = [immediate.size[0].abs(), first],
        "setsize" => immediate.size = [first, second],
        "visible" => immediate.visible = first != 0.,
        _ => {}
    }
    if matches!(name, "SetWidth" | "SetHeight" | "setsize") {
        immediate.render.size = Some(immediate.size);
    }
    let s = actor.destination_mut();
    match name {
        "x" => s.x = first,
        "y" => s.y = first,
        "z" => s.z = first,
        "addx" => s.x = captured_position.unwrap_or(s.x) + first,
        "addy" => s.y = captured_position.unwrap_or(s.y) + first,
        "addz" => s.z = captured_position.unwrap_or(s.z) + first,
        "zoom" => {
            s.zoom = first;
            s.zoom_x = first;
            s.zoom_y = first;
            s.zoom_z = first;
        }
        "zoomx" => s.zoom_x = first,
        "zoomy" => s.zoom_y = first,
        "zoomz" => s.zoom_z = first,
        "rotationx" => s.rot_x_deg = first,
        "rotationy" => s.rot_y_deg = first,
        "rotationz" => s.rot_z_deg = first,
        "addrotationx" => s.rot_x_deg += first,
        "addrotationy" => s.rot_y_deg += first,
        "addrotationz" => s.rot_z_deg += first,
        "aux" => s.aux = first,
        "SetWidth" | "SetHeight" | "setsize" | "visible" => {}
        _ => unreachable!(),
    }
    match name {
        "rotationx" | "addrotationx" => actor.state.rotation[0] = actor.destination().rot_x_deg,
        "rotationy" | "addrotationy" => actor.state.rotation[1] = actor.destination().rot_y_deg,
        "rotationz" | "addrotationz" => actor.state.rotation[2] = actor.destination().rot_z_deg,
        _ => {}
    }
    let template_position = if actor.offline_template {
        match name {
            "x" | "addx" => Some(("x", actor.destination().x)),
            "y" | "addy" => Some(("y", actor.destination().y)),
            "z" | "addz" => Some(("z", actor.destination().z)),
            _ => None,
        }
    } else {
        None
    };
    drop(guard);
    capture::property(call, store, id, name);
    if let Some((axis, value)) = template_position {
        text::capture_template_position(call, id, axis, value)?;
    }
    if matches!(name, "zoom" | "zoomx" | "zoomy") {
        text::pre_zoom(call, store, id, name != "zoomy", name != "zoomx")?;
    }
    song_replay::publish_scalar(call, store, id, name)
}
fn float_scalar(call: &HostCall<'_>, value: Value, allows_nonfinite: bool) -> Option<f32> {
    match value {
        Value::Number(value) => {
            let value = value as f32;
            (allows_nonfinite || value.is_finite()).then_some(value)
        }
        Value::String(id) => std::str::from_utf8(call.string_bytes(id)?)
            .ok()?
            .trim()
            .parse()
            .ok(),
        _ => None,
    }
}
fn integer_scalar(call: &HostCall<'_>, value: Value) -> Option<i32> {
    match value {
        Value::Number(value) if value.is_finite() => Some(value.round() as i32),
        Value::String(id) => {
            let text = std::str::from_utf8(call.string_bytes(id)?).ok()?.trim();
            text.parse()
                .ok()
                .or_else(|| text.parse::<f32>().ok().map(|value| value.round() as i32))
        }
        _ => None,
    }
}
fn boolish(call: &HostCall<'_>, value: Value) -> Option<bool> {
    match value {
        Value::Boolean(value) => Some(value),
        Value::Number(value) => Some(value != 0.0),
        Value::String(id) => {
            let text = std::str::from_utf8(call.string_bytes(id)?).ok()?.trim();
            if ["true", "yes", "on"]
                .iter()
                .any(|word| text.eq_ignore_ascii_case(word))
            {
                Some(true)
            } else if ["false", "no", "off"]
                .iter()
                .any(|word| text.eq_ignore_ascii_case(word))
            {
                Some(false)
            } else {
                text.parse::<f32>().ok().map(|value| value != 0.0)
            }
        }
        _ => None,
    }
}
fn get_scalar(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    if matches!(
        name,
        "GetWidth" | "GetHeight" | "GetZoomedWidth" | "GetZoomedHeight"
    ) {
        sprites::refresh_size(call, store, actor)?;
    }
    let store = store.lock().unwrap();
    let prior = song_pose::prior_position(&store, actor);
    let actor = &store.actors[&actor];
    let s = &actor.state;
    let current = &actor.current;
    let getters =
        actor
            .preparation_getters
            .unwrap_or([current.x, current.y, current.z, current.aux]);
    let dest = actor.getter_destination();
    let value = match name {
        "GetX" => prior.map_or(getters[0], |p| p[0]),
        "GetY" => prior.map_or(getters[1], |p| p[1]),
        "GetZ" => prior.map_or(getters[2], |p| p[2]),
        "GetDestX" => dest.x,
        "GetDestY" => dest.y,
        "GetDestZ" => dest.z,
        "GetZoom" | "GetZoomX" => dest.zoom_x,
        "GetZoomY" => dest.zoom_y,
        "GetZoomZ" => dest.zoom_z,
        "GetRotationX" => s.rotation[0],
        "GetRotationY" => s.rotation[1],
        "GetRotationZ" => s.rotation[2],
        "GetWidth" => s.size[0].abs(),
        "GetHeight" => s.size[1].abs(),
        "GetZoomedWidth" => s.size[0].abs() * (s.render.basezoom_x * dest.zoom_x),
        "GetZoomedHeight" => s.size[1].abs() * (s.render.basezoom_y * dest.zoom_y),
        "getaux" => getters[3],
        "GetVisible" => return call.push(Value::Boolean(s.visible)),
        _ => unreachable!(),
    };
    call.push(Value::Number(f64::from(value)))
}

//! Lazy actor state around the existing compiler touched-function probes.
use super::super::{SongActorFunctionBlocks, random::RandomState};
use super::*;

const KEYS: [&str; 3] = [
    crate::SONG_LUA_CAPTURE_ACTORS_KEY,
    crate::SONG_LUA_CAPTURE_ACTOR_SET_KEY,
    crate::SONG_LUA_CAPTURE_SNAPSHOTS_KEY,
];
pub(super) struct State {
    retained: TableId,
    actors: TableId,
    actor_set: TableId,
    snapshots: TableId,
    order: Vec<TableId>,
    seen: HashSet<TableId>,
    saved: Vec<(TableId, TableId, Option<function_capture::Saved>)>,
}
#[derive(Default)]
struct Output {
    previous: Option<State>,
    current: Option<State>,
    activated: bool,
    deactivated: bool,
    restored: bool,
    raw: bool,
    blocks: SongActorFunctionBlocks,
}
#[derive(Clone)]
struct Run {
    store: Shared,
    selected: Vec<(usize, TableId)>,
    output: Arc<Mutex<Output>>,
    action: Option<function_action::Scope>,
}
impl Actors {
    pub(in crate::rust_engine) fn capture_touched_actor_function(
        &self,
        vm: &mut Vm,
        actors: Vec<(usize, TableId)>,
        function: Value,
        arg: Option<f32>,
        random: &RandomState,
    ) -> (Result<SongActorFunctionBlocks, Error>, bool, Option<Root>) {
        self.capture_scoped_function(vm, actors, function, arg, random, None)
    }
    pub(super) fn capture_scoped_function(
        &self,
        vm: &mut Vm,
        actors: Vec<(usize, TableId)>,
        function: Value,
        arg: Option<f32>,
        random: &RandomState,
        action: Option<function_action::Scope>,
    ) -> (Result<SongActorFunctionBlocks, Error>, bool, Option<Root>) {
        let output = Arc::new(Mutex::new(Output::default()));
        let mut returned = None;
        let result = (|| {
            let retained = vm.try_new_table()?;
            let pin = vm.pin(Value::Table(retained))?;
            let result = (|| {
                let mut captures = [
                    Value::Table(self.registry),
                    Value::Table(self.helpers),
                    Value::Table(retained),
                ]
                .into_iter()
                .chain(actors.iter().map(|(_, a)| Value::Table(*a)))
                .collect::<Vec<_>>();
                if let Some(action) = &action {
                    captures.push(Value::Table(action.retained));
                }
                let data = Run {
                    store: self.store.clone(),
                    selected: actors,
                    output: output.clone(),
                    action,
                };
                // Allocate cleanup callbacks before activating the probe. Their
                // allocation must not run GC between freezing touched actors and
                // restoring the outer scope's command locals/globals.
                let start = vm.new_host_function_with_data(begin, &captures, data.clone())?;
                vm.raw_table_set(retained, Value::Number(11.), start)?;
                let inactive =
                    vm.new_host_function_with_data(deactivate, &captures, data.clone())?;
                vm.raw_table_set(retained, Value::Number(12.), inactive)?;
                let finish = vm.new_host_function_with_data(finish, &captures, data)?;
                vm.raw_table_set(retained, Value::Number(13.), finish)?;
                vm.call(start, &[])?;
                let previous_locals = self.begin_command_locals();
                let random = random.preserve();
                let args = arg
                    .map(|n| Value::Number(f64::from(n)))
                    .into_iter()
                    .collect::<Vec<_>>();
                let result = vm
                    .call(function, &args)
                    .map(|v| v.first().copied().unwrap_or(Value::Nil));
                let result = result.and_then(|value| vm.pin(value).map(|pin| returned = Some(pin)));
                {
                    // Native reads touched actor identities and snapshots before
                    // restoring command locals. Later cleanup activity belongs
                    // outside that frozen set of probe results.
                    let mut guard = self.store.lock().unwrap();
                    let state = guard.action_capture.as_mut().unwrap();
                    let frozen = State {
                        retained: state.retained,
                        actors: state.actors,
                        actor_set: state.actor_set,
                        snapshots: state.snapshots,
                        order: state.order.clone(),
                        seen: state.seen.clone(),
                        saved: std::mem::take(&mut state.saved),
                    };
                    let mut out = output.lock().unwrap();
                    out.current = Some(frozen);
                    out.raw = result
                        .as_ref()
                        .err()
                        .is_some_and(|e| e.kind() != ErrorKind::Runtime);
                }
                let locals = self.restore_command_locals(vm, previous_locals);
                let inactive = vm.call(inactive, &[]).map(|_| ());
                drop(random);
                locals?;
                inactive?;
                vm.call(finish, &[])?;
                result?;
                Ok(std::mem::take(&mut output.lock().unwrap().blocks))
            })();
            // VM allocation/entry failure must never leave a live Rust scope
            // whose retained values are about to lose their temporary root.
            {
                let mut out = output.lock().unwrap();
                if out.activated && !out.deactivated {
                    self.store.lock().unwrap().action_capture = out.previous.take();
                    out.deactivated = true;
                }
            }
            vm.unpin(pin)?;
            result
        })();
        let mut out = output.lock().unwrap();
        let restored = out.restored;
        out.current = None;
        if result.is_err() {
            out.blocks.clear();
        }
        (result, restored, returned)
    }
}
fn begin(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Run>().unwrap().clone();
    let globals = helper(call, 5)?;
    let retained = table(call, call.captures()[2])?;
    let mut tables = Vec::new();
    for (i, key) in KEYS.iter().enumerate() {
        let key = call.try_intern(key.as_bytes())?;
        call.raw_table_set(retained, Value::Number((i + 7) as f64), key)?;
        let old = call.table_get(globals, key)?;
        call.raw_table_set(retained, Value::Number((i + 1) as f64), old)?;
        let next = call.try_new_table()?;
        call.raw_table_set(retained, Value::Number((i + 4) as f64), Value::Table(next))?;
        tables.push((key, next));
    }
    for &(key, next) in &tables {
        call.table_set(globals, key, Value::Table(next))?;
    }
    let state = State {
        retained,
        actors: tables[0].1,
        actor_set: tables[1].1,
        snapshots: tables[2].1,
        order: Vec::new(),
        seen: HashSet::new(),
        saved: Vec::new(),
    };
    let previous = data.store.lock().unwrap().action_capture.replace(state);
    let mut output = data.output.lock().unwrap();
    output.previous = previous;
    output.activated = true;
    Ok(())
}
pub(super) fn prepare(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let tables = {
        let mut guard = store.lock().unwrap();
        let Some(state) = guard.action_capture.as_mut() else {
            return Ok(());
        };
        if !state.seen.insert(actor) {
            return Ok(());
        }
        (
            state.actors,
            state.actor_set,
            state.snapshots,
            state.retained,
        )
    };
    call.raw_table_set(tables.1, Value::Table(actor), Value::Boolean(true))?;
    let count = call.raw_table_len(tables.0)? + 1;
    call.raw_table_set(tables.0, Value::Number(count as f64), Value::Table(actor))?;
    store
        .lock()
        .unwrap()
        .action_capture
        .as_mut()
        .unwrap()
        .order
        .push(actor);
    let raw = state_snapshot::raw_copy(call, actor)?;
    call.with_roots(&[Value::Table(raw)], |call| {
        let row = call.try_new_table()?;
        call.with_roots(&[Value::Table(row)], |call| {
            call.raw_table_set(row, Value::Number(1.), Value::Table(actor))?;
            call.raw_table_set(row, Value::Number(2.), Value::Table(raw))?;
            let count = call.raw_table_len(tables.2)? + 1;
            call.raw_table_set(tables.3, Value::Table(row), Value::Boolean(true))?;
            call.raw_table_set(tables.2, Value::Number(count as f64), Value::Table(row))
        })
    })?;
    let saved = function_capture::Saved::read(store, actor, raw);
    store
        .lock()
        .unwrap()
        .action_capture
        .as_mut()
        .unwrap()
        .saved
        .push((actor, raw, saved));
    function_capture::reset(call, store, actor)
}
fn deactivate(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Run>().unwrap().clone();
    {
        let mut output = data.output.lock().unwrap();
        let mut store = data.store.lock().unwrap();
        store.action_capture = output.previous.take();
        output.deactivated = true;
    }
    let retained = table(call, call.captures()[2])?;
    let globals = helper(call, 5)?;
    for (i, key) in KEYS.iter().enumerate() {
        let old = call.raw_table_get(retained, Value::Number((i + 1) as f64))?;
        let key = call.try_intern(key.as_bytes())?;
        call.table_set(globals, key, old)?;
    }
    Ok(())
}
fn finish(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Run>().unwrap().clone();
    let (state, restore_raw) = {
        let mut out = data.output.lock().unwrap();
        (out.current.take().unwrap(), out.raw)
    };
    let mut blocks = Vec::new();
    for (index, actor) in &data.selected {
        if state.seen.contains(actor)
            && let Some(capture) = data
                .store
                .lock()
                .unwrap()
                .actors
                .get_mut(actor)
                .and_then(|a| a.capture.as_mut())
        {
            let captured = capture.snapshot().blocks;
            if !captured.is_empty() {
                blocks.push((*index, captured));
            }
        }
    }
    if let Some(action) = &data.action {
        action.before_actor_restore(call)?;
    }
    for actor in state.order {
        function_capture::reset(call, &data.store, actor)?;
    }
    for (actor, raw, saved) in state.saved {
        state_snapshot::restore_raw(call, actor, raw, restore_raw)?;
        if let Some(saved) = saved {
            saved.restore(&data.store);
        }
    }
    lifecycle::invalidate_plans(call, &data.store)?;
    if let Some(action) = &data.action {
        action.after_actor_restore(call)?;
    }
    let mut output = data.output.lock().unwrap();
    output.blocks = blocks;
    output.restored = true;
    Ok(())
}

//! Existing actor media-path lookup, independent of either Lua runtime.
use super::*;
use std::{
    fs,
    path::{Path, PathBuf},
    sync::OnceLock,
};

type PrefixCache = Mutex<HashMap<(String, String), Option<PathBuf>>>;
static PREFIXES: OnceLock<PrefixCache> = OnceLock::new();

pub(super) fn text(call: &mut HostCall<'_>, value: Value) -> Result<String, Error> {
    let bytes = bytes(call, value)?;
    String::from_utf8(bytes).map_err(|error| call.error(error.to_string().as_bytes()))
}

pub(super) fn field(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &[u8],
) -> Result<Option<String>, Error> {
    let key = call.try_intern(key)?;
    let value = call.table_get(Value::Table(actor), key)?;
    if value == Value::Nil {
        Ok(None)
    } else {
        text(call, value).map(Some)
    }
}

pub(super) fn resolve(
    call: &mut HostCall<'_>,
    actor: TableId,
    raw: &str,
) -> Result<Option<PathBuf>, Error> {
    let path = Path::new(raw.trim());
    if deadlib_assets::generated_texture_shared_key(raw.trim()).is_some()
        || (path.is_absolute() && path.is_file())
    {
        return Ok(Some(path.to_owned()));
    }
    if let Some(dir) =
        field(call, actor, b"__songlua_script_dir")?.filter(|dir| !dir.trim().is_empty())
    {
        let candidate = Path::new(&dir).join(raw);
        if candidate.is_file() {
            return Ok(Some(candidate));
        }
        return Ok(prefix(Path::new(&dir), path));
    }
    Ok(None)
}

fn prefix(base: &Path, path: &Path) -> Option<PathBuf> {
    if path.extension().is_some() {
        return None;
    }
    let prefix = path.file_name()?.to_str()?.trim();
    if prefix.is_empty() {
        return None;
    }
    let dir = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .map_or_else(|| base.to_owned(), |parent| base.join(parent));
    if !dir.is_dir() {
        return None;
    }
    let key = (
        dir.to_string_lossy().to_ascii_lowercase(),
        prefix.to_ascii_lowercase(),
    );
    let cache = PREFIXES.get_or_init(|| Mutex::new(HashMap::new()));
    if let Some(cached) = cache
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .get(&key)
        .cloned()
    {
        return cached;
    }
    let found = fs::read_dir(&dir)
        .ok()?
        .flatten()
        .filter_map(|entry| {
            let file = entry.file_name();
            let name = file.to_str()?;
            let path = name
                .get(..prefix.len())
                .is_some_and(|start| start.eq_ignore_ascii_case(prefix))
                .then(|| entry.path())?;
            (path.is_file() && crate::is_song_lua_media_path(&path)).then_some(path)
        })
        .min_by(|left, right| {
            let left = left
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("");
            let right = right
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("");
            left.bytes()
                .map(|b| b.to_ascii_lowercase())
                .cmp(right.bytes().map(|b| b.to_ascii_lowercase()))
        });
    cache
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .insert(key, found.clone());
    found
}

pub(super) fn texture_path(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Option<PathBuf>, Error> {
    let key = call.try_intern(b"__songlua_default_texture")?;
    if !matches!(
        call.raw_table_get(actor, key)?,
        Value::Nil | Value::Boolean(false)
    ) {
        return Ok(None);
    }
    let Some(texture) = field(call, actor, b"Texture")? else {
        return Ok(None);
    };
    let texture = texture.trim();
    if texture.is_empty() {
        return Ok(None);
    }
    let raw = Path::new(texture);
    if deadlib_assets::generated_texture_shared_key(texture).is_some()
        || (raw.is_absolute() && raw.exists())
    {
        return Ok(Some(raw.to_owned()));
    }
    if raw.is_absolute()
        && let Some(path) = prefix(Path::new(""), raw)
    {
        return Ok(Some(path));
    }
    for key in [b"__songlua_script_dir".as_slice(), b"__songlua_song_dir"] {
        if let Some(dir) = field(call, actor, key)? {
            let candidate = Path::new(&dir).join(texture);
            if candidate.exists() {
                return Ok(Some(candidate));
            }
            if let Some(path) = prefix(Path::new(&dir), raw) {
                return Ok(Some(path));
            }
        }
    }
    Ok(None)
}

//! Banner's existing Luna methods and the shared Sprite media helpers.
use super::*;
use sprites::{field, set};

pub(super) const METHODS: &[&str] = &[
    "scaletoclipped",
    "ScaleToClipped",
    "LoadFromSong",
    "LoadFromCourse",
    "LoadFromCachedBanner",
    "LoadIconFromCharacter",
    "LoadCardFromCharacter",
    "LoadBannerFromUnlockEntry",
    "LoadBackgroundFromUnlockEntry",
    "LoadFromSongGroup",
    "LoadFromSortOrder",
    "GetScrolling",
    "SetScrolling",
    "GetPercentScrolling",
];
pub(super) const SPRITE_METHODS: &[&str] = &["LoadFromSongBackground", "position", "loop", "rate"];

pub(super) const CURRENT_BACKGROUND: &[u8] = br#"
return function() return function(self)
    local song = GAMESTATE:GetCurrentSong()
    if not song then
        local trail = GAMESTATE:GetCurrentTrail(GAMESTATE:GetMasterPlayerNumber())
        local entries = trail:GetTrailEntries()
        if #entries > 0 then song = entries[1]:GetSong() end
    end
    if not song then return self end
    self:LoadFromSongBackground(song)
    return self
end end
"#;

fn truthy(value: Value) -> bool {
    !matches!(value, Value::Nil | Value::Boolean(false))
}

fn query(call: &mut HostCall<'_>, object: TableId, name: &str) -> Result<Value, Error> {
    let function = field(call, object, name)?;
    if function == Value::Nil {
        return Ok(Value::Nil);
    }
    if !matches!(function, Value::Function(_) | Value::Native(_)) {
        return Err(call.error(b"media path method must be a function"));
    }
    Ok(call
        .call(function, &[Value::Table(object)])?
        .first()
        .copied()
        .unwrap_or(Value::Nil))
}

fn set_path(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    path: &str,
) -> Result<bool, Error> {
    let path = path.trim();
    if path.is_empty() {
        return Ok(false);
    }
    let value = call.try_intern(path.as_bytes())?;
    set(call, actor, "Texture", value)?;
    // Preserve publication order even when an authored setter reenters Lua.
    let key = call.try_intern(b"__songlua_amv_texture_handle")?;
    call.raw_table_set(actor, key, Value::Nil)?;
    let key = call.try_intern(b"__songlua_default_texture")?;
    call.raw_table_set(actor, key, Value::Boolean(false))?;
    set(call, actor, "__songlua_aft_capture_name", Value::Nil)?;
    let video = sprites::is_video(call, actor)?;
    sprites::decode(call, store, actor, video)?;
    Ok(true)
}

fn from_methods(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    source: Value,
    names: &[&str],
) -> Result<bool, Error> {
    let Value::Table(source) = source else {
        return Ok(false);
    };
    for name in names {
        let value = query(call, source, name)?;
        if let Value::String(_) = value {
            let path = assets::text(call, value)?;
            if set_path(call, store, actor, &path)? {
                return Ok(true);
            }
        }
    }
    Ok(false)
}

fn reset_scrolling(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    set(
        call,
        actor,
        "__songlua_state_banner_scrolling",
        Value::Boolean(false),
    )?;
    set(
        call,
        actor,
        "__songlua_state_banner_scroll_percent",
        Value::Number(0.0),
    )
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = arg(call, 1);
    match name {
        "scaletoclipped" | "ScaleToClipped" => {
            return sprites::method(call, store, actor, "scaletoclipped");
        }
        "LoadFromCachedBanner" => sprites::set_texture(call, store, actor, value, true)?,
        "LoadFromSong" => {
            let mut path = None;
            if let Value::Table(song) = value
                && truthy(query(call, song, "HasBanner")?)
                && let Value::String(text) = query(call, song, "GetBannerPath")?
            {
                path = Some(String::from_utf8_lossy(call.string_bytes(text).unwrap()).into_owned());
            }
            let path = match path.filter(|p| !p.is_empty()) {
                Some(path) => path,
                None => crate::blank_texture::load_native_blank_texture()
                    .map_err(|e| call.error(e.as_bytes()))?
                    .to_owned(),
            };
            let value = call.try_intern(path.as_bytes())?;
            call.with_roots(&[value], |call| {
                sprites::load(call, store, actor, value, false)
            })?;
            reset_scrolling(call, actor)?;
        }
        "LoadFromCourse" | "LoadFromSongBackground" => {
            let methods = if name == "LoadFromCourse" {
                &["GetBannerPath", "GetBackgroundPath"][..]
            } else {
                &["GetBackgroundPath"][..]
            };
            from_methods(call, store, actor, value, methods)?;
        }
        "LoadFromSongGroup" => {
            let group = render::text(call, value).unwrap_or("").to_owned();
            let globals = table(call, helper(call, 5)?)?;
            let manager = field(call, globals, "SONGMAN")?;
            if manager == Value::Nil {
                return call.push(Value::Table(actor));
            }
            call.with_roots(&[manager], |call| {
                let manager = table(call, manager)?;
                let function = field(call, manager, "GetSongGroupBannerPath")?;
                if function == Value::Nil {
                    return Ok(());
                }
                if !matches!(function, Value::Function(_) | Value::Native(_)) {
                    return Err(call.error(b"GetSongGroupBannerPath must be a function"));
                }
                let result = call.with_roots(&[function], |call| {
                    let group = call.try_intern(group.as_bytes())?;
                    Ok(call
                        .call(function, &[Value::Table(manager), group])?
                        .first()
                        .copied()
                        .unwrap_or(Value::Nil))
                })?;
                let loaded = if matches!(result, Value::String(_)) {
                    let path = assets::text(call, result)?;
                    set_path(call, store, actor, &path)?
                } else {
                    false
                };
                if !loaded {
                    set_path(
                        call,
                        store,
                        actor,
                        &crate::theme_path("G", "Banner", "group fallback"),
                    )?;
                }
                reset_scrolling(call, actor)
            })?;
        }
        "LoadFromSortOrder" => {
            let sort = render::text(call, value).unwrap_or("SortOrder_Invalid");
            if let Some(path) = crate::banner_sort_order_path(sort) {
                set_path(call, store, actor, &path)?;
            }
            reset_scrolling(call, actor)?;
        }
        "LoadIconFromCharacter"
        | "LoadCardFromCharacter"
        | "LoadBannerFromUnlockEntry"
        | "LoadBackgroundFromUnlockEntry" => {
            let method = match name {
                "LoadIconFromCharacter" => "GetIconPath",
                "LoadCardFromCharacter" => "GetCardPath",
                "LoadBannerFromUnlockEntry" => "GetBannerFile",
                _ => "GetBackgroundFile",
            };
            if !from_methods(call, store, actor, value, &[method])? {
                set_path(
                    call,
                    store,
                    actor,
                    &crate::theme_path("G", "Common", "fallback banner"),
                )?;
            }
            reset_scrolling(call, actor)?;
        }
        "SetScrolling" => {
            let percent = float_scalar(call, arg(call, 2), false).unwrap_or(0.0);
            set(
                call,
                actor,
                "__songlua_state_banner_scrolling",
                Value::Boolean(truthy(value)),
            )?;
            set(
                call,
                actor,
                "__songlua_state_banner_scroll_percent",
                Value::Number(percent as f64),
            )?;
        }
        "GetScrolling" => {
            let value = field(call, actor, "__songlua_state_banner_scrolling")?;
            return call.push(Value::Boolean(truthy(value)));
        }
        "GetPercentScrolling" => {
            let value = field(call, actor, "__songlua_state_banner_scroll_percent")?;
            let percent = if value == Value::Nil {
                0.0
            } else {
                sprites::number(call, value)? as f32
            };
            return call.push(Value::Number(percent as f64));
        }
        "position" => return sprites::method(call, store, actor, "SetSecondsIntoAnimation"),
        "loop" | "rate" => sprites::texture_parameter(call, store, actor, name, value)?,
        _ => unreachable!(),
    }
    call.push(Value::Table(actor))
}

//! Constructor and startup command capture, before compiler frame replay.
//! This is song-host scheduling state, not part of the Lua interpreter.
use super::*;
use crate::{SongLuaOverlayCommandBlock as Block, SongLuaOverlayStateDelta as Delta};

/// Owned command output and queue metadata for preparation/baking. These values
/// retain no Lua handles. Step zero denotes direct or immediate capture output.
#[derive(Clone, Debug, PartialEq)]
pub struct ActorCommandCapture {
    pub blocks: Vec<Block>,
    pub block_steps: Vec<usize>,
    /// A command occupies a zero-duration queue state, represented by None.
    pub steps: Vec<Option<f32>>,
    pub queued_commands: Vec<(Vec<u8>, f32)>,
}

#[derive(Clone)]
struct Entry {
    changed: bool,
    block: Block,
    tween_step: usize,
}

#[derive(Clone)]
struct Spin {
    current: [f32; 3],
    queued: bool,
}

#[derive(Clone, Default)]
pub(super) struct Capture {
    cursor: f32,
    pub(super) time_left: f32,
    current: Option<Entry>,
    blocks: Vec<Entry>,
    // Finish replaces the block list without replacing native's cached
    // immediate block. None as the index represents that detached block.
    immediate: Option<(f32, Option<usize>)>,
    steps: VecDeque<Option<f32>>,
    pending: VecDeque<(Vec<u8>, f32)>,
    /// A self-queue describes a repeating command; it must not recurse during
    /// discovery. Frame scheduling will consume this retained command later.
    pub(super) recurring: recurring::State,
    queue_error_reported: bool,
    active_start: f32,
    active_exact: f64,
    spin: Option<Spin>,
    deferred: bool,
}

fn block(start: f32, duration: f32, easing: Option<String>, queued: bool) -> Block {
    Block {
        progress: None,
        queued,
        start,
        duration,
        easing,
        opt1: None,
        opt2: None,
        delta: Delta::default(),
    }
}

impl Capture {
    pub(super) fn begin_discovery(&mut self) {
        self.flush();
        self.blocks.clear();
        self.immediate = None;
    }

    pub(super) fn snapshot(&mut self) -> ActorCommandCapture {
        let blocks = self.blocks();
        ActorCommandCapture {
            blocks,
            block_steps: self.blocks.iter().map(|entry| entry.tween_step).collect(),
            steps: self.steps.iter().copied().collect(),
            queued_commands: self.pending.iter().cloned().collect(),
        }
    }

    pub(super) fn cursor(&self) -> f32 {
        self.cursor
    }

    pub(super) fn pending_steps(&self) -> usize {
        self.steps.len()
    }

    fn scheduled(&self) -> bool {
        self.cursor.max(0.) > f32::EPSILON
            || self
                .current
                .as_ref()
                .is_some_and(|entry| entry.block.duration.max(0.) > f32::EPSILON)
    }

    fn cancel(&mut self, finish: bool) {
        self.flush();
        if finish {
            let mut delta = Delta::default();
            for entry in &self.blocks {
                crate::merge_overlay_delta(&mut delta, &entry.block.delta);
            }
            self.blocks.clear();
            if !crate::overlay_delta_is_empty(&delta) {
                let mut final_block = block(0., 0., None, false);
                final_block.delta = delta;
                self.blocks.push(Entry {
                    changed: false,
                    block: final_block,
                    tween_step: 0,
                });
            }
            self.immediate = self.immediate.map(|(start, _)| (start, None));
        } else {
            self.blocks
                .retain(|entry| entry.tween_step == 0 && entry.block.duration == 0.);
            self.immediate = None;
        }
        self.cursor = 0.;
        self.time_left = 0.;
        self.steps.clear();
        self.pending.clear();
        self.recurring.command = None;
        self.recurring.remaining = None;
        self.deferred = false;
    }

    pub(super) fn hurry(&mut self, factor: f32) {
        self.flush();
        for entry in &mut self.blocks {
            entry.block.start *= factor;
            entry.block.duration *= factor;
        }
        for seconds in self.steps.iter_mut().flatten() {
            *seconds *= factor;
        }
        self.cursor *= factor;
        self.time_left *= factor;
        self.active_exact *= f64::from(factor);
        if let Some(left) = &mut self.recurring.remaining {
            *left *= f64::from(factor);
        }
        if let Some((start, Some(_))) = &mut self.immediate {
            *start *= factor;
        }
        // Queue dispatch starts are separate from the scaled tween clocks;
        // the production constructor retains those original starts as well.
    }

    fn current(&mut self, queued: bool) -> &mut Entry {
        self.current.get_or_insert_with(|| Entry {
            changed: false,
            block: block(self.cursor, 0., None, queued),
            tween_step: self.steps.len(),
        })
    }

    pub(super) fn mark_current_changed(&mut self, queued: bool) {
        self.current(queued).changed = true;
    }

    pub(super) fn flush(&mut self) {
        if let Some(entry) = self.current.take() {
            self.cursor = entry.block.start + entry.block.duration.max(0.);
            if entry.changed || !crate::overlay_delta_is_empty(&entry.block.delta) {
                self.blocks.push(entry);
            }
        }
    }

    pub(super) fn exact_step(&mut self, duration: f64) {
        self.active_exact += duration;
    }

    pub(super) fn reset_command(&mut self) {
        self.reset_blocks();
        self.steps.clear();
    }

    // Compiler probes replace capture history, preserving semantic queues.
    pub(super) fn reset_blocks(&mut self) {
        self.cursor = 0.;
        self.time_left = 0.;
        self.current = None;
        self.blocks.clear();
        self.immediate = None;
    }

    pub(super) fn begin_tween(&mut self, duration: f32, easing: &str, queued: bool) {
        self.flush();
        if let Some(spin) = &mut self.spin {
            spin.queued = true;
        }
        self.steps.push_back(Some(duration));
        self.time_left = self.cursor + duration;
        self.current = Some(Entry {
            changed: false,
            block: block(self.cursor, duration, Some(easing.to_owned()), queued),
            tween_step: self.steps.len(),
        });
    }

    pub(super) fn write(&mut self, delta: Delta, immediate: bool, scope: Option<f32>) {
        let start = scope.unwrap_or(0.);
        let direct = start == 0.
            && self.cursor == 0.
            && self.current.as_ref().is_none_or(|c| c.block.duration == 0.)
            && self.steps.is_empty();
        let target = if !immediate || direct {
            &mut self.current(scope.is_some()).block.delta
        } else {
            let index = if let Some((_, index)) = self
                .immediate
                .filter(|(cached, _)| (*cached - start).abs() <= f32::EPSILON)
            {
                let Some(index) = index else { return };
                index
            } else {
                let index = self
                    .blocks
                    .iter()
                    .position(|entry| {
                        entry.block.start > start
                            || (entry.block.start == start
                                && (entry.tween_step > 0 || entry.block.duration > 0.))
                    })
                    .unwrap_or(self.blocks.len());
                self.blocks.insert(
                    index,
                    Entry {
                        changed: false,
                        block: block(start, 0., None, scope.is_some()),
                        tween_step: 0,
                    },
                );
                self.immediate = Some((start, Some(index)));
                index
            };
            &mut self.blocks[index].block.delta
        };
        crate::merge_overlay_delta(target, &delta);
    }

    pub(super) fn blocks(&mut self) -> Vec<Block> {
        self.flush();
        self.blocks
            .iter()
            .map(|entry| {
                let mut block = entry.block.clone();
                block.duration = block.duration.max(0.);
                block
            })
            .collect()
    }
}

pub(super) fn write(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    delta: Delta,
    immediate: bool,
) {
    let mut guard = store.lock().unwrap();
    let scope = guard.capture_scope;
    let fallback = song_pose::mode(&guard, id);
    if let Some(actor) = guard.actors.get_mut(&id) {
        record(actor, &delta, immediate, scope, fallback);
    }
    drop(guard);
    if !song_pose::record(call, store, id, &delta) {
        song_messages::record(call, store, id, &delta);
    }
    song_immediate::delta(call, store, id, &delta, immediate);
    song_media::delta(call, store, id, &delta);
}

/// Frame publication also supplies command blocks during construction/probes.
/// Capture::write already retains its delta, so its frame path skips this hook.
pub(super) fn retain_render_update(
    store: &Shared,
    id: TableId,
    target: crate::SongLuaOverlayUpdateTarget,
    value: &crate::SongLuaOverlayUpdateValue,
    immediate: bool,
) {
    use crate::{SongLuaOverlayUpdateTarget as Target, SongLuaOverlayUpdateValue as Update};
    let mut guard = store.lock().unwrap();
    if !guard.preparing || guard.replay_frame.is_some() {
        return;
    }
    let mut delta = Delta::default();
    match (target, value) {
        (Target::Visible, Update::Bool(value)) => delta.visible = Some(*value),
        (Target::Hibernating, Update::Bool(value)) => delta.hibernating = Some(*value),
        (Target::HAlign, Update::F32(value)) => delta.halign = Some(*value),
        (Target::VAlign, Update::F32(value)) => delta.valign = Some(*value),
        (Target::TextAlign, Update::TextAlign(value)) => delta.text_align = Some(*value),
        (Target::BaseZoom, Update::F32(value)) => delta.basezoom = Some(*value),
        (Target::BaseZoomX, Update::F32(value)) => delta.basezoom_x = Some(*value),
        (Target::BaseZoomY, Update::F32(value)) => delta.basezoom_y = Some(*value),
        (Target::BaseZoomZ, Update::F32(value)) => delta.basezoom_z = Some(*value),
        (Target::BaseAlpha, Update::F32(value)) => delta.base_alpha = Some(*value),
        (Target::BaseRotation, Update::Vec3(value)) => delta.base_rotation = Some(*value),
        (Target::ShadowLen, Update::Vec2(value)) => delta.shadow_len = Some(*value),
        (Target::ShadowColor, Update::Vec4(value)) => delta.shadow_color = Some(*value),
        (Target::Size, Update::Vec2(value)) => delta.size = Some(*value),
        (Target::SpriteTexture, Update::Bool(value)) => delta.sprite_texture = Some(*value),
        (Target::SpriteStateIndex, Update::U32(value)) => delta.sprite_state_index = Some(*value),
        (Target::Vibrate, Update::Bool(value)) => delta.vibrate = Some(*value),
        (Target::Rainbow, Update::Bool(value)) => delta.rainbow = Some(*value),
        (Target::EffectMode, Update::EffectMode(value)) => delta.effect_mode = Some(*value),
        (Target::EffectPeriod, Update::F32(value)) => delta.effect_period = Some(*value),
        (Target::EffectTiming, Update::Vec5(value)) => delta.effect_timing = Some(*value),
        (Target::EffectMagnitude, Update::Vec3(value)) => delta.effect_magnitude = Some(*value),
        (Target::EffectColor1, Update::Vec4(value)) => delta.effect_color1 = Some(*value),
        (Target::EffectColor2, Update::Vec4(value)) => delta.effect_color2 = Some(*value),
        (Target::EffectOffset, Update::F32(value)) => delta.effect_offset = Some(*value),
        (Target::EffectClock, Update::EffectClock(value)) => delta.effect_clock = Some(*value),
        (Target::EffectNoOffset, Update::Bool(value)) => delta.effect_no_offset = Some(*value),
        (Target::EffectTimer, Update::Bool(value)) => delta.effect_timer = Some(*value),
        (Target::CullMode, Update::CullMode(value)) => delta.cull_mode = Some(*value),
        (Target::AftPreserve, Update::Bool(value)) => delta.aft_preserve = Some(*value),
        (Target::AftCreated, Update::Bool(value)) => delta.aft_created = Some(*value),
        (Target::ZBias, Update::F32(value)) => delta.z_bias = Some(*value),
        (Target::DrawOrder, Update::I32(value)) => delta.draw_order = Some(*value),
        (Target::DrawByZPosition, Update::Bool(value)) => delta.draw_by_z_position = Some(*value),
        (Target::Fov, Update::F32(value)) => delta.fov = Some(*value),
        (Target::Vanishpoint, Update::Vec2(value)) => delta.vanishpoint = Some(*value),
        (Target::Blend, Update::Blend(value)) => delta.blend = Some(*value),
        (Target::DepthTest, Update::Bool(value)) => delta.depth_test = Some(*value),
        (Target::DepthTestOnFail, Update::Bool(value)) => delta.depth_test_on_fail = Some(*value),
        (Target::DepthWrite, Update::Bool(value)) => delta.depth_write = Some(*value),
        (Target::TextureFiltering, Update::Bool(value)) => delta.texture_filtering = Some(*value),
        _ => return,
    }
    let scope = guard.capture_scope;
    let fallback = song_pose::mode(&guard, id);
    if let Some(actor) = guard.actors.get_mut(&id) {
        record(actor, &delta, immediate, scope, fallback);
    }
}

fn record(actor: &mut Actor, delta: &Delta, immediate: bool, scope: Option<f32>, fallback: bool) {
    if let Some(replay) = &mut actor.replay {
        for target in crate::tween_pose::TARGETS {
            if delta.has_update_target(target) {
                replay.targets |= 1u128 << target as usize;
            }
        }
    }
    if let Some(pose) = actor
        .replay
        .as_mut()
        .and_then(|replay| replay.getters.as_mut())
    {
        let mut state = crate::SongLuaOverlayState::default();
        pose.write_to(&mut state);
        crate::apply_overlay_delta(&mut state, delta);
        *pose = state.into();
    }
    if actor.replay.is_some() && !fallback {
        let current = actor.current;
        if let Some(getters) = &mut actor.preparation_getters {
            for ((getter, changed), value) in getters
                .iter_mut()
                .zip([delta.x, delta.y, delta.z, delta.aux])
                .zip([current.x, current.y, current.z, current.aux])
            {
                if changed.is_some() {
                    *getter = value;
                }
            }
        }
    }
    let Some(capture) = &mut actor.capture else {
        return;
    };
    if let Some(spin) = &mut capture.spin
        && !spin.queued
    {
        for (axis, value) in
            spin.current
                .iter_mut()
                .zip([delta.rot_x_deg, delta.rot_y_deg, delta.rot_z_deg])
        {
            if let Some(value) = value {
                *axis = value;
            }
        }
    }
    // Zero-duration construction steps do not defer current-position getters.
    // These fields are independent of the retained destination/spin queue.
    if !capture.scheduled() && !fallback {
        let values = [delta.x, delta.y, delta.z, delta.aux];
        if values.iter().any(Option::is_some) {
            let current = actor.current;
            let getters = actor.preparation_getters.get_or_insert([
                current.x,
                current.y,
                current.z,
                current.aux,
            ]);
            for (getter, value) in getters.iter_mut().zip(values) {
                if let Some(value) = value {
                    *getter = value;
                }
            }
        }
    }
    capture.write(*delta, immediate, scope);
}

pub(super) fn cancel(actor: &mut Actor, finish: bool) -> bool {
    if actor.capture.is_none() {
        return false;
    }
    let current = actor.current;
    let getters =
        actor
            .preparation_getters
            .unwrap_or([current.x, current.y, current.z, current.aux]);
    let mut dest = *actor.destination();
    if !finish {
        [dest.x, dest.y, dest.z] = [getters[0], getters[1], getters[2]];
    }
    if let Some(spin) = &mut actor.capture.as_mut().unwrap().spin {
        if finish {
            spin.current = [dest.rot_x_deg, dest.rot_y_deg, dest.rot_z_deg];
        }
        [dest.rot_x_deg, dest.rot_y_deg, dest.rot_z_deg] = spin.current;
        spin.queued = false;
    }
    actor.capture.as_mut().unwrap().cancel(finish);
    actor.current = dest;
    actor.queue.clear();
    actor.sync_rotation_getters();
    actor.preparation_getters = Some(getters);
    true
}

pub(super) fn start_spin(actor: &mut Actor) {
    let pose = *actor.destination();
    if let Some(capture) = &mut actor.capture {
        capture.spin.get_or_insert(Spin {
            current: [pose.rot_x_deg, pose.rot_y_deg, pose.rot_z_deg],
            queued: false,
        });
    }
}

/// Record an actual successful write, including writes equal to the old value.
/// Comparing snapshots would lose those writes and change later composition.
pub(super) fn property(call: &mut HostCall<'_>, store: &Shared, id: TableId, name: &str) {
    let mut guard = store.lock().unwrap();
    let fallback = song_pose::mode(&guard, id);
    let scope = guard.capture_scope;
    let immediate_visibility = scope.is_some()
        || guard.startup_queues.is_some()
        || guard.startup_discovery
        || guard.replay_frame.is_some();
    let actor = guard.actors.get_mut(&id).unwrap();
    if actor.capture.is_none() && actor.replay.is_none() {
        return;
    }
    let pose = actor.destination();
    let state = &actor.state;
    let render = &state.render;
    let mut delta = Delta::default();
    let mut immediate = false;
    match name {
        "x" | "addx" | "CenterX" => delta.x = Some(pose.x),
        "y" | "addy" | "CenterY" => delta.y = Some(pose.y),
        "z" | "addz" => delta.z = Some(pose.z),
        "Center" => {
            delta.x = Some(pose.x);
            delta.y = Some(pose.y);
        }
        "zoom" => {
            delta.zoom = Some(pose.zoom);
            delta.zoom_x = Some(pose.zoom_x);
            delta.zoom_y = Some(pose.zoom_y);
            delta.zoom_z = Some(pose.zoom_z);
        }
        "zoomx" | "zoomtowidth" => delta.zoom_x = Some(pose.zoom_x),
        "zoomy" | "zoomtoheight" => delta.zoom_y = Some(pose.zoom_y),
        "zoomz" => delta.zoom_z = Some(pose.zoom_z),
        "zoomto" => {
            delta.zoom_x = Some(pose.zoom_x);
            delta.zoom_y = Some(pose.zoom_y);
        }
        "scaletofit" | "scaletocover" => {
            delta.x = Some(pose.x);
            delta.y = Some(pose.y);
            delta.zoom = Some(pose.zoom);
            delta.zoom_x = Some(pose.zoom_x);
            delta.zoom_y = Some(pose.zoom_y);
            delta.zoom_z = Some(pose.zoom_z);
        }
        "stretchto" => {
            delta.x = Some(pose.x);
            delta.y = Some(pose.y);
            delta.zoom_x = Some(pose.zoom_x);
            delta.zoom_y = Some(pose.zoom_y);
        }
        "rotationx" | "addrotationx" => delta.rot_x_deg = Some(pose.rot_x_deg),
        "rotationy" | "addrotationy" => delta.rot_y_deg = Some(pose.rot_y_deg),
        "rotationz" | "addrotationz" => delta.rot_z_deg = Some(pose.rot_z_deg),
        "aux" => delta.aux = Some(pose.aux),
        "visible" => {
            delta.visible = Some(state.visible);
            immediate = immediate_visibility;
        }
        "draworder" => delta.draw_order = Some(state.draw_order),
        "size" | "SetWidth" | "SetHeight" | "setsize" => {
            delta.size = Some(state.size);
            immediate = true;
        }
        "diffuse" | "diffusecolor" | "diffusealpha" => delta.diffuse = Some(pose.diffuse),
        "glow" => delta.glow = Some(pose.glow),
        "vertex_colors" => delta.vertex_colors = pose.vertex_colors,
        "cropleft" => delta.cropleft = Some(pose.cropleft),
        "cropright" => delta.cropright = Some(pose.cropright),
        "croptop" => delta.croptop = Some(pose.croptop),
        "cropbottom" => delta.cropbottom = Some(pose.cropbottom),
        "fadeleft" => delta.fadeleft = Some(pose.fadeleft),
        "faderight" => delta.faderight = Some(pose.faderight),
        "fadetop" => delta.fadetop = Some(pose.fadetop),
        "fadebottom" => delta.fadebottom = Some(pose.fadebottom),
        "skewx" => delta.skew_x = Some(pose.skew_x),
        "skewy" => delta.skew_y = Some(pose.skew_y),
        "heading" | "pitch" | "roll" => delta.quaternion = Some(pose.quaternion),
        "halign" => {
            delta.halign = Some(render.halign);
            immediate = true;
        }
        "valign" => {
            delta.valign = Some(render.valign);
            immediate = true;
        }
        // Immediate renderer/base-transform properties do not join a tween.
        "basealpha" => {
            delta.base_alpha = Some(render.base_alpha);
            immediate = true;
        }
        "basezoom" => {
            delta.basezoom = Some(render.basezoom);
            delta.basezoom_x = Some(render.basezoom_x);
            delta.basezoom_y = Some(render.basezoom_y);
            delta.basezoom_z = Some(render.basezoom_z);
            immediate = true;
        }
        "basezoomx" => {
            delta.basezoom_x = Some(render.basezoom_x);
            immediate = true;
        }
        "basezoomy" => {
            delta.basezoom_y = Some(render.basezoom_y);
            immediate = true;
        }
        "basezoomz" => {
            delta.basezoom_z = Some(render.basezoom_z);
            immediate = true;
        }
        "baserotationx" | "baserotationy" | "baserotationz" => {
            delta.base_rotation = Some(render.base_rotation);
            immediate = true;
        }
        "shadowlength" | "shadowlengthx" | "shadowlengthy" => {
            delta.shadow_len = Some(render.shadow_len);
            immediate = true;
        }
        "shadowcolor" => {
            delta.shadow_color = Some(render.shadow_color);
            immediate = true;
        }
        "zbias" => delta.z_bias = Some(render.z_bias),
        "fov" => delta.fov = render.fov,
        _ => return,
    }
    record(actor, &delta, immediate, scope, fallback);
    drop(guard);
    if !song_pose::record(call, store, id, &delta) {
        song_messages::record(call, store, id, &delta);
    }
    song_immediate::delta(call, store, id, &delta, immediate);
    song_media::delta(call, store, id, &delta);
}

// Once a fallback actor queues during an update, that queue belongs to frame
// advancement. Captured commands outside the update instead drain synchronously.
pub(super) fn enter_replay_queue(store: &Shared, actor: TableId) {
    let mut guard = store.lock().unwrap();
    // Full-timeline preparation retains its fallback capture and command queue.
    // Streamed preparation continues to use the ordinary queue below.
    if guard.replay_clock.is_some() {
        return;
    }
    if guard.replay_frame.is_some() && guard.replay_advancing {
        let actor = guard.actors.get_mut(&actor).unwrap();
        if actor
            .capture
            .as_ref()
            .is_some_and(|c| c.recurring.command.is_some() || c.recurring.running)
        {
            return;
        }
        if actor.capture.take().is_some() {
            // Captured steps have already emitted their timed publications.
            // The first update-created queue starts its own clock; those old
            // durations must not postpone commands queued by this callback.
            actor.queue.clear();
        }
    }
}

pub(super) fn queue(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: Vec<u8>,
) -> Result<bool, Error> {
    action_capture::prepare(call, store, actor)?;
    enter_replay_queue(store, actor);
    let mut command_field = name.clone();
    command_field.extend_from_slice(b"Command");
    let overflow = {
        let guard = store.lock().unwrap();
        let target = &guard.actors[&actor];
        !target.active_commands.contains(&command_field)
            && target.capture.as_ref().is_some_and(|capture| {
                guard
                    .replay_clock
                    .as_ref()
                    .and_then(|clock| clock.queue_len(actor))
                    .unwrap_or_else(|| capture.pending_steps())
                    > 50
            })
    };
    if overflow {
        lifecycle::finish(call, store, actor)?;
    }
    let full_capture = {
        let guard = store.lock().unwrap();
        guard.replay_clock.is_some() && guard.actors[&actor].capture.is_some()
    };
    if full_capture {
        song_messages::timing(call, actor, 0., None)?;
    }
    let drain = {
        let mut guard = store.lock().unwrap();
        let startup = guard.startup_queues.is_some();
        let self_queue = guard.actors[&actor]
            .active_commands
            .contains(&command_field);
        if guard.actors[&actor].capture.is_some()
            && let Some(clock) = &mut guard.replay_clock
        {
            if self_queue {
                clock.flush(actor);
            } else {
                clock.tween(actor, None);
            }
        }
        let actor = guard.actors.get_mut(&actor).unwrap();
        let Some(capture) = &mut actor.capture else {
            return Ok(false);
        };
        capture.flush();
        let mut field = name.clone();
        field.extend_from_slice(b"Command");
        if actor.active_commands.contains(&field) {
            let interval = if capture.active_exact > f64::EPSILON {
                capture.active_exact
            } else {
                f64::from((capture.cursor - capture.active_start).max(0.))
            };
            capture.recurring.command = Some(name);
            if interval > f64::EPSILON {
                capture.recurring.interval = interval;
            }
            return Ok(true);
        }
        capture.steps.push_back(None);
        capture.pending.push_back((name, capture.cursor));
        startup || actor.active_commands.is_empty()
    };
    if store.lock().unwrap().replay_frame.is_some() {
        song_messages::timing(call, actor, 0., None)?;
    }
    if drain {
        drain_commands(call, store, actor)?;
    }
    Ok(true)
}

pub(super) fn advance_ready(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let ready = {
        let guard = store.lock().unwrap();
        guard.actors[&actor].registered
            && guard
                .replay_clock
                .as_ref()
                .is_some_and(|clock| clock.ready(actor))
    };
    if !ready {
        return Ok(());
    }
    match drain_commands(call, store, actor) {
        Err(error) if error.kind() == ErrorKind::Runtime => {
            let mut guard = store.lock().unwrap();
            let Some(capture) = guard
                .actors
                .get_mut(&actor)
                .and_then(|a| a.capture.as_mut())
            else {
                return Ok(());
            };
            if !capture.queue_error_reported {
                capture.queue_error_reported = true;
                guard.diagnostics.push(format!("update queue: {error}"));
            }
            Ok(())
        }
        result => result,
    }
}

pub(super) fn drain_commands(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    {
        let mut guard = store.lock().unwrap();
        let pending = guard
            .actors
            .get(&actor)
            .and_then(|actor| actor.capture.as_ref())
            .is_some_and(|capture| !capture.pending.is_empty());
        if let Some(queued) = &mut guard.startup_queues {
            if pending && !queued.contains(&actor) {
                queued.push(actor);
            }
            return Ok(());
        }
    }
    loop {
        let (next, clock_time) = {
            let mut guard = store.lock().unwrap();
            if !guard
                .actors
                .get(&actor)
                .and_then(|a| a.capture.as_ref())
                .is_some_and(|c| !c.pending.is_empty())
            {
                return Ok(());
            }
            let mut time = None;
            if let Some(clock) = &mut guard.replay_clock {
                clock.prime(actor);
                if clock.waiting(actor) {
                    return Ok(());
                }
                time = clock.pending_dispatch(actor);
            }
            let discovery = guard.startup_discovery;
            let full = guard.replay_clock.is_some();
            let capture = guard
                .actors
                .get_mut(&actor)
                .unwrap()
                .capture
                .as_mut()
                .unwrap();
            let (name, start) = capture.pending.front().unwrap();
            if !full && (discovery || capture.deferred) && (name.starts_with(b"!") || *start > 0.) {
                capture.deferred = true;
                return Ok(());
            }
            let next = capture.pending.pop_front().unwrap();
            while let Some(step) = capture.steps.pop_front() {
                if step.is_none() {
                    break;
                }
            }
            (next, time)
        };
        let (name, captured_start) = next;
        let start = if clock_time.is_some() {
            0.
        } else {
            captured_start
        };
        let (prior, previous_dispatch, previous_clock, was_recurring, remainder, cursor) = {
            let mut guard = store.lock().unwrap();
            let mut previous_clock = guard.replay_clock.as_ref().and_then(|c| c.dispatch);
            let mut seconds = None;
            let mut cursor = None;
            if let Some(clock) = &mut guard.replay_clock {
                if clock_time.is_some() {
                    previous_clock = clock.dispatched(actor, 0.);
                    seconds = clock.dispatch.map(|scope| clock.time(scope.frame));
                    cursor = Some(clock.cursor(actor));
                } else {
                    clock.dispatch = None;
                }
            }
            let capture = guard
                .actors
                .get_mut(&actor)
                .unwrap()
                .capture
                .as_mut()
                .unwrap();
            if let Some(cursor) = cursor {
                capture.flush();
                capture.cursor = cursor;
            }
            let was_recurring = capture.recurring.command.is_some();
            let prior = guard.capture_scope.replace(start);
            let dispatch = guard.replay_dispatch;
            if guard.replay_frame.is_some() {
                guard.replay_dispatch = Some(song_immediate::Dispatch {
                    seconds,
                    delay: start,
                });
            }
            (
                prior,
                dispatch,
                previous_clock,
                was_recurring,
                clock_time.map(|t| t.1 as f32),
                cursor,
            )
        };
        if let Some(cursor) = cursor {
            let result = (|| {
                song_messages::timing(call, actor, 0., None)?;
                song_replay::raw_set(
                    call,
                    actor,
                    "__songlua_capture_cursor",
                    Value::Number(f64::from(cursor)),
                )
            })();
            if let Err(error) = result {
                let mut guard = store.lock().unwrap();
                guard.capture_scope = prior;
                guard.replay_dispatch = previous_dispatch;
                if let Some(clock) = &mut guard.replay_clock {
                    clock.dispatch = previous_clock;
                }
                return Err(error);
            }
        }
        // The registry and this lexical root retain the dispatch target even
        // when its command edits the scene and forces a collection.
        let result = call.with_roots(&[Value::Table(actor)], |call| {
            if let Some(message) = name.strip_prefix(b"!") {
                messages::queued(call, store, message)
            } else {
                let mut field = name.clone();
                field.extend_from_slice(b"Command");
                let previous = store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .active_commands
                    .remove(&field);
                let result = dispatch(call, store, actor, &name);
                if previous {
                    store
                        .lock()
                        .unwrap()
                        .actors
                        .get_mut(&actor)
                        .unwrap()
                        .active_commands
                        .insert(field);
                }
                result
            }
        });
        {
            let mut guard = store.lock().unwrap();
            guard.capture_scope = prior;
            guard.replay_dispatch = previous_dispatch;
            if let Some(clock) = &mut guard.replay_clock {
                clock.dispatch = previous_clock;
            }
        }
        result?;
        song_pose::advance_position(call, store, actor)?;
        let recurring = store
            .lock()
            .unwrap()
            .actors
            .get(&actor)
            .and_then(|a| a.capture.as_ref())
            .is_some_and(|c| c.recurring.command.is_some());
        if !was_recurring
            && recurring
            && let Some(remainder) = remainder
        {
            recurring::advance(call, store, actor, remainder)?;
            if let Some(clock) = &mut store.lock().unwrap().replay_clock {
                clock.mark_recurring(actor);
            }
        }
    }
}

fn dispatch(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
) -> Result<(), Error> {
    {
        let mut guard = store.lock().unwrap();
        let start = guard.capture_scope.unwrap_or(0.);
        if let Some(capture) = guard
            .actors
            .get_mut(&actor)
            .and_then(|a| a.capture.as_mut())
            && capture.cursor < start
        {
            capture.flush();
            capture.cursor = start;
        }
    }
    native_children::run_command(call, store, actor, name, None)?;
    let kind = sprites::field(call, actor, "__songlua_actor_type")?;
    if matches!(kind, Value::String(id) if matches!(call.string_bytes(id), Some(b"ActorFrame" | b"ActorFrameTexture" | b"TopScreen")))
    {
        native_children::with_children(call, actor, |call, child| {
            dispatch(call, store, child, name)
        })?;
    }
    Ok(())
}

pub(super) fn command_start(store: &Shared, actor: TableId) -> Option<(f32, f64)> {
    let mut guard = store.lock().unwrap();
    let capture = guard.actors.get_mut(&actor)?.capture.as_mut()?;
    Some((
        std::mem::replace(&mut capture.active_start, capture.cursor),
        std::mem::take(&mut capture.active_exact),
    ))
}

pub(super) fn command_end(store: &Shared, actor: TableId, previous: Option<(f32, f64)>) {
    if let Some(previous) = previous
        && let Some(capture) = store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .and_then(|a| a.capture.as_mut())
    {
        (capture.active_start, capture.active_exact) = previous;
    }
}

impl Actors {
    pub(in crate::rust_engine) fn begin_preparation(&self, vm: &mut Vm) -> Result<bool, Error> {
        {
            let guard = self.store.lock().unwrap();
            if guard.preparing
                || guard.playback
                || guard.clock.live.load(std::sync::atomic::Ordering::Relaxed)
            {
                return Ok(false);
            }
        }
        let function = vm.rooted(self.prepare_definitions)?;
        vm.call(function, &[])?;
        let mut guard = self.store.lock().unwrap();
        guard.preparing = true;
        guard.constructing_capture = true;
        Ok(true)
    }

    pub(in crate::rust_engine) fn discover_startup(&self, vm: &mut Vm) -> Result<(), Error> {
        let function = vm.rooted(self.discover_startup)?;
        vm.call(function, &[])?;
        Ok(())
    }

    pub(super) fn discover_queued(&self, vm: &mut Vm, queued: Vec<TableId>) -> Result<(), Error> {
        let mut roots = vec![Value::Table(self.registry), Value::Table(self.helpers)];
        roots.extend(queued.iter().copied().map(Value::Table));
        let function = vm.new_host_function_with_data(
            |call| {
                let (store, queued) = call
                    .function_data::<(Shared, Vec<TableId>)>()
                    .unwrap()
                    .clone();
                run_discovery(call, &store, queued)
            },
            &roots,
            (self.store.clone(), queued),
        )?;
        vm.call(function, &[])?;
        Ok(())
    }

    pub(in crate::rust_engine) fn command_capture(
        &self,
        actor: Value,
    ) -> Option<ActorCommandCapture> {
        let Value::Table(actor) = actor else {
            return None;
        };
        let mut guard = self.store.lock().unwrap();
        let capture = guard.actors.get_mut(&actor)?.capture.as_mut()?;
        Some(capture.snapshot())
    }

    pub(in crate::rust_engine) fn captured_blocks(&self, actor: Value) -> Option<Vec<Block>> {
        let Value::Table(actor) = actor else {
            return None;
        };
        let mut guard = self.store.lock().unwrap();
        Some(guard.actors.get_mut(&actor)?.capture.as_mut()?.blocks())
    }
}

pub(super) fn discover_startup(call: &mut HostCall<'_>, store: &Shared) -> Result<(), Error> {
    let queued = store.lock().unwrap().startup_queues.take();
    let Some(queued) = queued else {
        return Ok(());
    };
    run_discovery(call, store, queued)
}

fn run_discovery(
    call: &mut HostCall<'_>,
    store: &Shared,
    queued: Vec<TableId>,
) -> Result<(), Error> {
    let previous = std::mem::replace(&mut store.lock().unwrap().startup_discovery, true);
    let roots = queued.iter().copied().map(Value::Table).collect::<Vec<_>>();
    let result = call.with_roots(&roots, |call| {
        for actor in queued {
            drain_commands(call, store, actor)?;
        }
        Ok(())
    });
    store.lock().unwrap().startup_discovery = previous;
    result
}

//! Command closures first reached inside an action probe, including nested scopes.
use super::*;
use crate::rust_engine::function_snapshot::Snapshot;

#[derive(Default)]
pub(in crate::rust_engine) struct Scope {
    functions: HashSet<deadlib_lua::FunctionId>,
    snapshots: Vec<Snapshot>,
}
impl Actors {
    pub(in crate::rust_engine) fn begin_command_locals(&self) -> Option<Scope> {
        self.store
            .lock()
            .unwrap()
            .command_locals
            .replace(Scope::default())
    }
    pub(in crate::rust_engine) fn restore_command_locals(
        &self,
        vm: &mut Vm,
        previous: Option<Scope>,
    ) -> Result<(), Error> {
        let current = self.store.lock().unwrap().command_locals.take().unwrap();
        if let Some(mut previous) = previous {
            // Nested stability probes let locals advance across attempts. The
            // outermost scope undoes snapshots backwards so the earliest wins.
            previous.functions.extend(current.functions);
            previous.snapshots.extend(current.snapshots);
            self.store.lock().unwrap().command_locals = Some(previous);
        } else {
            let mut snapshots = current.snapshots;
            while let Some(saved) = snapshots.pop() {
                if let Err(error) = saved.restore(vm) {
                    // The native scope drops all remaining saved handles on an
                    // early restoration error. Detach our traced roots as well.
                    for saved in snapshots.into_iter().rev() {
                        saved.discard(vm)?;
                    }
                    return Err(error);
                }
            }
        }
        Ok(())
    }
}
pub(super) fn capture(
    call: &mut HostCall<'_>,
    store: &Shared,
    function: Value,
) -> Result<(), Error> {
    let Value::Function(id) = function else {
        return Ok(());
    };
    let preserve = store
        .lock()
        .unwrap()
        .command_locals
        .as_mut()
        .is_some_and(|scope| scope.functions.insert(id));
    if preserve {
        let owner = table(call, call.captures()[0])?;
        let saved = Snapshot::capture_locals(call, owner, function)?;
        store
            .lock()
            .unwrap()
            .command_locals
            .as_mut()
            .expect("command scope remains active during snapshot")
            .snapshots
            .push(saved);
    }
    Ok(())
}

//! CourseContentsList display ownership, scroller fields and SetSong callbacks.
use super::*;
use sprites::{field, set};

pub(super) const METHODS: &[&str] = &[
    "Load",
    "SetFromGameState",
    "SetCurrentAndDestinationItem",
    "SetCurrentItem",
    "GetCurrentItem",
    "SetDestinationItem",
    "GetDestinationItem",
    "GetNumItems",
    "SetTransformFromFunction",
    "SetTransformFromHeight",
    "SetTransformFromWidth",
    "PositionItems",
    "GetSecondsToDestination",
    "SetSecondsPerItem",
    "SetLoop",
    "GetLoop",
    "SetPauseCountdownSeconds",
    "SetSecondsPauseBetweenItems",
    "GetSecondsPauseBetweenItems",
    "SetNumSubdivisions",
    "ScrollThroughAllItems",
    "ScrollWithPadding",
    "SetFastCatchup",
    "SetWrap",
    "SetMask",
    "SetNumItemsToDraw",
    "GetFullScrollLengthSeconds",
];

pub(super) fn install(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let methods = native_children::helper_function(call, b"course_methods")?;
    let methods = table(call, methods)?;
    let bound = get(call, actor, b"__songlua_bound_methods")?;
    let bound = table(call, bound)?;
    for &name in METHODS {
        let method = get(call, methods, name.as_bytes())?;
        let captures = [
            call.captures()[0],
            call.captures()[1],
            Value::Table(actor),
            method,
        ];
        let function = call.new_host_function_with_data(invoke_bound, &captures, name)?;
        set(call, bound, name, function)?;
    }
    Ok(())
}

pub(super) fn initialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
) -> Result<(), Error> {
    for (key, value) in [
        ("current_item", 0.),
        ("destination_item", 0.),
        ("num_items", 1.),
    ] {
        put(call, actor, key, Value::Number(value))?;
    }
    let display = field(call, actor, "Display")?;
    if display == Value::Nil {
        return Ok(());
    }
    let display = table(call, display)?;
    let name = field(call, display, "Name")?;
    if name == Value::Nil {
        let name = call.try_intern(b"Display")?;
        set(call, display, "Name", name)?;
    } else {
        assets::text(call, name)?;
    }
    native_children::adopt(call, store, display, actor)?;
    if store.lock().unwrap().actors[&actor].offline_instance
        || get(call, display, b"Condition")? != Value::Boolean(false)
    {
        attach(call, store, scene, display)?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .children
            .push(display);
        let len = call.raw_table_len(actor)?;
        let mut present = false;
        for i in 1..=len {
            present |= call.raw_table_get(actor, Value::Number(i as f64))? == Value::Table(display);
        }
        if !present {
            call.raw_table_set(
                actor,
                Value::Number((len + 1) as f64),
                Value::Table(display),
            )?;
        }
    }
    Ok(())
}

// The production constructor appends Display itself, including a plain Def
// table. Track it without adding instance methods or replacing its metatable.
pub(super) fn attach(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
) -> Result<(), Error> {
    {
        let guard = store.lock().unwrap();
        let actors = &guard.scenes[&scene].actors;
        if actors.contains(&actor) {
            return Ok(());
        }
    }
    if store.lock().unwrap().actors.contains_key(&actor) {
        if store.lock().unwrap().retired_scenes.contains_key(&scene) {
            let registry = table(call, call.captures()[0])?;
            retirement::retain(call, store, scene, actor, registry)?;
        }
        store
            .lock()
            .unwrap()
            .scenes
            .get_mut(&scene)
            .unwrap()
            .actors
            .push(actor);
        if !store.lock().unwrap().actors[&actor].initialized {
            let name = get(call, actor, b"Name")?;
            if matches!(name, Value::Number(_) | Value::String(_)) {
                let name = bytes(call, name)?;
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .load_name = Some(name);
            }
        }
        let mut descendants = children(call, store, actor)?;
        descendants.extend(
            store.lock().unwrap().actors[&actor]
                .wrappers
                .iter()
                .copied(),
        );
        for child in descendants {
            attach(call, store, scene, child)?;
        }
        return Ok(());
    }
    let name = get(call, actor, b"Name")?;
    let name = if matches!(name, Value::Number(_) | Value::String(_)) {
        Some(bytes(call, name)?)
    } else {
        None
    };
    let mut instance = Actor::new(scene, "Actor", None, name);
    instance.raw_instance = true;
    instance.initialized = boolean(call, actor, "__songlua_init_commands_ran")?;
    instance.started = boolean(call, actor, "__songlua_startup_commands_ran")?;
    if instance.initialized {
        let name = get(call, actor, b"__songlua_native_name")?;
        if matches!(name, Value::Number(_) | Value::String(_)) {
            instance.state.name = bytes(call, name)?;
        }
    }
    instance.registered = instance.initialized;
    let registry = table(call, call.captures()[0])?;
    retirement::retain(call, store, scene, actor, registry)?;
    store.lock().unwrap().actors.insert(actor, instance);
    store
        .lock()
        .unwrap()
        .scenes
        .get_mut(&scene)
        .unwrap()
        .actors
        .push(actor);
    refresh_raw_children(call, store, actor, false)
}

pub(super) fn refresh_raw_children(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    compact: bool,
) -> Result<(), Error> {
    let selected = call.call(helper(call, 10)?, &[Value::Table(actor)])?[0];
    call.with_roots(&[selected], |call| {
        let selected = table(call, selected)?;
        let owners: Vec<_> = store
            .lock()
            .unwrap()
            .scenes
            .iter()
            .filter_map(|(id, scene)| scene.actors.contains(&actor).then_some(*id))
            .collect();
        let mut children = Vec::new();
        for i in 1..=call.raw_table_len(selected)? {
            let child = table(call, call.raw_table_get(selected, Value::Number(i as f64))?)?;
            for &scene in &owners {
                attach(call, store, scene, child)?;
            }
            children.push(child);
        }
        if compact {
            let entries = call.call(helper(call, 7)?, &[Value::Table(actor)])?[0];
            call.with_roots(&[entries], |call| {
                let entries = table(call, entries)?;
                for i in 1..=call.raw_table_len(entries)? {
                    let pair = table(call, call.raw_table_get(entries, Value::Number(i as f64))?)?;
                    let key = call.raw_table_get(pair, Value::Number(1.))?;
                    if matches!(key, Value::Number(n) if n >= 1. && n.fract()==0.) {
                        call.raw_table_set(actor, key, Value::Nil)?;
                    }
                }
                Ok(())
            })?;
            for (i, child) in children.iter().enumerate() {
                call.raw_table_set(actor, Value::Number((i + 1) as f64), Value::Table(*child))?;
            }
        }
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .children = children;
        Ok(())
    })
}

pub(super) fn prepare_raw_init(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    if !store.lock().unwrap().actors[&actor].raw_instance {
        return Ok(());
    }
    let initialized = boolean(call, actor, "__songlua_init_commands_ran")?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .initialized = initialized;
    if initialized {
        return Ok(());
    }
    refresh_raw_children(call, store, actor, true)?;
    let name = get(call, actor, b"Name")?;
    let name = if matches!(name, Value::Number(_) | Value::String(_)) {
        Some(bytes(call, name)?)
    } else {
        None
    };
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .load_name = name;
    let empty = call.try_intern(b"")?;
    for name in [b"__songlua_native_name".as_slice(), b"__songlua_load_name"] {
        let key = call.try_intern(name)?;
        call.raw_table_set(actor, key, empty)?;
    }
    Ok(())
}

pub(super) fn share_child(
    call: &mut HostCall<'_>,
    store: &Shared,
    owner: TableId,
    child: TableId,
) -> Result<(), Error> {
    let owners: Vec<_> = store
        .lock()
        .unwrap()
        .scenes
        .iter()
        .filter_map(|(id, scene)| scene.actors.contains(&owner).then_some(*id))
        .collect();
    for scene in owners {
        attach(call, store, scene, child)?;
    }
    Ok(())
}

pub(super) fn publish_raw_name(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    original: Value,
) -> Result<(), Error> {
    let name = {
        let guard = store.lock().unwrap();
        let a = &guard.actors[&actor];
        (a.raw_instance || a.offline_instance).then(|| a.state.name.clone())
    };
    if let Some(name) = name {
        let value = if original == Value::Nil {
            call.try_intern(&name)?
        } else {
            original
        };
        let key = call.try_intern(b"__songlua_native_name")?;
        call.raw_table_set(actor, key, value)?;
        if original != Value::Nil {
            let key = call.try_intern(b"Name")?;
            call.raw_table_set(actor, key, original)?;
        }
        let key = call.try_intern(b"__songlua_load_name")?;
        call.raw_table_set(actor, key, Value::Nil)?;
    }
    Ok(())
}
pub(super) fn publish_raw_flag(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    key: &str,
) -> Result<(), Error> {
    let publish = {
        let guard = store.lock().unwrap();
        let a = &guard.actors[&actor];
        a.raw_instance || a.offline_instance
    };
    if publish {
        set(call, actor, key, Value::Boolean(true))?;
    }
    Ok(())
}
fn boolean(call: &mut HostCall<'_>, actor: TableId, key: &str) -> Result<bool, Error> {
    // Lua's bool conversion uses truthiness; nil is the optional default.
    Ok(!matches!(
        field(call, actor, key)?,
        Value::Nil | Value::Boolean(false)
    ))
}
fn put(call: &mut HostCall<'_>, actor: TableId, key: &str, value: Value) -> Result<(), Error> {
    set(call, actor, &format!("__songlua_scroller_{key}"), value)
}
fn float(call: &mut HostCall<'_>, actor: TableId, key: &str, default: f32) -> Result<f32, Error> {
    let value = field(call, actor, &format!("__songlua_scroller_{key}"))?;
    if value == Value::Nil {
        Ok(default)
    } else {
        Ok(sprites::number(call, value)? as f32)
    }
}
fn count(call: &mut HostCall<'_>, actor: TableId) -> Result<i64, Error> {
    let value = field(call, actor, "__songlua_scroller_num_items")?;
    if value == Value::Nil {
        return Ok(1);
    }
    let n = sprites::number(call, value)?;
    if !(i64::MIN as f64..9223372036854775808.0).contains(&n) {
        return Err(call.error(b"scroller item count out of range"));
    }
    Ok(n as i64)
}
fn function(call: &HostCall<'_>, value: Value) -> Result<Option<Value>, Error> {
    match value {
        Value::Nil => Ok(None),
        Value::Function(_) | Value::Native(_) => Ok(Some(value)),
        _ => Err(call.error(b"function expected")),
    }
}
fn display(call: &mut HostCall<'_>, actor: TableId) -> Result<Option<TableId>, Error> {
    let named = native_children::named_children(call, actor)?;
    call.with_roots(&[named], |call| {
        let value = field(call, table(call, named)?, "Display")?;
        if value == Value::Nil {
            Ok(None)
        } else {
            Ok(Some(table(call, value)?))
        }
    })
}
fn position(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let Some(display) = display(call, actor)? else {
        return Ok(());
    };
    call.with_roots(&[Value::Table(display)], |call| {
        let count = count(call, actor)?.max(1);
        let transform = field(call, actor, "__songlua_scroller_transform_function")?;
        if let Some(transform) = function(call, transform)? {
            call.call(
                transform,
                &[
                    Value::Table(display),
                    Value::Number(0.),
                    Value::Number(0.),
                    Value::Number(count as f64),
                ],
            )?;
        } else {
            for (key, axis) in [("item_height", "Y"), ("item_width", "X")] {
                let value = field(call, actor, &format!("__songlua_scroller_{key}"))?;
                if value != Value::Nil {
                    let offset = 0.0_f32 * sprites::number(call, value)? as f32;
                    set(call, display, axis, Value::Number(offset as f64))?;
                    break;
                }
            }
        }
        Ok(())
    })
}
fn call_method(
    call: &mut HostCall<'_>,
    object: TableId,
    name: &str,
    extra: Option<Value>,
) -> Result<Value, Error> {
    call.with_roots(
        &[Value::Table(object), extra.unwrap_or(Value::Nil)],
        |call| {
            let method = field(call, object, name)?;
            let Some(method) = function(call, method)? else {
                return Ok(Value::Nil);
            };
            let args = [Value::Table(object), extra.unwrap_or(Value::Nil)];
            Ok(call
                .call(method, &args[..if extra.is_some() { 2 } else { 1 }])?
                .first()
                .copied()
                .unwrap_or(Value::Nil))
        },
    )
}
fn gamestate(call: &mut HostCall<'_>, name: &str, extra: Option<Value>) -> Result<Value, Error> {
    let globals = table(call, helper(call, 5)?)?;
    let value = field(call, globals, "GAMESTATE")?;
    if value == Value::Nil {
        Ok(Value::Nil)
    } else {
        call_method(call, table(call, value)?, name, extra)
    }
}
fn set_song(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    params: Value,
    leaf: bool,
) -> Result<(), Error> {
    if !store.lock().unwrap().actors.contains_key(&actor) {
        if !leaf && let Some((command, _)) = command(call, actor, b"SetSong")? {
            run_actor_function(call, store, actor, command, Some(params))?;
        }
        if leaf {
            for child in native_children::group_members(call, actor)? {
                set_song(call, store, child, params, true)?;
            }
        }
    } else if leaf {
        leaves(call, store, actor, &mut |call, child| {
            run_named(call, store, child, b"SetSong", Some(params))
        })?;
    } else {
        run_named(call, store, actor, b"SetSong", Some(params))?;
    }
    Ok(())
}
fn populate(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let Some(display) = display(call, actor)? else {
        return Ok(());
    };
    call.with_roots(&[Value::Table(display)], |call| {
        for player in [b"PlayerNumber_P1", b"PlayerNumber_P2"] {
            let params = call.try_new_table()?;
            call.with_roots(&[Value::Table(params)], |call| {
                set(call, params, "Number", Value::Number(0.))?;
                let player = call.try_intern(player)?;
                set(call, params, "PlayerNumber", player)?;
                let song = gamestate(call, "GetCurrentSong", None)?;
                set(call, params, "Song", song)?;
                let steps = gamestate(call, "GetCurrentSteps", Some(player))?;
                set(call, params, "Steps", steps)?;
                for (name, method, default) in [
                    ("Meter", "GetMeter", "?"),
                    ("Difficulty", "GetDifficulty", "Difficulty_Medium"),
                ] {
                    let value = if let Value::Table(steps) = steps {
                        call_method(call, steps, method, None)?
                    } else {
                        Value::Nil
                    };
                    let value = if value == Value::Nil {
                        call.try_intern(default.as_bytes())?
                    } else {
                        value
                    };
                    set(call, params, name, value)?;
                }
                let params = Value::Table(params);
                set_song(call, store, display, params, false)?;
                set_song(call, store, display, params, true)
            })?;
        }
        Ok(())
    })
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = arg(call, 1);
    match name {
        "Load" => return sprites::method(call, store, actor, name),
        "SetFromGameState" => {
            if assets::field(call, actor, b"__songlua_actor_type")?
                .is_some_and(|s| s.eq_ignore_ascii_case("CourseContentsList"))
            {
                set(
                    call,
                    actor,
                    "__songlua_course_contents_from_gamestate",
                    Value::Boolean(true),
                )?;
                put(call, actor, "num_items", Value::Number(1.))?;
                populate(call, store, actor)?;
            }
        }
        "PositionItems" => position(call, actor)?,
        "GetCurrentItem" | "GetDestinationItem" | "GetSecondsPauseBetweenItems" => {
            let key = match name {
                "GetCurrentItem" => "current_item",
                "GetDestinationItem" => "destination_item",
                _ => "pause_between",
            };
            let value = float(call, actor, key, 0.)?;
            return call.push(Value::Number(value as f64));
        }
        "GetNumItems" => {
            let n = count(call, actor)?.max(0);
            return call.push(Value::Number(n as f64));
        }
        "GetLoop" => {
            let value = boolean(call, actor, "__songlua_scroller_loop")?;
            return call.push(Value::Boolean(value));
        }
        "GetSecondsToDestination" => {
            let current = float(call, actor, "current_item", 0.)?;
            let destination = float(call, actor, "destination_item", current)?;
            let seconds = float(call, actor, "seconds_per_item", 0.)?;
            return call.push(Value::Number(
                ((destination - current).abs() * seconds) as f64,
            ));
        }
        "GetFullScrollLengthSeconds" => {
            let count = count(call, actor)?.max(0) as f32;
            let seconds = float(call, actor, "seconds_per_item", 0.)?;
            let pause = float(call, actor, "pause_between", 0.)?;
            return call.push(Value::Number(
                (count - 1.).max(0.).mul_add(pause, count * seconds) as f64,
            ));
        }
        "SetTransformFromFunction" => {
            if matches!(value, Value::Function(_) | Value::Native(_)) {
                put(call, actor, "transform_function", value)?;
            }
        }
        "SetLoop" | "SetFastCatchup" | "SetWrap" | "SetMask" => {
            let key = match name {
                "SetLoop" => "loop",
                "SetFastCatchup" => "fast_catchup",
                "SetWrap" => "wrap",
                _ => "mask",
            };
            if name != "SetLoop" || call.arguments().len() > 1 {
                put(
                    call,
                    actor,
                    key,
                    Value::Boolean(!matches!(value, Value::Nil | Value::Boolean(false))),
                )?;
            }
        }
        "SetNumSubdivisions" | "SetNumItemsToDraw" => {
            if let Some(n) = integer_scalar(call, value) {
                put(
                    call,
                    actor,
                    if name == "SetNumSubdivisions" {
                        "num_subdivisions"
                    } else {
                        "num_items_to_draw"
                    },
                    Value::Number(n.max(0) as f64),
                )?;
            }
        }
        "ScrollThroughAllItems" | "ScrollWithPadding" => {
            let before = float_scalar(call, value, false).unwrap_or(0.).max(0.);
            let after = float_scalar(call, arg(call, 2), false)
                .unwrap_or(0.)
                .max(0.);
            let last = count(call, actor)?.saturating_sub(1).max(0) as f32;
            let destination = if name == "ScrollWithPadding" {
                put(call, actor, "current_item", Value::Number(-before as f64))?;
                last + after
            } else {
                last
            };
            put(
                call,
                actor,
                "destination_item",
                Value::Number(destination as f64),
            )?;
        }
        _ => {
            if let Some(value) = float_scalar(call, value, false) {
                let (key, clamp) = match name {
                    "SetCurrentAndDestinationItem" | "SetCurrentItem" => ("current_item", false),
                    "SetDestinationItem" => ("destination_item", true),
                    "SetTransformFromHeight" => ("item_height", false),
                    "SetTransformFromWidth" => ("item_width", false),
                    "SetSecondsPerItem" => ("seconds_per_item", true),
                    "SetPauseCountdownSeconds" => ("pause_countdown", true),
                    "SetSecondsPauseBetweenItems" => ("pause_between", true),
                    _ => unreachable!(),
                };
                let value = Value::Number(if clamp { value.max(0.) } else { value } as f64);
                put(call, actor, key, value)?;
                if name == "SetCurrentAndDestinationItem" {
                    put(call, actor, "destination_item", value)?;
                }
            }
        }
    }
    call.push(Value::Table(actor))
}

//! Custom draw traversal and render-target scopes over the Rust host API.
use super::*;
use crate::draw_commands::{
    Capture, Context, DRAW_INSTALLED_KEY, MAX_BYTES, MAX_OPS, RawCall, RawFrame, RawOp,
    partially_opaque,
};
use sprites::{field, set};

const ACTIVE: &str = "__songlua_draw_callback_active";
const FUNCTION: &[u8] = b"__songlua_draw_function";

fn live(store: &Shared) -> bool {
    store
        .lock()
        .unwrap()
        .clock
        .live
        .load(std::sync::atomic::Ordering::Relaxed)
}
fn pointer(call: &mut HostCall<'_>, actor: TableId) -> usize {
    call.object_pointer(Value::Table(actor))
        .expect("rooted actor identity")
}
fn truthy(value: Value) -> bool {
    !matches!(value, Value::Nil | Value::Boolean(false))
}
fn raw_text(call: &mut HostCall<'_>, actor: TableId, key: &[u8]) -> Result<Option<String>, Error> {
    let value = get(call, actor, key)?;
    if value == Value::Nil {
        Ok(None)
    } else {
        assets::text(call, value).map(Some)
    }
}
fn raw_bytes(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &[u8],
) -> Result<Option<Vec<u8>>, Error> {
    let value = get(call, actor, key)?;
    if value == Value::Nil {
        Ok(None)
    } else {
        bytes(call, value).map(Some)
    }
}
fn function(call: &mut HostCall<'_>, actor: TableId) -> Result<Value, Error> {
    let value = get(call, actor, FUNCTION)?;
    if matches!(value, Value::Nil | Value::Function(_) | Value::Native(_)) {
        Ok(value)
    } else {
        Err(call.error(b"actor draw function must be a function"))
    }
}
fn budget(call: &HostCall<'_>) -> Error {
    call.error(b"custom draw capture exceeds its song budget")
}
fn push(call: &HostCall<'_>, store: &Shared, op: RawOp) -> Result<(), Error> {
    let live = live(store);
    let mut store = store.lock().unwrap();
    let Some(capture) = &mut store.draw_capture else {
        return Ok(());
    };
    let Some(context) = &capture.context else {
        return Ok(());
    };
    let owner = context.owner;
    let extra = match &op {
        RawOp::Draw(_, _, context, vertices) => {
            context.parents.len() * size_of::<crate::SongLuaOverlayState>()
                + vertices.as_ref().map_or(0, |vertices| {
                    vertices.len() * size_of::<crate::SongLuaOverlayMeshVertex>()
                })
        }
        _ => 0,
    };
    let bytes = size_of::<RawCall>() + extra;
    if (!live && capture.frame_ops >= MAX_OPS) || capture.bytes.saturating_add(bytes) > MAX_BYTES {
        return Err(budget(call));
    }
    capture.bytes += bytes;
    capture.frame_ops += 1;
    capture.calls.push(RawCall { owner, op });
    Ok(())
}
pub(super) fn begin(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    preserve: bool,
) -> Result<(), Error> {
    let pointer = pointer(call, actor);
    push(call, store, RawOp::Begin(pointer, preserve))?;
    if let Some(capture) = &mut store.lock().unwrap().draw_capture
        && let Some(prior) = capture.context.take()
    {
        let owner = prior.owner;
        capture.targets.push((pointer, prior));
        capture.context = Some(Context {
            owner,
            ..Context::default()
        });
    }
    Ok(())
}
pub(super) fn finish(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let pointer = pointer(call, actor);
    if let Some(capture) = &store.lock().unwrap().draw_capture
        && capture.context.is_some()
        && capture
            .targets
            .last()
            .is_none_or(|(target, _)| *target != pointer)
    {
        return Err(call.error(b"FinishRenderingTo does not match the active target"));
    }
    push(call, store, RawOp::Finish(pointer))?;
    if let Some(capture) = &mut store.lock().unwrap().draw_capture
        && let Some((_, prior)) = capture.targets.pop()
    {
        capture.context = Some(prior);
    }
    Ok(())
}
fn state(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<crate::SongLuaOverlayState, Error> {
    // The native preparation reader resolves an uninitialized Sprite's
    // Texture/AFT getter before reading later scalar fields. Keep this read
    // at draw time; snapshotting raw semantic state must not invoke it early.
    if !live(store) {
        let kind = get(call, actor, b"__songlua_actor_type")?;
        let sprite = matches!(kind,Value::String(id)if call.string_bytes(id).is_some_and(|s|s.eq_ignore_ascii_case(b"Sprite")));
        if sprite && get(call, actor, b"__songlua_state_sprite_texture")? == Value::Nil {
            return initial_state::read(call, store, actor);
        }
    }
    let store = store.lock().unwrap();
    let live = store.clock.live.load(std::sync::atomic::Ordering::Relaxed);
    let actor = store
        .actors
        .get(&actor)
        .ok_or_else(|| call.error(b"draw actor has been released"))?;
    let mut state = actor.state.render;
    // The existing preparation reader exports authored destination fields.
    // Live drawing reads the native current tween pose and its baked spin flag.
    // Keep that distinction at this boundary, without changing queue state.
    if live {
        actor.current.write_to(&mut state);
    } else {
        actor.destination().write_to(&mut state);
        // Spin updates its native pose without publishing the preparation
        // reader's rotation fields until a setter/queue synchronization does.
        [state.rot_x_deg, state.rot_y_deg, state.rot_z_deg] = actor.state.rotation;
    }
    state.visible = actor.state.visible;
    state.draw_order = actor.state.draw_order;
    state.hibernating = actor.hibernate > 0.0;
    state.spin_baked = live && actor.effects.spin_baked;
    Ok(state)
}
fn scoped_context(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    prior: &Context,
) -> Result<Option<Context>, Error> {
    let transition = get(call, actor, b"__songlua_transition_state")?;
    if transition != Value::Nil {
        let transition = sprites::number(call, transition)?.trunc();
        if !(0.0..256.0).contains(&transition) {
            return Err(call.error(b"transition state out of range"));
        }
        if transition == 0.0 {
            return Ok(None);
        }
    }
    if truthy(get(call, actor, b"__songlua_theme_hibernating")?) {
        return Ok(None);
    }
    let kind = assets::field(call, actor, b"__songlua_actor_type")?.unwrap_or_default();
    if kind.eq_ignore_ascii_case("ActorFrameTexture") {
        let allocation = get(call, actor, b"__songlua_aft_allocation")?;
        if allocation == Value::Nil {
            return Ok(None);
        }
        table(call, allocation)?;
    }
    let (wrappers, live) = {
        let store = store.lock().unwrap();
        let native = store
            .actors
            .get(&actor)
            .ok_or_else(|| call.error(b"draw actor has been released"))?;
        (
            native.wrappers.clone(),
            store.clock.live.load(std::sync::atomic::Ordering::Relaxed),
        )
    };
    let mut parents = Vec::with_capacity(prior.parents.len() + wrappers.len() + 1);
    parents.extend_from_slice(&prior.parents);
    for wrapper in wrappers.into_iter().rev() {
        let wrapper = state(call, store, wrapper)?;
        if !wrapper.draw_visible() || (live && !partially_opaque(wrapper, &parents)) {
            return Ok(None);
        }
        parents.push(wrapper);
    }
    let state = state(call, store, actor)?;
    if !state.draw_visible() || (live && !partially_opaque(state, &parents)) {
        return Ok(None);
    }
    parents.push(state);
    Ok(Some(Context {
        owner: prior.owner,
        parents: parents.into(),
        camera: if state.fov.is_some() {
            Some(state)
        } else {
            prior.camera
        },
    }))
}
fn children_each(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    mut action: impl FnMut(&mut HostCall<'_>, &Shared, TableId) -> Result<(), Error>,
) -> Result<(), Error> {
    let mut index = 1;
    loop {
        let value = call.raw_table_get(actor, Value::Number(index as f64))?;
        if value == Value::Nil {
            return Ok(());
        }
        let child = table(call, value)?;
        call.with_roots(&[value], |call| action(call, store, child))?;
        index += 1;
    }
}
fn report(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    error: Error,
) -> Result<(), Error> {
    if error.kind() != ErrorKind::Runtime {
        return Err(error);
    }
    if !truthy(field(call, actor, "__songlua_draw_error_reported")?) {
        set(
            call,
            actor,
            "__songlua_draw_error_reported",
            Value::Boolean(true),
        )?;
        store.lock().unwrap().diagnostics.push(error.to_string());
    }
    Ok(())
}
fn draw(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let prior = store
        .lock()
        .unwrap()
        .draw_capture
        .as_ref()
        .and_then(|capture| capture.context.clone());
    let Some(prior) = prior else {
        return immediate(call, store, actor);
    };
    let Some(context) = scoped_context(call, store, actor, &prior)? else {
        return Ok(());
    };
    store.lock().unwrap().draw_capture.as_mut().unwrap().context = Some(context.clone());
    let result = (|| {
        let kind = assets::field(call, actor, b"__songlua_actor_type")?.unwrap_or_default();
        let target = kind.eq_ignore_ascii_case("ActorFrameTexture");
        if target {
            let preserve = truthy(field(call, actor, "__songlua_state_aft_preserve")?);
            begin(call, store, actor, preserve)?;
        }
        let result = (|| {
            let callback = function(call, actor)?;
            if callback != Value::Nil {
                let result =
                    call.with_roots(&[callback], |call| run_scoped(call, actor, callback, None));
                return if live(store) {
                    result.or_else(|error| report(call, store, actor, error))
                } else {
                    // Owned actors already use tween replay in preparation as
                    // well as live playback. Like the native replay path, Draw
                    // does not dispatch their queued commands before Update.
                    result
                };
            }
            let screen = raw_text(call, actor, b"__songlua_top_screen_child_name")?;
            let player = raw_text(call, actor, b"__songlua_player_child_name")?;
            let external = matches!(
                screen.as_deref(),
                Some("Underlay" | "Overlay" | "SongBackground" | "SongForeground" | "In")
            ) || matches!(player.as_deref(), Some("Judgment" | "Combo"));
            if kind.eq_ignore_ascii_case("Actor") {
                return Ok(());
            }
            if kind.eq_ignore_ascii_case("BitmapText")
                && raw_bytes(call, actor, b"Text")?.is_none_or(|text| text.is_empty())
            {
                return Ok(());
            }
            let local = *context
                .parents
                .last()
                .expect("actor included in draw context");
            if kind.eq_ignore_ascii_case("Sprite")
                && raw_bytes(call, actor, b"Texture")?.as_deref()
                    == Some(crate::blank_texture::NATIVE_BLANK_TEXTURE_PATH.as_bytes())
                && local.blend == crate::SongLuaOverlayBlendMode::Alpha
                && !local.depth_write
                && !local.mask_source
                && !local.mask_dest
            {
                return Ok(());
            }
            if !external && kind.eq_ignore_ascii_case("ActorProxy") {
                let target = get(call, actor, b"__songlua_proxy_target_actor")?;
                if target == Value::Nil {
                    return Ok(());
                }
                table(call, target)?;
            }
            if !external
                && (kind.eq_ignore_ascii_case("ActorFrame")
                    || kind.eq_ignore_ascii_case("ActorFrameTexture"))
            {
                return children_each(call, store, actor, draw);
            }
            let pointer = pointer(call, actor);
            let missing = !store
                .lock()
                .unwrap()
                .draw_capture
                .as_ref()
                .unwrap()
                .labels
                .contains_key(&pointer);
            if missing {
                let name = raw_text(call, actor, b"Name")?.unwrap_or_default();
                let label = format!(
                    "{kind} '{name}' (screen child '{}')",
                    screen.unwrap_or_default()
                );
                let bytes = label.len() + size_of::<(usize, String)>();
                let mut store = store.lock().unwrap();
                let capture = store.draw_capture.as_mut().unwrap();
                if capture.bytes.saturating_add(bytes) > MAX_BYTES {
                    return Err(budget(call));
                }
                capture.bytes += bytes;
                capture.labels.insert(pointer, label);
            }
            let vertices = meshes::read(call, actor)?.map(|mesh| mesh.vertices);
            let parents = Arc::from(&context.parents[..context.parents.len() - 1]);
            push(
                call,
                store,
                RawOp::Draw(pointer, local, Context { parents, ..context }, vertices),
            )
        })();
        if target {
            finish(call, store, actor)?;
        }
        result
    })();
    store.lock().unwrap().draw_capture.as_mut().unwrap().context = Some(prior);
    result
}
fn second(call: &mut HostCall<'_>, store: &Shared) -> Result<f32, Error> {
    let globals = table(call, helper(call, 5)?)?;
    let runtime = field(call, globals, crate::SONG_LUA_RUNTIME_KEY)?;
    let table = table(call, runtime)?;
    call.with_roots(&[runtime], |call| {
        let value = field(call, table, crate::SONG_LUA_RUNTIME_SECONDS_KEY)?;
        let elapsed = sprites::number(call, value)? as f32;
        let value = field(call, table, crate::SONG_LUA_RUNTIME_RATE_KEY)?;
        let rate = sprites::number(call, value)? as f32;
        let origin = store
            .lock()
            .unwrap()
            .clock
            .timing
            .as_ref()
            .map_or(0.0, |clock| clock.get_time_for_beat_exact(0.0));
        Ok(elapsed * rate + origin)
    })
}
fn immediate(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let second = second(call, store)?;
    let owner = pointer(call, actor);
    let start = {
        let mut store = store.lock().unwrap();
        let capture = store.draw_capture.get_or_insert_with(Capture::default);
        capture.context = Some(Context {
            owner,
            ..Context::default()
        });
        capture.calls.len()
    };
    let result = draw(call, store, actor);
    let mut store = store.lock().unwrap();
    let capture = store.draw_capture.as_mut().unwrap();
    capture.context = None;
    let calls = capture.calls.split_off(start);
    if !calls.is_empty() {
        let bytes = size_of::<RawFrame>() + size_of::<usize>();
        if capture.bytes.saturating_add(bytes) > MAX_BYTES {
            return Err(budget(call));
        }
        capture.bytes += bytes;
        capture.frames.push(RawFrame {
            second,
            immediate: true,
            owners: vec![owner],
            calls,
        });
    }
    result
}
fn visit(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    prior: &Context,
) -> Result<(), Error> {
    if live(store) && truthy(get(call, actor, b"__songlua_live_inactive")?) {
        return Ok(());
    }
    if function(call, actor)? != Value::Nil {
        let owner = pointer(call, actor);
        {
            let mut store = store.lock().unwrap();
            let capture = store.draw_capture.get_or_insert_with(Capture::default);
            capture.owners.push(owner);
            capture.context = Some(Context {
                owner,
                ..prior.clone()
            });
        }
        let result = draw(call, store, actor);
        let mut store = store.lock().unwrap();
        let capture = store.draw_capture.as_mut().unwrap();
        capture.context = None;
        if !capture.targets.is_empty() {
            capture.targets.clear();
            return Err(call.error(b"draw callback left a render target active"));
        }
        return result;
    }
    let Some(context) = scoped_context(call, store, actor, prior)? else {
        return Ok(());
    };
    children_each(call, store, actor, |call, store, child| {
        visit(call, store, child, &context)
    })
}
fn run(call: &mut HostCall<'_>, store: &Shared, root: TableId) -> Result<(), Error> {
    if live(store)
        && let Some(capture) = &mut store.lock().unwrap().draw_capture
    {
        capture.context = None;
        capture.targets.clear();
        capture.calls.clear();
        capture.owners.clear();
        capture.frames.retain(|frame| frame.immediate);
        if capture.frames.is_empty() {
            capture.labels.clear();
            capture.bytes = 0;
        }
        capture.frame_ops = 0;
    }
    let globals = table(call, helper(call, 5)?)?;
    if !truthy(get(call, globals, DRAW_INSTALLED_KEY.as_bytes())?) {
        if let Some(capture) = &mut store.lock().unwrap().draw_capture {
            capture.frame_ops = 0;
        }
        return Ok(());
    }
    let screen = get(call, globals, b"__songlua_top_screen")?;
    let screen = if screen == Value::Nil {
        None
    } else {
        Some(state(call, store, table(call, screen)?)?)
    };
    let parents = screen.as_ref().map_or_else(
        || Arc::from([]),
        |state| Arc::from(std::slice::from_ref(state)),
    );
    let result = visit(
        call,
        store,
        root,
        &Context {
            parents,
            camera: screen.filter(|state| state.fov.is_some()),
            ..Context::default()
        },
    );
    let second = second(call, store)?;
    if let Some(capture) = &mut store.lock().unwrap().draw_capture {
        let bytes = size_of::<RawFrame>() + capture.owners.len() * size_of::<usize>();
        if capture.bytes.saturating_add(bytes) > MAX_BYTES {
            capture.calls.clear();
            capture.owners.clear();
            return Err(budget(call));
        }
        capture.bytes += bytes;
        let calls = std::mem::take(&mut capture.calls);
        let owners = std::mem::take(&mut capture.owners);
        capture.frames.push(RawFrame {
            second,
            immediate: false,
            owners,
            calls,
        });
        capture.frame_ops = 0;
    }
    result
}
pub(super) fn scene(call: &mut HostCall<'_>, store: &Shared, root: TableId) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let key = call.try_intern(ACTIVE.as_bytes())?;
    let prior = call.raw_table_get(globals, key)?;
    call.with_roots(&[key, prior], |call| {
        call.raw_table_set(globals, key, Value::Boolean(true))?;
        let result = run(call, store, root);
        call.raw_table_set(globals, key, prior)?;
        result
    })
}
pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    match name {
        "SetDrawFunction" => {
            let function = arg(call, 1);
            if !matches!(function, Value::Nil | Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"SetDrawFunction requires a function or nil"));
            }
            if function != Value::Nil {
                let globals = table(call, helper(call, 5)?)?;
                let key = call.try_intern(DRAW_INSTALLED_KEY.as_bytes())?;
                call.raw_table_set(globals, key, Value::Boolean(true))?;
            }
            set(call, actor, "__songlua_draw_function", function)?;
        }
        "GetDrawFunction" => {
            let value = field(call, actor, "__songlua_draw_function")?;
            if !matches!(value, Value::Nil | Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"actor draw function must be a function"));
            }
            return call.push(value);
        }
        "Draw" => {
            let value = field(call, actor, "__songlua_visible")?;
            if value == Value::Nil || truthy(value) {
                let globals = table(call, helper(call, 5)?)?;
                let active = field(call, globals, ACTIVE)?;
                let screen = assets::field(call, actor, b"__songlua_top_screen_child_name")?;
                let player = screen
                    .as_deref()
                    .is_some_and(|name| matches!(name, "PlayerP1" | "PlayerP2"));
                if truthy(active) && !player {
                    let state = native_children::state(call, store, actor)?;
                    let snapshot = state_snapshot::write(call, store, actor, &state)?;
                    song_replay::raw_set(
                        call,
                        actor,
                        "__songlua_manual_draw_state",
                        Value::Table(snapshot),
                    )?;
                }
                draw(call, store, actor)?;
            }
        }
        _ => unreachable!(),
    }
    call.push(Value::Table(actor))
}

//! Native actor effect selection, phase and spin, before tween advancement.
use super::{Actor, Shared, arg, float_scalar, helper, render, table};
use crate::{SongLuaOverlayState, SongLuaOverlayUpdateTarget as Target, rust_engine::Clock};
use deadlib_lua::{Error, HostCall, TableId, Value};
use deadlib_present::anim::{EffectClock, EffectMode};
use std::sync::atomic::Ordering;

pub(super) const METHODS: &[&str] = &[
    "diffuseblink",
    "diffuseshift",
    "diffuseramp",
    "glowblink",
    "glowshift",
    "glowramp",
    "rainbow",
    "wag",
    "bounce",
    "bob",
    "pulse",
    "spin",
    "vibrate",
    "stopeffect",
    "effectcolor1",
    "effectcolor2",
    "effectperiod",
    "effecttiming",
    "effect_hold_at_full",
    "effectoffset",
    "effectclock",
    "effectmagnitude",
    "geteffectmagnitude",
    "GetSecsIntoEffect",
    "GetEffectDelta",
];

#[derive(Clone, Copy, Default)]
pub(super) struct State {
    // None preserves getters' runtime-clock fallback before the first update.
    motion: Option<Motion>,
    spin_seen: bool,
    pub(super) spin_baked: bool,
}

#[derive(Clone, Copy, Default)]
struct Motion {
    // A failed first external-clock read leaves the clock created but without
    // units, as in the production host. Its delta getter still defaults to zero.
    units: Option<f32>,
    delta: f32,
}

fn set_period(render: &mut SongLuaOverlayState, period: f32) {
    render.effect_period = period;
    if render.effect_timing.is_some() {
        render.effect_timing = Some([period / 2.0, 0.0, period / 2.0, 0.0, 0.0]);
    }
}

fn select(actor: &mut Actor, name: &str) -> smallvec::SmallVec<[Target; 8]> {
    let mut fields = smallvec::smallvec![Target::Vibrate, Target::Rainbow, Target::EffectMode];
    if name == "spin" {
        super::capture::start_spin(actor);
    }
    let render = &mut actor.state.render;
    let mode = crate::parse_overlay_effect_mode(name).unwrap_or(EffectMode::None);
    let motion = matches!(name, "bob" | "bounce" | "wag");
    let color = matches!(
        name,
        "diffuseblink" | "diffuseshift" | "diffuseramp" | "glowblink" | "glowshift" | "glowramp"
    );
    let reset = (motion
        && (name == "bounce"
            || mode != render.effect_mode
            || (name == "bob" && render.effect_period != 2.0)))
        || (color && mode != render.effect_mode)
        || (name == "rainbow" && !render.rainbow);
    if motion || color || matches!(name, "pulse" | "rainbow") {
        let clock = actor.effects.motion.get_or_insert(Motion {
            units: Some(0.0),
            delta: 0.0,
        });
        if reset {
            clock.units = Some(0.0);
        }
    }
    render.effect_mode = mode;
    render.vibrate = name == "vibrate";
    render.rainbow = name == "rainbow";
    match name {
        "glowblink" | "glowshift" | "glowramp" => {
            set_period(render, 1.0);
            fields.push(Target::EffectPeriod);
            if render.effect_timing.is_some() {
                fields.push(Target::EffectTiming);
            }
            fields.extend([Target::EffectColor1, Target::EffectColor2]);
            render.effect_color1 = [1.0, 1.0, 1.0, 0.2];
            render.effect_color2 = [1.0, 1.0, 1.0, 0.8];
        }
        "diffuseblink" | "diffuseshift" | "diffuseramp" => {
            set_period(render, 1.0);
            fields.push(Target::EffectPeriod);
            if render.effect_timing.is_some() {
                fields.push(Target::EffectTiming);
            }
            fields.extend([Target::EffectColor1, Target::EffectColor2]);
            render.effect_color1 = if name == "diffuseblink" {
                [0.5; 4]
            } else {
                [0.0, 0.0, 0.0, 1.0]
            };
            render.effect_color2 = [1.0; 4];
        }
        "bob" | "bounce" | "wag" | "pulse" => {
            if name != "bob" || reset {
                set_period(render, 2.0);
                fields.push(Target::EffectPeriod);
                if render.effect_timing.is_some() {
                    fields.push(Target::EffectTiming);
                }
            }
            fields.push(Target::EffectMagnitude);
            render.effect_magnitude = match name {
                "pulse" => [0.5, 1.0, 1.0],
                "wag" => [0.0, 0.0, 20.0],
                _ => [0.0, 20.0, 0.0],
            };
        }
        "rainbow" => {
            set_period(render, 2.0);
            fields.push(Target::EffectPeriod);
            if render.effect_timing.is_some() {
                fields.push(Target::EffectTiming);
            }
        }
        "spin" => {
            fields.push(Target::EffectMagnitude);
            actor.effects.spin_seen = true;
            render.effect_magnitude = [0.0, 0.0, 180.0];
        }
        "vibrate" => {
            fields.push(Target::EffectMagnitude);
            render.effect_magnitude = [10.0; 3];
        }
        _ => {}
    }
    fields
}

fn number(call: &mut HostCall<'_>, value: Value) -> Result<f64, Error> {
    if let Value::Number(value) = value {
        return Ok(value);
    }
    match call.call(helper(call, 6)?, &[value])?[0] {
        Value::Number(value) => Ok(value),
        _ => Err(call.error(b"number expected")),
    }
}

fn field(call: &mut HostCall<'_>, runtime: Value, key: &str) -> Result<f64, Error> {
    let key = call.try_intern(key.as_bytes())?;
    let value = call.table_get(runtime, key)?;
    number(call, value)
}

fn runtime<T>(
    call: &mut HostCall<'_>,
    read: impl FnOnce(&mut HostCall<'_>, Value) -> Result<T, Error>,
) -> Result<T, Error> {
    let key = call.try_intern(crate::SONG_LUA_RUNTIME_KEY.as_bytes())?;
    let runtime = call.table_get(helper(call, 5)?, key)?;
    table(call, runtime)?;
    // A global __index may synthesize a table that detaches itself and collects
    // while a later field is read. Root the selected table for the whole read.
    call.with_roots(&[runtime], |call| read(call, runtime))
}

pub(super) fn values(call: &mut HostCall<'_>, delta: bool) -> Result<[f32; 2], Error> {
    runtime(call, |call, runtime| {
        let (beat, seconds) = if delta {
            (
                crate::SONG_LUA_RUNTIME_DELTA_BEAT_KEY,
                crate::SONG_LUA_RUNTIME_DELTA_SECONDS_KEY,
            )
        } else {
            (
                crate::SONG_LUA_RUNTIME_BEAT_KEY,
                crate::SONG_LUA_RUNTIME_SECONDS_KEY,
            )
        };
        Ok([
            field(call, runtime, beat)? as f32,
            field(call, runtime, seconds)? as f32,
        ])
    })
}

fn music(call: &mut HostCall<'_>, clock: &Clock) -> Result<f32, Error> {
    runtime(call, |call, runtime| {
        let seconds = field(call, runtime, crate::SONG_LUA_RUNTIME_SECONDS_KEY)?;
        let rate = field(call, runtime, crate::SONG_LUA_RUNTIME_RATE_KEY)? as f32;
        let seconds = if clock.live.load(Ordering::Relaxed) {
            seconds as f32
        } else {
            (seconds * f64::from(rate)) as f32
                + clock
                    .timing
                    .as_ref()
                    .map_or(0.0, |clock| clock.get_time_for_beat_exact(0.0))
        };
        // Preserve the production integer-valued-float path (notably -0).
        Ok(if seconds.fract() == 0.0 && seconds.abs() < 1e14 {
            (seconds as i64) as f32
        } else {
            seconds
        })
    })
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = arg(call, 1);
    let mut fields = smallvec::SmallVec::<[Target; 8]>::new();
    match name {
        "GetSecsIntoEffect" | "GetEffectDelta" => {
            let (state, clock) = {
                let store = store.lock().unwrap();
                let actor = &store.actors[&actor];
                (actor.effects, actor.state.render.effect_clock)
            };
            let delta = name == "GetEffectDelta";
            let value = match state.motion {
                Some(motion) if delta => motion.delta,
                Some(motion) => motion
                    .units
                    .ok_or_else(|| call.error(b"effect clock has no units"))?,
                None => values(call, delta)?[usize::from(clock == EffectClock::Time)],
            };
            return call.push(Value::Number(value as f64));
        }
        "geteffectmagnitude" => {
            let values = store.lock().unwrap().actors[&actor]
                .state
                .render
                .effect_magnitude;
            for value in values {
                call.push(Value::Number(value as f64))?;
            }
            return Ok(());
        }
        "effectcolor1" | "effectcolor2" => {
            let color = render::color(call)?.unwrap_or([1.0; 4]);
            super::action_capture::prepare(call, store, actor)?;
            let mut store = store.lock().unwrap();
            let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
            if name == "effectcolor1" {
                render.effect_color1 = color;
                fields.push(Target::EffectColor1);
            } else {
                render.effect_color2 = color;
                fields.push(Target::EffectColor2);
            }
        }
        "effectperiod" | "effectoffset" => {
            if let Some(value) = float_scalar(call, value, false) {
                super::action_capture::prepare(call, store, actor)?;
                let mut store = store.lock().unwrap();
                let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
                if name == "effectperiod" {
                    set_period(render, value);
                    fields.push(Target::EffectPeriod);
                    if render.effect_timing.is_some() {
                        fields.push(Target::EffectTiming);
                    }
                } else {
                    render.effect_offset = value;
                    fields.push(Target::EffectOffset);
                }
            }
        }
        "effectmagnitude" => {
            let magnitude =
                [1, 2, 3].map(|i| float_scalar(call, arg(call, i), false).unwrap_or(0.0));
            super::action_capture::prepare(call, store, actor)?;
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .render
                .effect_magnitude = magnitude;
            fields.push(Target::EffectMagnitude);
        }
        "effecttiming" => {
            let mut timing = [0.0; 5];
            for (i, index) in [0, 1, 2, 4].into_iter().enumerate() {
                let Some(value) = float_scalar(call, arg(call, i + 1), false) else {
                    return call.push(Value::Table(actor));
                };
                timing[index] = value.max(0.0);
            }
            timing[3] = float_scalar(call, arg(call, 5), false)
                .unwrap_or(0.0)
                .max(0.0);
            let total = timing.iter().sum::<f32>();
            if total > 0.0 {
                super::action_capture::prepare(call, store, actor)?;
                let mut store = store.lock().unwrap();
                let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
                render.effect_timing = Some(timing);
                render.effect_period = total;
                fields.extend([Target::EffectTiming, Target::EffectPeriod]);
            }
        }
        "effect_hold_at_full" => {
            let hold = number(call, value)? as f32;
            let render = store.lock().unwrap().actors[&actor].state.render;
            let period = render.effect_period;
            let mut timing =
                render
                    .effect_timing
                    .unwrap_or([period / 2.0, 0.0, period / 2.0, 0.0, 0.0]);
            timing[3] = hold;
            let total = timing.iter().sum::<f32>();
            if hold < 0.0 || total <= 0.0 {
                return Err(call.error(b"effect timings must be nonnegative and not all zero"));
            }
            super::action_capture::prepare(call, store, actor)?;
            let mut guard = store.lock().unwrap();
            let render = &mut guard.actors.get_mut(&actor).unwrap().state.render;
            render.effect_timing = Some(timing);
            render.effect_period = total;
            fields.extend([Target::EffectTiming, Target::EffectPeriod]);
        }
        "effectclock" => {
            if let Some(raw) = render::text(call, value)
                && let Some(clock) = crate::parse_overlay_effect_clock(raw)
            {
                let no_offset = raw.eq_ignore_ascii_case("beatnooffset");
                let timer = raw.eq_ignore_ascii_case("timer");
                super::action_capture::prepare(call, store, actor)?;
                let mut store = store.lock().unwrap();
                let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
                render.effect_clock = clock;
                render.effect_no_offset = no_offset;
                render.effect_timer = timer;
                fields.extend([
                    Target::EffectClock,
                    Target::EffectNoOffset,
                    Target::EffectTimer,
                ]);
            }
        }
        _ => {
            super::action_capture::prepare(call, store, actor)?;
            fields = select(store.lock().unwrap().actors.get_mut(&actor).unwrap(), name);
        }
    }
    if !fields.is_empty() {
        let state = store.lock().unwrap().actors[&actor].state.render;
        for target in fields {
            let mut delta = crate::SongLuaOverlayStateDelta::default();
            match target {
                Target::Vibrate => delta.vibrate = Some(state.vibrate),
                Target::Rainbow => delta.rainbow = Some(state.rainbow),
                Target::EffectMode => delta.effect_mode = Some(state.effect_mode),
                Target::EffectColor1 => delta.effect_color1 = Some(state.effect_color1),
                Target::EffectColor2 => delta.effect_color2 = Some(state.effect_color2),
                Target::EffectPeriod => delta.effect_period = Some(state.effect_period),
                Target::EffectMagnitude => delta.effect_magnitude = Some(state.effect_magnitude),
                Target::EffectOffset => delta.effect_offset = Some(state.effect_offset),
                Target::EffectClock => delta.effect_clock = Some(state.effect_clock),
                Target::EffectNoOffset => delta.effect_no_offset = Some(state.effect_no_offset),
                Target::EffectTimer => delta.effect_timer = Some(state.effect_timer),
                Target::EffectTiming => delta.effect_timing = state.effect_timing,
                _ => unreachable!("effect setter published a non-effect target"),
            }
            super::capture::write(call, store, actor, delta, true);
        }
    }
    call.push(Value::Table(actor))
}

pub(super) fn advance(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    delta: f32,
) -> Result<(), Error> {
    let (previous, render, clock) = {
        let mut store = store.lock().unwrap();
        let clock = store.clock.clone();
        let actor = store.actors.get_mut(&actor).unwrap();
        let previous = actor
            .effects
            .motion
            .get_or_insert_with(Motion::default)
            .units
            .unwrap_or(0.0);
        (previous, actor.state.render, clock)
    };
    let (units, elapsed) = if render.effect_timer {
        let mut units = previous + delta;
        // Native Actor subtracts once, with strict >, rather than modulo.
        if units > render.effect_period {
            units -= render.effect_period;
        }
        (units, delta)
    } else {
        let units = if render.effect_clock == EffectClock::Beat {
            if render.effect_no_offset {
                let seconds = music(call, &clock)?;
                // The production fallback evaluates the runtime beat even if
                // timing data supplies the selected no-offset position.
                let fallback = values(call, false)?[0];
                clock.no_offset.as_ref().map_or(fallback, |timing| {
                    timing.get_song_position_no_offset(seconds).beat
                })
            } else {
                values(call, false)?[0]
            }
        } else {
            music(call, &clock)?
        };
        (units, units - previous)
    };
    let mut store = store.lock().unwrap();
    let actor = store.actors.get_mut(&actor).unwrap();
    actor.effects.motion = Some(Motion {
        units: Some(units),
        delta: elapsed,
    });
    if actor.effects.spin_seen {
        if actor.state.render.effect_mode == EffectMode::Spin {
            let magnitude = actor.state.render.effect_magnitude;
            for (angle, speed) in [
                &mut actor.current.rot_x_deg,
                &mut actor.current.rot_y_deg,
                &mut actor.current.rot_z_deg,
            ]
            .into_iter()
            .zip(magnitude)
            {
                *angle = (*angle + elapsed * speed).rem_euclid(360.0);
            }
        }
        actor.effects.spin_baked = true;
    }
    Ok(())
}

pub(super) fn render_time(actor: &Actor, frame_clock: [f32; 2], render: &mut SongLuaOverlayState) {
    render.spin_baked = actor.effects.spin_baked;
    if (render.rainbow || !matches!(render.effect_mode, EffectMode::None | EffectMode::Spin))
        && let Some(motion) = actor.effects.motion
    {
        render.effect_time = Some([
            frame_clock[usize::from(render.effect_clock == EffectClock::Beat)],
            motion.units.unwrap_or(0.0),
        ]);
    }
}

//! ActorFrameTexture allocation requests and retained resource metadata.
use super::*;
use sprites::{field, set};

#[derive(Clone, Debug, PartialEq)]
pub struct FrameTexture {
    pub capture_name: String,
    pub capture_size: Option<[f32; 2]>,
    pub alpha_buffer: bool,
    pub depth_buffer: bool,
    pub float_buffer: bool,
}

pub(super) const METHODS: &[&str] = &[
    "Create",
    "EnableDepthBuffer",
    "EnableAlphaBuffer",
    "EnableFloat",
    "EnablePreserveTexture",
    "SetTextureName",
    "GetTexture",
];

fn allocation(call: &mut HostCall<'_>, actor: TableId) -> Result<Option<TableId>, Error> {
    let value = get(call, actor, b"__songlua_aft_allocation")?;
    if value == Value::Nil {
        Ok(None)
    } else {
        table(call, value).map(Some)
    }
}

pub(super) fn capture_name(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Option<String>, Error> {
    if let Some(allocation) = allocation(call, actor)? {
        assets::field(call, allocation, b"name")
    } else {
        assets::field(call, actor, b"__songlua_aft_capture_name")
    }
}

pub(super) fn initialize(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    if capture_name(call, actor)?.is_some() {
        return Ok(());
    }
    let globals = table(call, helper(call, 5)?)?;
    let count = field(call, globals, "__songlua_aft_counter")?;
    let count = if count == Value::Nil {
        0
    } else {
        let value = sprites::number(call, count)?;
        if !(i64::MIN as f64..9223372036854775808.0).contains(&value) {
            return Err(call.error(b"ActorFrameTexture counter out of range"));
        }
        value as i64
    }
    .saturating_add(1);
    set(
        call,
        globals,
        "__songlua_aft_counter",
        Value::Number(count as f64),
    )?;
    let name = call.try_intern(format!("ActorFrameTexture {count}").as_bytes())?;
    set(call, actor, "__songlua_aft_capture_name", name)
}

fn flag(call: &mut HostCall<'_>, actor: TableId, key: &str) -> Result<bool, Error> {
    Ok(!matches!(
        field(call, actor, key)?,
        Value::Nil | Value::Boolean(false)
    ))
}

pub(super) fn read(call: &mut HostCall<'_>, actor: TableId) -> Result<FrameTexture, Error> {
    let allocation = allocation(call, actor)?;
    let flags = allocation.unwrap_or(actor);
    call.with_roots(&[Value::Table(flags)], |call| {
        let capture_name = capture_name(call, actor)?
            .ok_or_else(|| call.error(b"ActorFrameTexture has no texture name"))?;
        let capture_size = if let Some(allocation) = allocation {
            let size = field(call, allocation, "size")?;
            table(call, size)?;
            sprites::vector::<2>(call, size)?
        } else {
            None
        };
        Ok(FrameTexture {
            capture_name,
            capture_size,
            alpha_buffer: flag(call, flags, "__songlua_aft_alpha_buffer")?,
            depth_buffer: flag(call, flags, "__songlua_aft_depth_buffer")?,
            float_buffer: flag(call, flags, "__songlua_aft_float_buffer")?,
        })
    })
}

pub(super) fn report(call: &mut HostCall<'_>, store: &Shared, message: &str) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let key = call.try_intern(b"__songlua_reporting_script_error")?;
    if !matches!(
        call.raw_table_get(globals, key)?,
        Value::Nil | Value::Boolean(false)
    ) {
        return Ok(());
    }
    call.with_roots(&[key], |call| {
        call.raw_table_set(globals, key, Value::Boolean(true))?;
        let result = (|| {
            messages::side_effect(call)?;
            let params = call.try_new_table()?;
            call.with_roots(&[Value::Table(params)], |call| {
                let text = call.try_intern(message.as_bytes())?;
                set(call, params, "message", text)?;
                messages::dispatch(
                    call,
                    store,
                    b"ScriptError",
                    Some(Value::Table(params)),
                    true,
                )
            })?;
            store.lock().unwrap().diagnostics.push(message.to_owned());
            Ok(())
        })();
        call.raw_table_set(globals, key, Value::Boolean(false))?;
        result
    })
}

fn immediate(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    created: bool,
    value: bool,
) -> Result<(), Error> {
    action_capture::prepare(call, store, actor)?;
    let key = if created {
        "__songlua_state_aft_created"
    } else {
        "__songlua_state_aft_preserve"
    };
    set(call, actor, key, Value::Boolean(value))?;
    let mut guard = store.lock().unwrap();
    let state = &mut guard.actors.get_mut(&actor).unwrap().state.render;
    if created {
        state.aft_created = value;
    } else {
        state.aft_preserve = value;
    }
    drop(guard);
    song_immediate::record(
        call,
        store,
        actor,
        if created {
            crate::SongLuaOverlayUpdateTarget::AftCreated
        } else {
            crate::SongLuaOverlayUpdateTarget::AftPreserve
        },
        crate::SongLuaOverlayUpdateValue::Bool(value),
    );
    Ok(())
}

fn create(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    if allocation(call, actor)?.is_some() {
        return report(
            call,
            store,
            "Can't Create an already created ActorFrameTexture",
        );
    }
    let value = field(call, actor, "__songlua_aft_capture_name")?;
    let name = textures::collapse(&assets::text(call, value)?);
    let actors = store.lock().unwrap().actor_order.clone();
    for other in actors {
        if let Some(allocation) = allocation(call, other)? {
            let value = field(call, allocation, "name")?;
            if assets::text(call, value)? == name {
                return report(
                    call,
                    store,
                    "ActorFrameTexture: Texture Name already in use.",
                );
            }
        }
        if let Some(path) = assets::texture_path(call, other)?
            && textures::collapse(&crate::file_path_string(&path)) == name
        {
            return report(
                call,
                store,
                "ActorFrameTexture: Texture Name already in use.",
            );
        }
    }
    let value = get(call, actor, b"__songlua_state_size")?;
    let requested = sprites::vector::<2>(call, value)?;
    {
        // Authored request vectors are also the native actor's render size.
        // The allocation takes a separate, truncated copy below.
        let mut store = store.lock().unwrap();
        let actor = store.actors.get_mut(&actor).unwrap();
        actor.state.size = requested.unwrap_or([1.0; 2]);
        actor.state.render.size = requested;
    }
    let size = requested.unwrap_or([1.0; 2]).map(f32::trunc);
    if size.iter().any(|v| !v.is_finite() || *v < 1.0) {
        return report(
            call,
            store,
            "ActorFrameTexture: Cannot have width or height less than 1",
        );
    }
    let allocation = call.try_new_table()?;
    call.with_roots(&[Value::Table(allocation)], |call| {
        let name = call.try_intern(name.as_bytes())?;
        set(call, allocation, "name", name)?;
        let size = sprites::vector_value(call, &size)?;
        set(call, allocation, "size", size)?;
        for key in [
            "__songlua_aft_alpha_buffer",
            "__songlua_aft_depth_buffer",
            "__songlua_aft_float_buffer",
        ] {
            let value = flag(call, actor, key)?;
            set(call, allocation, key, Value::Boolean(value))?;
        }
        let key = call.try_intern(b"__songlua_aft_allocation")?;
        call.raw_table_set(actor, key, Value::Table(allocation))?;
        messages::side_effect(call)?;
        immediate(call, store, actor, true, true)
    })
}

fn equal(call: &mut HostCall<'_>) -> Result<(), Error> {
    let left = table(call, arg(call, 0))?;
    let right = table(call, arg(call, 1))?;
    let left = get(call, left, b"__songlua_aft_capture_name")?;
    if left == Value::Nil {
        return call.push(Value::Boolean(false));
    }
    let left = assets::text(call, left)?;
    let right = get(call, right, b"__songlua_aft_capture_name")?;
    let result = right != Value::Nil && left == assets::text(call, right)?;
    call.push(Value::Boolean(result))
}

fn texture(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    if allocation(call, actor)?.is_none() {
        return call.push(Value::Nil);
    }
    let texture = call.try_new_table()?;
    call.with_roots(&[Value::Table(texture)], |call| {
        let kind = call.try_intern(b"RageTexture")?;
        set(call, texture, "__songlua_native_type", kind)?;
        if let Some(name) = capture_name(call, actor)? {
            let name = call.try_intern(name.as_bytes())?;
            set(call, texture, "__songlua_aft_capture_name", name)?;
        }
        let globals = table(call, helper(call, 5)?)?;
        let meta = get(call, globals, b"__songlua_aft_texture_meta")?;
        let meta = if meta == Value::Nil {
            let meta = call.try_new_table()?;
            call.with_roots(&[Value::Table(meta)], |call| {
                let equal = call.new_host_function(equal, &[])?;
                set(call, meta, "__eq", equal)?;
                let key = call.try_intern(b"__songlua_aft_texture_meta")?;
                call.raw_table_set(globals, key, Value::Table(meta))?;
                Ok(meta)
            })?
        } else {
            table(call, meta)?
        };
        let helpers = table(call, call.captures()[1])?;
        let setmetatable = get(call, helpers, b"setmetatable")?;
        call.call(setmetatable, &[Value::Table(texture), Value::Table(meta)])?;
        let allocation = field(call, actor, "__songlua_aft_allocation")?;
        let allocation = table(call, allocation)?;
        call.with_roots(&[Value::Table(allocation)], |call| {
            let size = field(call, allocation, "size")?;
            let size = table(call, size)?;
            let dimensions = call.with_roots(&[Value::Table(size)], |call| {
                let mut dimensions = [0.; 2];
                for (i, dimension) in dimensions.iter_mut().enumerate() {
                    let value = call.raw_table_get(size, Value::Number((i + 1) as f64))?;
                    *dimension = sprites::number(call, value)? as f32;
                }
                Ok(dimensions)
            })?;
            let value = field(call, allocation, "name")?;
            let path = textures::collapse(&assets::text(call, value)?);
            textures::install(
                call,
                store,
                actor,
                texture,
                textures::Info {
                    path,
                    source: dimensions,
                    image: dimensions,
                    allocation: dimensions
                        .map(|n| (n as u32).checked_next_power_of_two().unwrap_or(u32::MAX) as f32),
                    frames: 1,
                },
                (1, 1),
            )?;
            let captures = [
                call.captures()[0],
                call.captures()[1],
                Value::Table(actor),
                Value::Table(texture),
            ];
            for (name, begin) in [("BeginRenderingTo", true), ("FinishRenderingTo", false)] {
                let function = call.new_host_function_with_data(
                    render_target,
                    &captures,
                    TargetBinding {
                        store: store.clone(),
                        begin,
                    },
                )?;
                set(call, texture, name, function)?;
            }
            call.push(Value::Table(texture))
        })
    })
}

#[derive(Clone)]
struct TargetBinding {
    store: Shared,
    begin: bool,
}

fn render_target(call: &mut HostCall<'_>) -> Result<(), Error> {
    let TargetBinding { store, begin } = call.function_data::<TargetBinding>().unwrap().clone();
    let actor = table(call, call.captures()[2])?;
    if begin {
        let offset = usize::from(matches!(arg(call, 0), Value::Table(_)));
        let preserve = !matches!(arg(call, offset), Value::Nil | Value::Boolean(false));
        draw::begin(call, &store, actor, preserve)?;
    } else {
        draw::finish(call, &store, actor)?;
    }
    call.push(call.captures()[3])
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    match name {
        "Create" => create(call, store, actor)?,
        "GetTexture" => return texture(call, store, actor),
        "SetTextureName" => {
            let id = call
                .coerce_string(arg(call, 1))?
                .ok_or_else(|| call.error(b"SetTextureName: string expected"))?;
            set(call, actor, "__songlua_aft_capture_name", Value::String(id))?;
        }
        _ => {
            let Value::Boolean(value) = arg(call, 1) else {
                return Err(call.error(b"boolean expected"));
            };
            let key = match name {
                "EnableAlphaBuffer" => "__songlua_aft_alpha_buffer",
                "EnableDepthBuffer" => "__songlua_aft_depth_buffer",
                "EnableFloat" => "__songlua_aft_float_buffer",
                "EnablePreserveTexture" => {
                    immediate(call, store, actor, false, value)?;
                    return call.push(Value::Table(actor));
                }
                _ => unreachable!(),
            };
            set(call, actor, key, Value::Boolean(value))?;
        }
    }
    call.push(Value::Table(actor))
}

//! Outer state and output around the compiler's existing function-action probe.
use super::*;
use crate::rust_engine::function_snapshot::Snapshot;
use std::path::PathBuf;

const BROADCASTS: usize = 2;
const SOUNDS: usize = 4;
const ROOTS: usize = 6;
const GLOBALS: [&str; 3] = [
    crate::SONG_LUA_BROADCASTS_KEY,
    crate::SONG_LUA_SOUND_CALLS_KEY,
    crate::SONG_LUA_SUPPRESS_BROADCAST_KEY,
];
type Broadcasts = Vec<(String, bool)>;
#[derive(Default)]
struct State {
    columns: Vec<ColumnSnapshot>,
    before: i64,
    side_effects: i64,
    broadcasts: Option<Result<Broadcasts, Error>>,
    sounds: Option<Result<Vec<PathBuf>, Error>>,
}
struct ColumnSnapshot {
    player: TableId,
    field: Option<TableId>,
    columns: Option<TableId>,
    handlers: Vec<HandlerSnapshot>,
}
struct HandlerSnapshot {
    handler: TableId,
    spline: TableId,
    values: Vec<(&'static str, Value)>,
    spline_values: Vec<(&'static str, Value)>,
}
#[derive(Clone)]
pub(super) struct Scope {
    pub(super) retained: TableId,
    data: Arc<Mutex<State>>,
}
pub(in crate::rust_engine) struct Session {
    scope: Scope,
    pin: Root,
}
impl Session {
    pub(in crate::rust_engine) fn output(&self) -> Result<(Broadcasts, Vec<PathBuf>, i64), Error> {
        let mut state = self.scope.data.lock().unwrap();
        let broadcasts = state.broadcasts.take().unwrap()?;
        let sounds = state.sounds.take().unwrap()?;
        Ok((broadcasts, sounds, state.side_effects))
    }
    pub(in crate::rust_engine) fn release(self, vm: &mut Vm) -> Result<(), Error> {
        vm.unpin(self.pin)?;
        Ok(())
    }
}
impl Actors {
    pub(in crate::rust_engine) fn begin_column_capture(
        &self,
        vm: &mut Vm,
    ) -> Result<Session, Error> {
        let retained = vm.try_new_table()?;
        let pin = vm.pin(Value::Table(retained))?;
        let scope = Scope {
            retained,
            data: Arc::new(Mutex::new(State::default())),
        };
        let result = (|| {
            let roots = vm.try_new_table()?;
            vm.raw_table_set(retained, Value::Number(ROOTS as f64), Value::Table(roots))?;
            let setup = vm.new_host_function_with_data(
                |call| {
                    let scope = call.function_data::<Scope>().unwrap().clone();
                    let columns = snapshot_columns(call, &scope)?;
                    scope.data.lock().unwrap().columns = columns;
                    Ok(())
                },
                &[
                    Value::Table(self.registry),
                    Value::Table(self.helpers),
                    Value::Table(retained),
                ],
                scope.clone(),
            )?;
            vm.call(setup, &[])?;
            Ok(())
        })();
        if let Err(error) = result {
            vm.unpin(pin)?;
            return Err(error);
        }
        Ok(Session { scope, pin })
    }
    pub(in crate::rust_engine) fn restore_column_capture(
        &self,
        vm: &mut Vm,
        session: &Session,
    ) -> Result<(), Error> {
        let finish = vm.new_host_function_with_data(
            |call| {
                let scope = call.function_data::<Scope>().unwrap().clone();
                let columns = std::mem::take(&mut scope.data.lock().unwrap().columns);
                restore_columns(call, columns)
            },
            &[
                Value::Table(self.registry),
                Value::Table(self.helpers),
                Value::Table(session.scope.retained),
            ],
            session.scope.clone(),
        )?;
        vm.call(finish, &[])?;
        Ok(())
    }
    pub(in crate::rust_engine) fn snapshot_function_action(
        &self,
        vm: &mut Vm,
        function: Value,
    ) -> Result<Snapshot, Error> {
        Snapshot::capture_functions(vm, self.registry, &[function])
    }
    pub(in crate::rust_engine) fn begin_function_action(
        &self,
        vm: &mut Vm,
    ) -> Result<Session, Error> {
        let retained = vm.try_new_table()?;
        let pin = vm.pin(Value::Table(retained))?;
        let scope = Scope {
            retained,
            data: Arc::new(Mutex::new(State::default())),
        };
        let result = (|| {
            let roots = vm.try_new_table()?;
            vm.raw_table_set(retained, Value::Number(ROOTS as f64), Value::Table(roots))?;
            let setup = vm.new_host_function_with_data(
                setup,
                &[
                    Value::Table(self.registry),
                    Value::Table(self.helpers),
                    Value::Table(retained),
                ],
                scope.clone(),
            )?;
            vm.call(setup, &[])?;
            Ok(())
        })();
        if let Err(error) = result {
            vm.unpin(pin)?;
            return Err(error);
        }
        Ok(Session { scope, pin })
    }
    pub(in crate::rust_engine) fn capture_function_action(
        &self,
        vm: &mut Vm,
        actors: Vec<(usize, TableId)>,
        function: Value,
        random: &super::super::random::RandomState,
        session: &Session,
    ) -> (
        Result<super::super::SongActorFunctionBlocks, Error>,
        bool,
        Option<Root>,
    ) {
        self.capture_scoped_function(
            vm,
            actors,
            function,
            None,
            random,
            Some(session.scope.clone()),
        )
    }
}

pub(super) fn install(vm: &mut Vm, helpers: TableId) -> Result<(), Error> {
    let code = compile_named(
        br#"
        local type,next,rawset=type,next,rawset
        local function clone(value)
            if type(value)~='table' then return value end
            local result={}
            for key,item in next,value do rawset(result,clone(key),clone(item)) end
            return result
        end
        return clone
    "#,
        b"=function action column values",
    )?;
    let function = vm.execute(&code)?[0];
    super::super::put(vm, helpers, "function_action_clone", function)
}
fn global(call: &mut HostCall<'_>, name: &str) -> Result<Value, Error> {
    let key = call.try_intern(name.as_bytes())?;
    call.table_get(helper(call, 5)?, key)
}
fn field(call: &mut HostCall<'_>, actor: TableId, name: &str) -> Result<Value, Error> {
    sprites::field(call, actor, name)
}
fn optional_table(call: &HostCall<'_>, value: Value) -> Result<Option<TableId>, Error> {
    if value == Value::Nil {
        Ok(None)
    } else {
        table(call, value).map(Some)
    }
}
impl Scope {
    fn keep(&self, call: &mut HostCall<'_>, value: Value) -> Result<Value, Error> {
        if !matches!(value, Value::Nil | Value::Boolean(_) | Value::Number(_)) {
            let roots = table(
                call,
                call.raw_table_get(self.retained, Value::Number(ROOTS as f64))?,
            )?;
            call.raw_table_set(roots, value, Value::Boolean(true))?;
        }
        Ok(value)
    }
    fn copy(&self, call: &mut HostCall<'_>, value: Value) -> Result<Value, Error> {
        call.with_roots(&[value], |call| {
            let clone = native_children::helper_function(call, b"function_action_clone")?;
            let result = call.call(clone, &[value])?[0];
            self.keep(call, result)
        })
    }
    pub(super) fn before_actor_restore(&self, call: &mut HostCall<'_>) -> Result<(), Error> {
        // Output errors are reported only after all ordinary cleanup, matching
        // native. Column restoration precedes both side-effect measurement and
        // actor reset, so authored restoration callbacks retain that ordering.
        let broadcasts = table(
            call,
            call.raw_table_get(self.retained, Value::Number(BROADCASTS as f64))?,
        )?;
        let sounds = table(
            call,
            call.raw_table_get(self.retained, Value::Number(SOUNDS as f64))?,
        )?;
        let broadcasts = read_broadcasts(call, broadcasts);
        let sounds = read_paths(call, sounds);
        let columns = std::mem::take(&mut self.data.lock().unwrap().columns);
        restore_columns(call, columns)?;
        let count = side_effect_count(call)?;
        let mut state = self.data.lock().unwrap();
        state.broadcasts = Some(broadcasts);
        state.sounds = Some(sounds);
        state.side_effects = count.saturating_sub(state.before);
        Ok(())
    }
    pub(super) fn after_actor_restore(&self, call: &mut HostCall<'_>) -> Result<(), Error> {
        let globals = helper(call, 5)?;
        for (i, name) in GLOBALS.iter().enumerate() {
            let old = call.raw_table_get(self.retained, Value::Number((i * 2 + 1) as f64))?;
            let key = call.try_intern(name.as_bytes())?;
            call.table_set(globals, key, old)?;
        }
        Ok(())
    }
}
fn setup(call: &mut HostCall<'_>) -> Result<(), Error> {
    let scope = call.function_data::<Scope>().unwrap().clone();
    let before = side_effect_count(call)?;
    let columns = snapshot_columns(call, &scope)?;
    {
        let mut data = scope.data.lock().unwrap();
        data.before = before;
        data.columns = columns;
    }
    for (i, name) in GLOBALS.iter().enumerate() {
        let old = global(call, name)?;
        call.raw_table_set(scope.retained, Value::Number((i * 2 + 1) as f64), old)?;
        let next = if i == 2 {
            Value::Boolean(true)
        } else {
            Value::Table(call.try_new_table()?)
        };
        if i < 2 {
            call.raw_table_set(scope.retained, Value::Number((i * 2 + 2) as f64), next)?;
        }
        let key = call.try_intern(name.as_bytes())?;
        call.table_set(helper(call, 5)?, key, next)?;
    }
    Ok(())
}
fn snapshot_columns(call: &mut HostCall<'_>, scope: &Scope) -> Result<Vec<ColumnSnapshot>, Error> {
    let mut result = Vec::new();
    for name in [
        "__songlua_top_screen_player_1",
        "__songlua_top_screen_player_2",
    ] {
        let value = global(call, name)?;
        let value = scope.keep(call, value)?;
        let Some(player) = optional_table(call, value)? else {
            continue;
        };
        let key = call.try_intern(b"__songlua_children")?;
        let children = call.raw_table_get(player, key)?;
        let children = if call.raw_table_len(player)? == 0 {
            optional_table(call, children)?
        } else {
            None
        };
        let value = if let Some(children) = children {
            let key = call.try_intern(b"NoteField")?;
            call.raw_table_get(children, key)?
        } else {
            let named = native_children::named_children(call, player)?;
            call.with_roots(&[named], |call| {
                let named = table(call, named)?;
                field(call, named, "NoteField")
            })?
        };
        let value = scope.keep(call, value)?;
        let note_field = optional_table(call, value)?;
        let columns = if let Some(note_field) = note_field {
            let value = field(call, note_field, "__songlua_note_columns")?;
            let value = scope.keep(call, value)?;
            optional_table(call, value)?
        } else {
            None
        };
        let mut handlers = Vec::new();
        if let Some(columns) = columns {
            for i in 1usize.. {
                let value = call.raw_table_get(columns, Value::Number(i as f64))?;
                if value == Value::Nil {
                    break;
                }
                let value = scope.keep(call, value)?;
                let column = table(call, value)?;
                for key in [
                    "__songlua_pos_handler",
                    "__songlua_rot_handler",
                    "__songlua_zoom_handler",
                ] {
                    let value = field(call, column, key)?;
                    let value = scope.keep(call, value)?;
                    let Some(handler) = optional_table(call, value)? else {
                        continue;
                    };
                    let value = field(call, handler, "__songlua_spline")?;
                    let value = scope.keep(call, value)?;
                    let Some(spline) = optional_table(call, value)? else {
                        continue;
                    };
                    let mut values = Vec::new();
                    let mut spline_values = Vec::new();
                    for key in [
                        "__songlua_spline_mode",
                        "__songlua_subtract_song_beat",
                        "__songlua_receptor_t",
                        "__songlua_beats_per_t",
                    ] {
                        let value = field(call, handler, key)?;
                        values.push((key, scope.copy(call, value)?));
                    }
                    for key in [
                        "__songlua_spline_size",
                        "__songlua_spline_loop",
                        "__songlua_spline_points",
                    ] {
                        let value = field(call, spline, key)?;
                        let value = if key == "__songlua_spline_loop" {
                            scope.keep(call, value)?
                        } else {
                            scope.copy(call, value)?
                        };
                        spline_values.push((key, value));
                    }
                    handlers.push(HandlerSnapshot {
                        handler,
                        spline,
                        values,
                        spline_values,
                    });
                }
            }
        }
        result.push(ColumnSnapshot {
            player,
            field: note_field,
            columns,
            handlers,
        });
    }
    Ok(result)
}
fn restore_columns(call: &mut HostCall<'_>, columns: Vec<ColumnSnapshot>) -> Result<(), Error> {
    for saved in columns {
        let registry = native_children::helper_function(call, b"native_registry")?;
        let children = call.call(registry, &[Value::Table(saved.player)])?[0];
        call.with_roots(&[children], |call| {
            let key = call.try_intern(b"NoteField")?;
            call.table_set(children, key, saved.field.map_or(Value::Nil, Value::Table))?;
            if let Some(field) = saved.field {
                sprites::set(
                    call,
                    field,
                    "__songlua_note_columns",
                    saved.columns.map_or(Value::Nil, Value::Table),
                )?;
            }
            Ok(())
        })?;
        for handler in saved.handlers {
            for (key, value) in handler.values {
                sprites::set(call, handler.handler, key, value)?;
            }
            for (key, value) in handler.spline_values {
                sprites::set(call, handler.spline, key, value)?;
            }
        }
    }
    Ok(())
}
fn side_effect_count(call: &mut HostCall<'_>) -> Result<i64, Error> {
    let value = global(call, crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY)?;
    if value == Value::Nil {
        return Ok(0);
    }
    let result = Arc::new(Mutex::new(0_i64));
    let read = call.new_host_function_with_data(
        |call| {
            let result = call.function_data::<Arc<Mutex<i64>>>().unwrap().clone();
            let value = call.captures()[0];
            let count = {
                let mut stack = call.native_stack()?;
                stack.push(value)?;
                stack
                    .to_integer(-1)
                    .ok_or_else(|| stack.error(b"side-effect integer expected"))?
                    as i64
            };
            *result.lock().unwrap() = count;
            Ok(())
        },
        &[value],
        result.clone(),
    )?;
    call.call(read, &[])?;
    Ok(*result.lock().unwrap())
}
fn text(call: &mut HostCall<'_>, value: Value) -> Result<String, Error> {
    let id = call
        .coerce_string(value)?
        .ok_or_else(|| call.error(b"string expected"))?;
    std::str::from_utf8(call.string_bytes(id).unwrap())
        .map(str::to_owned)
        .map_err(|e| call.error(e.to_string().as_bytes()))
}
fn read_broadcasts(call: &mut HostCall<'_>, values: TableId) -> Result<Broadcasts, Error> {
    let mut result = Vec::new();
    for i in 1usize.. {
        let value = call.raw_table_get(values, Value::Number(i as f64))?;
        if value == Value::Nil {
            break;
        }
        call.with_roots(&[value], |call| {
            let entry = table(call, value)?;
            let message = field(call, entry, "message")?;
            if message == Value::Nil {
                return Ok(());
            }
            let message = text(call, message)?;
            let has_params = field(call, entry, "has_params")?.is_truthy();
            result.push((message, has_params));
            Ok(())
        })?;
    }
    Ok(result)
}
pub(super) fn read_paths(call: &mut HostCall<'_>, values: TableId) -> Result<Vec<PathBuf>, Error> {
    let mut result = Vec::new();
    for i in 1usize.. {
        let value = call.raw_table_get(values, Value::Number(i as f64))?;
        if value == Value::Nil {
            break;
        }
        result.push(PathBuf::from(text(call, value)?));
    }
    Ok(result)
}

//! Existing indexed actor-function capture used by compiler easing readers.
use super::super::SongActorFunctionBlocks;
use super::*;
use crate::tween_pose::TweenPose;

pub(super) struct Saved {
    pub(super) actor: TableId,
    pub(super) raw: TableId,
    state: ActorSnapshot,
    current: TweenPose,
    queue: VecDeque<TweenStep>,
    replay: Option<song_replay::State>,
    capture: Option<capture::Capture>,
    getters: Option<[f32; 4]>,
    hibernate: f32,
    rate: f32,
    effects: effects::State,
    wrappers: Vec<TableId>,
}
impl Saved {
    pub(super) fn read(store: &Shared, actor: TableId, raw: TableId) -> Option<Self> {
        let guard = store.lock().unwrap();
        let a = guard.actors.get(&actor)?;
        Some(Self {
            actor,
            raw,
            state: a.state.clone(),
            current: a.current,
            queue: a.queue.clone(),
            replay: a.replay.clone(),
            capture: a.capture.clone(),
            getters: a.preparation_getters,
            hibernate: a.hibernate,
            rate: a.update_rate,
            effects: a.effects,
            wrappers: a.wrappers.clone(),
        })
    }
    pub(super) fn restore(self, store: &Shared) {
        self.restore_inner(store, false);
    }
    pub(super) fn restore_mutable(self, store: &Shared) {
        self.restore_inner(store, true);
    }
    fn restore_inner(self, store: &Shared, retain_capture: bool) {
        let mut guard = store.lock().unwrap();
        let Some(a) = guard.actors.get_mut(&self.actor) else {
            return;
        };
        // Child attachment and parent changes are structural native mutations;
        // wrapper membership is explicitly part of semantic actor state.
        let children = std::mem::take(&mut a.state.children);
        let parent = a.state.parent;
        a.state = self.state;
        a.state.children = children;
        a.state.parent = parent;
        a.current = self.current;
        a.queue = self.queue;
        a.replay = self.replay;
        a.preparation_getters = self.getters;
        a.hibernate = self.hibernate;
        a.update_rate = self.rate;
        a.effects = self.effects;
        a.wrappers = self.wrappers;
        a.capture = self.capture;
        if !retain_capture {
            a.capture
                .get_or_insert_with(capture::Capture::default)
                .reset_blocks();
        }
    }
}
#[derive(Default)]
struct Output {
    saved: Vec<Saved>,
    blocks: SongActorFunctionBlocks,
    restored: bool,
}
#[derive(Clone)]
struct Run {
    store: Shared,
    actors: Vec<(usize, TableId)>,
    raw: bool,
    output: Arc<Mutex<Output>>,
}
impl Actors {
    pub(in crate::rust_engine) fn actor_function_capture_ready(&self) -> bool {
        let guard = self.store.lock().unwrap();
        guard.preparing
            && !guard.playback
            && !guard.clock.live.load(std::sync::atomic::Ordering::Relaxed)
    }
    pub(in crate::rust_engine) fn capture_actor_function(
        &self,
        vm: &mut Vm,
        actors: Vec<(usize, TableId)>,
        function: Value,
        arg: Option<f32>,
    ) -> (Result<SongActorFunctionBlocks, Error>, bool, Option<Root>) {
        let output = Arc::new(Mutex::new(Output::default()));
        let mut returned = None;
        let result = (|| {
            let retained = vm.try_new_table()?;
            let pin = vm.pin(Value::Table(retained))?;
            let result = (|| {
                let captures = [
                    Value::Table(self.registry),
                    Value::Table(self.helpers),
                    function,
                    Value::Table(retained),
                ]
                .into_iter()
                .chain(actors.iter().map(|(_, actor)| Value::Table(*actor)))
                .collect::<Vec<_>>();
                let mut data = Run {
                    store: self.store.clone(),
                    actors,
                    raw: false,
                    output: output.clone(),
                };
                let setup = vm.new_host_function_with_data(setup, &captures, data.clone())?;
                vm.call(setup, &[])?;
                // A failed Lua entry must finish before restoration begins. A
                // fatal instruction abort applies to its entire nested call tree.
                let args = arg
                    .map(|n| Value::Number(f64::from(n)))
                    .into_iter()
                    .collect::<Vec<_>>();
                let result = vm
                    .call(function, &args)
                    .map(|values| values.first().copied().unwrap_or(Value::Nil));
                // Native function.call::<Value> retains its first result
                // throughout actor restoration and the outer clock rewind.
                let result = result.and_then(|value| vm.pin(value).map(|pin| returned = Some(pin)));
                data.raw = result
                    .as_ref()
                    .err()
                    .is_some_and(|e| e.kind() != ErrorKind::Runtime);
                let finish = vm.new_host_function_with_data(finish, &captures, data)?;
                vm.call(finish, &[])?;
                result?;
                Ok(std::mem::take(&mut output.lock().unwrap().blocks))
            })();
            vm.unpin(pin)?;
            result
        })();
        let mut output = output.lock().unwrap();
        let restored = output.restored;
        output.saved.clear();
        if result.is_err() {
            output.blocks.clear();
        }
        (result, restored, returned)
    }
}

pub(super) fn reset(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    if let Some(a) = store.lock().unwrap().actors.get_mut(&actor) {
        a.capture
            .get_or_insert_with(capture::Capture::default)
            .reset_blocks();
    }
    for key in [
        "__songlua_capture_cursor",
        "__songlua_capture_duration",
        "__songlua_capture_tween_time_left",
    ] {
        song_replay::raw_set(call, actor, key, Value::Number(0.))?;
    }
    for key in [
        "__songlua_startup_queue_seconds",
        "__songlua_capture_easing",
        "__songlua_capture_opt1",
        "__songlua_capture_opt2",
        "__songlua_capture_block",
        "__songlua_capture_immediate_block",
    ] {
        song_replay::raw_set(call, actor, key, Value::Nil)?;
    }
    let blocks = call.try_new_table()?;
    song_replay::raw_set(
        call,
        actor,
        "__songlua_capture_blocks",
        Value::Table(blocks),
    )
}
fn setup(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Run>().unwrap().clone();
    let retained = table(call, call.captures()[3])?;
    let mut saved = Vec::new();
    for (i, (_, actor)) in data.actors.iter().enumerate() {
        let raw = state_snapshot::raw_copy(call, *actor)?;
        call.raw_table_set(retained, Value::Number((i + 1) as f64), Value::Table(raw))?;
        saved.push(
            Saved::read(&data.store, *actor, raw)
                .ok_or_else(|| call.error(b"capture actor is not owned by this runtime"))?,
        );
    }
    for (_, actor) in &data.actors {
        reset(call, &data.store, *actor)?;
    }
    data.output.lock().unwrap().saved = saved;
    Ok(())
}
fn finish(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Run>().unwrap().clone();
    let mut blocks = Vec::new();
    for (index, id) in &data.actors {
        if let Some(capture) = data
            .store
            .lock()
            .unwrap()
            .actors
            .get_mut(id)
            .and_then(|a| a.capture.as_mut())
        {
            let captured = capture.snapshot().blocks;
            if !captured.is_empty() {
                blocks.push((*index, captured));
            }
        }
    }
    for (_, actor) in &data.actors {
        reset(call, &data.store, *actor)?;
    }
    let saved = std::mem::take(&mut data.output.lock().unwrap().saved);
    for state in saved {
        state_snapshot::restore_raw(call, state.actor, state.raw, data.raw)?;
        state.restore(&data.store);
    }
    lifecycle::invalidate_plans(call, &data.store)?;
    let mut output = data.output.lock().unwrap();
    output.blocks = blocks;
    output.restored = true;
    Ok(())
}

