        key: "_VisualStyles/Thonk/GameplayIn minisplode",
        filename: "_VisualStyles/Thonk/GameplayIn minisplode (doubleres).png",
        bytes: include_bytes!(
            "../../../assets/simply-love/Graphics/_VisualStyles/Thonk/GameplayIn minisplode (doubleres).png"
        ),
        prepared: OnceLock::new(),
    },
    NativeGameplayInBitmap {
        key: "_VisualStyles/Thonk/GameplayIn splode",
        filename: "_VisualStyles/Thonk/GameplayIn splode (doubleres).png",
        bytes: include_bytes!(
            "../../../assets/simply-love/Graphics/_VisualStyles/Thonk/GameplayIn splode (doubleres).png"
        ),
        prepared: OnceLock::new(),
    },
];

pub(super) fn load(name: &str) -> Result<String, String> {
    let bitmap = NATIVE_GAMEPLAY_IN_BITMAPS
        .iter()
        .find(|bitmap| bitmap.key == name || bitmap.filename == name)
        .ok_or_else(|| format!("missing native gameplay-in bitmap: {name}"))?;
    bitmap
        .prepared
        .get_or_init(|| {
            let decoded =
                image::load_from_memory_with_format(bitmap.bytes, image::ImageFormat::Png)
                    .map_err(|error| error.to_string())?;
            let mut image = decoded.into_rgba8();
            let source_size = [image.width(), image.height()];
            let mut hints = deadlib_assets::parse_texture_hints(bitmap.filename);
            hints.min_size = Some(8);
            hints.max_size = Some(2048);
            let size = deadlib_assets::texture_image_size(source_size, &hints)
                .map_err(|error| error.to_string())?;
            if size != source_size {
                image = image::imageops::resize(
                    &image,
                    size[0],
                    size[1],
                    image::imageops::FilterType::Triangle,
                );
            }
            deadlib_assets::apply_texture_hints(&mut image, &hints);
            deadlib_assets::fix_hidden_alpha(&mut image);
            let path = format!("{}G/{}", crate::SONG_LUA_THEME_PATH_PREFIX, bitmap.filename);
            deadlib_assets::register_prepared_generated_texture(
                &path,
                image,
                source_size,
                hints.sampler_desc(),
            );
            Ok(path)
        })
        .as_ref()
        .cloned()
        .map_err(Clone::clone)
}

//! Bundled gameplay actors, loaded in the production host's separate phases.
use super::*;

mod overlay;
mod source;
mod underlay;

#[derive(Clone, Copy)]
pub(in crate::rust_engine) enum Phase {
    Combo,
    Underlay,
    Overlay { capture_probe: bool },
    Decorations,
    Transitions,
}

#[derive(Clone)]
struct Load {
    store: Shared,
    scene: u64,
    phase: Phase,
}

impl Actors {
    pub(in crate::rust_engine) fn load_gameplay_theme_phase(
        &self,
        vm: &mut Vm,
        scene: ActorScene,
        phase: Phase,
    ) -> Result<bool, Error> {
        if self.root(scene).is_none() {
            return Ok(false);
        }
        let function = vm.new_host_function_with_data(
            load,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Load {
                store: self.store.clone(),
                scene: scene.id,
                phase,
            },
        )?;
        vm.call(function, &[])?;
        Ok(true)
    }
}

fn load(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Load>().unwrap().clone();
    let first = data.store.lock().unwrap().next;
    let result = match data.phase {
        Phase::Combo => combo(call, &data),
        Phase::Underlay => song_capture::without_live_broadcasts(call, &data.store, |call| {
            underlay::load(call, &data)
        }),
        Phase::Overlay { capture_probe } => overlay::load(call, &data, capture_probe),
        Phase::Decorations => overlay::decorations(call, &data),
        Phase::Transitions => transitions(call, &data),
    };
    // Def/LoadFont concatenation can leave an implicit template owner behind.
    // Its callbacks share Lua upvalues with the loaded copy, and can therefore
    // retain the screen after Init stores an actor in one of those upvalues.
    // All objects constructed in this theme phase belong to its screen, even
    // when a file or callback fails before the returned root can be attached.
    let created = data
        .store
        .lock()
        .unwrap()
        .scenes
        .keys()
        .copied()
        .filter(|id| *id > first)
        .collect::<Vec<_>>();
    for scene in created {
        adopt_scene(&data, scene);
    }
    result?;
    lifecycle::invalidate_plans(call, &data.store)
}

fn field(call: &mut HostCall<'_>, actor: TableId, name: &str) -> Result<Value, Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        sprites::field(call, actor, name)
    })
}

fn set(call: &mut HostCall<'_>, actor: TableId, name: &str, value: Value) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor), value], |call| {
        let key = call.try_intern(name.as_bytes())?;
        call.raw_table_set(actor, key, value)
    })
}

fn parent(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    owner: TableId,
) -> Result<(), Error> {
    set(call, actor, "__songlua_parent", Value::Table(owner))?;
    if let Some(actor) = store.lock().unwrap().actors.get_mut(&actor) {
        actor.parent = Some(owner);
    }
    Ok(())
}

fn member(call: &mut HostCall<'_>, owner: TableId, name: &str) -> Result<TableId, Error> {
    let value = field(call, owner, name)?;
    table(call, value)
}

// Materialization owns a separate scene, including implicit offline Def owners.
// Transfer all members before Init: a callback may fail or replace a child, but
// the screen must still release every actor registered by this load.
fn own(call: &mut HostCall<'_>, data: &Load, definition: Value) -> Result<TableId, Error> {
    call.with_roots(&[definition], |call| {
        let scene = materialize(
            call,
            &data.store,
            table(call, definition)?,
            Materialization::Construct,
        )?;
        let actor = data.store.lock().unwrap().scenes[&scene]
            .root
            .expect("constructed actor root");
        adopt_scene(data, scene);
        Ok(actor)
    })
}

fn adopt_scene(data: &Load, scene: u64) {
    adopt_owned_scene(&data.store, data.scene, scene);
}

pub(super) fn adopt_owned_scene(store: &Shared, owner: u64, scene: u64) {
    if scene == owner {
        return;
    }
    let mut guard = store.lock().unwrap();
    guard.constructor_scenes.remove(&scene);
    let loaded = guard
        .scenes
        .remove(&scene)
        .expect("theme construction owner");
    for actor in loaded.actors {
        if !guard.scenes[&owner].actors.contains(&actor) {
            guard.scenes.get_mut(&owner).unwrap().actors.push(actor);
        }
        if guard.actors[&actor].scene == scene {
            guard.actors.get_mut(&actor).unwrap().scene = owner;
        }
    }
}

fn owned_lookup(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let kind = field(call, actor, "__songlua_actor_type")?;
    if kind != Value::Nil && assets::text(call, kind)?.eq_ignore_ascii_case("ActorFrame") {
        set(
            call,
            actor,
            "__songlua_owned_child_lookup",
            Value::Boolean(true),
        )?;
    }
    native_children::with_children(call, actor, owned_lookup)
}

fn combo(call: &mut HostCall<'_>, data: &Load) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let sl = member(call, globals, "SL")?;
    call.with_roots(&[Value::Table(sl)], |call| {
        // Native gameplay constructs explosions for both players, including a
        // disabled player's retained subtree. HideComboExplosions is Lua truthy.
        for index in 1..=crate::LUA_PLAYERS {
            let player = member(
                call,
                globals,
                &format!("__songlua_top_screen_player_{index}"),
            )?;
            let registry = native_children::helper_function(call, b"native_registry")?;
            let children = call.call(registry, &[Value::Table(player)])?[0];
            call.with_roots(&[children], |call| {
                let combo = member(call, table(call, children)?, "Combo")?;
                call.with_roots(&[Value::Table(combo)], |call| {
                    let mods = member(call, sl, &format!("P{index}"))?;
                    let mods = member(call, mods, "ActiveModifiers")?;
                    let kind = field(call, combo, "__songlua_actor_type")?;
                    let hidden = field(call, mods, "HideComboExplosions")?;
                    if kind == Value::Nil
                        || !assets::text(call, kind)?.eq_ignore_ascii_case("ActorFrame")
                        || !matches!(hidden, Value::Nil | Value::Boolean(false))
                    {
                        return Ok(());
                    }
                    let children = call.call(registry, &[Value::Table(combo)])?[0];
                    call.with_roots(&[children], |call| {
                        let children = table(call, children)?;
                        let number = member(call, children, "Number")?;
                        call.with_roots(&[Value::Table(number)], |call| {
                            for (ordinal, name, thousand) in [
                                (1, "OneHundredMilestone", false),
                                (2, "OneThousandMilestone", true),
                            ] {
                                let definition = load_combo(call, thousand)?;
                                let child = own(call, data, definition)?;
                                let name_value = call.try_intern(name.as_bytes())?;
                                set(call, child, "Name", name_value)?;
                                owned_lookup(call, child)?;
                                initialize(call, &data.store, child)?;
                                // Init runs while the milestone has no Combo parent.
                                parent(call, &data.store, child, combo)?;
                                call.raw_table_set(
                                    combo,
                                    Value::Number(ordinal as f64),
                                    Value::Table(child),
                                )?;
                                set(call, children, name, Value::Table(child))?;
                            }
                            call.raw_table_set(combo, Value::Number(3.), Value::Table(number))?;
                            let mut declared = Vec::new();
                            for index in 1.. {
                                match call.raw_table_get(combo, Value::Number(index as f64))? {
                                    Value::Nil => break,
                                    Value::Table(child) => declared.push(child),
                                    _ => {}
                                }
                            }
                            data.store
                                .lock()
                                .unwrap()
                                .actors
                                .get_mut(&combo)
                                .unwrap()
                                .children = declared;
                            Ok(())
                        })
                    })
                })
            })?;
        }
        Ok(())
    })
}

fn load_combo(call: &mut HostCall<'_>, thousand: bool) -> Result<Value, Error> {
    let globals = helper(call, 5)?;
    let environment = source::environment(call, globals, false)?;
    call.with_roots(&[environment], |call| {
        let loader = call.new_host_function(combo_resource, call.captures().to_vec().as_slice())?;
        set(call, table(call, environment)?, "LoadActor", loader)?;
        source::evaluate(
            call,
            if thousand {
                source::THOUSAND
            } else {
                source::HUNDRED
            },
            environment,
            &[],
        )
    })
}

fn combo_resource(call: &mut HostCall<'_>) -> Result<(), Error> {
    let path = assets::text(call, arg(call, 0))?;
    if path == "../Combo 100milestone" {
        let value = load_combo(call, false)?;
        return call.push(value);
    }
    let key = if path == "explosion.png" {
        "Combo 100milestone/explosion.png"
    } else {
        path.strip_prefix(crate::SONG_LUA_THEME_PATH_PREFIX)
            .and_then(|p| p.strip_prefix("G/"))
            .unwrap_or(&path)
    };
    let path = gameplay_bitmaps::load(key).map_err(|error| call.error(error.as_bytes()))?;
    let definition = call.try_new_table()?;
    call.with_roots(&[Value::Table(definition)], |call| {
        let path = call.try_intern(path.as_bytes())?;
        set(call, definition, "Texture", path)?;
        let globals = table(call, helper(call, 5)?)?;
        let def = member(call, globals, "Def")?;
        let function = field(call, def, "Sprite")?;
        call.call_and_return(function, &[Value::Table(definition)])
    })
}

fn transitions(call: &mut HostCall<'_>, data: &Load) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let top = get(call, globals, b"__songlua_top_screen")?;
    let top = table(call, top)?;
    native_children::with_children(call, top, |call, wrapper| {
        let role = get(call, wrapper, b"__songlua_screen_actor_role")?;
        if role == Value::Nil {
            return Ok(());
        }
        let source = match assets::text(call, role)?.as_str() {
            "Toasty" => source::TOASTY,
            "NextSong" => source::NEXT_SONG,
            "Ready" | "Go" | "Failed" => source::BLANK,
            _ => return Ok(()),
        };
        let definition = source::evaluate(call, source, Value::Table(globals), &[])?;
        let child = own(call, data, definition)?;
        set(
            call,
            wrapper,
            "__songlua_transition_child",
            Value::Table(child),
        )?;
        parent(call, &data.store, child, wrapper)?;
        let mut found = false;
        for i in 1..=call.raw_table_len(wrapper)? {
            found |= call.raw_table_get(wrapper, Value::Number(i as f64))? == Value::Table(child);
        }
        if !found {
            call.raw_table_set(
                wrapper,
                Value::Number((call.raw_table_len(wrapper)? + 1) as f64),
                Value::Table(child),
            )?;
            data.store
                .lock()
                .unwrap()
                .actors
                .get_mut(&wrapper)
                .unwrap()
                .children
                .push(child);
        }
        let registry = native_children::helper_function(call, b"native_registry")?;
        let registry = call.call(registry, &[Value::Table(wrapper)])?[0];
        call.with_roots(&[registry], |call| {
            set(call, table(call, registry)?, "", Value::Table(child))
        })?;
        let visible = field(call, wrapper, "visible")?;
        call.call(visible, &[Value::Table(wrapper), Value::Boolean(true)])?;
        owned_lookup(call, wrapper)?;
        initialize(call, &data.store, child)
    })
}

//! Original overlay logic and screen decorations, in native replacement order.
use super::*;
use underlay::{command, named, registry};

const ENVIRONMENT: &[u8] = b"__songlua_overlay_environment";

fn resource(call: &mut HostCall<'_>) -> Result<(), Error> {
    let path = assets::text(call, arg(call, 0))
        .map_err(|_| call.error(b"native LoadActor requires a path"))?;
    let globals = table(call, helper(call, 5)?)?;
    let environment = get(call, globals, ENVIRONMENT)?;
    table(call, environment)?;
    let arguments = call.arguments().iter().skip(1).copied().collect::<Vec<_>>();
    let value = evaluate(call, environment, &path, &arguments)?;
    call.push(value)
}

fn evaluate(
    call: &mut HostCall<'_>,
    environment: Value,
    path: &str,
    arguments: &[Value],
) -> Result<Value, Error> {
    let name = path.strip_prefix("./").unwrap_or(path);
    let source = source::overlay(name)
        .ok_or_else(|| call.error(format!("unknown native Overlay resource {path}").as_bytes()))?;
    source::evaluate(call, source, environment, arguments)
}

fn order(call: &mut HostCall<'_>, actor: TableId) -> Result<i32, Error> {
    let value = get(call, actor, b"__songlua_state_draw_order")?;
    if value == Value::Nil {
        return Ok(0);
    }
    let value = sprites::number(call, value)?.trunc();
    if !(i32::MIN as f64..=i32::MAX as f64).contains(&value) {
        return Err(call.error(b"draw order out of range"));
    }
    Ok(value as i32)
}

fn replace(
    call: &mut HostCall<'_>,
    data: &Load,
    screen: TableId,
    previous: TableId,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    for index in 1..=call.raw_table_len(screen)? {
        let key = Value::Number(index as f64);
        if call.raw_table_get(screen, key)? == Value::Table(previous) {
            call.raw_table_set(screen, key, Value::Table(actor))?;
        }
    }
    let children = registry(call, screen)?;
    call.with_roots(&[children], |call| {
        set(call, table(call, children)?, name, Value::Table(actor))
    })?;
    for child in &mut data
        .store
        .lock()
        .unwrap()
        .actors
        .get_mut(&screen)
        .unwrap()
        .children
    {
        if *child == previous {
            *child = actor;
        }
    }
    Ok(())
}

pub(super) fn load(call: &mut HostCall<'_>, data: &Load, capture_probe: bool) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let environment = source::environment(call, Value::Table(globals), true)?;
    call.with_roots(&[environment], |call| {
        let key = call.try_intern(ENVIRONMENT)?;
        call.raw_table_set(globals, key, environment)?;
        let captures = call.captures().to_vec();
        let loader = call.new_host_function(resource, &captures)?;
        set(call, table(call, environment)?, "LoadActor", loader)?;
        let definition = evaluate(call, environment, "default.lua", &[])?;
        let actor = own(call, data, definition)?;
        let screen = get(call, globals, b"__songlua_top_screen")?;
        let screen = table(call, screen)?;
        let overlay = named(call, screen, "Overlay")?;
        if capture_probe {
            parent(call, &data.store, actor, overlay)?;
            screen_parts::append(call, &data.store, overlay, actor)?;
            let children = registry(call, overlay)?;
            set(call, table(call, children)?, "", Value::Table(actor))?;
        } else {
            parent(call, &data.store, actor, screen)?;
            let name = call.try_intern(b"Overlay")?;
            call.with_roots(&[name], |call| {
                if get(call, actor, b"__songlua_load_name")? != Value::Nil {
                    set(call, actor, "__songlua_load_name", name)?;
                }
                set(call, actor, "__songlua_native_name", name)?;
                set(call, actor, "Name", name)?;
                set(call, actor, "__songlua_top_screen_child_name", name)
            })?;
            let order = order(call, overlay)?;
            set(
                call,
                actor,
                "__songlua_state_draw_order",
                Value::Number(order as f64),
            )?;
            {
                let mut guard = data.store.lock().unwrap();
                let state = &mut guard.actors.get_mut(&actor).unwrap().state;
                state.name = b"Overlay".to_vec();
                state.draw_order = order;
                state.render.draw_order = order;
            }
            replace(call, data, screen, overlay, actor, "Overlay")?;
        }
        owned_lookup(call, actor)?;
        initialize(call, &data.store, actor)?;
        command(call, actor, b"BeginCommand")?;
        command(call, actor, b"OnCommand")?;
        if capture_probe {
            // The diagnostic probe uses ActorDefinitionHost, which the native
            // host installs only in live mode. Its error occurs after On and
            // leaves the loaded theme attached to the original wrapper.
            let live = data
                .store
                .lock()
                .unwrap()
                .clock
                .live
                .load(std::sync::atomic::Ordering::Relaxed);
            if !live {
                return Err(call.error(b"Overlay requires its actor host"));
            }
            let probe = generated_players::dummy(
                call,
                &data.store,
                data.scene,
                "ActorFrame",
                "ITGmaniaHarnessTraceProbe",
                Some(overlay),
            )?;
            screen_parts::append(call, &data.store, overlay, probe)?;
            let children = registry(call, overlay)?;
            set(
                call,
                table(call, children)?,
                "ITGmaniaHarnessTraceProbe",
                Value::Table(probe),
            )?;
        }
        Ok(())
    })
}

fn screen_string(call: &mut HostCall<'_>) -> Result<(), Error> {
    let name = call.function_data::<String>().unwrap().clone();
    let key = assets::text(call, arg(call, 0))?;
    let text = crate::theme_string(&name, &key);
    let text = call.try_intern(text.as_bytes())?;
    call.push(text)
}

pub(super) fn decorations(call: &mut HostCall<'_>, data: &Load) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let screen = get(call, globals, b"__songlua_top_screen")?;
    let screen = table(call, screen)?;
    let name = actor_name(call, &data.store, screen)?;
    let name =
        String::from_utf8(name).map_err(|_| call.error(b"screen name must be valid UTF-8"))?;
    let environment = source::environment(call, Value::Table(globals), false)?;
    call.with_roots(&[environment], |call| {
        let function = call.new_host_function_with_data(screen_string, &[], name)?;
        set(call, table(call, environment)?, "ScreenString", function)?;
        for (name, source) in [("Header", source::HEADER), ("Footer", source::FOOTER)] {
            let definition = source::evaluate(call, source, environment, &[])?;
            let actor = own(call, data, definition)?;
            let previous = named(call, screen, name)?;
            parent(call, &data.store, actor, screen)?;
            owned_lookup(call, actor)?;
            initialize(call, &data.store, actor)?;
            let on = source::evaluate(call, source::DECORATION_ON, Value::Table(globals), &[])?;
            set(call, actor, "OnCommand", on)?;
            replace(call, data, screen, previous, actor, name)?;
            command(call, actor, b"BeginCommand")?;
            command(call, actor, b"OnCommand")?;
        }
        let mut children = Vec::new();
        for index in 1.. {
            let child = call.raw_table_get(screen, Value::Number(index as f64))?;
            if child == Value::Nil {
                break;
            }
            let child = table(call, child)?;
            children.push((order(call, child).unwrap_or(0), child));
        }
        children.sort_by_key(|&(order, _)| order);
        for (index, &(_, child)) in children.iter().enumerate() {
            call.raw_table_set(
                screen,
                Value::Number((index + 1) as f64),
                Value::Table(child),
            )?;
        }
        data.store
            .lock()
            .unwrap()
            .actors
            .get_mut(&screen)
            .unwrap()
            .children = children.into_iter().map(|(_, child)| child).collect();
        Ok(())
    })
}

//! Fresh chunks preserve the bundled source's filename, lines and environment.
use super::*;
use deadlib_lua::NativeLoadStatus;

#[derive(Clone, Copy)]
pub(super) struct Source {
    bytes: &'static [u8],
    name: &'static [u8],
}

macro_rules! bundled {
    ($path:literal) => {
        Source {
            bytes: include_bytes!(concat!("../../../../assets/simply-love/", $path)),
            name: concat!("@theme:/", $path).as_bytes(),
        }
    };
}

pub(super) const HUNDRED: Source = bundled!("Graphics/Combo 100milestone/default.lua");
pub(super) const THOUSAND: Source = bundled!("Graphics/Combo 1000milestone/default.lua");
pub(super) const TOASTY: Source = bundled!("BGAnimations/ScreenGameplay toasty.lua");
pub(super) const NEXT_SONG: Source =
    bundled!("BGAnimations/ScreenGameplay next course song/default.lua");
pub(super) const BLANK: Source = Source {
    bytes: b"return Def.Actor{};",
    name: b"@theme:/BGAnimations/_blank.lua",
};

pub(super) fn evaluate(
    call: &mut HostCall<'_>,
    source: Source,
    environment: Value,
    arguments: &[Value],
) -> Result<Value, Error> {
    let mut values = Vec::with_capacity(arguments.len() + 1);
    values.push(environment);
    values.extend_from_slice(arguments);
    call.with_roots(&values, |call| {
        let loader = call.new_host_function_with_data(evaluate_callback, &[], source)?;
        Ok(call.call(loader, &values)?[0])
    })
}

fn evaluate_callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let source = *call.function_data::<Source>().unwrap();
    let mut stack = call.native_stack()?;
    let count = stack.top();
    if stack.load_buffer(source.bytes, Some(source.name))? != NativeLoadStatus::Ok {
        return Err(stack.raise(stack.value(-1).unwrap()));
    }
    stack.push(stack.value(1).unwrap())?;
    stack.set_environment(-2)?;
    for index in 2..=count {
        stack.push(stack.value(index as isize).unwrap())?;
    }
    stack.call(count - 1, Some(1))?;
    stack.finish(1)
}

pub(super) fn environment(
    call: &mut HostCall<'_>,
    globals: Value,
    forward_writes: bool,
) -> Result<Value, Error> {
    let factory =
        call.new_host_function_with_data(environment_callback, &[globals], forward_writes)?;
    Ok(call.call(factory, &[])?[0])
}

fn environment_callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let globals = call.captures()[0];
    let forward = *call.function_data::<bool>().unwrap();
    let mut stack = call.native_stack()?;
    stack.create_table(0, 1)?;
    stack.create_table(0, 2)?;
    stack.push(globals)?;
    stack.set_field(-2, b"__index")?;
    if forward {
        stack.push(globals)?;
        stack.set_field(-2, b"__newindex")?;
    }
    stack.set_metatable(-2)?;
    stack.finish(1)
}

