//! Original gameplay underlay files and their native load/Init/message order.
use super::*;

const ENVIRONMENT: &[u8] = b"__songlua_step_statistics_environment";

fn invoke(
    call: &mut HostCall<'_>,
    owner: TableId,
    name: &str,
    args: &[Value],
) -> Result<Value, Error> {
    call.with_roots(&[Value::Table(owner)], |call| {
        let function = field(call, owner, name)?;
        let mut values = Vec::with_capacity(args.len() + 1);
        values.push(Value::Table(owner));
        values.extend_from_slice(args);
        Ok(call
            .call(function, &values)?
            .first()
            .copied()
            .unwrap_or(Value::Nil))
    })
}

pub(super) fn registry(call: &mut HostCall<'_>, actor: TableId) -> Result<Value, Error> {
    let function = native_children::helper_function(call, b"native_registry")?;
    Ok(call.call(function, &[Value::Table(actor)])?[0])
}

pub(super) fn named(call: &mut HostCall<'_>, actor: TableId, name: &str) -> Result<TableId, Error> {
    let children = registry(call, actor)?;
    call.with_roots(&[children], |call| {
        let value = get(call, table(call, children)?, name.as_bytes())?;
        table(call, value)
    })
}

fn environment(call: &mut HostCall<'_>) -> Result<Value, Error> {
    let globals = table(call, helper(call, 5)?)?;
    let existing = get(call, globals, ENVIRONMENT)?;
    if existing != Value::Nil {
        table(call, existing)?;
        return Ok(existing);
    }
    let environment = source::environment(call, Value::Table(globals), true)?;
    call.with_roots(&[environment], |call| {
        let key = call.try_intern(ENVIRONMENT)?;
        call.raw_table_set(globals, key, environment)?;
        let captures = call.captures().to_vec();
        let loader = call.new_host_function(step_resource, &captures)?;
        set(call, table(call, environment)?, "LoadActor", loader)?;
        source::evaluate(call, source::HISTOGRAM, environment, &[])?;
        Ok(environment)
    })
}

fn step_resource(call: &mut HostCall<'_>) -> Result<(), Error> {
    let path = assets::text(call, arg(call, 0))
        .map_err(|_| call.error(b"native LoadActor requires a path"))?;
    let globals = table(call, helper(call, 5)?)?;
    let environment = get(call, globals, ENVIRONMENT)?;
    table(call, environment)?;
    let args = call.arguments().iter().skip(1).copied().collect::<Vec<_>>();
    let value = step(call, environment, &path, &args)?;
    call.push(value)
}

fn step(
    call: &mut HostCall<'_>,
    environment: Value,
    path: &str,
    args: &[Value],
) -> Result<Value, Error> {
    let name = path.strip_prefix("./").unwrap_or(path);
    let source = source::statistics(name).ok_or_else(|| {
        call.error(format!("unknown native StepStatistics resource {path}").as_bytes())
    })?;
    source::evaluate(call, source, environment, args)
}

fn note_field(call: &mut HostCall<'_>, path: &str, args: &[Value]) -> Result<Value, Error> {
    let source = source::note_field(path)
        .ok_or_else(|| call.error(format!("unknown native NoteField actor {path}").as_bytes()))?;
    let globals = helper(call, 5)?;
    let environment = source::environment(call, globals, true)?;
    call.with_roots(&[environment], |call| {
        let directory = path
            .rsplit_once('/')
            .map_or_else(String::new, |(parent, _)| format!("{parent}/"));
        let captures = call.captures().to_vec();
        let loader = call.new_host_function_with_data(note_resource, &captures, directory)?;
        set(call, table(call, environment)?, "LoadActor", loader)?;
        source::evaluate(call, source, environment, args)
    })
}

fn note_resource(call: &mut HostCall<'_>) -> Result<(), Error> {
    let directory = call.function_data::<String>().unwrap().clone();
    let child = assets::text(call, arg(call, 0))
        .map_err(|_| call.error(b"native NoteField LoadActor requires a path"))?;
    let args = call.arguments().iter().skip(1).copied().collect::<Vec<_>>();
    let path = format!("{directory}{}", child.trim_start_matches("./"));
    let value = note_field(call, &path, &args)?;
    call.push(value)
}

fn player(call: &HostCall<'_>, value: Value) -> Option<usize> {
    match value {
        Value::Number(value)
            if value >= 0. && value < crate::LUA_PLAYERS as f64 && value.fract() == 0. =>
        {
            Some(value as usize)
        }
        Value::String(id) => {
            let bytes = call.string_bytes(id)?;
            [b"P1".as_slice(), b"P2"]
                .iter()
                .position(|name| bytes.eq_ignore_ascii_case(name))
                .or_else(|| {
                    [b"PlayerNumber_P1".as_slice(), b"PlayerNumber_P2"]
                        .iter()
                        .position(|name| bytes.eq_ignore_ascii_case(name))
                })
        }
        _ => None,
    }
}

fn attach(
    call: &mut HostCall<'_>,
    data: &Load,
    underlay: TableId,
    definition: Value,
    lookup: bool,
    name: Option<&str>,
) -> Result<TableId, Error> {
    let actor = own(call, data, definition)?;
    parent(call, &data.store, actor, underlay)?;
    initialize(call, &data.store, actor)?;
    if lookup {
        owned_lookup(call, actor)?;
    }
    let name = match name {
        Some(name) => name.as_bytes().to_vec(),
        None => actor_name(call, &data.store, actor)?,
    };
    let children = registry(call, underlay)?;
    call.with_roots(&[children], |call| {
        let key = call.try_intern(&name)?;
        call.raw_table_set(table(call, children)?, key, Value::Table(actor))
    })?;
    let count = call.raw_table_len(underlay)?;
    let mut found = false;
    for index in 1..=count {
        found |= call.raw_table_get(underlay, Value::Number(index as f64))? == Value::Table(actor);
    }
    if !found {
        call.raw_table_set(
            underlay,
            Value::Number((count + 1) as f64),
            Value::Table(actor),
        )?;
        data.store
            .lock()
            .unwrap()
            .actors
            .get_mut(&underlay)
            .unwrap()
            .children
            .push(actor);
    }
    Ok(actor)
}

// These theme phases call the raw Begin/On handlers directly, without the
// authored playcommand wrapper. Enumerate children after each parent callback.
pub(super) fn command(call: &mut HostCall<'_>, actor: TableId, name: &[u8]) -> Result<(), Error> {
    let callback = get(call, actor, name)?;
    if callback != Value::Nil {
        if !matches!(callback, Value::Function(_) | Value::Native(_)) {
            return Err(call.error(b"theme actor command must be a function"));
        }
        call.call(callback, &[Value::Table(actor)])?;
    }
    native_children::with_children(call, actor, |call, child| command(call, child, name))
}

pub(super) fn load(call: &mut HostCall<'_>, data: &Load) -> Result<(), Error> {
    let environment = environment(call)?;
    call.with_roots(&[environment], |call| {
        let globals = table(call, helper(call, 5)?)?;
        let screen = get(call, globals, b"__songlua_top_screen")?;
        let screen = table(call, screen)?;
        let underlay = named(call, screen, "Underlay")?;
        let game = member(call, globals, "GAMESTATE")?;
        let players = invoke(call, game, "GetHumanPlayers", &[])?;
        table(call, players)?;
        call.with_roots(&[players], |call| {
            data.store
                .lock()
                .unwrap()
                .startup_queues
                .get_or_insert_with(Vec::new);
            source::evaluate(call, source::UTF8, Value::Table(globals), &[])?;
            source::evaluate(call, source::TEXT_HELPERS, Value::Table(globals), &[])?;
            steps_displays::initialize(call, &data.store, screen)?;
            for index in 1.. {
                let value =
                    call.raw_table_get(table(call, players)?, Value::Number(index as f64))?;
                if value == Value::Nil {
                    break;
                }
                let Some(player) = player(call, value) else {
                    continue;
                };
                let child = named(call, screen, &format!("PlayerOptionsP{}", player + 1))?;
                let game = member(call, globals, "GAMESTATE")?;
                let state = invoke(call, game, "GetPlayerState", &[value])?;
                call.with_roots(&[state], |call| {
                    let level = call.try_intern(b"ModsLevel_Current")?;
                    let text = invoke(
                        call,
                        table(call, state)?,
                        "GetPlayerOptionsString",
                        &[level],
                    )?;
                    let text = assets::text(call, text)?;
                    let text = call.try_intern(text.as_bytes())?;
                    set(call, child, "Text", text)
                })?;
            }
            let mut panes = Vec::new();
            for index in 1.. {
                let player =
                    call.raw_table_get(table(call, players)?, Value::Number(index as f64))?;
                if player == Value::Nil {
                    break;
                }
                let danger =
                    source::evaluate(call, source::DANGER, Value::Table(globals), &[player])?;
                if danger != Value::Nil {
                    panes.push(attach(call, data, underlay, danger, false, None)?);
                }
                let pane = step(call, environment, "default.lua", &[player])?;
                if pane != Value::Nil {
                    panes.push(attach(call, data, underlay, pane, true, None)?);
                }
                let container = note_field(call, "default.lua", &[player])?;
                panes.push(attach(call, data, underlay, container, true, None)?);
            }
            let meter = source::evaluate(call, source::SONG_INFO, Value::Table(globals), &[])?;
            panes.push(attach(
                call,
                data,
                underlay,
                meter,
                true,
                Some("SongMeter"),
            )?);
            reorder(call, data, underlay)?;
            set(
                call,
                underlay,
                "__songlua_owned_child_lookup",
                Value::Boolean(true),
            )?;
            for &pane in &panes {
                command(call, pane, b"BeginCommand")?;
            }
            for &pane in &panes {
                command(call, pane, b"OnCommand")?;
            }
            // Keep normal listener delivery; this internal song-change event
            // does not record an authored Broadcast or increment its counter.
            messages::dispatch(call, &data.store, b"CurrentSongChanged", None, false)
        })
    })
}

fn reorder(call: &mut HostCall<'_>, data: &Load, underlay: TableId) -> Result<(), Error> {
    const ORDER: &[&[u8]] = &[
        b"DangerP1",
        b"StepStatsPaneP1",
        b"filter0",
        b"DangerP2",
        b"StepStatsPaneP2",
        b"filter1",
        b"Header",
        b"SongMeter",
        b"P1Score",
        b"difficulty0",
        b"life0",
        b"NoteFieldContainerP1",
        b"P2Score",
        b"difficulty1",
        b"life1",
        b"NoteFieldContainerP2",
        b"bpm",
    ];
    let mut children = Vec::new();
    native_children::with_children(call, underlay, |call, child| {
        let name = actor_name(call, &data.store, child).unwrap_or_default();
        let role = get(call, child, b"__songlua_underlay_role")
            .ok()
            .and_then(|value| {
                if value == Value::Nil {
                    None
                } else {
                    assets::text(call, value).ok()
                }
            });
        let name = role
            .as_ref()
            .map_or(name.as_slice(), |role| role.as_bytes());
        let rank = ORDER.iter().position(|&role| name == role).unwrap_or(99);
        children.push((rank, child));
        Ok(())
    })?;
    children.sort_by_key(|&(rank, _)| rank);
    for (index, &(_, child)) in children.iter().enumerate() {
        call.raw_table_set(
            underlay,
            Value::Number((index + 1) as f64),
            Value::Table(child),
        )?;
    }
    data.store
        .lock()
        .unwrap()
        .actors
        .get_mut(&underlay)
        .unwrap()
        .children = children.into_iter().map(|(_, child)| child).collect();
    Ok(())
}

//! ScreenGameplay's engine player constructor and life-meter bindings.
//! The player Init phase attaches its visible parts in this same scene.
use super::*;
use sprites::{field, set};

type Statistics = Arc<Mutex<super::super::statistics::State>>;

#[derive(Clone)]
pub(super) struct Build {
    store: Shared,
    statistics: Statistics,
    player: crate::SongLuaPlayerContext,
    index: usize,
    style: String,
    parts: bool,
}
#[derive(Clone)]
struct Method {
    store: Shared,
    statistics: Statistics,
    index: usize,
    name: &'static str,
}

impl Actors {
    // This is the Player constructor phase, before ScreenGameplay::Init attaches
    // its visible parts. Keep it private until the complete screen factory uses it.
    pub(in crate::rust_engine) fn player_base(
        &self,
        vm: &mut Vm,
        context: &crate::SongLuaCompileContext,
        index: usize,
        statistics: Statistics,
        catalog: Value,
    ) -> Result<ActorScene, Error> {
        self.player(vm, context, (index, false), statistics, catalog)
    }

    pub(in crate::rust_engine) fn gameplay_player(
        &self,
        vm: &mut Vm,
        context: &crate::SongLuaCompileContext,
        index: usize,
        statistics: Statistics,
        catalog: Value,
    ) -> Result<ActorScene, Error> {
        self.player(vm, context, (index, true), statistics, catalog)
    }

    fn player(
        &self,
        vm: &mut Vm,
        context: &crate::SongLuaCompileContext,
        (index, parts): (usize, bool),
        statistics: Statistics,
        catalog: Value,
    ) -> Result<ActorScene, Error> {
        let Some(player) = context.players.get(index) else {
            return vm.with_native_stack(|stack| {
                Err(stack.error(b"gameplay player index out of range"))
            });
        };
        let function = vm.new_host_function_with_data(
            construct,
            &[
                Value::Table(self.registry),
                Value::Table(self.helpers),
                catalog,
            ],
            Build {
                store: self.store.clone(),
                statistics,
                player: player.clone(),
                index,
                style: context.style_name.clone(),
                parts,
            },
        )?;
        let Value::Number(id) = vm.call(function, &[])?[0] else {
            unreachable!()
        };
        Ok(ActorScene {
            owner: self.instantiate,
            id: id as u64,
        })
    }
}

impl Build {
    pub(super) fn new(
        store: Shared,
        statistics: Statistics,
        context: &crate::SongLuaCompileContext,
        index: usize,
    ) -> Self {
        Self {
            store,
            statistics,
            player: context.players[index].clone(),
            index,
            style: context.style_name.clone(),
            parts: false,
        }
    }
    fn method(&self) -> Method {
        Method {
            store: self.store.clone(),
            statistics: self.statistics.clone(),
            index: self.index,
            name: "",
        }
    }
    pub(super) fn create_meter(&self, call: &mut HostCall<'_>, id: u64) -> Result<TableId, Error> {
        let store = self.store.clone();
        let method = self.method();
        let meter = dummy(
            call,
            &store,
            id,
            "LifeMeter",
            &format!("LifeP{}", method.index + 1),
            None,
        )?;
        set(
            call,
            meter,
            "__songlua_life",
            Value::Number(crate::SONG_LUA_INITIAL_LIFE as f64),
        )?;
        for name in ["GetLife", "IsFailing", "IsHot", "IsInDanger"] {
            bind(call, meter, &method, name)?;
        }
        // The native internal LifeMeter keeps its bound child queries even
        // though its public method class is Actor, not ActorFrame.
        top_screen::bind_queries(call, meter)?;
        Ok(meter)
    }
    pub(super) fn create_player(&self, call: &mut HostCall<'_>, id: u64) -> Result<TableId, Error> {
        let store = self.store.clone();
        let method = self.method();
        let player = &self.player;
        let style = &self.style;
        let actor = dummy(
            call,
            &store,
            id,
            "PlayerActor",
            &format!("PlayerP{}", method.index + 1),
            None,
        )?;
        set(
            call,
            actor,
            "__songlua_player_index",
            Value::Number(method.index as f64),
        )?;
        let style_value = call.try_intern(style.as_bytes())?;
        set(call, actor, "__songlua_style_name", style_value)?;
        set(call, actor, "__songlua_visible", Value::Boolean(true))?;
        for name in ["get_oitg_zoom_mode", "set_oitg_zoom_mode", "SetLife"] {
            bind(call, actor, &method, name)?;
        }
        let attack = dummy(call, &store, id, "ActorFrame", "", Some(actor))?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&attack)
            .unwrap()
            .current
            .x = -40.;
        call.raw_table_set(actor, Value::Number(1.), Value::Table(attack))?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .children
            .push(attack);
        native_children::insert(call, actor, "", Value::Table(attack))?;
        set(
            call,
            actor,
            "__songlua_attack_display",
            Value::Table(attack),
        )?;
        {
            let mut guard = store.lock().unwrap();
            let pose = &mut guard.actors.get_mut(&actor).unwrap().current;
            pose.x = player.screen_x;
            pose.y = player.screen_y;
        }
        if let Some(path) = &player.judgment_texture {
            let path = crate::file_path_string(path);
            let path = call.try_intern(path.as_bytes())?;
            set(call, actor, "__songlua_judgment_texture", path)?;
        }
        Ok(actor)
    }
}

fn construct(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Build>().unwrap().clone();
    let store = data.store.clone();
    let style = data.style.clone();
    let parts = data.parts;
    let method = Method {
        store: store.clone(),
        statistics: data.statistics.clone(),
        index: data.index,
        name: "",
    };
    let id = {
        let mut guard = store.lock().unwrap();
        if guard.next >= (1u64 << 53) - 1 {
            return Err(call.error(b"actor scene identity exhausted"));
        }
        guard.next += 1;
        let id = guard.next;
        guard.scenes.insert(
            id,
            Scene {
                actors: Vec::new(),
                root: None,
                ended: false,
                sounds_retired: false,
                initial_states: None,
                song_session: None,
            },
        );
        id
    };
    let result = (|| {
        let meter = data.create_meter(call, id)?;
        let actor = data.create_player(call, id)?;
        // ScreenGameplay owns the connection, after constructing the player.
        set(call, actor, "__songlua_life_meter", Value::Table(meter))?;
        if parts {
            player_parts::install(call, &store, id, actor, method.index, &style)?;
        }
        store.lock().unwrap().scenes.get_mut(&id).unwrap().root = Some(actor);
        Ok(())
    })();
    if let Err(error) = result {
        release(call, &store, id)?;
        return Err(error);
    }
    call.push(Value::Number(id as f64))
}

pub(super) fn dummy(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    kind: &str,
    name: &str,
    parent: Option<TableId>,
) -> Result<TableId, Error> {
    let attrs = call.try_new_table()?;
    call.with_roots(&[Value::Table(attrs)], |call| {
        let class = call.try_intern(kind.as_bytes())?;
        set(call, attrs, "Class", class)?;
        for key in ["__songlua_script_dir", "__songlua_song_dir"] {
            let value = field(call, table(call, helper(call, 5)?)?, key)?;
            if value != Value::Nil {
                assets::text(call, value)?;
                set(call, attrs, key, value)?;
            }
        }
        let node = call.call(helper(call, 2)?, &[Value::Table(attrs)])?[0];
        let actor = call.with_roots(&[node], |call| {
            Ok(build(call, store, scene, table(call, node)?, parent, false, true)?.unwrap())
        })?;
        // create_dummy_actor does not run the authored Sprite initializer.
        // Its render animation flag remains false until an explicit command.
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .render
            .sprite_animate = false;
        let value = call.try_intern(name.as_bytes())?;
        set(call, actor, "Name", value)?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .native_children = true;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .name = name.as_bytes().to_vec();
        if let Some(parent) = parent {
            native_children::adopt(call, store, actor, parent)?;
        }
        Ok(actor)
    })
}

fn bind(
    call: &mut HostCall<'_>,
    actor: TableId,
    method: &Method,
    name: &'static str,
) -> Result<(), Error> {
    let mut data = method.clone();
    data.name = name;
    let captures = [
        call.captures()[0],
        call.captures()[1],
        call.captures()[2],
        // Life queries are bound to this meter. The player's setters and zoom
        // getter use their supplied receiver and must not retain an old player.
        if matches!(name, "GetLife" | "IsFailing" | "IsHot" | "IsInDanger") {
            Value::Table(actor)
        } else {
            Value::Nil
        },
    ];
    let function = call.new_host_function_with_data(invoke, &captures, data)?;
    call.with_roots(&[function], |call| {
        let bound = get(call, actor, b"__songlua_bound_methods")?;
        set(call, table(call, bound)?, name, function)
    })
}

fn raw_bool(call: &mut HostCall<'_>, actor: TableId, name: &[u8]) -> Result<bool, Error> {
    let key = call.try_intern(name)?;
    // The native typed bool conversion follows Lua truthiness; Option only
    // supplies the nil default. Strings and numbers are not conversion errors.
    Ok(!matches!(
        call.raw_table_get(actor, key)?,
        Value::Nil | Value::Boolean(false)
    ))
}
fn raw_set(
    call: &mut HostCall<'_>,
    actor: TableId,
    name: &[u8],
    value: Value,
) -> Result<(), Error> {
    let key = call.try_intern(name)?;
    call.raw_table_set(actor, key, value)
}

fn invoke(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Method>().unwrap().clone();
    let receiver = call.captures()[3];
    match data.name {
        "GetLife" | "IsFailing" | "IsHot" | "IsInDanger" => {
            let live = data
                .statistics
                .lock()
                .unwrap()
                .players
                .as_ref()
                .map(|p| p[data.index].life);
            let mut stack = call.native_stack()?;
            let value = if data.name == "GetLife"
                && let Some(life) = live
            {
                life
            } else {
                stack.push(receiver)?;
                stack.get_field(-1, b"__songlua_life")?;
                if stack.value(-1) == Some(Value::Nil) {
                    crate::SONG_LUA_INITIAL_LIFE
                } else {
                    stack.number(-1)? as f32
                }
            };
            stack.push(match data.name {
                "GetLife" => Value::Number(value as f64),
                "IsFailing" => Value::Boolean(value <= 0.),
                "IsHot" => Value::Boolean(value >= 1.),
                "IsInDanger" => Value::Boolean(value < crate::SONG_LUA_DANGER_LIFE),
                _ => unreachable!(),
            })?;
            stack.finish(1)
        }
        "get_oitg_zoom_mode" => {
            let actor = table(call, arg(call, 0))?;
            let value = raw_bool(call, actor, b"__songlua_oitg_zoom_mode")?;
            call.push(Value::Boolean(value))
        }
        "set_oitg_zoom_mode" => {
            let actor = table(call, arg(call, 0))?;
            let value = !matches!(arg(call, 1), Value::Nil | Value::Boolean(false));
            raw_set(
                call,
                actor,
                b"__songlua_oitg_zoom_mode",
                Value::Boolean(value),
            )?;
            call.push(Value::Table(actor))
        }
        "SetLife" => {
            let actor = table(call, arg(call, 0))?;
            let life = (call.number(1)? as f32).clamp(0., 1.);
            if raw_bool(call, actor, b"__songlua_inside_set_life")? {
                return Err(call.error(b"Do not call SetLife from inside LifeChangedMessageCommand because SetLife causes a LifeChangedMessageCommand."));
            }
            raw_set(
                call,
                actor,
                b"__songlua_inside_set_life",
                Value::Boolean(true),
            )?;
            let result = change_life(call, &data, actor, life);
            raw_set(
                call,
                actor,
                b"__songlua_inside_set_life",
                Value::Boolean(false),
            )?;
            result?;
            // Native typed i64 read, including string coercion and range checks.
            // This path adds no internal tonumber call visible to authored hooks.
            let globals = helper(call, 5)?;
            let mut stack = call.native_stack()?;
            stack.push(globals)?;
            let global_index = stack.top();
            stack.get_field(
                global_index as isize,
                crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes(),
            )?;
            let count = if stack.value(-1) == Some(Value::Nil) {
                0
            } else {
                let value = stack.number(-1)?;
                if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&value) {
                    return Err(stack.error(b"side effect count is out of range"));
                }
                value as i64
            };
            stack.push_bytes(crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes())?;
            stack.push(Value::Number(count.saturating_add(1) as f64))?;
            stack.set_table(global_index as isize, false)?;
            stack.push(Value::Table(actor))?;
            stack.finish(1)
        }
        _ => unreachable!(),
    }
}

fn change_life(
    call: &mut HostCall<'_>,
    data: &Method,
    actor: TableId,
    life: f32,
) -> Result<(), Error> {
    {
        let mut state = data.statistics.lock().unwrap();
        if let Some(players) = state.players.as_mut() {
            players[data.index].life = life;
            players[data.index].life_record_latest = Some(life);
        }
    }
    let catalog = table(call, call.captures()[2])?;
    let key = call.try_intern(b"statistics_players")?;
    let players = table(call, call.raw_table_get(catalog, key)?)?;
    let stats = table(
        call,
        call.raw_table_get(players, Value::Number((data.index + 1) as f64))?,
    )?;
    raw_set(call, stats, b"__songlua_life", Value::Number(life as f64))?;
    if data
        .store
        .lock()
        .unwrap()
        .clock
        .live
        .load(std::sync::atomic::Ordering::Relaxed)
    {
        data.statistics
            .lock()
            .unwrap()
            .writes
            .push(crate::live::SongLuaLivePlayerWrite::SetLife {
                player: data.index,
                life,
            });
    }
    let key = call.try_intern(b"__songlua_life_meter")?;
    let meter = table(call, call.raw_table_get(actor, key)?)?;
    raw_set(call, meter, b"__songlua_life", Value::Number(life as f64))?;
    let params = call.try_new_table()?;
    call.with_roots(&[Value::Table(params)], |call| {
        let player = call.try_intern(format!("PlayerNumber_P{}", data.index + 1).as_bytes())?;
        raw_set(call, params, b"Player", player)?;
        raw_set(call, params, b"LifeMeter", Value::Table(meter))?;
        messages::dispatch(
            call,
            &data.store,
            b"LifeChanged",
            Some(Value::Table(params)),
            true,
        )
    })
}

//! GraphDisplay's native children, life-record capture and owned render payload.
use super::*;
use sprites::{field, set};

#[derive(Clone, Debug)]
pub struct GraphDisplay {
    pub size: [f32; 2],
    pub body_values: Arc<[f32]>,
    pub body_state: crate::SongLuaOverlayState,
    pub line_state: crate::SongLuaOverlayState,
}

pub(super) fn install(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let methods = native_children::helper_function(call, b"graph_methods")?;
    let methods = table(call, methods)?;
    let bound = get(call, actor, b"__songlua_bound_methods")?;
    let bound = table(call, bound)?;
    for name in ["Load", "Set"] {
        let method = get(call, methods, name.as_bytes())?;
        let captures = [
            call.captures()[0],
            call.captures()[1],
            Value::Table(actor),
            method,
        ];
        let function = call.new_host_function_with_data(invoke_bound, &captures, name)?;
        let key = call.try_intern(name.as_bytes())?;
        call.raw_table_set(bound, key, function)?;
    }
    Ok(())
}

fn child(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    parent: TableId,
    kind: &str,
    name: &str,
) -> Result<TableId, Error> {
    let attrs = call.try_new_table()?;
    call.with_roots(&[Value::Table(attrs)], |call| {
        let class = call.try_intern(kind.as_bytes())?;
        set(call, attrs, "Class", class)?;
        // Native dummy actors inherit the active file scope, not the parent's
        // declaration directory, and are registered before that parent's Init.
        for key in ["__songlua_script_dir", "__songlua_song_dir"] {
            let value = field(call, table(call, helper(call, 5)?)?, key)?;
            if value != Value::Nil {
                assets::text(call, value)?;
                set(call, attrs, key, value)?;
            }
        }
        let node = call.call(helper(call, 2)?, &[Value::Table(attrs)])?[0];
        let child = call.with_roots(&[node], |call| {
            Ok(build(
                call,
                store,
                scene,
                table(call, node)?,
                Some(parent),
                false,
                true,
            )?
            .unwrap())
        })?;
        {
            let mut store = store.lock().unwrap();
            // Native dummy graph children register during materialization,
            // before Init registers the ordinary nodes of this new scene.
            store.actor_order.retain(|id| *id != child);
            let position = store
                .actor_order
                .iter()
                .position(|id| {
                    let a = &store.actors[id];
                    a.scene == scene
                        && !matches!(a.state.class, "GraphDisplayBody" | "GraphDisplayLine")
                })
                .unwrap_or(store.actor_order.len());
            store.actor_order.insert(position, child);
        }
        let value = call.try_intern(name.as_bytes())?;
        set(call, child, "Name", value)?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&child)
            .unwrap()
            .state
            .name = name.as_bytes().to_vec();
        Ok(child)
    })
}

pub(super) fn initialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
) -> Result<(), Error> {
    {
        let mut store = store.lock().unwrap();
        let size = store.graph_size;
        let actor = store.actors.get_mut(&actor).unwrap();
        actor.state.size = size;
        actor.state.render.size = Some(size);
    }
    let first = child(call, store, scene, actor, "GraphDisplayBody", "")?;
    let second = child(call, store, scene, actor, "GraphDisplayBody", "")?;
    let line = child(call, store, scene, actor, "GraphDisplayLine", "Line")?;
    let bodies = group(call, &[first, second])?;
    native_children::insert(call, actor, "", bodies)?;
    native_children::insert(call, actor, "Line", Value::Table(line))?;
    Ok(())
}

fn tolerate<T>(result: Result<T, Error>) -> Result<Option<T>, Error> {
    match result {
        Ok(value) => Ok(Some(value)),
        Err(error) if error.kind() == ErrorKind::Runtime => Ok(None),
        Err(error) => Err(error),
    }
}

fn capture(
    call: &mut HostCall<'_>,
    actor: TableId,
    stage: Value,
    player: Value,
) -> Result<(), Error> {
    let seconds = if let Value::Table(stage) = stage {
        tolerate((|| {
            let value = field(call, stage, "__songlua_total_steps_seconds")?;
            if value == Value::Nil {
                Ok(0.0)
            } else {
                sprites::number(call, value).map(|n| n as f32)
            }
        })())?
        .unwrap_or(0.0)
    } else {
        0.0
    };
    let record = if let Value::Table(player) = player {
        tolerate((|| {
            let method = field(call, player, "GetLifeRecord")?;
            if !matches!(method, Value::Function(_) | Value::Native(_)) {
                return Ok(Value::Nil);
            }
            Ok(call
                .call(
                    method,
                    &[
                        Value::Table(player),
                        Value::Number(seconds as f64),
                        Value::Number(crate::GRAPH_DISPLAY_VALUE_RESOLUTION as f64),
                    ],
                )?
                .first()
                .copied()
                .unwrap_or(Value::Nil))
        })())?
        .unwrap_or(Value::Nil)
    } else {
        Value::Nil
    };
    call.with_roots(&[record], |call| {
        // Production eagerly creates the fallback even after a successful
        // callback. Keep the returned table rooted across that allocation.
        let fallback = call.try_new_table()?;
        for i in 1..=crate::GRAPH_DISPLAY_VALUE_RESOLUTION {
            call.raw_table_set(
                fallback,
                Value::Number(i as f64),
                Value::Number(crate::SONG_LUA_INITIAL_LIFE as f64),
            )?;
        }
        let values = if matches!(record, Value::Table(_)) {
            record
        } else {
            Value::Table(fallback)
        };
        set(call, actor, "__songlua_graph_display_values", values)
    })
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let graph = assets::field(call, actor, b"__songlua_actor_type")?
        .is_some_and(|kind| kind.eq_ignore_ascii_case("GraphDisplay"));
    if name == "Load" {
        if !graph {
            return sprites::method(call, store, actor, name);
        }
        if let Some(metric) = render::text(call, arg(call, 1)).map(str::to_owned) {
            let metric = call.try_intern(metric.as_bytes())?;
            set(call, actor, "__songlua_graph_display_metric", metric)?;
        }
    } else if graph {
        set(
            call,
            actor,
            "__songlua_graph_display_set",
            Value::Boolean(true),
        )?;
        for (i, key) in [
            (1, "__songlua_graph_display_stage_stats"),
            (2, "__songlua_graph_display_player_stats"),
        ] {
            if let Some(value) = call.arguments().get(i).copied() {
                set(call, actor, key, value)?;
            }
        }
        capture(call, actor, arg(call, 1), arg(call, 2))?;
    }
    call.push(Value::Table(actor))
}

fn child_state(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    body: bool,
) -> Result<crate::SongLuaOverlayState, Error> {
    let map = native_children::named_children(call, actor)?;
    call.with_roots(&[map], |call| {
        let child = field(call, table(call, map)?, if body { "" } else { "Line" })?;
        if child == Value::Nil {
            return Ok(crate::SongLuaOverlayState::default());
        }
        call.with_roots(&[child], |call| {
            let child = table(call, child)?;
            let child = if body {
                let second = call.raw_table_get(child, Value::Number(2.0))?;
                if second != Value::Nil {
                    Some(table(call, second)?)
                } else {
                    let first = call.raw_table_get(child, Value::Number(1.0))?;
                    if let Value::Table(first) = first {
                        Some(first)
                    } else {
                        None
                    }
                }
            } else {
                Some(child)
            };
            child.map_or(Ok(crate::SongLuaOverlayState::default()), |child| {
                native_children::state(call, store, child)
            })
        })
    })
}

pub(super) fn read(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<GraphDisplay, Error> {
    let size = native_children::state(call, store, actor)?
        .size
        .unwrap_or(store.lock().unwrap().graph_size)
        .map(|n| n.abs().max(1.0));
    let values = field(call, actor, "__songlua_graph_display_values")?;
    let body_values = call.with_roots(&[values], |call| {
        let mut result = vec![crate::SONG_LUA_INITIAL_LIFE; crate::GRAPH_DISPLAY_VALUE_RESOLUTION];
        if values != Value::Nil {
            let values = table(call, values)?;
            for (i, out) in result.iter_mut().enumerate() {
                let value = call.raw_table_get(values, Value::Number((i + 1) as f64))?;
                *out = float_scalar(call, value, false)
                    .unwrap_or(crate::SONG_LUA_INITIAL_LIFE)
                    .clamp(0.0, 1.0);
            }
        }
        Ok(Arc::from(result))
    })?;
    Ok(GraphDisplay {
        size,
        body_values,
        body_state: child_state(call, store, actor, true)?,
        line_state: child_state(call, store, actor, false)?,
    })
}

//! Compiler initial state: native Rust properties plus authored raw overrides.
//! This reads the existing preparation representation without invoking property
//! getters or advancing tweens. Captured values own no Lua allocations.
use super::*;
use crate::SongLuaOverlayState;

pub(super) fn read(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<SongLuaOverlayState, Error> {
    let mut state = {
        let guard = store.lock().unwrap();
        guard
            .actors
            .get(&actor)
            .map(|actor| {
                let mut state = actor.state.render;
                actor.destination().write_to(&mut state);
                [state.rot_x_deg, state.rot_y_deg, state.rot_z_deg] = actor.state.rotation;
                state.visible = actor.state.visible;
                state.draw_order = actor.state.draw_order;
                state.hibernating = actor.hibernate > 0.;
                state
            })
            .unwrap_or_default()
    };
    let class = text(call, actor, "__songlua_actor_type")?;
    if !store.lock().unwrap().actors.contains_key(&actor) {
        let model = class
            .as_deref()
            .is_some_and(|class| class.eq_ignore_ascii_case("Model"));
        state.depth_test = model;
        state.depth_write = model;
        state.texture_wrapping = model;
        state.cull_mode = if model {
            deadlib_render_core::CullMode::Back
        } else {
            deadlib_render_core::CullMode::None
        };
    }
    if let Some(mode) = integer(call, actor, "__songlua_state_cull_mode", 0., 255.)? {
        state.cull_mode = match mode {
            1 => deadlib_render_core::CullMode::Back,
            2 => deadlib_render_core::CullMode::Front,
            _ => deadlib_render_core::CullMode::None,
        };
    }
    if let Some(left) = number(call, actor, "__songlua_hibernate_seconds")? {
        state.hibernating = left > 0.;
    }
    state.hibernating |= flag(call, actor, "__songlua_theme_hibernating")?.unwrap_or(false);
    if let Some(aux) = number(call, actor, "__songlua_state_aux")? {
        state.aux = aux;
    }
    if let Some(visible) = flag(call, actor, "__songlua_visible")? {
        state.visible = visible;
    }
    if let Some(value) = flag(call, actor, "__songlua_state_sprite_texture")? {
        state.sprite_texture = value;
    } else if class
        .as_deref()
        .is_some_and(|class| class.eq_ignore_ascii_case("Sprite"))
    {
        let texture = sprites::field(call, actor, "Texture")?;
        let has_texture = value_text(call, texture)?.is_some();
        let capture = if has_texture {
            None
        } else {
            let allocation = get(call, actor, b"__songlua_aft_allocation")?;
            let value = if allocation == Value::Nil {
                sprites::field(call, actor, "__songlua_aft_capture_name")?
            } else {
                sprites::field(call, table(call, allocation)?, "name")?
            };
            value_text(call, value)?
        };
        state.sprite_texture = has_texture || capture.is_some();
    }
    if let Some(value) = number(call, actor, "__songlua_state_x")? {
        state.x = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_y")? {
        state.y = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_z")? {
        state.z = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_z_bias")? {
        state.z_bias = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_halign")? {
        state.halign = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_valign")? {
        state.valign = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_cropleft")? {
        state.cropleft = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_cropright")? {
        state.cropright = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_croptop")? {
        state.croptop = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_cropbottom")? {
        state.cropbottom = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_fadeleft")? {
        state.fadeleft = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_faderight")? {
        state.faderight = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_fadetop")? {
        state.fadetop = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_fadebottom")? {
        state.fadebottom = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_zoom")? {
        state.zoom = value;
    }
    if let Some(value) = number(call, actor, "__songlua_state_zoom_x")? {
        state.zoom_x = value;
