fn number(call: &mut HostCall<'_>, actor: TableId, key: &str) -> Result<Option<f32>, Error> {
    let value = get(call, actor, key.as_bytes())?;
    if value == Value::Nil {
        return Ok(None);
    }
    sprites::number(call, value).map(|value| Some(value as f32))
}
fn integer(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &str,
    min: f64,
    max: f64,
) -> Result<Option<i64>, Error> {
    let value = get(call, actor, key.as_bytes())?;
    if value == Value::Nil {
        return Ok(None);
    }
    let value = sprites::number(call, value)?.trunc();
    if !(min..=max).contains(&value) {
        return Err(call.error(format!("{key}: integer out of range").as_bytes()));
    }
    Ok(Some(value as i64))
}
fn flag(call: &mut HostCall<'_>, actor: TableId, key: &str) -> Result<Option<bool>, Error> {
    let value = get(call, actor, key.as_bytes())?;
    Ok((value != Value::Nil).then_some(!matches!(value, Value::Nil | Value::Boolean(false))))
}
pub(super) fn value_text(call: &mut HostCall<'_>, value: Value) -> Result<Option<String>, Error> {
    if value == Value::Nil {
        return Ok(None);
    }
    let id = call
        .coerce_string(value)?
        .ok_or_else(|| call.error(b"actor state: string expected"))?;
    let text = std::str::from_utf8(call.string_bytes(id).unwrap())
        .map_err(|e| call.error(e.to_string().as_bytes()))?;
    Ok(Some(text.to_owned()))
}
fn text(call: &mut HostCall<'_>, actor: TableId, key: &str) -> Result<Option<String>, Error> {
    let value = get(call, actor, key.as_bytes())?;
    value_text(call, value)
}
fn optional_table(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &str,
) -> Result<Option<TableId>, Error> {
    let value = get(call, actor, key.as_bytes())?;
    if value == Value::Nil {
        return Ok(None);
    }
    table(call, value).map(Some)
}
fn vector<const N: usize>(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &str,
) -> Result<Option<[f32; N]>, Error> {
    match optional_table(call, actor, key)? {
        Some(t) => components(call, t),
        None => Ok(None),
    }
}
fn components<const N: usize>(
    call: &mut HostCall<'_>,
    t: TableId,
) -> Result<Option<[f32; N]>, Error> {
    let mut values = [0.; N];
    for (i, dest) in values.iter_mut().enumerate() {
        let value = call.raw_table_get(t, Value::Number((i + 1) as f64))?;
        // Vector conversion ignores malformed components; scalar properties error.
        let converted = call.call(helper(call, 6)?, &[value])?[0];
        let Value::Number(value) = converted else {
            return Ok(None);
        };
        *dest = value as f32;
    }
    Ok(Some(values))
}

//! Existing actor queue and frame lifecycle, owned by the song host.
use super::*;

#[derive(Clone)]
