fn color(call: &mut HostCall<'_>, value: Value) -> Result<[f32; 4], Error> {
    match value {
        Value::Table(t) => call.with_roots(&[value], |call| {
            let mut color = [1.0; 4];
            for (i, component) in color.iter_mut().enumerate() {
                let value = call.raw_table_get(t, Value::Number((i + 1) as f64))?;
                if i == 3 && value == Value::Nil {
                    continue;
                }
                let converted = if matches!(value, Value::Number(_)) {
                    value
                } else {
                    call.call(helper(call, 6)?, &[value])?[0]
                };
                let Value::Number(n) = converted else {
                    return Ok([1.0; 4]);
                };
                *component = n as f32;
            }
            Ok(color)
        }),
        Value::String(_) => Ok(render::text(call, value)
            .and_then(crate::parse_color_text)
            .unwrap_or([1.0; 4])),
        _ => Ok([1.0; 4]),
    }
}

fn points(call: &mut HostCall<'_>, vertices: TableId) -> Result<Vec<Point>, Error> {
    call.with_roots(&[Value::Table(vertices)], |call| {
        let mut points = Vec::with_capacity(call.raw_table_len(vertices)?);
        for i in 1usize.. {
            let value = call.raw_table_get(vertices, Value::Number(i as f64))?;
            if value == Value::Nil {
                break;
            }
            let Value::Table(vertex) = value else {
                continue;
            };
            let point = call.with_roots(&[value], |call| {
                let position = call.raw_table_get(vertex, Value::Number(1.0))?;
                let Value::Table(position_table) = position else {
                    return Ok(None);
                };
                call.with_roots(&[position], |call| {
                    let x = call.raw_table_get(position_table, Value::Number(1.0))?;
                    let y = call.raw_table_get(position_table, Value::Number(2.0))?;
                    let (Some(x), Some(y)) =
                        (float_scalar(call, x, true), float_scalar(call, y, true))
                    else {
                        return Ok(None);
                    };
                    let value = call.raw_table_get(vertex, Value::Number(2.0))?;
                    let color = color(call, value)?;
                    let value = call.raw_table_get(vertex, Value::Number(3.0))?;
                    let mut uv = [0.0; 2];
                    if let Value::Table(t) = value {
                        for (i, component) in uv.iter_mut().enumerate() {
                            let value = call.raw_table_get(t, Value::Number((i + 1) as f64))?;
                            *component = float_scalar(call, value, false).unwrap_or(0.0);
                        }
                    }
                    let z = call.raw_table_get(position_table, Value::Number(3.0))?;
                    Ok(Some(Point {
                        pos: [x, y],
                        z: float_scalar(call, z, true).unwrap_or(0.0),
                        color,
                        uv,
                    }))
                })
            })?;
            if let Some(point) = point {
                points.push(point);
            }
        }
        Ok(points)
    })
}

const POINT_BYTES: usize = 9 * size_of::<f32>();
pub(super) const BUFFERS_KEY: &str = "mesh_buffers";
fn buffers(call: &mut HostCall<'_>) -> Result<TableId, Error> {
    let helpers = table(call, call.captures()[1])?;
    let key = call.try_intern(BUFFERS_KEY.as_bytes())?;
    table(call, call.raw_table_get(helpers, key)?)
}
fn upload(call: &mut HostCall<'_>, actor: TableId, vertices: TableId) -> Result<(), Error> {
    // Count is published before conversion, including when a later write fails.
    let count = call.raw_table_len(vertices)?;
    set(
        call,
        actor,
        "__songlua_vertex_count",
        Value::Number(count as f64),
    )?;
    let points = points(call, vertices)?;
    let size = points
        .len()
        .checked_mul(POINT_BYTES)
        .ok_or_else(|| call.error(b"vertex buffer too large"))?;
    let buffer = call.try_new_userdata(size)?;
    let Value::Userdata(id) = buffer else {
        unreachable!()
    };
    let bytes = call.userdata_bytes_mut(id).expect("new vertex storage");
    for (bytes, point) in bytes
        .as_chunks_mut::<POINT_BYTES>()
        .0
        .iter_mut()
        .zip(points)
    {
        for (bytes, scalar) in bytes.as_chunks_mut::<4>().0.iter_mut().zip([
            point.pos[0],
            point.pos[1],
            point.z,
            point.color[0],
            point.color[1],
            point.color[2],
            point.color[3],
            point.uv[0],
            point.uv[1],
        ]) {
            bytes.copy_from_slice(&scalar.to_le_bytes());
        }
    }
    // A private weak-key set authenticates this userdata type without retaining
    // uploaded buffers. The VM accounts for and frees all owned scalar storage.
    call.with_roots(&[buffer], |call| {
        let buffers = buffers(call)?;
        call.raw_table_set(buffers, buffer, Value::Boolean(true))?;
        set(call, actor, "__songlua_vertices", buffer)
    })
}

fn source(call: &mut HostCall<'_>, value: Value) -> Result<Option<Vec<Point>>, Error> {
    match value {
        Value::Nil => Ok(None),
        Value::Table(t) => points(call, t).map(Some),
        Value::Userdata(id) => {
            let buffers = buffers(call)?;
            if call.raw_table_get(buffers, value)? != Value::Boolean(true) {
                return Err(call.error(b"invalid ActorMultiVertex vertex buffer"));
            }
            let bytes = call.userdata_bytes(id).expect("live vertex storage");
            Ok(Some(
                bytes
                    .as_chunks::<POINT_BYTES>()
                    .0
                    .iter()
                    .map(|bytes| {
                        let mut values = [0.0; 9];
                        for (value, bytes) in values.iter_mut().zip(bytes.as_chunks::<4>().0) {
                            *value = f32::from_le_bytes(*bytes);
                        }
                        Point {
                            pos: [values[0], values[1]],
                            z: values[2],
                            color: [values[3], values[4], values[5], values[6]],
                            uv: [values[7], values[8]],
                        }
                    })
                    .collect(),
            ))
        }
        _ => Err(call.error(b"invalid ActorMultiVertex vertex buffer")),
    }
}

fn range_value(call: &mut HostCall<'_>, state: TableId, key: &str) -> Result<Option<i32>, Error> {
    match field(call, state, key) {
        Ok(value) => Ok(integer_scalar(call, value)),
        // Production ignores ordinary authored errors in First/Num getters.
        Err(error) if error.kind() == ErrorKind::Runtime => Ok(None),
        Err(error) => Err(error),
    }
}

pub(super) fn vertices(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Option<Arc<[Vertex]>>, Error> {
    let value = field(call, actor, "__songlua_vertices")?;
    let Some(points) = source(call, value)?.filter(|points| !points.is_empty()) else {
        return Ok(None);
    };
    let value = field(call, actor, "__songlua_draw_state")?;
    let (first, num) = if value == Value::Nil {
        (1, -1)
    } else {
        let state = table(call, value)?;
        call.with_roots(&[value], |call| {
            Ok((
                range_value(call, state, "First")?.unwrap_or(1),
                range_value(call, state, "Num")?.unwrap_or(-1),
            ))
        })?
    };
    let start = (first.max(1) as usize - 1).min(points.len());
    let end = if num < 0 {
        points.len()
    } else {
        start.saturating_add(num as usize).min(points.len())
    };
    if end <= start {
        return Ok(None);
    }
    let mode = assets::field(call, actor, b"__songlua_draw_state_mode")?
        .unwrap_or_else(|| "DrawMode_Triangles".into());
    let value = field(call, actor, "__songlua_line_width")?;
    let width = if value == Value::Nil {
        1.0
    } else {
        sprites::number(call, value)? as f32
    }
    .max(0.0);
    let Some(vertices) = geometry::actor_multi_vertex_mesh_arc(&points[start..end], &mode, width)
    else {
        return Ok(None);
    };
    Ok(Some(vertices))
}
pub(super) fn texture_path(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Option<PathBuf>, Error> {
    let texture_path = if sprites::default_texture(call, actor)? {
        const KEY: &str = "__songlua_native_default_texture.png";
        static PREPARED: OnceLock<()> = OnceLock::new();
        PREPARED.get_or_init(|| {
            deadlib_assets::register_prepared_generated_texture(
                KEY,
                image::RgbaImage::from_pixel(1, 1, image::Rgba([255; 4])),
                [1, 1],
                Default::default(),
            )
        });
        Some(PathBuf::from(KEY))
    } else {
        assets::texture_path(call, actor)?
    };
    Ok(texture_path)
}
pub(super) fn read(call: &mut HostCall<'_>, actor: TableId) -> Result<Option<ActorMesh>, Error> {
    let Some(vertices) = vertices(call, actor)? else {
        return Ok(None);
    };
    let texture_path = texture_path(call, actor)?;
    Ok(Some(ActorMesh {
        vertices,
        texture_path,
    }))
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = arg(call, 1);
    match name {
        "SetVertices" => {
            if let Value::Table(vertices) = value {
                upload(call, actor, vertices)?;
            }
        }
        "SetNumVertices" => {
            let count = integer_scalar(call, value).unwrap_or(0).max(0);
            set(
                call,
                actor,
                "__songlua_vertex_count",
                Value::Number(count as f64),
            )?;
        }
        "GetNumVertices" => {
            let value = field(call, actor, "__songlua_vertex_count")?;
            let count = if value == Value::Nil {
                let value = field(call, actor, "__songlua_vertices")?;
                if value == Value::Nil {
                    0.0
                } else {
                    call.raw_table_len(table(call, value)?)? as f64
                }
            } else {
                let n = sprites::number(call, value)?;
                if !(i64::MIN as f64..9223372036854775808.0).contains(&n) {
                    return Err(call.error(b"vertex count out of range"));
                }
                (n as i64).max(0) as f64
            };
            return call.push(Value::Number(count));
        }
        "SetDrawState" => {
            if let Value::Table(state) = value {
                let value = field(call, actor, "__songlua_draw_state")?;
                let destination = if value == Value::Nil {
                    call.try_new_table()?
                } else {
                    table(call, value)?
                };
                call.with_roots(&[Value::Table(destination)], |call| {
                    for key in ["Mode", "First", "Num"] {
                        let value = field(call, state, key)?;
                        if value != Value::Nil {
                            set(call, destination, key, value)?;
                        }
                    }
                    set(
                        call,
                        actor,
                        "__songlua_draw_state",
                        Value::Table(destination),
                    )?;
                    if let Some(mode) = assets::field(call, state, b"Mode")? {
                        let mode = call.try_intern(mode.as_bytes())?;
                        set(call, actor, "__songlua_draw_state_mode", mode)?;
                    }
                    Ok(())
                })?;
            }
        }
        "GetDestDrawMode" => {
            let mode = assets::field(call, actor, b"__songlua_draw_state_mode")?;
            let value = match mode {
                Some(mode) => call.try_intern(mode.as_bytes())?,
                None => Value::Nil,
            };
            return call.push(value);
        }
        "SetLineWidth" => {
            if let Some(width) = float_scalar(call, value, false).filter(|w| *w >= 0.0) {
                set(
                    call,
                    actor,
                    "__songlua_line_width",
                    Value::Number(width as f64),
                )?;
            }
        }
        "LoadTexture" => {
            super::action_capture::prepare(call, store, actor)?;
            if value == Value::Nil {
                sprites::set_texture(call, store, actor, value, true)?;
                let key = call.try_intern(b"__songlua_default_texture")?;
                call.raw_table_set(actor, key, Value::Boolean(true))?;
            } else {
                let path = call
                    .coerce_string(value)?
                    .ok_or_else(|| call.error(b"LoadTexture: string expected"))?;
                call.with_roots(&[Value::String(path)], |call| {
                    sprites::set_texture(call, store, actor, Value::String(path), false)
                })?;
            }
        }
        "SetEffectMode"
        | "GetNumStates"
        | "GetState"
        | "SetStateProperties"
        | "SetAllStateDelays"
        | "SetSecondsIntoAnimation"
        | "GetDecodeMovie"
        | "SetDecodeMovie"
        | "SetTexture"
        | "GetTexture" => return sprites::method(call, store, actor, name),
        _ => {
            return Err(call.error(
                format!("native actor method {name} has no semantic implementation").as_bytes(),
            ));
        }
    }
    call.push(Value::Table(actor))
}

//! MessageManager delivery over owned Rust actors and traced Lua parameters.
use super::*;
mod capture;
mod compilation;
mod judgment;
mod probe;
pub(super) use capture::Deferred;

const ACTIVE: &[u8] = b"__songlua_active_broadcast";
const MANAGER_HELPER: usize = 8;

#[derive(Clone, Copy)]
pub(super) enum MessageOp {
    Broadcast,
    Logging,
    Host,
}

pub(super) fn install(vm: &mut Vm, store: &Shared, captures: &[Value]) -> Result<Root, Error> {
    let manager = vm.try_new_table()?;
    let Value::Table(helpers) = captures[1] else {
        unreachable!()
    };
    vm.raw_table_set(
        helpers,
        Value::Number(MANAGER_HELPER as f64),
        Value::Table(manager),
    )?;
    for (name, op) in [
        ("Broadcast", MessageOp::Broadcast),
        ("SetLogging", MessageOp::Logging),
    ] {
        install_method(vm, manager, name, Op::Message(op), store, captures)?;
    }
    vm.set_global(b"MESSAGEMAN", Value::Table(manager))?;
    vm.set_global(
        crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes(),
        Value::Number(0.0),
    )?;
    let callback = vm.new_host_function_with_data(
        super::callback,
        captures,
        Binding {
            store: store.clone(),
            op: Op::Message(MessageOp::Host),
        },
    )?;
    vm.pin(callback)
}

fn global(call: &mut HostCall<'_>, key: &[u8], raw: bool) -> Result<Value, Error> {
    let globals = helper(call, 5)?;
    let key = call.try_intern(key)?;
    if raw {
        call.raw_table_get(table(call, globals)?, key)
    } else {
        call.table_get(globals, key)
    }
}

pub(super) fn side_effect(call: &mut HostCall<'_>) -> Result<(), Error> {
    let globals = helper(call, 5)?;
    let tonumber = helper(call, 6)?;
    super::super::managers::side_effect(call, globals, tonumber)
}

pub(super) fn record(
    call: &mut HostCall<'_>,
    message: &[u8],
    has_params: bool,
) -> Result<(), Error> {
    let history = global(call, crate::SONG_LUA_BROADCASTS_KEY.as_bytes(), false)?;
    if history == Value::Nil {
        return Ok(());
    }
    let history = table(call, history)?;
    call.with_roots(&[Value::Table(history)], |call| {
        let entry = call.try_new_table()?;
        let message = call.try_intern(message)?;
        call.with_roots(&[Value::Table(entry), message], |call| {
            judgment::set(call, entry, b"message", message)?;
            judgment::set(call, entry, b"has_params", Value::Boolean(has_params))?;
            let index = call.raw_table_len(history)? + 1;
            call.raw_table_set(history, Value::Number(index as f64), Value::Table(entry))
        })
    })
}

pub(super) fn callback(
    call: &mut HostCall<'_>,
    store: &Shared,
    op: MessageOp,
) -> Result<(), Error> {
    if matches!(op, MessageOp::Host) {
        let name =
            command_name(call, arg(call, 0)).ok_or_else(|| call.error(b"message name expected"))?;
        // Internal manager bindings share the native guarded ScriptError path.
        if arg(call, 4) == Value::Boolean(true) {
            let text = String::from_utf8_lossy(&name);
            return framebuffers::report(call, store, &text);
        }
        let params = (arg(call, 1) == Value::Boolean(true)).then(|| arg(call, 2));
        return dispatch(
            call,
            store,
            &name,
            params,
            arg(call, 3) == Value::Boolean(true),
        );
    }
    if matches!(op, MessageOp::Logging) {
        side_effect(call)?;
    } else {
        let offset = usize::from(matches!(arg(call, 0), Value::Table(_)));
        if let Some(name) = command_name(call, arg(call, offset)) {
            let params = call.arguments().get(offset + 1).copied();
            if let Some(value) = params
                && !matches!(value, Value::Table(_) | Value::Nil)
            {
                return Err(call.error(b"bad argument #2 to 'Broadcast' (table or nil expected)"));
            }
            side_effect(call)?;
            let has_params = matches!(params, Some(Value::Table(_)));
            record(call, &name, has_params)?;
            let suppressed = global(
                call,
                crate::SONG_LUA_SUPPRESS_BROADCAST_KEY.as_bytes(),
                true,
            )?;
            if has_params || matches!(suppressed, Value::Nil | Value::Boolean(false)) {
                dispatch(call, store, &name, params, true)?;
            }
        }
    }
    call.push(helper(call, MANAGER_HELPER)?)
}

pub(super) fn queued(call: &mut HostCall<'_>, store: &Shared, message: &[u8]) -> Result<(), Error> {
    record(call, message, true)?;
    let params = Value::Table(call.try_new_table()?);
    call.with_roots(&[params], |call| {
        dispatch(call, store, message, Some(params), true)
    })
}

pub(super) fn dispatch(
    call: &mut HostCall<'_>,
    store: &Shared,
    message: &[u8],
    params: Option<Value>,
    normalize: bool,
) -> Result<(), Error> {
    if std::str::from_utf8(message).is_ok_and(|message| message.trim().is_empty()) {
        return Ok(());
    }
    song_capture::broadcast(call, store, message, params.is_some())?;
    let active_key = call.try_intern(ACTIVE)?;
    let globals = table(call, helper(call, 5)?)?;
    let previous = call.raw_table_get(globals, active_key)?;
    let name = call.try_intern(message)?;
    call.with_roots(
        &[active_key, previous, name, params.unwrap_or(Value::Nil)],
        |call| {
            call.raw_table_set(globals, active_key, name)?;
            let previous_message = std::mem::replace(
                &mut store.lock().unwrap().active_message,
                std::str::from_utf8(message).ok().map(str::to_owned),
            );
            let result = deliver(call, store, message, params, normalize);
            store.lock().unwrap().active_message = previous_message;
            // Raw restoration also works after a fatal instruction limit.
            call.raw_table_set(globals, active_key, previous)?;
            result
        },
    )
}

fn deliver(
    call: &mut HostCall<'_>,
    store: &Shared,
    message: &[u8],
    params: Option<Value>,
    normalize: bool,
) -> Result<(), Error> {
    let field = [message, b"MessageCommand"].concat();
    let key = call.try_intern(&field)?;
    call.with_roots(&[key], |call| {
        let order = store.lock().unwrap().actor_order.clone();
        let mut actors = Vec::new();
        for actor in order {
            let function = call.table_get(Value::Table(actor), key)?;
            if matches!(function, Value::Function(_) | Value::Native(_)) {
                let identity = call
                    .object_pointer(Value::Table(actor))
                    .expect("registry owns actor");
                actors.push((identity, actor));
            }
        }
        actors.sort_unstable_by_key(|&(identity, _)| identity);
        // Differential controls import allocator identities, just as the
        // existing production oracle does. Normal delivery uses VM identities.
        #[cfg(feature = "test-support")]
        {
            let store = store.lock().unwrap();
            let mut known = Vec::new();
            let mut slots = Vec::new();
            for (slot, &(_, actor)) in actors.iter().enumerate() {
                if let Some(&rank) = store.message_ranks.get(&actor) {
                    slots.push(slot);
                    known.push((rank, actor));
                }
            }
            known.sort_unstable_by_key(|&(rank, _)| rank);
            for (slot, actor) in slots.into_iter().zip(known) {
                actors[slot] = actor;
            }
        }
        if normalize
            && message.eq_ignore_ascii_case(b"Judgment")
            && let Some(Value::Table(params)) = params
        {
            judgment::normalize(call, params)?;
        }
        let name = [message, b"Message"].concat();
        for (_, actor) in actors {
            // A broadcast is synchronous even when the same handler is already
            // active. Direct playcommand keeps its separate recursion guard.
            let was_active = store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .active_commands
                .remove(&field);
            let result = run_named(call, store, actor, &name, params);
            if was_active {
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .active_commands
                    .insert(field.clone());
            }
            result?;
            let mut guard = store.lock().unwrap();
            if guard.replay_clock.is_some() {
                for entry in &mut guard.deferred_messages {
                    if entry.actor == actor && entry.command.as_bytes() == field {
                        entry.observed = true;
                    }
                }
            }
        }
        Ok(())
    })
}

