    }
    pub(in crate::rust_engine) fn message_command_names(
        &self,
        vm: &mut Vm,
        actor: Value,
    ) -> Result<Vec<String>, Error> {
        let output = Arc::new(Mutex::new(None));
        let scan = vm.new_host_function_with_data(
            |call| {
                let out = call
                    .function_data::<Arc<Mutex<Option<Vec<String>>>>>()
                    .unwrap()
                    .clone();
                let actor = call.captures()[0];
                let names = {
                    let mut stack = call.native_stack()?;
                    stack.push(actor)?;
                    let actor = stack.top_offset();
                    stack.push(Value::Nil)?;
                    let mut names = Vec::new();
                    while stack.next_table(actor)? {
                        if matches!(stack.value(-2), Some(Value::String(_)))
                            && matches!(
                                stack.value(-1),
                                Some(Value::Function(_) | Value::Native(_))
                            )
                        {
                            let bytes = stack.to_bytes(-2)?.unwrap();
                            if let Ok(name) = std::str::from_utf8(bytes)
                                && name.ends_with("MessageCommand")
                            {
                                names.push(name.to_owned());
                            }
                        }
                        stack.set_top(stack.top() - 1)?;
                    }
                    names.sort_unstable();
                    names
                };
                *out.lock().unwrap() = Some(names);
                Ok(())
            },
            &[actor],
            output.clone(),
        )?;
        vm.call(scan, &[])?;
        Ok(output.lock().unwrap().take().unwrap())
    }
    pub(in crate::rust_engine) fn begin_message_sounds(
        &self,
        vm: &mut Vm,
    ) -> Result<SoundSession, Error> {
        let retained = vm.try_new_table()?;
        let pin = vm.pin(Value::Table(retained))?;
        let output = Arc::new(Mutex::new(SoundOutput::default()));
        let result = (|| {
            let captures = [
                Value::Table(self.registry),
                Value::Table(self.helpers),
                Value::Table(retained),
            ];
            let setup = vm.new_host_function(
                |call| {
                    let retained = table(call, call.captures()[2])?;
                    let key = call.try_intern(crate::SONG_LUA_SOUND_CALLS_KEY.as_bytes())?;
                    let globals = helper(call, 5)?;
                    let old = call.table_get(globals, key)?;
                    call.raw_table_set(retained, Value::Number(1.), old)?;
                    let next = call.try_new_table()?;
                    call.raw_table_set(retained, Value::Number(2.), Value::Table(next))?;
                    call.table_set(globals, key, Value::Table(next))
                },
                &captures,
            )?;
            vm.call(setup, &[])?;
            let finish = vm.new_host_function_with_data(
                |call| {
                    let output = call
                        .function_data::<Arc<Mutex<SoundOutput>>>()
                        .unwrap()
                        .clone();
                    let retained = table(call, call.captures()[2])?;
                    let paths = table(call, call.raw_table_get(retained, Value::Number(2.))?)?;
                    let result = function_action::read_paths(call, paths);
                    output.lock().unwrap().paths = Some(result);
                    let old = call.raw_table_get(retained, Value::Number(1.))?;
                    let key = call.try_intern(crate::SONG_LUA_SOUND_CALLS_KEY.as_bytes())?;
                    call.table_set(helper(call, 5)?, key, old)
                },
                &captures,
                output.clone(),
            )?;
            vm.raw_table_set(retained, Value::Number(3.), finish)?;
            Ok(())
        })();
        if let Err(error) = result {
            vm.unpin(pin)?;
            return Err(error);
        }
        Ok(SoundSession {
            retained,
            pin,
            output,
        })
    }
    pub(in crate::rust_engine) fn defer_actor_message(
        &self,
        vm: &mut Vm,
        actor: Value,
        name: &str,
        error: &str,
    ) -> Result<String, Error> {
        self.defer_message(vm, actor, name, Failure::Source(error.to_owned()))
    }
    pub(in crate::rust_engine) fn defer_dynamic_actor_message(
        &self,
        vm: &mut Vm,
        actor: Value,
        name: &str,
        error: Option<&str>,
    ) -> Result<String, Error> {
        self.defer_message(
            vm,
            actor,
            name,
            error.map_or(Failure::Changed, |e| Failure::Replay(e.to_owned())),
        )
    }
    fn defer_message(
        &self,
        vm: &mut Vm,
        actor: Value,
        name: &str,
        failure: Failure,
    ) -> Result<String, Error> {
        let output = Arc::new(Mutex::new(None));
        let record = vm.new_host_function_with_data(
            |call| {
                let (store, name, failure, output) = call
                    .function_data::<(Shared, String, Failure, Arc<Mutex<Option<String>>>)>()
                    .unwrap()
                    .clone();
                let actor = table(call, call.captures()[2])?;
                let prior = store
                    .lock()
                    .unwrap()
                    .deferred_messages
                    .iter()
                    .find(|m| m.actor == actor && m.command == name)
                    .map(|m| m.detail.clone());
                let detail = if let Some(prior) = prior {
                    prior
                } else {
                    let mut label = "Actor".to_owned();
                    let mut display = None;
                    for key in ["__songlua_actor_type", "Name"] {
                        let value: Result<Option<String>, Error> = (|| {
                            let key = call.try_intern(key.as_bytes())?;
                            let v = call.table_get(Value::Table(actor), key)?;
                            let Some(id) = call.coerce_string(v)? else {
                                return Ok(None);
                            };
                            Ok(call
                                .string_bytes(id)
                                .and_then(|b| std::str::from_utf8(b).ok())
                                .map(str::to_owned))
                        })();
                        if let Ok(Some(value)) = value {
                            if key == "Name" {
                                display = Some(value)
                            } else {
                                label = value
                            }
                        }
                    }
                    if let Some(display) = display.filter(|n| !n.trim().is_empty()) {
                        label = format!("{label} '{display}'");
                    }
                    let detail = match failure {
                        Failure::Source(error) => format!("{label}.{name}: {error}"),
                        Failure::Replay(error) => format!("{label}.{name} cannot be replayed for stable cross-actor capture: {error}"),
                        Failure::Changed => format!("{label}.{name} changes cross-actor targets or effects between runs"),
                    };
                    let helpers = table(call, call.captures()[1])?;
                    let key = call.try_intern(b"deferred_message_actors")?;
                    let roots = match call.raw_table_get(helpers, key)? {
                        Value::Nil => {
                            let roots = call.try_new_table()?;
                            call.raw_table_set(helpers, key, Value::Table(roots))?;
                            roots
                        }
                        value => table(call, value)?,
                    };
                    call.raw_table_set(roots, Value::Table(actor), Value::Boolean(true))?;
                    store.lock().unwrap().deferred_messages.push(Deferred {
                        actor,
                        command: name,
                        detail: detail.clone(),
                        observed: false,
                    });
                    detail
                };
                *output.lock().unwrap() = Some(detail);
                Ok(())
            },
            &[
                Value::Table(self.registry),
                Value::Table(self.helpers),
                actor,
            ],
            (
                self.store.clone(),
                name.to_owned(),
                failure,
                output.clone(),
            ),
        )?;
        vm.call(record, &[])?;
        Ok(output.lock().unwrap().take().unwrap())
    }
    #[cfg(feature = "test-support")]
    pub(in crate::rust_engine) fn deferred_message_states(
        &self,
    ) -> Vec<(TableId, String, String, bool)> {
        self.store
            .lock()
            .unwrap()
            .deferred_messages
            .iter()
            .map(|m| (m.actor, m.command.clone(), m.detail.clone(), m.observed))
            .collect()
    }
    #[cfg(feature = "test-support")]
    pub(in crate::rust_engine) fn seed_message_sound_block(
        &self,
        actor: Value,
        played: bool,
    ) -> bool {
        let Value::Table(actor) = actor else {
            return false;
        };
        let mut store = self.store.lock().unwrap();
        let Some(actor) = store.actors.get_mut(&actor) else {
            return false;
        };
        actor
            .capture
            .get_or_insert_with(super::super::capture::Capture::default)
            .write(
                crate::SongLuaOverlayStateDelta {
                    sound_play: Some(played),
                    ..Default::default()
                },
                false,
                None,
            );
        true
    }
    #[cfg(feature = "test-support")]
    pub(in crate::rust_engine) fn clear_deferred_message_states(
        &self,
        vm: &mut Vm,
    ) -> Result<(), Error> {
        self.store.lock().unwrap().deferred_messages.clear();
        let key = vm.try_intern(b"deferred_message_actors")?;
        vm.raw_table_set(self.helpers, key, Value::Nil)
    }
}
fn run(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Run>().unwrap().clone();
    let actor = table(call, call.captures()[2])?;
    let Some(command) = lookup(call, actor, &data.name)? else {
        return Ok(());
    };
    call.with_roots(&[command], |call| {
        function_capture::reset(call, &data.store, actor)?;
        let params = super::probe::defaults(call, &data.name)?;
        call.with_roots(&[params.unwrap_or(Value::Nil)], |call| {
            run_guarded_command(
                call,
                &data.store,
                actor,
                data.name.as_bytes().to_vec(),
                command,
                params,
                true,
            )
        })?;
        let blocks = data
            .store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .and_then(|a| a.capture.as_mut())
            .map(|c| c.snapshot().blocks)
            .unwrap_or_default();
        data.output.lock().unwrap().blocks = blocks;
        Ok(())
    })
}

//! Source capture history and scalar globals around one compiler command probe.
use super::*;

pub(super) struct Snapshot {
    actor: TableId,
    raw: TableId,
    saved: function_capture::Saved,
    scalars: Vec<(Value, Value)>,
    names: HashSet<String>,
}
fn scalar(value: Value) -> bool {
    matches!(
        value,
        Value::Boolean(_) | Value::Number(_) | Value::String(_)
    )
}
impl Snapshot {
    pub(super) fn capture(
        call: &mut HostCall<'_>,
        store: &Shared,
        actor: TableId,
        retained: TableId,
    ) -> Result<Self, Error> {
        let raw = state_snapshot::raw_copy_mutable(call, actor)?;
        call.raw_table_set(retained, Value::Number(1.), Value::Table(raw))?;
        let saved = function_capture::Saved::read(store, actor, raw)
            .ok_or_else(|| call.error(b"capture actor is not owned by this runtime"))?;
        let roots = call.try_new_table()?;
        call.raw_table_set(retained, Value::Number(2.), Value::Table(roots))?;
        let output = Arc::new(Mutex::new(None::<ScalarRows>));
        let scan = call.new_host_function_with_data(
            capture_scalars,
            &[helper(call, 5)?, Value::Table(roots)],
            output.clone(),
        )?;
        call.call(scan, &[])?;
        let (scalars, names) = output.lock().unwrap().take().unwrap();
        Ok(Self {
            actor,
            raw,
            saved,
            scalars,
            names,
        })
    }
    pub(super) fn restore(
        self,
        call: &mut HostCall<'_>,
        store: &Shared,
        raw: bool,
    ) -> Result<(), Error> {
        let globals = helper(call, 5)?;
        let output: Removals = Arc::new(Mutex::new(None));
        let scan = call.new_host_function_with_data(
            scan_scalar_removals,
            &[globals],
            (self.names, output.clone()),
        )?;
        call.call(scan, &[])?;
        let keys = output.lock().unwrap().take().unwrap();
        // Validate the complete global-key scan before making any changes.
        for (key, value) in keys
            .into_iter()
            .map(|key| (key, Value::Nil))
            .chain(self.scalars)
        {
            if raw {
                call.raw_table_set(table(call, globals)?, key, value)?;
            } else {
                call.table_set(globals, key, value)?;
            }
        }
        state_snapshot::restore_mutable(call, self.actor, self.raw, raw)?;
        self.saved.restore_mutable(store);
        lifecycle::invalidate_plans(call, store)
    }
}
type ScalarRows = (Vec<(Value, Value)>, HashSet<String>);
fn capture_scalars(call: &mut HostCall<'_>) -> Result<(), Error> {
    let output = call
        .function_data::<Arc<Mutex<Option<ScalarRows>>>>()
        .unwrap()
        .clone();
    let globals = call.captures()[0];
    let roots = call.captures()[1];
    let result = {
        let mut stack = call.native_stack()?;
        stack.push(roots)?;
        let retained = stack.top_offset();
        stack.push(globals)?;
        let globals = stack.top_offset();
        stack.push(Value::Nil)?;
        let mut rows = Vec::new();
        let mut names = HashSet::new();
        while stack.next_table(globals)? {
            let key = stack.value(-2).unwrap();
            let value = stack.value(-1).unwrap();
            if matches!(key, Value::String(_)) && scalar(value) {
                let name = std::str::from_utf8(stack.to_bytes(-2)?.unwrap()).map(str::to_owned);
                let name = name.map_err(|e| stack.error(e.to_string().as_bytes()))?;
                names.insert(name);
                let index = rows.len() * 2 + 1;
                for (slot, item) in [(index, key), (index + 1, value)] {
                    stack.push(Value::Number(slot as f64))?;
                    stack.push(item)?;
                    stack.set_table(retained, true)?;
                }
                rows.push((key, value));
            }
            stack.set_top(stack.top() - 1)?;
        }
        (rows, names)
    };
    *output.lock().unwrap() = Some(result);
    Ok(())
}
type Removals = Arc<Mutex<Option<Vec<Value>>>>;
fn scan_scalar_removals(call: &mut HostCall<'_>) -> Result<(), Error> {
    let (names, output) = call
        .function_data::<(HashSet<String>, Removals)>()
        .unwrap()
        .clone();
    let globals = call.captures()[0];
    let result = {
        let mut stack = call.native_stack()?;
        stack.push(globals)?;
        let globals = stack.top_offset();
        stack.push(Value::Nil)?;
        let mut keys = Vec::new();
        while stack.next_table(globals)? {
            if matches!(stack.value(-2), Some(Value::String(_))) {
                let name = std::str::from_utf8(stack.to_bytes(-2)?.unwrap()).map(str::to_owned);
                let name = name.map_err(|e| stack.error(e.to_string().as_bytes()))?;
                if scalar(stack.value(-1).unwrap()) && !names.contains(&name) {
                    keys.push(stack.value(-2).unwrap());
                }
            }
            stack.set_top(stack.top() - 1)?;
        }
        keys
    };
    *output.lock().unwrap() = Some(result);
    Ok(())
}

//! Retained inputs for the compiler's stable and deferred message passes.
use super::*;

pub(in crate::rust_engine) struct Commands {
    pub rows: Vec<(usize, String, Value)>,
    pub pin: Root,
}
pub(in crate::rust_engine) struct DeferredBatch {
    pub rows: Vec<Deferred>,
    pub pin: Root,
}
type Rows = Arc<Mutex<Vec<(usize, String, Value)>>>;
impl Actors {
    pub(in crate::rust_engine) fn message_command_functions(
        &self,
        vm: &mut Vm,
        actors: &[Value],
    ) -> Result<Commands, Error> {
        let retained = vm.try_new_table()?;
        let pin = vm.pin(Value::Table(retained))?;
        let output: Rows = Arc::new(Mutex::new(Vec::new()));
        let result = (|| {
            let mut captures = vec![Value::Table(retained)];
            captures.extend_from_slice(actors);
            let scan =
                vm.new_host_function_with_data(
                    |call| {
                        let output = call.function_data::<Rows>().unwrap().clone();
                        let retained = table(call, call.captures()[0])?;
                        let actors = call.captures()[1..].to_vec();
                        let rows = {
                            let mut stack = call.native_stack()?;
                            let mut rows = Vec::new();
                            for (source, actor) in actors.into_iter().enumerate() {
                                stack.push(actor)?;
                                let actor = stack.top_offset();
                                stack.push(Value::Nil)?;
                                while stack.next_table(actor)? {
                                    if matches!(stack.value(-2), Some(Value::String(_)))
                                        && let Some(
                                            function @ (Value::Function(_) | Value::Native(_)),
                                        ) = stack.value(-1)
                                        && let Some(bytes) = stack.to_bytes(-2)?
                                        && let Ok(name) = std::str::from_utf8(bytes)
                                        && name.ends_with("MessageCommand")
                                    {
                                        rows.push((source, name.to_owned(), function));
                                    }
                                    stack.set_top(stack.top() - 1)?;
                                }
                                stack.set_top(stack.top() - 1)?;
                            }
                            rows
                        };
                        let roots = rows.iter().map(|r| r.2).collect::<Vec<_>>();
                        call.with_roots(&roots, |call| {
                            for (i, function) in roots.iter().enumerate() {
                                call.raw_table_set(
                                    retained,
                                    Value::Number((i + 1) as f64),
                                    *function,
                                )?;
                            }
                            Ok(())
                        })?;
                        *output.lock().unwrap() = rows;
                        Ok(())
                    },
                    &captures,
                    output.clone(),
                )?;
            vm.call(scan, &[])?;
            Ok(())
        })();
        if let Err(error) = result {
            vm.unpin(pin)?;
            return Err(error);
        }
        Ok(Commands {
            rows: std::mem::take(&mut *output.lock().unwrap()),
            pin,
        })
    }
    pub(in crate::rust_engine) fn take_deferred_messages(
        &self,
        vm: &mut Vm,
    ) -> Result<DeferredBatch, Error> {
        let key = vm.try_intern(b"deferred_message_actors")?;
        let roots = vm.raw_table_get(self.helpers, key)?;
        // Native removes its app data before retrying. Keep the removed actors
        // independently rooted, including actors already retired from a scene.
        let pin = vm.pin(roots)?;
        if let Err(error) = vm.raw_table_set(self.helpers, key, Value::Nil) {
            vm.unpin(pin)?;
            return Err(error);
        }
        let rows = std::mem::take(&mut self.store.lock().unwrap().deferred_messages);
        Ok(DeferredBatch { rows, pin })
    }
}

//! Existing authored Judgment normalization and retained note/result methods.
use super::*;

fn field(call: &mut HostCall<'_>, table: TableId, name: &[u8]) -> Result<Value, Error> {
    let name = call.try_intern(name)?;
    call.table_get(Value::Table(table), name)
}
pub(super) fn set(
    call: &mut HostCall<'_>,
    table: TableId,
    name: &[u8],
    value: Value,
) -> Result<(), Error> {
    let name = call.try_intern(name)?;
    call.table_set(Value::Table(table), name, value)
}
fn first<T>(
    call: &mut HostCall<'_>,
    table: TableId,
    names: &[&[u8]],
    convert: impl Fn(&HostCall<'_>, Value) -> Option<T>,
) -> Result<Option<T>, Error> {
    for name in names {
        let value = field(call, table, name)?;
        if let Some(value) = convert(call, value) {
            return Ok(Some(value));
        }
    }
    Ok(None)
}
fn text_field(
    call: &mut HostCall<'_>,
    table: TableId,
    names: &[&[u8]],
) -> Result<Option<Vec<u8>>, Error> {
    first(call, table, names, command_name)
}
fn float_field(
    call: &mut HostCall<'_>,
    table: TableId,
    names: &[&[u8]],
) -> Result<Option<f32>, Error> {
    first(call, table, names, |call, value| {
        float_scalar(call, value, false)
    })
}
fn constant(call: &mut HostCall<'_>) -> Result<(), Error> {
    call.push(call.captures()[0])
}
fn method(call: &mut HostCall<'_>, table: TableId, name: &[u8], value: Value) -> Result<(), Error> {
    let function = call.new_host_function(constant, &[value])?;
    set(call, table, name, function)
}
fn string_method(
    call: &mut HostCall<'_>,
    table: TableId,
    name: &[u8],
    value: &[u8],
) -> Result<(), Error> {
    let value = call.try_intern(value)?;
    method(call, table, name, value)
}

pub(super) fn normalize(call: &mut HostCall<'_>, params: TableId) -> Result<(), Error> {
    for (key, default) in [
        (b"Player".as_slice(), b"PlayerNumber_P1".as_slice()),
        (b"TapNoteScore", b"TapNoteScore_W3"),
        (b"HoldNoteScore", b"HoldNoteScore_None"),
    ] {
        if field(call, params, key)? == Value::Nil {
            let default = call.try_intern(default)?;
            set(call, params, key, default)?;
        }
    }
    if field(call, params, b"TapNoteOffset")? == Value::Nil {
        set(call, params, b"TapNoteOffset", Value::Number(0.0))?;
    }
    let notes = match field(call, params, b"Notes")? {
        Value::Table(notes) => notes,
        _ => {
            let notes = call.try_new_table()?;
            call.with_roots(&[Value::Table(notes)], |call| {
                let track = first(call, params, &[b"FirstTrack", b"Column"], integer_scalar)?
                    .unwrap_or(0)
                    .max(0);
                let note = create_note(call, params, None)?;
                call.raw_table_set(notes, Value::Number(track as f64 + 1.0), Value::Table(note))?;
                set(call, params, b"Notes", Value::Table(notes))?;
                Ok(notes)
            })?
        }
    };
    call.with_roots(&[Value::Table(notes)], |call| {
        let entries = call.call(helper(call, 7)?, &[Value::Table(notes)])?[0];
        call.with_roots(&[entries], |call| {
            let entries = table(call, entries)?;
            let count = call.raw_table_len(entries)?;
            if count == 0 {
                let note = create_note(call, params, None)?;
                call.raw_table_set(notes, Value::Number(1.0), Value::Table(note))?;
            }
            for index in 1..=count {
                let entry = table(
                    call,
                    call.raw_table_get(entries, Value::Number(index as f64))?,
                )?;
                let key = call.raw_table_get(entry, Value::Number(1.0))?;
                let value = call.raw_table_get(entry, Value::Number(2.0))?;
                let note = match value {
                    Value::Table(note) => {
                        normalize_note(call, params, note)?;
                        note
                    }
                    value => create_note(call, params, Some(value))?,
                };
                call.table_set(Value::Table(notes), key, Value::Table(note))?;
            }
            Ok(())
        })
    })
}

fn create_note(
    call: &mut HostCall<'_>,
    params: TableId,
    value: Option<Value>,
) -> Result<TableId, Error> {
    let note = call.try_new_table()?;
    call.with_roots(&[Value::Table(note)], |call| {
        if let Some(value) = value {
            set(call, note, b"TapNoteType", value)?;
        }
        normalize_note(call, params, note)?;
        Ok(note)
    })
}

fn normalize_note(call: &mut HostCall<'_>, params: TableId, note: TableId) -> Result<(), Error> {
    if field(call, note, b"GetTapNoteType")? != Value::Nil {
        return Ok(());
    }
    let result = match field(call, note, b"TapNoteResult")? {
        Value::Table(result) => result,
        _ => call.try_new_table()?,
    };
    call.with_roots(&[Value::Table(result)], |call| {
        if field(call, result, b"GetHeld")? == Value::Nil {
            result_methods(call, params, note, result)?;
        }
        set(call, note, b"TapNoteResult", Value::Table(result))?;
        set(call, note, b"HoldNoteResult", Value::Table(result))?;
        note_methods(call, params, note, result)
    })
}

fn result_methods(
    call: &mut HostCall<'_>,
    params: TableId,
    note: TableId,
    result: TableId,
) -> Result<(), Error> {
    let held = first(call, note, &[b"Held", b"held"], boolish)?.unwrap_or(false);
    let hidden = first(call, note, &[b"Hidden", b"hidden"], boolish)?.unwrap_or(false);
    let offset = float_field(call, note, &[b"TapNoteOffset", b"Offset"])?
        .or(float_field(call, params, &[b"TapNoteOffset", b"Offset"])?)
        .unwrap_or(0.0);
    let score = text_field(call, note, &[b"TapNoteScore", b"Score"])?
        .or(text_field(call, params, &[b"TapNoteScore", b"Score"])?)
        .unwrap_or_else(|| b"TapNoteScore_None".to_vec());
    method(call, result, b"GetHeld", Value::Boolean(held))?;
    method(call, result, b"GetHidden", Value::Boolean(hidden))?;
    method(
        call,
        result,
        b"GetTapNoteOffset",
        Value::Number(offset as f64),
    )?;
    string_method(call, result, b"GetTapNoteScore", &score)
}

fn note_methods(
    call: &mut HostCall<'_>,
    params: TableId,
    note: TableId,
    result: TableId,
) -> Result<(), Error> {
    let kind = text_field(call, note, &[b"TapNoteType", b"Type", b"NoteType"])?
        .or(text_field(
            call,
            params,
            &[b"TapNoteType", b"Type", b"NoteType"],
        )?)
        .unwrap_or_else(|| b"TapNoteType_Tap".to_vec());
    let source = text_field(call, note, &[b"TapNoteSource", b"Source"])?
        .unwrap_or_else(|| b"TapNoteSource_Original".to_vec());
    let subtype = text_field(call, note, &[b"TapNoteSubType", b"SubType"])?
        .unwrap_or_else(|| b"TapNoteSubType_Hold".to_vec());
    let player =
        text_field(call, params, &[b"Player"])?.unwrap_or_else(|| b"PlayerNumber_P1".to_vec());
    let hold = float_field(call, note, &[b"HoldDuration"])?.unwrap_or(0.0);
    let attack = float_field(call, note, &[b"AttackDuration"])?.unwrap_or(0.0);
    let mods = text_field(call, note, &[b"AttackModifiers"])?.unwrap_or_default();
    let keysound = first(call, note, &[b"KeysoundIndex"], integer_scalar)?.unwrap_or(0);
    for (name, value) in [
        (b"GetTapNoteType".as_slice(), kind),
        (b"GetTapNoteSource", source),
        (b"GetTapNoteSubType", subtype),
        (b"GetPlayerNumber", player),
        (b"GetAttackModifiers", mods),
    ] {
        string_method(call, note, name, &value)?;
    }
    method(call, note, b"GetTapNoteResult", Value::Table(result))?;
    method(call, note, b"GetHoldNoteResult", Value::Table(result))?;
    for (name, value) in [
        (b"GetHoldDuration".as_slice(), hold as f64),
        (b"GetAttackDuration", attack as f64),
        (b"GetKeysoundIndex", keysound as f64),
    ] {
        method(call, note, name, Value::Number(value))?;
    }
    Ok(())
}

//! Existing compiler message defaults and a retained, guarded command runner.
use super::*;

#[derive(Clone)]
struct Run {
    store: Shared,
    name: Vec<u8>,
}
impl Actors {
    pub(in crate::rust_engine) fn default_message_command_params(
        &self,
        vm: &mut Vm,
        name: &str,
    ) -> Result<Option<Root>, Error> {
        let produce = vm.new_host_function_with_data(
            |call| {
                let name = call.function_data::<String>().unwrap().clone();
                let params = defaults(call, &name)?;
                call.push(params.unwrap_or(Value::Nil))
            },
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            name.to_owned(),
        )?;
        let value = vm.call(produce, &[])?[0];
        if value == Value::Nil {
            Ok(None)
        } else {
            vm.pin(value).map(Some)
        }
    }

    pub(in crate::rust_engine) fn message_capture_runner(
        &self,
        vm: &mut Vm,
        actor: Value,
        name: &str,
        command: Value,
    ) -> Result<Root, Error> {
        let mut inputs = Vec::new();
        let result = (|| {
            inputs.push(vm.pin(actor)?);
            inputs.push(vm.pin(command)?);
            if !matches!(actor, Value::Table(id) if self.store.lock().unwrap().actors.contains_key(&id))
            {
                return vm.with_native_stack(|s| Err(s.error(b"owned actor table expected")));
            }
            if !matches!(command, Value::Function(_) | Value::Native(_)) {
                return vm
                    .with_native_stack(|s| Err(s.error(b"message command function expected")));
            }
            let produce = vm.new_host_function_with_data(
                |call| {
                    let data = call.function_data::<Run>().unwrap().clone();
                    let name = std::str::from_utf8(&data.name).unwrap();
                    let params = defaults(call, name)?.unwrap_or(Value::Nil);
                    call.with_roots(&[params], |call| {
                        let mut captures = call.captures().to_vec();
                        captures.push(params);
                        let runner = call.new_host_function_with_data(run, &captures, data)?;
                        call.push(runner)
                    })
                },
                &[
                    Value::Table(self.registry),
                    Value::Table(self.helpers),
                    actor,
                    command,
                ],
                Run {
                    store: self.store.clone(),
                    name: name.as_bytes().to_vec(),
                },
            )?;
            let runner = vm.call(produce, &[])?[0];
            vm.pin(runner)
        })();
        for input in inputs {
            vm.unpin(input)?;
        }
        result
    }
}

fn run(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Run>().unwrap().clone();
    let actor = table(call, call.captures()[2])?;
    let command = call.captures()[3];
    let params = call.captures()[4];
    // Use the selected function even when its source field was replaced. The
    // command path drains its receiver and work queued by it, not other actors.
    run_guarded_command(
        call,
        &data.store,
        actor,
        data.name,
        command,
        (params != Value::Nil).then_some(params),
        true,
    )
}

fn constant(call: &mut HostCall<'_>) -> Result<(), Error> {
    call.push(call.captures()[0])
}
fn set_text(
    call: &mut HostCall<'_>,
    params: TableId,
    key: &[u8],
    text: &[u8],
) -> Result<(), Error> {
    let value = call.try_intern(text)?;
    judgment::set(call, params, key, value)
}
pub(super) fn defaults(call: &mut HostCall<'_>, name: &str) -> Result<Option<Value>, Error> {
    let Some(message) = name.strip_suffix("MessageCommand") else {
        return Ok(None);
    };
    let params = call.try_new_table()?;
    call.with_roots(&[Value::Table(params)], |call| {
        match message {
            "Judgment" => {
                set_text(call, params, b"Player", b"PlayerNumber_P1")?;
                set_text(call, params, b"TapNoteScore", b"TapNoteScore_W3")?;
                judgment::set(call, params, b"TapNoteOffset", Value::Number(0.))?;
                judgment::set(call, params, b"FirstTrack", Value::Number(0.))?;
                judgment::normalize(call, params)?;
            }
            "EarlyHit" => {
                set_text(call, params, b"Player", b"PlayerNumber_P1")?;
                set_text(call, params, b"TapNoteScore", b"TapNoteScore_W3")?;
                judgment::set(
                    call,
                    params,
                    b"TapNoteOffset",
                    Value::Number(f64::from(-0.02_f32)),
                )?;
                judgment::set(call, params, b"Early", Value::Boolean(true))?;
            }
            "LifeChanged" => {
                set_text(call, params, b"Player", b"PlayerNumber_P1")?;
                let meter = call.try_new_table()?;
                call.with_roots(&[Value::Table(meter)], |call| {
                    for (name, value) in [
                        (
                            b"GetLife".as_slice(),
                            Value::Number(f64::from(crate::SONG_LUA_INITIAL_LIFE)),
                        ),
                        (b"IsFailing", Value::Boolean(false)),
                        (b"IsHot", Value::Boolean(false)),
                        (b"IsInDanger", Value::Boolean(false)),
                    ] {
                        let method = call.new_host_function(constant, &[value])?;
                        judgment::set(call, meter, name, method)?;
                    }
                    judgment::set(call, params, b"LifeMeter", Value::Table(meter))
                })?;
            }
            "HealthStateChanged" => {
                set_text(call, params, b"Player", b"PlayerNumber_P1")?;
                set_text(call, params, b"PlayerNumber", b"PlayerNumber_P1")?;
                set_text(call, params, b"HealthState", b"HealthState_Alive")?;
            }
            "ExCountsChanged" => {
                set_text(call, params, b"Player", b"PlayerNumber_P1")?;
                let counts = call.try_new_table()?;
                call.with_roots(&[Value::Table(counts)], |call| {
                    for key in [
                        "W0", "W1", "W2", "W3", "W4", "W5", "Miss", "Held", "LetGo", "HitMine",
                    ] {
                        judgment::set(call, counts, key.as_bytes(), Value::Number(0.))?;
                    }
                    judgment::set(call, params, b"ExCounts", Value::Table(counts))
                })?;
                for key in ["ExScore", "ActualPoints"] {
                    judgment::set(call, params, key.as_bytes(), Value::Number(0.))?;
                }
                for key in ["ActualPossible", "CurrentPossible"] {
                    judgment::set(call, params, key.as_bytes(), Value::Number(1.))?;
                }
            }
            "PlayerOptionsChanged" => {
                set_text(call, params, b"Player", b"PlayerNumber_P1")?;
                set_text(call, params, b"PlayerNumber", b"PlayerNumber_P1")?;
            }
            _ => return Ok(None),
        }
        Ok(Some(Value::Table(params)))
    })
}

//! Model resources and the existing preparation-time material clocks.
use super::*;
use std::path::PathBuf;

pub(super) fn initialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    template: bool,
) -> Result<(), Error> {
    let methods = native_children::helper_function(call, b"model_methods")?;
    let methods = table(call, methods)?;
    let bound = get(call, actor, b"__songlua_bound_methods")?;
    let bound = table(call, bound)?;
    for &name in sprites::SPRITE_METHODS
        .iter()
        .chain(["GetChild", "GetChildren", "GetNumChildren"].iter())
    {
        let method = get(call, methods, name.as_bytes())?;
        let captures = [
            call.captures()[0],
            call.captures()[1],
            Value::Table(actor),
            method,
        ];
        let function = call.new_host_function_with_data(invoke_bound, &captures, name)?;
        sprites::set(call, bound, name, function)?;
    }
    if !template {
        let mut guard = store.lock().unwrap();
        let state = &mut guard.actors.get_mut(&actor).unwrap().state.render;
        state.depth_test = true;
        state.depth_write = true;
        state.texture_wrapping = true;
        state.cull_mode = deadlib_render_core::CullMode::Back;
    }
    Ok(())
}

pub(super) fn paths(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Option<[PathBuf; 3]>, Error> {
    let mut paths = [None, None, None];
    for (index, key) in [b"Meshes".as_slice(), b"Materials", b"Bones"]
        .into_iter()
        .enumerate()
    {
        let Some(raw) = assets::field(call, actor, key)?.filter(|path| !path.trim().is_empty())
        else {
            continue;
        };
        let path = assets::resolve(call, actor, &raw)?.ok_or_else(|| {
            call.error(format!("actor asset '{raw}' could not be resolved").as_bytes())
        })?;
        paths[index] = Some(path);
    }
    let Some(fallback) = paths.iter().flatten().next().cloned() else {
        return Ok(None);
    };
    Ok(Some(
        paths.map(|path| path.unwrap_or_else(|| fallback.clone())),
    ))
}

pub(super) fn tap_model(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Option<crate::lua_util::SongLuaNoteskinTapActorModel>, Error> {
    let Some(skin) = assets::field(call, actor, b"__songlua_noteskin_name")?
        .filter(|skin| !skin.trim().is_empty())
    else {
        return Ok(None);
    };
    let Some(element) = assets::field(call, actor, b"__songlua_noteskin_element")?
        .filter(|element| element.eq_ignore_ascii_case("Tap Note"))
    else {
        return Ok(None);
    };
    let Some(model_paths) = paths(call, actor)? else {
        return Ok(None);
    };
    Ok(Some(crate::lua_util::SongLuaNoteskinTapActorModel {
        skin,
        element,
        model_paths,
    }))
}

pub(super) fn advance_materials(store: &Shared, actor: TableId, delta: f32) {
    if let Some(actor) = store.lock().unwrap().actors.get_mut(&actor) {
        for clock in actor.model_materials.iter_mut().flatten() {
            clock.update(delta);
        }
    }
}

impl Actors {
    pub(in crate::rust_engine) fn model_paths(
        &self,
        vm: &mut Vm,
        actor: Value,
    ) -> Result<Option<[PathBuf; 3]>, Error> {
        self.store.lock().unwrap().model_paths_output = None;
        let function = vm.rooted(self.read_model_paths)?;
        let result = vm.call(function, &[actor]);
        let paths = self.store.lock().unwrap().model_paths_output.take();
        result?;
        Ok(paths)
    }

    pub(in crate::rust_engine) fn install_model_materials<V>(
        &self,
        actor: Value,
        layers: &[crate::SongLuaOverlayModelLayer<V>],
    ) -> Result<(), String> {
        let Value::Table(actor) = actor else {
            return Err("model material owner must be an actor table".into());
        };
        let mut store = self.store.lock().unwrap();
        let actor = store
            .actors
            .get_mut(&actor)
            .ok_or("model material owner has been released or belongs to another runtime")?;
        let state = actor.state.render.sprite_state_index;
        actor.model_materials = layers
            .iter()
            .map(|layer| crate::model_texture::Clock::with_initial_state(layer, state))
            .collect();
        Ok(())
    }

    pub(in crate::rust_engine) fn sample_model_materials(&self, second: f32) {
        for actor in self.store.lock().unwrap().actors.values_mut() {
            for clock in actor.model_materials.iter_mut().flatten() {
                clock.sample(second);
            }
        }
    }

    pub(in crate::rust_engine) fn take_model_material_samples(
        &self,
        actor: Value,
    ) -> Result<Vec<Arc<[crate::SongLuaTextureSample]>>, String> {
        let Value::Table(actor) = actor else {
            return Err("model material owner must be an actor table".into());
        };
        let mut store = self.store.lock().unwrap();
        let actor = store
            .actors
            .get_mut(&actor)
            .ok_or("model material owner has been released or belongs to another runtime")?;
        Ok(std::mem::take(&mut actor.model_materials)
            .into_iter()
            .map(|clock| clock.map_or_else(|| Arc::from([]), crate::model_texture::Clock::finish))
            .collect())
    }
}

//! Named native children shared by composite actor bindings.
use super::*;
use sprites::set;

pub(super) fn install_helpers(vm: &mut Vm, actor: TableId, helpers: TableId) -> Result<(), Error> {
    let setup = compile_named(
        include_bytes!("native_children.lua"),
        b"=DeadSync native children",
    )?;
    let setup = vm.execute(&setup)?[0];
    let root = vm.pin(setup)?;
    let key = vm.try_intern(b"GetName")?;
    let get_name = vm.raw_table_get(actor, key)?;
    let group = vm.raw_table_get(helpers, Value::Number(3.0))?;
    let functions = vm.call(setup, &[group, get_name])?.to_vec();
    for (key, function) in [
        "native_registry",
        "native_named_children",
        "native_children",
        "native_is_group",
    ]
    .into_iter()
    .zip(functions)
    {
        super::super::put(vm, helpers, key, function)?;
    }
    vm.unpin(root)?;
    Ok(())
}

pub(super) fn helper_function(call: &mut HostCall<'_>, name: &[u8]) -> Result<Value, Error> {
    let helpers = table(call, call.captures()[1])?;
    get(call, helpers, name)
}

pub(super) fn named_children(call: &mut HostCall<'_>, actor: TableId) -> Result<Value, Error> {
    let function = helper_function(call, b"native_named_children")?;
    Ok(call.call(function, &[Value::Table(actor)])?[0])
}

pub(super) fn children(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<Vec<TableId>, Error> {
    let function = helper_function(call, b"native_children")?;
    let values = call.call(function, &[Value::Table(actor)])?[0];
    call.with_roots(&[values], |call| {
        let values = table(call, values)?;
        let mut result = Vec::new();
        for i in 1..=call.raw_table_len(values)? {
            let value = call.raw_table_get(values, Value::Number(i as f64))?;
            let id = table(call, value)?;
            if !store.lock().unwrap().actors.contains_key(&id) {
                return Err(call.error(b"native child is not owned by this runtime"));
            }
            result.push(id);
        }
        Ok(result)
    })
}

pub(super) fn state(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<crate::SongLuaOverlayState, Error> {
    if !store.lock().unwrap().actors.contains_key(&actor) {
        let is_group = helper_function(call, b"native_is_group")?;
        if call.call(is_group, &[Value::Table(actor)])?[0] == Value::Boolean(true) {
            return Ok(crate::SongLuaOverlayState::default());
        }
    }
    let store = store.lock().unwrap();
    let actor = store
        .actors
        .get(&actor)
        .ok_or_else(|| call.error(b"graph render child has been released"))?;
    let mut state = actor.state.render;
    actor.destination().write_to(&mut state);
    [state.rot_x_deg, state.rot_y_deg, state.rot_z_deg] = actor.state.rotation;
    state.visible = actor.state.visible;
    state.draw_order = actor.state.draw_order;
    state.hibernating = actor.hibernate > 0.0;
    Ok(state)
}

pub(super) fn insert(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &str,
    value: Value,
) -> Result<(), Error> {
    call.with_roots(&[value], |call| {
        let registry = helper_function(call, b"native_registry")?;
        let registry = call.call(registry, &[Value::Table(actor)])?[0];
        call.with_roots(&[registry], |call| {
            set(call, table(call, registry)?, key, value)
        })
    })
}

pub(super) fn group_members(
    call: &mut HostCall<'_>,
    group: TableId,
) -> Result<Vec<TableId>, Error> {
    let check = helper_function(call, b"native_is_group")?;
    if call.call(check, &[Value::Table(group)])?[0] != Value::Boolean(true) {
        return Err(call.error(b"native child is not an actor or a generated child group"));
    }
    let mut members = Vec::new();
    for i in 1..=call.raw_table_len(group)? {
        members.push(table(
            call,
            call.raw_table_get(group, Value::Number(i as f64))?,
        )?);
    }
    Ok(members)
}

pub(super) fn adopt(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    parent: TableId,
) -> Result<(), Error> {
    set(call, actor, "__songlua_parent", Value::Table(parent))?;
    if let Some(actor) = store.lock().unwrap().actors.get_mut(&actor) {
        actor.parent = Some(parent);
    }
    Ok(())
}

pub(super) fn adopt_declared(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    parent: TableId,
) -> Result<(), Error> {
    let kind = call.try_intern(b"__songlua_actor_type")?;
    let value = call.raw_table_get(parent, kind)?;
    if value == Value::Nil {
        return Ok(());
    }
    assets::text(call, value)?;
    let key = call.try_intern(b"__songlua_parent")?;
    call.raw_table_set(actor, key, Value::Table(parent))?;
    if let Some(actor) = store.lock().unwrap().actors.get_mut(&actor) {
        actor.parent = Some(parent);
    }
    Ok(())
}

pub(super) fn group_lifecycle(
    call: &mut HostCall<'_>,
    store: &Shared,
    group: TableId,
    startup: bool,
) -> Result<(), Error> {
    call.with_roots(&[Value::Table(group)], |call| {
        let children = group_members(call, group)?;
        // A fresh group forwards the lifecycle guard to its last child, just
        // like any other instance field. Authored children have already run.
        if children.last().is_some_and(|child| {
            store
                .lock()
                .unwrap()
                .actors
                .get(child)
                .is_some_and(|a| if startup { a.started } else { a.initialized })
        }) {
            return Ok(());
        }
        if startup && let Some((function, _)) = command(call, group, b"On")? {
            run_actor_function(call, store, group, function, None)?;
        }
        for child in children {
            adopt_declared(call, store, child, group)?;
            if startup {
                lifecycle::startup(call, store, child)?;
            } else {
                initialize(call, store, child)?;
            }
        }
        if !startup && let Some((function, _)) = command(call, group, b"Init")? {
            run_actor_function(call, store, group, function, None)?;
        }
        Ok(())
    })
}

pub(super) fn with_children(
    call: &mut HostCall<'_>,
    actor: TableId,
    mut action: impl FnMut(&mut HostCall<'_>, TableId) -> Result<(), Error>,
) -> Result<(), Error> {
    let helper = native_children::helper_function(call, b"native_children")?;
    let children = call.call(helper, &[Value::Table(actor)])?[0];
    // Native direct-child enumeration owns its snapshot even when a callback
    // removes a plain table child from the current registry and collects.
    call.with_roots(&[children], |call| {
        let children = table(call, children)?;
        for index in 1..=call.raw_table_len(children)? {
            let value = call.raw_table_get(children, Value::Number(index as f64))?;
            action(call, table(call, value)?)?;
        }
        Ok(())
    })
}

pub(super) fn run_command(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Option<Value>,
) -> Result<(), Error> {
    run_command_with_drain(call, store, actor, name, params, true)
}
pub(super) fn run_command_with_drain(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Option<Value>,
    drain: bool,
) -> Result<(), Error> {
    if store.lock().unwrap().actors.contains_key(&actor) {
        return run_named_with_drain(call, store, actor, name, params, drain);
    }
    // These setters accept a table receiver, and native named registries can
    // contain plain callback tables. Preserve their guard without treating an
    // unowned table as an entry in the Rust actor store.
    let Some((function, command_field)) = command(call, actor, name)? else {
        return Ok(());
    };
    call.with_roots(
        &[Value::Table(actor), function, params.unwrap_or(Value::Nil)],
        |call| {
            let active = sprites::field(call, actor, "__songlua_active_commands")?;
            let active = if active == Value::Nil {
                let value = Value::Table(call.try_new_table()?);
                sprites::set(call, actor, "__songlua_active_commands", value)?;
                value
            } else {
                active
            };
            table(call, active)?;
            call.with_roots(&[active], |call| {
                let key = call.try_intern(&command_field)?;
                call.with_roots(&[key], |call| {
                    if !matches!(
                        call.table_get(active, key)?,
                        Value::Nil | Value::Boolean(false)
                    ) {
                        return Ok(());
                    }
                    call.table_set(active, key, Value::Boolean(true))?;
                    let result = (|| {
                        let theme =
                            call.call(helper(call, 4)?, &[function])?[0] == Value::Boolean(true);
                        match run_actor_function(call, store, actor, function, params) {
                            Err(error) if theme && error.kind() == ErrorKind::Runtime => {
                                store.lock().unwrap().diagnostics.push(error.to_string());
                                Ok(())
                            }
                            result => result,
                        }
                    })();
                    call.table_set(active, key, Value::Nil)?;
                    result
                })
            })
        },
    )
}

//! Generated NoteField, Board and the eagerly owned style-column vector.
use super::*;
use generated_players::dummy;
use sprites::{field, set};

#[derive(Clone)]
struct Binding {
    store: Shared,
    scene: u64,
    name: &'static str,
}
struct Build {
    store: Shared,
    player: usize,
    style: String,
}
impl Actors {
    pub(in crate::rust_engine) fn note_field(
        &self,
        vm: &mut Vm,
        player: usize,
        style: &str,
    ) -> Result<ActorScene, Error> {
        let function = vm.new_host_function_with_data(
            construct,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Build {
                store: self.store.clone(),
                player,
                style: style.to_owned(),
            },
        )?;
        let Value::Number(id) = vm.call(function, &[])?[0] else {
            unreachable!()
        };
        Ok(ActorScene {
            owner: self.instantiate,
            id: id as u64,
        })
    }
}
fn construct(call: &mut HostCall<'_>) -> Result<(), Error> {
    let build = call.function_data::<Build>().unwrap();
    let store = build.store.clone();
    let player = build.player;
    let style = build.style.clone();
    let id = {
        let mut guard = store.lock().unwrap();
        if guard.next >= (1u64 << 53) - 1 {
            return Err(call.error(b"actor scene identity exhausted"));
        }
        guard.next += 1;
        let id = guard.next;
        guard.scenes.insert(
            id,
            Scene {
                actors: Vec::new(),
                root: None,
                ended: false,
                sounds_retired: false,
                initial_states: None,
                song_session: None,
            },
        );
        id
    };
    let result = create(call, &store, id, player, &style);
    match result {
        Ok(actor) => store.lock().unwrap().scenes.get_mut(&id).unwrap().root = Some(actor),
        Err(error) => {
            release(call, &store, id)?;
            return Err(error);
        }
    }
    call.push(Value::Number(id as f64))
}

pub(super) fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    player: usize,
    style: &str,
) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "NoteField", "", None)?;
    let board = dummy(call, store, scene, "Sprite", "Board", Some(actor))?;
    let path =
        crate::blank_texture::load_native_blank_texture().map_err(|e| call.error(e.as_bytes()))?;
    let path = call.try_intern(path.as_bytes())?;
    sprites::set_texture(call, store, board, path, false)?;
    call.raw_table_set(actor, Value::Number(1.), Value::Table(board))?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .children
        .push(board);
    native_children::insert(call, actor, "Board", Value::Table(board))?;
    set(
        call,
        actor,
        "__songlua_player_index",
        Value::Number(player as f64),
    )?;
    let style = call.try_intern(style.as_bytes())?;
    set(call, actor, "__songlua_style_name", style)?;
    let kind = call.try_intern(b"NoteField")?;
    set(call, actor, "__songlua_player_child_name", kind)?;
    set(call, actor, "__songlua_beat_bars", Value::Boolean(false))?;
    let alpha = call.try_new_table()?;
    set(
        call,
        actor,
        "__songlua_beat_bars_alpha",
        Value::Table(alpha),
    )?;
    for name in [
        "GetColumnActors",
        "get_column_actors",
        "SetBeatBars",
        "SetBeatBarsAlpha",
        "SetDidTapNoteCallback",
        "did_tap_note",
    ] {
        let function = call.new_host_function_with_data(
            method,
            &[call.captures()[0], call.captures()[1], Value::Table(actor)],
            Binding {
                store: store.clone(),
                scene,
                name,
            },
        )?;
        call.with_roots(&[function], |call| {
            let value = get(call, actor, b"__songlua_bound_methods")?;
            let bound = table(call, value)?;
            set(call, bound, name, function)?;
            if name == "SetDidTapNoteCallback" {
                set(call, bound, "set_did_tap_note_callback", function)?;
            }
            Ok(())
        })?;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .current
        .y = f32::midpoint(crate::THEME_RECEPTOR_Y_STD, crate::THEME_RECEPTOR_Y_REV);
    columns(call, store, scene, actor)?;
    Ok(actor)
}

fn text(call: &HostCall<'_>, value: Value) -> Result<String, Error> {
    let Value::String(id) = value else {
        return Err(call.error(b"string field expected"));
    };
    std::str::from_utf8(
        call.string_bytes(id)
            .ok_or_else(|| call.error(b"string is not retained"))?,
    )
    .map(str::to_owned)
    .map_err(|_| call.error(b"UTF-8 string expected"))
}
fn tolerate<T>(result: Result<T, Error>) -> Result<Option<T>, Error> {
    match result {
        Ok(value) => Ok(Some(value)),
        Err(error) if error.kind() == ErrorKind::Runtime => Ok(None),
        Err(error) => Err(error),
    }
}
fn current_style(call: &mut HostCall<'_>) -> Result<String, Error> {
    let globals = helper(call, 5)?;
    let selected = tolerate((|| {
        let key = call.try_intern(b"GAMESTATE")?;
        let state = call.table_get(globals, key)?;
        call.with_roots(&[state], |call| {
            let key = call.try_intern(b"__songlua_current_style")?;
            let slots = table(call, call.raw_table_get(table(call, state)?, key)?)?;
            call.raw_table_get(slots, Value::Number(1.))
        })
    })())?;
    let selected = if let Some(selected) = selected {
        Some(selected)
    } else {
        tolerate((|| {
            let key = call.try_intern(b"GAMESTATE")?;
            let state = call.table_get(globals, key)?;
            call.with_roots(&[state], |call| {
                let function = field(call, table(call, state)?, "GetCurrentStyle")?;
                if !matches!(function, Value::Function(_) | Value::Native(_)) {
                    return Err(call.error(b"style getter expected"));
                }
                Ok(call
                    .call(function, &[state])?
                    .first()
                    .copied()
                    .unwrap_or(Value::Nil))
            })
        })())?
    };
    let Some(Value::Table(style)) = selected else {
        return Ok("single".into());
    };
    call.with_roots(&[Value::Table(style)], |call| {
        let key = call.try_intern(b"__songlua_style_key")?;
        if let Some(key) = tolerate(text(call, call.raw_table_get(style, key)?))? {
            return Ok(key);
        }
        let value = tolerate((|| {
            let function = field(call, style, "GetName")?;
            if !matches!(function, Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"style getter expected"));
            }
            let value = call
                .call(function, &[Value::Table(style)])?
                .first()
                .copied()
                .unwrap_or(Value::Nil);
            text(call, value)
        })())?;
        Ok(value.unwrap_or_else(|| "single".into()))
    })
}

fn columns(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
) -> Result<Value, Error> {
    let cached = field(call, actor, "__songlua_note_columns")?;
    if cached != Value::Nil {
        table(call, cached)?;
        return Ok(cached);
    }
    if !store.lock().unwrap().scenes.contains_key(&scene) {
        return Err(call.error(b"NoteField scene has been released"));
    }
    let columns = call.try_new_table()?;
    call.with_roots(&[Value::Table(columns)], |call| {
        let value = field(call, actor, "__songlua_player_index")?;
        let player = if value == Value::Nil {
            0
        } else {
            let n = sprites::number(call, value)?;
            if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&n) {
                return Err(call.error(b"player index out of range"));
            }
            n as i64 as usize
        };
        let value = field(call, actor, "__songlua_style_name")?;
        let style = if value == Value::Nil {
            current_style(call)?
        } else {
            text(call, value)?
        };
        for index in 0..crate::song_lua_style_info(&style).columns {
            let column = dummy(call, store, scene, "NoteColumnRenderer", "", Some(actor))?;
            set(
                call,
                column,
                "__songlua_player_index",
                Value::Number(player as i64 as f64),
            )?;
            set(
                call,
                column,
                "__songlua_column_index",
                Value::Number(index as f64),
            )?;
            let x = crate::song_lua_style_column_x(&style, index);
            if !store
                .lock()
                .unwrap()
                .clock
                .live
                .load(std::sync::atomic::Ordering::Relaxed)
            {
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&column)
                    .unwrap()
                    .current
                    .x = x;
            }
            for (key, value) in [
                ("__songlua_state_x", x),
                ("__songlua_state_y", 0.),
                ("__songlua_state_z", 0.),
            ] {
                set(call, column, key, Value::Number(value as f64))?;
            }
            for (field_name, name, alias) in [
                ("__songlua_pos_handler", "GetPosHandler", "get_pos_handler"),
                ("__songlua_rot_handler", "GetRotHandler", "get_rot_handler"),
                (
                    "__songlua_zoom_handler",
                    "GetZoomHandler",
                    "get_zoom_handler",
                ),
            ] {
                let handler = splines::handler(call)?;
                set(call, column, field_name, Value::Table(handler))?;
                let getter = call.new_host_function(
                    |call| call.push(call.captures()[0]),
                    &[Value::Table(handler)],
                )?;
                let value = get(call, column, b"__songlua_bound_methods")?;
                let bound = table(call, value)?;
                set(call, bound, name, getter)?;
                set(call, bound, alias, getter)?;
            }
            call.raw_table_set(
                columns,
                Value::Number((index + 1) as f64),
                Value::Table(column),
            )?;
        }
        set(call, actor, "__songlua_note_columns", Value::Table(columns))?;
        lifecycle::invalidate_plans(call, store)?;
        Ok(Value::Table(columns))
    })
}

fn method(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Binding>().unwrap().clone();
    let actor = table(call, call.captures()[2])?;
    let offset = usize::from(matches!(arg(call, 0), Value::Table(_)));
    match data.name {
        "GetColumnActors" => {
            let child = field(call, actor, "__songlua_player_child_name")?;
            let mut valid =
                child != Value::Nil && text(call, child)?.eq_ignore_ascii_case("NoteField");
            if !valid {
                let kind = field(call, actor, "__songlua_actor_type")?;
                valid = kind != Value::Nil && text(call, kind)?.eq_ignore_ascii_case("NoteField");
            }
            let value = if valid {
                columns(call, &data.store, data.scene, actor)?
            } else {
                Value::Nil
            };
            return call.push(value);
        }
        "get_column_actors" => {
            let function = field(call, actor, "GetColumnActors")?;
            let value = if matches!(function, Value::Function(_) | Value::Native(_)) {
                call.call(function, &[Value::Table(actor)])?
                    .first()
                    .copied()
                    .unwrap_or(Value::Nil)
            } else {
                Value::Nil
            };
            return call.push(value);
        }
        "SetBeatBars" => {
            if let Some(value) = call.arguments().get(offset).copied() {
                set(
                    call,
                    actor,
                    "__songlua_beat_bars",
                    Value::Boolean(!matches!(value, Value::Nil | Value::Boolean(false))),
                )?;
                return finish_effect(call, actor);
            }
        }
        "SetBeatBarsAlpha" => {
            let alpha = call.try_new_table()?;
            call.with_roots(&[Value::Table(alpha)], |call| {
                for index in 0..4 {
                    let value =
                        splines::optional_float(call, arg(call, offset + index)).unwrap_or(0.);
                    call.raw_table_set(
                        alpha,
                        Value::Number((index + 1) as f64),
                        Value::Number(value as f64),
                    )?;
                }
                set(
                    call,
                    actor,
                    "__songlua_beat_bars_alpha",
                    Value::Table(alpha),
                )
            })?;
            return finish_effect(call, actor);
        }
        "SetDidTapNoteCallback" => {
            let value = arg(call, 1);
            let value = if matches!(value, Value::Function(_) | Value::Native(_)) {
                value
            } else {
                Value::Nil
            };
            set(call, actor, "__songlua_did_tap_note_callback", value)?;
        }
        "did_tap_note" => {
            let column = match arg(call, offset) {
                Value::Number(n) if n.is_finite() => {
                    n.round().clamp(i32::MIN as f64, i32::MAX as f64) as i32
                }
                Value::String(id) => call
                    .string_bytes(id)
                    .and_then(|s| std::str::from_utf8(s).ok())
                    .and_then(|s| {
                        s.trim()
                            .parse::<i32>()
                            .ok()
                            .or_else(|| s.trim().parse::<f32>().ok().map(|n| n.round() as i32))
                    })
                    .unwrap_or(0),
                _ => 0,
            };
            let score = arg(call, offset + 1);
            let bright = !matches!(arg(call, offset + 2), Value::Nil | Value::Boolean(false));
            set(
                call,
                actor,
                "__songlua_last_tap_note_column",
                Value::Number(column as f64),
            )?;
            set(call, actor, "__songlua_last_tap_note_score", score)?;
            set(
                call,
                actor,
                "__songlua_last_tap_note_bright",
                Value::Boolean(bright),
            )?;
            let callback = field(call, actor, "__songlua_did_tap_note_callback")?;
            if callback != Value::Nil {
                if !matches!(callback, Value::Function(_) | Value::Native(_)) {
                    return Err(call.error(b"tap callback must be a function"));
                }
                call.call(
                    callback,
                    &[Value::Number(column as f64), score, Value::Boolean(bright)],
                )?;
            }
            return finish_effect(call, actor);
        }
        _ => unreachable!(),
    }
    call.push(Value::Table(actor))
}

fn finish_effect(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let globals = helper(call, 5)?;
    let mut stack = call.native_stack()?;
    stack.push(globals)?;
    let target = stack.top();
    stack.get_field(
        target as isize,
        crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes(),
    )?;
    let count = if stack.value(-1) == Some(Value::Nil) {
        0
    } else {
        let value = stack.number(-1)?;
        if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&value) {
            return Err(stack.error(b"side effect count is out of range"));
        }
        value as i64
    };
    stack.push_bytes(crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes())?;
    stack.push(Value::Number(count.saturating_add(1) as f64))?;
    stack.set_table(target as isize, false)?;
    stack.push(Value::Table(actor))?;
    stack.finish(1)
}

pub(super) fn update_columns(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Vec<TableId>, Error> {
    let key = call.try_intern(b"__songlua_note_columns")?;
    let columns = call.raw_table_get(actor, key)?;
    if columns == Value::Nil {
        return Ok(Vec::new());
    }
    let columns = table(call, columns)?;
    let mut result = Vec::new();
    for index in 1usize.. {
        let value = call.raw_table_get(columns, Value::Number(index as f64))?;
        if value == Value::Nil {
            break;
        }
        result.push(table(call, value)?);
    }
    Ok(result)
}

//! Existing offline Def constructors: in-place instances before Init.
use super::*;

const CLASSES: &[&str] = &[
    "Actor",
    "ActorFrame",
    "Sprite",
    "Banner",
    "ActorMultiVertex",
    "Sound",
    "BitmapText",
    "BPMDisplay",
    "RollingNumbers",
    "GraphDisplay",
    "SongMeterDisplay",
    "CourseContentsList",
    "DeviceList",
    "InputList",
    "Model",
    "Quad",
    "ActorProxy",
    "ActorFrameTexture",
];

pub(super) fn install(call: &mut HostCall<'_>, store: &Shared) -> Result<(), Error> {
    let def = Value::Table(call.try_new_table()?);
    call.with_roots(&[def], |call| {
        let captures = call.captures().to_vec();
        for &class in CLASSES {
            let function = call.new_host_function_with_data(
                callback,
                &captures,
                Binding {
                    store: store.clone(),
                    op: Op::OfflineConstructor(class),
                },
            )?;
            let key = call.try_intern(class.as_bytes())?;
            call.raw_table_set(table(call, def)?, key, function)?;
        }
        let globals = table(call, helper(call, 5)?)?;
        sprites::set(call, globals, "Def", def)?;
        let loader = call.new_host_function_with_data(
            callback,
            &captures,
            Binding {
                store: store.clone(),
                op: Op::LoadPreparationActor,
            },
        )?;
        sprites::set(call, globals, "LoadActor", loader)?;
        let null = get(call, globals, b"NullActor")?;
        let null = table(call, null)?;
        sprites::set(call, null, "__songlua_def_owned", Value::Boolean(true))?;
        let mut guard = store.lock().unwrap();
        guard.offline_definitions = true;
        let null = guard.actors.get_mut(&null).expect("owned NullActor");
        null.offline_instance = true;
        null.capture.get_or_insert_with(capture::Capture::default);
        Ok(())
    })
}

pub(super) fn construct(
    call: &mut HostCall<'_>,
    store: &Shared,
    class: &'static str,
) -> Result<(), Error> {
    let supplied = match arg(call, 0) {
        Value::Table(actor) => Some(actor),
        _ => None,
    };
    let actor = create(call, store, class, supplied, false)?;
    call.push(Value::Table(actor))
}

pub(super) fn dummy(
    call: &mut HostCall<'_>,
    store: &Shared,
    class: &'static str,
) -> Result<TableId, Error> {
    create(call, store, class, None, true)
}

fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    class: &'static str,
    supplied: Option<TableId>,
    dummy: bool,
) -> Result<TableId, Error> {
    let actor = match supplied {
        Some(actor) => actor,
        None => call.try_new_table()?,
    };
    call.with_roots(&[Value::Table(actor)], |call| {
        let existing = store.lock().unwrap().actors.get(&actor).map(|a| {
            (
                a.scene,
                TemplateState::from(a),
                a.initialized,
                a.registered,
                a.parent,
            )
        });
        let scene = if let Some((scene, ..)) = &existing {
            *scene
        } else {
            new_scene(call, store)?
        };
        if existing.is_none() {
            store.lock().unwrap().constructor_scenes.insert(scene);
        }
        let kind = call.try_intern(class.as_bytes())?;
        call.call(
            helper(call, 1)?,
            &[
                kind,
                Value::Nil,
                Value::Table(actor),
                Value::Boolean(false),
                Value::Boolean(true),
            ],
        )?;
        let globals = table(call, helper(call, 5)?)?;
        for key in ["__songlua_script_dir", "__songlua_song_dir"] {
            let current = get(call, actor, key.as_bytes())?;
            let value = if key == "__songlua_script_dir" && current != Value::Nil {
                current
            } else {
                get(call, globals, key.as_bytes())?
            };
            if value != Value::Nil {
                sprites::set(call, actor, key, value)?;
            }
        }
        let name = get(call, actor, b"Name")?;
        let load_name = if matches!(name, Value::Number(_) | Value::String(_)) {
            Some(bytes(call, name)?)
        } else {
            None
        };
        let mut instance = Actor::new(scene, class, None, load_name);
        instance.offline_instance = true;
        instance.pending_init = true;
        instance.registered = dummy;
        instance.capture = store
            .lock()
            .unwrap()
            .constructing_capture
            .then(capture::Capture::default);
        if let Some((_, previous, initialized, registered, parent)) = existing {
            restore_pose(&mut instance, &previous);
            instance.state.name = previous.state.name;
            instance.initialized = initialized;
            instance.pending_init = !initialized;
            instance.registered = registered;
            instance.parent = parent;
        }
        let registry = table(call, call.captures()[0])?;
        retirement::retain(call, store, scene, actor, registry)?;
        {
            let mut guard = store.lock().unwrap();
            let members = &mut guard.scenes.get_mut(&scene).unwrap().actors;
            if !members.contains(&actor) {
                members.push(actor);
            }
            guard
                .scenes
                .get_mut(&scene)
                .unwrap()
                .root
                .get_or_insert(actor);
            guard.actors.insert(actor, instance);
            if dummy {
                guard.actor_order.push(actor);
            }
        }
        if matches!(class, "Quad" | "ActorMultiVertex") {
            sprites::set(
                call,
                actor,
                "__songlua_default_texture",
                Value::Boolean(true),
            )?;
        }
        initialize_resources(
            call,
            store,
            scene,
            actor,
            class,
            if dummy {
                ResourceMode::Dummy
            } else {
                ResourceMode::Constructor
            },
        )?;
        call.call(helper(call, 13)?, &[Value::Table(actor)])?;
        own_children(call, store, actor)?;
        Ok(actor)
    })
}

fn restore_pose(actor: &mut Actor, previous: &TemplateState) {
    actor.current = previous.pose;
    actor.hibernate = previous.hibernate;
    actor.update_rate = previous.update_rate;
    actor.propagate = previous.propagate;
    actor.update_error_reported = previous.update_error_reported;
    actor.state.size = previous.state.size;
    actor.state.visible = previous.state.visible;
    actor.state.draw_order = previous.state.draw_order;
    actor.state.render = previous.state.render;
    actor.state.rotation = previous.state.rotation;
    actor.effects = previous.effects;
    actor.preparation_getters = previous.preparation_getters;
}

fn already_owned(call: &mut HostCall<'_>, actor: TableId) -> Result<bool, Error> {
    Ok(!matches!(
        get(call, actor, b"__songlua_def_owned")?,
        Value::Nil | Value::Boolean(false)
    ))
}

// Native cloning copies Lua state and rebinds methods; it does not rerun the
// resource constructor. Concatenation additionally leaves child identities shared.
pub(super) fn clone_actor(
    call: &mut HostCall<'_>,
    store: &Shared,
    source: TableId,
    own: bool,
) -> Result<TableId, Error> {
    let previous = TemplateState::from(&store.lock().unwrap().actors[&source]);
    let value = call.call(helper(call, 12)?, &[Value::Table(source)])?[0];
    call.with_roots(&[value], |call| {
        let actor = table(call, value)?;
        let scene = new_scene(call, store)?;
        let class = previous.state.class;
        let kind = call.try_intern(class.as_bytes())?;
        call.call(
            helper(call, 1)?,
            &[
                kind,
                Value::Nil,
                value,
                Value::Boolean(true),
                Value::Boolean(true),
            ],
        )?;
        let name = get(call, actor, b"Name")?;
        let name = if matches!(name, Value::String(_) | Value::Number(_)) {
            Some(bytes(call, name)?)
        } else {
            None
        };
        let mut instance = Actor::new(scene, class, None, name);
        restore_pose(&mut instance, &previous);
        instance.offline_instance = true;
        instance.pending_init = true;
        instance.registered = false;
        instance.capture = previous.capture;
        let registry = table(call, call.captures()[0])?;
        retirement::retain(call, store, scene, actor, registry)?;
        {
            let mut guard = store.lock().unwrap();
            guard.constructor_scenes.insert(scene);
            let owner = guard.scenes.get_mut(&scene).unwrap();
            owner.root = Some(actor);
            owner.actors.push(actor);
            guard.actors.insert(actor, instance);
        }
        initialize_resources(call, store, scene, actor, class, ResourceMode::OfflineClone)?;
        call.call(helper(call, 13)?, &[value])?;
        if own {
            own_children(call, store, actor)?;
        } else {
            share_children(call, store, actor)?;
        }
        Ok(actor)
    })
}

fn share_children(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let scene = store.lock().unwrap().actors[&actor].scene;
    let mut declared = Vec::new();
    for i in 1.. {
        match call.raw_table_get(actor, Value::Number(i as f64))? {
            Value::Nil => break,
            Value::Table(child) => {
                courses::attach(call, store, scene, child)?;
                declared.push(child);
            }
            _ => {}
        }
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .children = declared;
    for child in children(call, store, actor)? {
        courses::attach(call, store, scene, child)?;
    }
    Ok(())
}

// Transfer the implicit constructor owner after claiming its root. The native
// host keeps abandoned constructor objects until VM teardown; an explicitly
// owned scene instead supplies the existing release boundary for its subtree.
fn transfer(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
) -> Result<(), Error> {
    courses::attach(call, store, scene, actor)?;
    let old = {
        let guard = store.lock().unwrap();
        guard
            .constructor_scenes
            .iter()
            .copied()
            .filter(|id| *id != scene && guard.scenes[id].root == Some(actor))
            .collect::<Vec<_>>()
    };
    let mut guard = store.lock().unwrap();
    for id in old {
        guard.constructor_scenes.remove(&id);
        let previous = guard.scenes.remove(&id).unwrap();
        for member in previous.actors {
            if !guard.scenes[&scene].actors.contains(&member) {
                guard.scenes.get_mut(&scene).unwrap().actors.push(member);
            }
            if guard.actors[&member].scene == id {
                guard.actors.get_mut(&member).unwrap().scene = scene;
            }
        }
    }
    Ok(())
}

fn own_children(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let scene = store.lock().unwrap().actors[&actor].scene;
    let values = call
        .call(helper(call, 11)?, &[Value::Table(actor)])?
        .to_vec();
    call.with_roots(&values, |call| {
        let source = table(call, values[0])?;
        let entries = table(call, values[1])?;
        for i in 1..=call.raw_table_len(entries)? {
            let entry = table(call, call.raw_table_get(entries, Value::Number(i as f64))?)?;
            let key = call.raw_table_get(entry, Value::Number(1.))?;
            let child = table(call, call.raw_table_get(entry, Value::Number(2.))?)?;
            let typed = get(call, child, b"__songlua_actor_type")? != Value::Nil;
            let child = if typed && already_owned(call, child)? {
                clone_actor(call, store, child, true)?
            } else {
                child
            };
            if typed {
                sprites::set(call, child, "__songlua_def_owned", Value::Boolean(true))?;
                call.raw_table_set(source, key, Value::Table(child))?;
            }
            transfer(call, store, scene, child)?;
        }
        let mut children = Vec::new();
        for i in 1.. {
            match call.raw_table_get(actor, Value::Number(i as f64))? {
                Value::Nil => break,
                Value::Table(child) => {
                    transfer(call, store, scene, child)?;
                    children.push(child);
                }
                _ => {}
            }
        }
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .children = children;
        // Native children (for example a supplied SongMeter Stream) also
        // leave their temporary constructor owner when this instance claims them.
        for child in super::children(call, store, actor)? {
            transfer(call, store, scene, child)?;
        }
        Ok(())
    })
}

pub(super) fn own_root(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    init: bool,
) -> Result<u64, Error> {
    let actor = if already_owned(call, actor)? {
        clone_actor(call, store, actor, true)?
    } else {
        actor
    };
    let existing = store.lock().unwrap().actors[&actor].scene;
    let scene = if store.lock().unwrap().scenes[&existing].root == Some(actor) {
        existing
    } else {
        let scene = new_scene(call, store)?;
        transfer(call, store, scene, actor)?;
        store.lock().unwrap().scenes.get_mut(&scene).unwrap().root = Some(actor);
        scene
    };
    store.lock().unwrap().constructor_scenes.remove(&scene);
    sprites::set(call, actor, "__songlua_def_owned", Value::Boolean(true))?;
    if init {
        super::prepare_init(store);
        if let Err(error) = initialize(call, store, actor) {
            release(call, store, scene)?;
            return Err(error);
        }
    }
    Ok(scene)
}

pub(super) fn prepare_init(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let initialized = !matches!(
        get(call, actor, b"__songlua_init_commands_ran")?,
        Value::Nil | Value::Boolean(false)
    );
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .initialized = initialized;
    if initialized {
        return Ok(());
    }
    courses::refresh_raw_children(call, store, actor, true)?;
    let name = get(call, actor, b"Name")?;
    let name = if matches!(name, Value::Number(_) | Value::String(_)) {
        Some(bytes(call, name)?)
    } else {
        None
    };
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .load_name = name;
    let empty = call.try_intern(b"")?;
    for key in ["__songlua_native_name", "__songlua_load_name"] {
        sprites::set(call, actor, key, empty)?;
    }
    Ok(())
}

//! Player::Init's existing engine-owned children, before theme commands load.
use super::*;
use generated_players::dummy;
use sprites::{field, set};

pub(super) fn install(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    player: TableId,
    index: usize,
    style: &str,
) -> Result<(), Error> {
    let combo = combo(call, store, scene, index)?;
    attach_part(call, store, player, combo, "Combo", (index, style))?;
    let judgment = judgment(call, store, scene, player, index)?;
    attach_part(call, store, player, judgment, "Judgment", (index, style))?;
    hold_judgments(call, store, scene, player, index, style)?;
    let field = notefields::create(call, store, scene, index, style)?;
    attach_part(call, store, player, field, "NoteField", (index, style))?;
    lifecycle::invalidate_plans(call, store)?;
    Ok(())
}

fn append(
    call: &mut HostCall<'_>,
    store: &Shared,
    parent: TableId,
    child: TableId,
) -> Result<(), Error> {
    let index = call.raw_table_len(parent)? + 1;
    call.raw_table_set(parent, Value::Number(index as f64), Value::Table(child))?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&parent)
        .unwrap()
        .children
        .push(child);
    Ok(())
}

fn attach_part(
    call: &mut HostCall<'_>,
    store: &Shared,
    parent: TableId,
    child: TableId,
    name: &str,
    (index, style): (usize, &str),
) -> Result<(), Error> {
    let value = call.try_intern(name.as_bytes())?;
    set(call, child, "Name", value)?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&child)
        .unwrap()
        .state
        .name = name.as_bytes().to_vec();
    set(
        call,
        child,
        "__songlua_player_index",
        Value::Number(index as f64),
    )?;
    let style = call.try_intern(style.as_bytes())?;
    set(call, child, "__songlua_style_name", style)?;
    set(call, child, "__songlua_player_child_name", value)?;
    native_children::adopt(call, store, child, parent)?;
    native_children::insert(call, parent, name, Value::Table(child))?;
    append(call, store, parent, child)
}

fn texture(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    value: Value,
) -> Result<(), Error> {
    let path = assets::text(call, value)?;
    let path = path.trim();
    if !path.is_empty() {
        let value = call.try_intern(path.as_bytes())?;
        sprites::set_texture(call, store, actor, value, false)?;
    }
    Ok(())
}

fn judgment(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    player: TableId,
    index: usize,
) -> Result<TableId, Error> {
    let frame = dummy(call, store, scene, "ActorFrame", "Judgment", None)?;
    let sprite = dummy(
        call,
        store,
        scene,
        "Sprite",
        "JudgmentWithOffsets",
        Some(frame),
    )?;
    set(
        call,
        sprite,
        "__songlua_sprite_animate",
        Value::Boolean(false),
    )?;
    set(call, sprite, "__songlua_visible", Value::Boolean(false))?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&sprite)
        .unwrap()
        .state
        .visible = false;
    set(
        call,
        sprite,
        "__songlua_judgment_sprite_player",
        Value::Number(index as f64),
    )?;
    let path = field(call, player, "__songlua_judgment_texture")?;
    if path != Value::Nil {
        texture(call, store, sprite, path)?;
    }
    append(call, store, frame, sprite)?;
    native_children::insert(call, frame, "JudgmentWithOffsets", Value::Table(sprite))?;
    Ok(frame)
}

fn combo(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    index: usize,
) -> Result<TableId, Error> {
    let globals = table(call, helper(call, 5)?)?;
    let function = field(call, globals, "GetComboFonts")?;
    if !matches!(function, Value::Function(_) | Value::Native(_)) {
        return Err(call.error(b"GetComboFonts function expected"));
    }
    let fonts = call
        .call(function, &[])?
        .first()
        .copied()
        .unwrap_or(Value::Nil);
    let fonts = table(call, fonts)?;
    call.with_roots(&[Value::Table(fonts)], |call| {
        let sl = field(call, globals, "SL")?;
        call.with_roots(&[sl], |call| {
            let player = field(call, table(call, sl)?, &format!("P{}", index + 1))?;
            call.with_roots(&[player], |call| {
                let mods = field(call, table(call, player)?, "ActiveModifiers")?;
                call.with_roots(&[mods], |call| {
                    let hide = field(call, table(call, mods)?, "HideCombo")?;
                    let hide = !matches!(hide, Value::Nil | Value::Boolean(false));
                    if hide || call.raw_table_len(fonts)? == 0 {
                        let actor = dummy(call, store, scene, "Actor", "Combo", None)?;
                        let key = call.try_intern(b"__songlua_visible")?;
                        call.raw_table_set(actor, key, Value::Boolean(false))?;
                        store
                            .lock()
                            .unwrap()
                            .actors
                            .get_mut(&actor)
                            .unwrap()
                            .state
                            .visible = false;
                        Ok(actor)
                    } else {
                        let frame = dummy(call, store, scene, "ActorFrame", "Combo", None)?;
                        let number =
                            dummy(call, store, scene, "BitmapText", "Number", Some(frame))?;
                        append(call, store, frame, number)?;
                        native_children::insert(call, frame, "Number", Value::Table(number))?;
                        Ok(frame)
                    }
                })
            })
        })
    })
}

fn hold_judgments(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    player: TableId,
    index: usize,
    style: &str,
) -> Result<(), Error> {
    // These two arrays are native forwarding groups, including when empty.
    let empty = call.try_new_table()?;
    let frames = call.call(helper(call, 3)?, &[Value::Table(empty)])?[0];
    call.with_roots(&[frames], |call| {
        let empty = call.try_new_table()?;
        let unnamed = call.call(helper(call, 3)?, &[Value::Table(empty)])?[0];
        call.with_roots(&[unnamed], |call| {
            let frames = table(call, frames)?;
            let unnamed = table(call, unnamed)?;
            let attack = get(call, player, b"__songlua_attack_display")?;
            if attack != Value::Nil {
                table(call, attack)?;
                call.raw_table_set(unnamed, Value::Number(1.), attack)?;
            }
            // Native holds use raw SL lookup but ordinary THEME method lookup.
            let globals = table(call, helper(call, 5)?)?;
            let sl = get(call, globals, b"SL")?;
            let mods = call.with_roots(&[sl], |call| {
                let player = get(
                    call,
                    table(call, sl)?,
                    if index == 0 { b"P1" } else { b"P2" },
                )?;
                call.with_roots(&[player], |call| {
                    get(call, table(call, player)?, b"ActiveModifiers")
                })
            })?;
            let label = call.with_roots(&[mods], |call| {
                let label = get(call, table(call, mods)?, b"HoldJudgment")?;
                if label == Value::Nil {
                    Ok("None 1x2.png".to_owned())
                } else {
                    assets::text(call, label)
                }
            })?;
            let theme = get(call, globals, b"THEME")?;
            let path = call.with_roots(&[theme], |call| {
                let function = field(call, table(call, theme)?, "GetPathG")?;
                call.with_roots(&[function], |call| {
                    if !matches!(function, Value::Function(_) | Value::Native(_)) {
                        return Err(call.error(b"THEME.GetPathG function expected"));
                    }
                    let empty = call.try_intern(b"")?;
                    let path = call.try_intern(format!("_HoldJudgments/{label}").as_bytes())?;
                    let value = call
                        .call(function, &[theme, empty, path])?
                        .first()
                        .copied()
                        .unwrap_or(Value::Nil);
                    assets::text(call, value)
                })
            })?;
            for column in 0..crate::song_lua_style_info(style).columns {
                let frame = dummy(call, store, scene, "HoldJudgment", "", Some(player))?;
                let sprite = dummy(call, store, scene, "Sprite", "HoldJudgment", Some(frame))?;
                set(
                    call,
                    sprite,
                    "__songlua_sprite_animate",
                    Value::Boolean(false),
                )?;
                let path = call.try_intern(path.as_bytes())?;
                texture(call, store, sprite, path)?;
                let alpha = field(call, sprite, "diffusealpha")?;
                if !matches!(alpha, Value::Function(_) | Value::Native(_)) {
                    return Err(call.error(b"diffusealpha function expected"));
                }
                call.call(alpha, &[Value::Table(sprite), Value::Number(0.)])?;
                append(call, store, frame, sprite)?;
                native_children::insert(call, frame, "HoldJudgment", Value::Table(sprite))?;
                call.raw_table_set(
                    frames,
                    Value::Number((column + 1) as f64),
                    Value::Table(frame),
                )?;
                let ordinal = call.raw_table_len(unnamed)? + 1;
                call.raw_table_set(unnamed, Value::Number(ordinal as f64), Value::Table(frame))?;
                append(call, store, player, frame)?;
            }
            native_children::insert(call, player, "", Value::Table(unnamed))?;
            let key = call.try_intern(b"__songlua_hold_judgments")?;
            call.raw_table_set(player, key, Value::Table(frames))
        })
    })
}

// Reuse Player::Init's actual HUD constructors for compiler fallback children.
pub(super) fn tracked_child(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    player: TableId,
    index: usize,
    name: &str,
) -> Result<TableId, Error> {
    let child = match name {
        "Judgment" => judgment(call, store, scene, player, index)?,
        "Combo" => combo(call, store, scene, index)?,
        _ => unreachable!(),
    };
    underlay::copy_tags(call, player, child)?;
    let value = call.try_intern(name.as_bytes())?;
    set(call, child, "__songlua_player_child_name", value)?;
    native_children::adopt(call, store, child, player)?;
    native_children::insert(call, player, name, Value::Table(child))?;
    append(call, store, player, child)?;
    lifecycle::invalidate_plans(call, store)?;
    Ok(child)
}

//! ActorProxy target ownership and the existing renderer-facing classification.
use super::*;
use crate::SongLuaProxyTarget;
use sprites::{field, set};

pub(super) fn install(call: &mut HostCall<'_>, actor: TableId, proxy: bool) -> Result<(), Error> {
    let methods = get(call, actor, b"__songlua_bound_methods")?;
    let methods = if methods == Value::Nil {
        let methods = call.try_new_table()?;
        let key = call.try_intern(b"__songlua_bound_methods")?;
        call.raw_table_set(actor, key, Value::Table(methods))?;
        methods
    } else {
        table(call, methods)?
    };
    // Native SetTarget is bound on every actor, but only ActorProxy publishes
    // it through the class table. Captures keep the owner and its target alive.
    let captures = [Value::Table(actor), call.captures()[1]];
    let setter = call.new_host_function(set_target, &captures)?;
    let key = call.try_intern(b"SetTarget")?;
    call.raw_table_set(methods, key, setter)?;
    if proxy {
        let getter = call.new_host_function(get_target, &captures)?;
        let key = call.try_intern(b"GetTarget")?;
        call.raw_table_set(methods, key, getter)?;
    }
    Ok(())
}

fn optional_integer(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &str,
) -> Result<Option<i64>, Error> {
    let value = field(call, actor, key)?;
    if value == Value::Nil {
        return Ok(None);
    }
    let n = sprites::number(call, value)?;
    if !(i64::MIN as f64..9223372036854775808.0).contains(&n) {
        return Err(call.error(b"proxy player index out of range"));
    }
    Ok(Some(n as i64))
}

fn set_kind(call: &mut HostCall<'_>, actor: TableId, kind: &str) -> Result<(), Error> {
    let kind = call.try_intern(kind.as_bytes())?;
    set(call, actor, "__songlua_proxy_target_kind", kind)
}

fn set_target(call: &mut HostCall<'_>) -> Result<(), Error> {
    let actor = table(call, call.captures()[0])?;
    let Value::Table(target) = arg(call, 1) else {
        return Err(call.error(b"ActorProxy.SetTarget requires an Actor"));
    };
    let kind = get(call, target, b"__songlua_actor_type")?;
    if kind == Value::Nil {
        return Err(call.error(b"ActorProxy.SetTarget requires an Actor"));
    }
    assets::text(call, kind)?;
    set(call, actor, "__songlua_proxy_target_kind", Value::Nil)?;
    set(call, actor, "__songlua_proxy_player_index", Value::Nil)?;
    set(
        call,
        actor,
        "__songlua_proxy_target_actor",
        Value::Table(target),
    )?;
    if let Some(name) = assets::field(call, target, b"__songlua_top_screen_child_name")? {
        if let Some(index) = crate::underlay_score_index(&name) {
            set_kind(call, actor, "score")?;
            set(
                call,
                actor,
                "__songlua_proxy_player_index",
                Value::Number(index as f64),
            )?;
        } else if name.eq_ignore_ascii_case("Underlay") {
            set_kind(call, actor, "underlay")?;
        } else if name.eq_ignore_ascii_case("Overlay") {
            set_kind(call, actor, "overlay")?;
        }
    } else if let Some(index) = optional_integer(call, target, "__songlua_player_index")? {
        set(
            call,
            actor,
            "__songlua_proxy_player_index",
            Value::Number(index as f64),
        )?;
        let child = assets::field(call, target, b"__songlua_player_child_name")?;
        let kind = match child.as_deref() {
            Some(name) if name.eq_ignore_ascii_case("NoteField") => "notefield",
            Some(name) if name.eq_ignore_ascii_case("Judgment") => "judgment",
            Some(name) if name.eq_ignore_ascii_case("Combo") => "combo",
            _ => "player",
        };
        set_kind(call, actor, kind)?;
    } else if assets::field(call, target, b"__songlua_actor_type")?.is_some() {
        set_kind(call, actor, "actor")?;
    }
    call.push(Value::Table(actor))
}

fn get_target(call: &mut HostCall<'_>) -> Result<(), Error> {
    let actor = table(call, call.captures()[0])?;
    let target = get(call, actor, b"__songlua_proxy_target_actor")?;
    call.push(target)
}

pub(super) fn read(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Option<SongLuaProxyTarget>, Error> {
    let Some(kind) = assets::field(call, actor, b"__songlua_proxy_target_kind")? else {
        return Ok(None);
    };
    let player_index = optional_integer(call, actor, "__songlua_proxy_player_index")?
        .and_then(|index| usize::try_from(index).ok());
    let target = field(call, actor, "__songlua_proxy_target_actor")?;
    let target_id = if target == Value::Nil {
        None
    } else {
        Some(table(call, target)?)
    };
    call.with_roots(&[target], |call| {
        let hidden = if let Some(target) = target_id {
            match field(call, target, "__songlua_visible") {
                Ok(value) => value == Value::Boolean(false),
                Err(error) if error.kind() == ErrorKind::Runtime => false,
                Err(error) => return Err(error),
            }
        } else {
            false
        };
        Ok(match kind.as_str() {
            "player" => {
                player_index.map(|player_index| SongLuaProxyTarget::Player { player_index })
            }
            "notefield" => {
                player_index.map(|player_index| SongLuaProxyTarget::NoteField { player_index })
            }
            "judgment" => {
                player_index.map(|player_index| SongLuaProxyTarget::Judgment { player_index })
            }
            "combo" => player_index.map(|player_index| SongLuaProxyTarget::Combo { player_index }),
            "score" => player_index.map(|player_index| SongLuaProxyTarget::Score { player_index }),
            "underlay" => Some(SongLuaProxyTarget::Underlay { hidden }),
            "overlay" => Some(SongLuaProxyTarget::Overlay { hidden }),
            "actor" => target_id.map(|id| SongLuaProxyTarget::Actor {
                overlay_index: call
                    .object_pointer(Value::Table(id))
                    .expect("rooted proxy target"),
            }),
            _ => None,
        })
    })
}

//! Preparation callbacks retained by the non-startup capture scheduler.
use super::*;

#[derive(Clone, Default)]
pub(super) struct State {
    pub(super) command: Option<Vec<u8>>,
    pub(super) interval: f64,
    pub(super) remaining: Option<f64>,
    pub(super) running: bool,
    error_reported: bool,
}

fn invoke(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    command: &[u8],
    queued: Option<f32>,
) -> Result<(), Error> {
    let (prior, prior_clock) = {
        let mut guard = store.lock().unwrap();
        let prior_clock = if let Some(remaining) = queued {
            guard.replay_clock.as_mut().and_then(|clock| {
                clock.reset(actor);
                clock.dispatched(actor, remaining)
            })
        } else {
            guard.replay_clock.as_ref().and_then(|clock| clock.dispatch)
        };
        let time = guard.replay_frame.map(|(_, time)| time);
        let target = guard.actors.get_mut(&actor).unwrap();
        let capture = target.capture.as_mut().unwrap();
        capture.reset_command();
        capture.recurring.command = None;
        capture.recurring.running = true;
        target.queue.clear();
        let prior = guard.replay_dispatch;
        if queued.is_some() {
            guard.replay_dispatch = Some(song_immediate::Dispatch {
                seconds: time,
                delay: 0.,
            });
        }
        (prior, prior_clock)
    };
    let result = (|| {
        song_messages::timing(call, actor, 0., None)?;
        for key in [
            "__songlua_capture_cursor",
            "__songlua_capture_tween_time_left",
        ] {
            song_replay::raw_set(call, actor, key, Value::Number(0.))?;
        }
        song_replay::raw_set(call, actor, "__songlua_capture_opt2", Value::Nil)?;
        // This scheduler invokes the actor's own named command. ActorFrame's
        // recursive PlayCommand dispatch is a separate queue path.
        run_named(call, store, actor, command, None)?;
        song_pose::advance_position(call, store, actor)
    })();
    let mut guard = store.lock().unwrap();
    guard.replay_dispatch = prior;
    if let Some(clock) = &mut guard.replay_clock {
        clock.dispatch = prior_clock;
    }
    let recurring = &mut guard
        .actors
        .get_mut(&actor)
        .unwrap()
        .capture
        .as_mut()
        .unwrap()
        .recurring;
    recurring.running = false;
    match result {
        Err(error) if error.kind() == ErrorKind::Runtime => {
            if !recurring.error_reported {
                recurring.error_reported = true;
                guard.diagnostics.push(format!(
                    "{}Command: {error}",
                    String::from_utf8_lossy(command)
                ));
            }
            Ok(())
        }
        result => result,
    }
}

pub(super) fn advance(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    delta: f32,
) -> Result<(), Error> {
    let (command, mut interval, mut left) = {
        let guard = store.lock().unwrap();
        if guard.replay_frame.is_none()
            || guard.clock.live.load(std::sync::atomic::Ordering::Relaxed)
        {
            return Ok(());
        }
        let actor = &guard.actors[&actor];
        if !actor.registered {
            return Ok(());
        }
        let Some(capture) = &actor.capture else {
            return Ok(());
        };
        let recurring = &capture.recurring;
        let Some(command) = &recurring.command else {
            return Ok(());
        };
        (
            command.clone(),
            recurring.interval,
            recurring.remaining.unwrap_or(recurring.interval) as f32,
        )
    };
    // The native zero-interval branch runs once per active update, including
    // a zero or negative delta, and carries no queued publication scope.
    if interval <= f64::EPSILON {
        return invoke(call, store, actor, &command, None);
    }
    let mut delta = delta.max(0.);
    let mut runs = 0;
    while delta > 0. && runs < 64 {
        if left > 0. {
            let used = left.min(delta);
            left -= used;
            delta -= used;
            if delta == 0. {
                break;
            }
        }
        invoke(call, store, actor, &command, Some(delta))?;
        {
            let mut guard = store.lock().unwrap();
            let recurring = &mut guard
                .actors
                .get_mut(&actor)
                .unwrap()
                .capture
                .as_mut()
                .unwrap()
                .recurring;
            if recurring.command.is_none() {
                recurring.remaining = None;
                return Ok(());
            }
            interval = recurring.interval;
        }
        runs += 1;
        if interval <= f64::EPSILON {
            break;
        }
        left = interval as f32;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .capture
        .as_mut()
        .unwrap()
        .recurring
        .remaining = Some(f64::from(left));
    Ok(())
}

//! Song actor render bindings. Tween destinations and immediate render settings
//! stay separate so queued commands cannot delay native immediate properties.
use super::action_capture;
use super::{
    Shared, arg, capture, children, float_scalar, helper, song_immediate, song_media,
    song_properties, song_replay,
};
