pub(super) fn initialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let key = call.try_intern(b"FOV")?;
    let value = call.raw_table_get(actor, key)?;
    if value != Value::Nil {
        let number = super::sprites::number(call, value)? as f32;
        action_capture::prepare(call, store, actor)?;
        scalar(call, store, actor, "fov", number);
    }
    Ok(())
}

pub(super) fn text<'a>(call: &'a HostCall<'_>, value: Value) -> Option<&'a str> {
    let Value::String(id) = value else {
        return None;
    };
    std::str::from_utf8(call.string_bytes(id)?).ok()
}

fn alignment(call: &HostCall<'_>, value: Value, vertical: bool) -> Option<f32> {
    if let Some(number) = float_scalar(call, value, false) {
        return Some(number);
    }
    let token = crate::borrowed_alignment_token(text(call, value)?);
    if token.eq_ignore_ascii_case(if vertical { "top" } else { "left" }) {
        Some(0.0)
    } else if token.eq_ignore_ascii_case("center") || token.eq_ignore_ascii_case("middle") {
        Some(0.5)
    } else if token.eq_ignore_ascii_case(if vertical { "bottom" } else { "right" }) {
        Some(1.0)
    } else {
        None
    }
}

pub(super) fn color(call: &mut HostCall<'_>) -> Result<Option<[f32; 4]>, Error> {
    color_at(call, 1)
}
pub(super) fn color_at(call: &mut HostCall<'_>, offset: usize) -> Result<Option<[f32; 4]>, Error> {
    match arg(call, offset) {
        Value::Table(table) => {
            let mut out = [1.0; 4];
            for (i, component) in out.iter_mut().enumerate() {
                let value = call.raw_table_get(table, Value::Number((i + 1) as f64))?;
                if i == 3 && value == Value::Nil {
                    continue;
                }
                // The production table reader uses Lua numeric coercion, which
                // accepts hex strings and nonfinite numbers. It ignores __index.
                let converted = call.call(helper(call, 6)?, &[value])?[0];
                let Value::Number(number) = converted else {
                    return Ok(None);
                };
                *component = number as f32;
            }
            Ok(Some(out))
        }
        Value::String(_) => Ok(text(call, arg(call, offset))
            .map(|text| crate::parse_color_text(text).unwrap_or([1.0; 4]))),
        first => {
            let Some(r) = float_scalar(call, first, false) else {
                return Ok(None);
            };
            let Some(g) = float_scalar(call, arg(call, offset + 1), false) else {
                return Ok(None);
            };
            let Some(b) = float_scalar(call, arg(call, offset + 2), false) else {
                return Ok(None);
            };
            Ok(Some([
                r,
                g,
                b,
                float_scalar(call, arg(call, offset + 3), false).unwrap_or(1.0),
            ]))
        }
    }
}

fn push_color(call: &mut HostCall<'_>, color: [f32; 4]) -> Result<(), Error> {
    let table = call.try_new_table()?;
    call.with_roots(&[Value::Table(table)], |call| {
        for (i, component) in color.into_iter().enumerate() {
            call.raw_table_set(
                table,
                Value::Number((i + 1) as f64),
                Value::Number(component as f64),
            )?;
        }
        call.push(Value::Table(table))
    })
}

fn strict_boolean(call: &HostCall<'_>, name: &str) -> Result<bool, Error> {
    match arg(call, 1) {
        Value::Boolean(value) => Ok(value),
        Value::Number(value) => Ok(value.trunc() != 0.0),
        _ => Err(call.error(format!("{name} expects a boolean or number").as_bytes())),
    }
}

fn cull_mode(call: &HostCall<'_>) -> Result<CullMode, Error> {
    match arg(call, 1) {
        Value::Number(0.0) => Ok(CullMode::Back),
        Value::Number(1.0) => Ok(CullMode::Front),
        Value::Number(2.0) => Ok(CullMode::None),
        value => match text(call, value) {
            Some("CullMode_Back") => Ok(CullMode::Back),
            Some("CullMode_Front") => Ok(CullMode::Front),
            Some("CullMode_None") => Ok(CullMode::None),
            Some(value) if value.eq_ignore_ascii_case("back") => Ok(CullMode::Back),
            Some(value) if value.eq_ignore_ascii_case("front") => Ok(CullMode::Front),
            Some(value) if value.eq_ignore_ascii_case("none") => Ok(CullMode::None),
            _ => Err(call.error(b"invalid CullMode")),
        },
    }
}

fn depth(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    test: Option<(bool, bool)>,
    write: Option<bool>,
) -> Result<(), Error> {
    if let Some((enabled, on_fail)) = test {
        depth_flag(call, store, actor, Target::DepthTest, enabled)?;
        depth_flag(call, store, actor, Target::DepthTestOnFail, on_fail)?;
    }
    if let Some(enabled) = write {
        depth_flag(call, store, actor, Target::DepthWrite, enabled)?;
    }
    Ok(())
}

fn depth_flag(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    target: Target,
    enabled: bool,
) -> Result<(), Error> {
    action_capture::prepare(call, store, actor)?;
    {
        let mut store = store.lock().unwrap();
        let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
        match target {
            Target::DepthTest => render.depth_test = enabled,
            Target::DepthTestOnFail => render.depth_test_on_fail = enabled,
            Target::DepthWrite => render.depth_write = enabled,
            _ => unreachable!(),
        }
    }
    song_properties::record(call, store, actor, target, Update::Bool(enabled));
    for child in children(call, store, actor)? {
        depth_flag(call, store, child, target, enabled)?;
    }
    Ok(())
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = arg(call, 1);
    if name == "align" {
        for (index, vertical) in [(1, false), (2, true)] {
            if let Some(value) = alignment(call, arg(call, index), vertical) {
                action_capture::prepare(call, store, actor)?;
                let mut delta = crate::SongLuaOverlayStateDelta::default();
                {
                    let mut guard = store.lock().unwrap();
                    let render = &mut guard.actors.get_mut(&actor).unwrap().state.render;
                    if vertical {
                        render.valign = value;
                        delta.valign = Some(value);
                    } else {
                        render.halign = value;
                        delta.halign = Some(value);
                    }
                }
                capture::write(call, store, actor, delta, true);
            }
        }
        return call.push(Value::Table(actor));
    }
    if matches!(name, "FullScreen" | "Center" | "CenterX" | "CenterY") {
        screen_geometry(call, store, actor, name)?;
        return call.push(Value::Table(actor));
    }
    // Parse values before taking the metadata lock. Lua numeric conversion and
    // return-table allocation may reenter the VM or collect traced captures.
    if matches!(name, "GetDiffuse" | "GetGlow") {
        let color = {
            let store = store.lock().unwrap();
            let pose = store.actors[&actor].getter_destination();
            if name == "GetDiffuse" {
                pose.diffuse
            } else {
                pose.glow
            }
        };
        return push_color(call, color);
    }
    if name == "getrotation" {
        let rotation = store.lock().unwrap().actors[&actor].state.rotation;
        for value in rotation {
            call.push(Value::Number(value as f64))?;
        }
        return Ok(());
    }
    if name.starts_with("Get") {
        let value = {
            let store = store.lock().unwrap();
            let actor = &store.actors[&actor];
            let render = &actor.state.render;
            match name {
                "GetDiffuseAlpha" => actor.getter_destination().diffuse[3],
                "GetBaseZoomX" => render.basezoom_x,
                "GetBaseZoomY" => render.basezoom_y,
                "GetBaseZoomZ" => render.basezoom_z,
                "GetHAlign" => render.halign,
                "GetVAlign" => render.valign,
                _ => unreachable!(),
            }
        };
        return call.push(Value::Number(value as f64));
    }
    if matches!(name, "diffuse" | "diffusecolor" | "glow" | "shadowcolor")
        || corner_mask(name).is_some()
    {
        if let Some(mut color) = color(call)? {
            action_capture::prepare(call, store, actor)?;
            let shared = store;
            let id = actor;
            let mut store = store.lock().unwrap();
            let sync = !store.playback && matches!(name, "diffuse" | "diffusecolor");
            let actor = store.actors.get_mut(&actor).unwrap();
            let alpha = actor.getter_destination().diffuse[3];
            if name == "shadowcolor" {
                actor.state.render.shadow_color = color;
            } else {
                let pose = actor.destination_mut();
                if let Some(mask) = corner_mask(name) {
                    for (i, vertex) in pose
                        .vertex_colors
                        .get_or_insert([[1.0; 4]; 4])
                        .iter_mut()
                        .enumerate()
                    {
                        if mask & (1 << i) != 0 {
                            *vertex = color;
                        }
                    }
                } else if name == "glow" {
                    pose.glow = color;
                } else {
                    if name == "diffusecolor" {
                        color[3] = alpha;
                    }
                    pose.diffuse = color;
                }
            }
            if sync {
                actor.sync_rotation_getters();
            }
            drop(store);
            capture::property(
                call,
                shared,
                id,
                if corner_mask(name).is_some() {
                    "vertex_colors"
                } else {
                    name
                },
            );
            if matches!(name, "diffuse" | "diffusecolor") {
                song_replay::sync_getters(call, shared, id)?;
            }
        }
    } else if matches!(name, "halign" | "valign" | "horizalign" | "vertalign") {
        let align = alignment(call, value, matches!(name, "valign" | "vertalign"));
        let text_align = (name == "horizalign")
            .then(|| text(call, value).and_then(crate::parse_overlay_text_align))
            .flatten();
        if align.is_some() || text_align.is_some() {
            action_capture::prepare(call, store, actor)?;
        }
        let shared = store;
        let mut guard = store.lock().unwrap();
        let render = &mut guard.actors.get_mut(&actor).unwrap().state.render;
        if let Some(value) = align {
            if matches!(name, "valign" | "vertalign") {
                render.valign = value;
            } else {
                render.halign = value;
            }
        }
        if let Some(value) = text_align {
            render.text_align = value;
        }
        drop(guard);
        if let Some(value) = align {
            song_immediate::record(
                call,
                shared,
                actor,
                if matches!(name, "valign" | "vertalign") {
                    crate::SongLuaOverlayUpdateTarget::VAlign
                } else {
                    crate::SongLuaOverlayUpdateTarget::HAlign
                },
                crate::SongLuaOverlayUpdateValue::F32(value),
            );
        }
        if let Some(value) = text_align {
            song_immediate::record(
                call,
                shared,
                actor,
                crate::SongLuaOverlayUpdateTarget::TextAlign,
                crate::SongLuaOverlayUpdateValue::TextAlign(value),
            );
        }
    } else if name == "backfacecull" || name == "cullmode" {
        let mode = if name == "backfacecull" {
            if strict_boolean(call, name)? {
                CullMode::Back
            } else {
                CullMode::None
            }
        } else {
            cull_mode(call)?
        };
        action_capture::prepare(call, store, actor)?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .render
            .cull_mode = mode;
        song_immediate::record(
            call,
            store,
            actor,
            crate::SongLuaOverlayUpdateTarget::CullMode,
            crate::SongLuaOverlayUpdateValue::CullMode(mode),
        );
    } else if matches!(name, "MaskSource" | "MaskDest") {
        action_capture::prepare(call, store, actor)?;
        let key = if name == "MaskSource" {
            "mask_source"
        } else {
            "mask_dest"
        };
        {
            let mut guard = store.lock().unwrap();
            let render = &mut guard.actors.get_mut(&actor).unwrap().state.render;
            if name == "MaskSource" {
                render.mask_source = true;
            } else {
                render.mask_dest = true;
            }
        }
        super::sprites::set(
            call,
            actor,
            &format!("__songlua_state_{key}"),
            Value::Boolean(true),
        )?;
        song_media::record(call, store, actor, key);
    } else if matches!(name, "zbuffer" | "ztest" | "zwrite") {
        let enabled = strict_boolean(call, name)?;
        depth(
            call,
            store,
            actor,
            (name != "zwrite").then_some((enabled, false)),
            (name != "ztest").then_some(enabled),
        )?;
    } else if name == "ztestmode" {
        let mode = text(call, value).ok_or_else(|| call.error(b"ztestmode expects a ZTestMode"))?;
        let flags = match mode
            .trim()
            .trim_start_matches("ZTestMode_")
            .to_ascii_lowercase()
            .as_str()
        {
            "off" => (false, false),
            "writeonpass" => (true, false),
            "writeonfail" => (true, true),
            _ => return Err(call.error(format!("invalid ZTestMode: {mode}").as_bytes())),
        };
        depth(call, store, actor, Some(flags), None)?;
    } else if matches!(name, "SetTextureFiltering" | "SetDrawByZPosition") {
        let enabled = call
            .arguments()
            .get(1)
            .is_none_or(|v| !matches!(v, Value::Nil | Value::Boolean(false)));
        action_capture::prepare(call, store, actor)?;
        let mut guard = store.lock().unwrap();
        let render = &mut guard.actors.get_mut(&actor).unwrap().state.render;
        if name == "SetTextureFiltering" {
            render.texture_filtering = enabled;
        } else {
            render.draw_by_z_position = enabled;
        }
        drop(guard);
        song_properties::record(
            call,
            store,
            actor,
            if name == "SetTextureFiltering" {
                Target::TextureFiltering
            } else {
                Target::DrawByZPosition
            },
            Update::Bool(enabled),
        );
    } else if name == "blend" {
        if let Some(blend) = text(call, value).and_then(crate::parse_overlay_blend_mode) {
            action_capture::prepare(call, store, actor)?;
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .render
                .blend = blend;
            song_properties::record(call, store, actor, Target::Blend, Update::Blend(blend));
        }
    } else if matches!(
        name,
        "stretchto"
            | "scaletofit"
            | "scaletocover"
            | "zoomto"
            | "zoomtowidth"
            | "zoomtoheight"
            | "vanishpoint"
    ) {
        geometry(call, store, actor, name)?;
    } else if name != "clearzbuffer" {
        let nonfinite = matches!(
            name,
            "croptop"
                | "cropbottom"
                | "fadeleft"
                | "faderight"
                | "fadetop"
                | "fadebottom"
                | "basealpha"
                | "heading"
                | "pitch"
                | "roll"
        ) || (name == "diffusealpha"
            && matches!(value, Value::Number(v) if v.is_infinite()));
        if let Some(number) = float_scalar(call, value, nonfinite) {
            action_capture::prepare(call, store, actor)?;
            scalar(call, store, actor, name, number);
            if name == "diffusealpha" {
                song_replay::sync_getters(call, store, actor)?;
            }
        }
    }
    call.push(Value::Table(actor))
}

fn corner_mask(name: &str) -> Option<u8> {
    Some(match name {
        "diffuseupperleft" => 1,
        "diffuseupperright" => 2,
        "diffuselowerleft" => 4,
        "diffuselowerright" => 8,
        "diffuseleftedge" => 5,
        "diffuserightedge" => 10,
        "diffusetopedge" => 3,
        "diffusebottomedge" => 12,
        _ => return None,
    })
}

fn scalar(call: &mut HostCall<'_>, store: &Shared, actor: TableId, name: &str, value: f32) {
    let shared = store;
    let id = actor;
    let mut store = store.lock().unwrap();
    let sync = name == "diffusealpha" && !store.playback;
    let actor = store.actors.get_mut(&actor).unwrap();
    let diffuse = actor.getter_destination().diffuse;
    let render = &mut actor.state.render;
    match name {
        "basealpha" => render.base_alpha = value,
        "basezoom" => {
            render.basezoom = value;
            render.basezoom_x = value;
            render.basezoom_y = value;
            render.basezoom_z = value;
        }
        "basezoomx" => render.basezoom_x = value,
        "basezoomy" => render.basezoom_y = value,
        "basezoomz" => render.basezoom_z = value,
        "baserotationx" => render.base_rotation[0] = value,
        "baserotationy" => render.base_rotation[1] = value,
        "baserotationz" => render.base_rotation[2] = value,
        "shadowlength" => render.shadow_len = [value, -value],
        "shadowlengthx" => render.shadow_len[0] = value,
        "shadowlengthy" => render.shadow_len[1] = -value,
        "zbias" => render.z_bias = value,
        "fov" => render.fov = (value != -1.0).then_some(value),
        _ => {
            let pose = actor.destination_mut();
            match name {
                "cropleft" => pose.cropleft = value,
                "cropright" => pose.cropright = value,
                "croptop" => pose.croptop = value,
                "cropbottom" => pose.cropbottom = value,
                "fadeleft" => pose.fadeleft = value,
                "faderight" => pose.faderight = value,
                "fadetop" => pose.fadetop = value,
                "fadebottom" => pose.fadebottom = value,
                "skewx" => pose.skew_x = value,
                "skewy" => pose.skew_y = value,
                "diffusealpha" => {
                    pose.diffuse = diffuse;
                    pose.diffuse[3] = value;
                }
                "heading" | "pitch" | "roll" => {
                    let axis = match name {
                        "heading" => 1,
                        "pitch" => 0,
                        _ => 2,
                    };
                    pose.quaternion = crate::actor_quaternion::rotate(pose.quaternion, axis, value);
                }
                _ => unreachable!(),
            }
        }
    }
    if sync {
        actor.sync_rotation_getters();
    }
    drop(store);
    capture::property(call, shared, id, name);
    if matches!(name, "zbias" | "fov") {
        song_properties::record(
            call,
            shared,
            id,
            if name == "zbias" {
                Target::ZBias
            } else {
                Target::Fov
            },
            Update::F32(value),
        );
    }
}

fn geometry(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let count = match name {
        "zoomtowidth" | "zoomtoheight" => 1,
        "zoomto" | "vanishpoint" => 2,
        _ => 4,
    };
    let mut values = [0.0; 4];
    for (i, value) in values.iter_mut().enumerate().take(count) {
        match float_scalar(call, arg(call, i + 1), false) {
            Some(number) => *value = number,
            None if name == "stretchto" => {}
            None => return Ok(()),
        }
    }
    geometry_values(call, store, actor, name, values)
}

fn screen_size(call: &mut HostCall<'_>) -> Result<[f32; 2], Error> {
    let globals = super::table(call, helper(call, 5)?)?;
    let mut size = [640., 480.];
    for (index, key) in ["SCREEN_WIDTH", "SCREEN_HEIGHT"].into_iter().enumerate() {
        let value = super::sprites::field(call, globals, key)?;
        if value != Value::Nil {
            let number = super::sprites::number(call, value)?.trunc();
            if !(i32::MIN as f64..=i32::MAX as f64).contains(&number) {
                return Err(call.error(b"screen size out of range"));
            }
            size[index] = number as i32 as f32;
        }
    }
    Ok(size)
}

fn screen_geometry(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    if name == "FullScreen" {
        let [width, height] = screen_size(call)?;
        return geometry_values(call, store, actor, "stretchto", [0., 0., width, height]);
    }
    let globals = super::table(call, helper(call, 5)?)?;
    let mut center = [0.; 2];
    for (index, key) in ["SCREEN_CENTER_X", "SCREEN_CENTER_Y"]
        .into_iter()
        .enumerate()
    {
        let value = super::sprites::field(call, globals, key)?;
        let value = if value == Value::Nil {
            None
        } else {
            Some(super::sprites::number(call, value)? as f32)
        };
        // The original helper eagerly evaluates its size fallback, even with
        // an explicit center; invalid dimensions must still report an error.
        center[index] = value.unwrap_or(screen_size(call)?[index] * 0.5);
    }
    action_capture::prepare(call, store, actor)?;
    let mut guard = store.lock().unwrap();
    let pose = guard.actors.get_mut(&actor).unwrap().destination_mut();
    if name != "CenterY" {
        pose.x = center[0];
    }
    if name != "CenterX" {
        pose.y = center[1];
    }
    drop(guard);
    capture::property(call, store, actor, name);
    Ok(())
}

fn geometry_values(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
    values: [f32; 4],
) -> Result<(), Error> {
    if name != "vanishpoint" {
        super::sprites::refresh_size(call, store, actor)?;
    }
    let bitmap = store.lock().unwrap().actors[&actor].state.class == "BitmapText";
    let text_height =
        bitmap && name == "zoomtoheight" && !super::text::content(call, actor)?.is_empty();
    let scale_plan = if matches!(name, "scaletofit" | "scaletocover") {
        let guard = store.lock().unwrap();
        let instance = &guard.actors[&actor];
        let plan = crate::scale_to_rect_plan(
            values,
            instance.state.size.map(f32::abs),
            [instance.state.render.halign, instance.state.render.valign],
            name == "scaletocover",
        );
        let Some(plan) = plan else { return Ok(()) };
        Some(plan)
    } else {
        None
    };
    action_capture::prepare(call, store, actor)?;
    let id = actor;
    let mut guard = store.lock().unwrap();
    let actor = guard.actors.get_mut(&id).unwrap();
    if bitmap && (matches!(name, "zoomto" | "zoomtowidth") || text_height) {
        let [width, height] = actor.state.size.map(f32::abs);
        let size = match name {
            "zoomtowidth" => [values[0], height],
            "zoomtoheight" => [width, values[0]],
            _ => [values[0], values[1]],
        };
        actor.state.size = size;
        actor.state.render.size = Some(size);
        drop(guard);
        capture::property(call, store, id, "size");
        return Ok(());
    }
    let mut scaled = false;
    let [width, height] = actor.state.size.map(f32::abs);
    let render = &mut actor.state.render;
    if name == "vanishpoint" {
        render.vanishpoint = Some([values[0], values[1]]);
        drop(guard);
        song_properties::record(
            call,
            store,
            id,
            Target::Vanishpoint,
            Update::Vec2([values[0], values[1]]),
        );
        return Ok(());
    }
    let pose = actor.destination_mut();
    match name {
        "zoomtowidth" => pose.zoom_x = values[0] / width,
        "zoomtoheight" => pose.zoom_y = values[0] / height,
        "zoomto" => {
            pose.zoom_x = values[0] / width;
            pose.zoom_y = values[1] / height;
        }
        "stretchto" => {
            let w = values[2] - values[0];
            let h = values[3] - values[1];
            pose.x = values[0] + w / 2.0;
            pose.y = values[1] + h / 2.0;
            pose.zoom_x = w / width;
            pose.zoom_y = h / height;
        }
        "scaletofit" | "scaletocover" => {
            let plan = scale_plan.unwrap();
            scaled = true;
            pose.x = plan.pos[0];
            pose.y = plan.pos[1];
            pose.zoom = plan.zoom;
            pose.zoom_x = plan.zoom;
            pose.zoom_y = plan.zoom;
            pose.zoom_z = plan.zoom;
            if plan.flip_x {
                pose.rot_y_deg = 180.0;
            }
            if plan.flip_y {
                pose.rot_x_deg = 180.0;
            }
            if plan.flip_x {
                actor.state.rotation[1] = 180.0;
            }
            if plan.flip_y {
                actor.state.rotation[0] = 180.0;
            }
        }
        _ => unreachable!(),
    }
    drop(guard);
    capture::property(call, store, id, name);
    if let Some(plan) = scale_plan {
        if plan.flip_x {
            capture::property(call, store, id, "rotationy");
        }
        if plan.flip_y {
            capture::property(call, store, id, "rotationx");
        }
    }
    if scaled {
        super::text::pre_zoom(call, store, id, true, true)?;
    }
    Ok(())
}

//! Transfer an outgoing scene from process roots to Lua-owned reachability.
use super::*;

type Collected = Arc<Mutex<Vec<(u64, TableId)>>>;
struct CollectedScene {
    queue: Collected,
    id: u64,
    owner: TableId,
}
impl Drop for CollectedScene {
    fn drop(&mut self) {
        // GC/shutdown only notifies. Never acquire Store or reenter the VM from
        // a closure destructor, including collection inside an actor callback.
        self.queue
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push((self.id, self.owner));
    }
}
fn lifetime(_: &mut HostCall<'_>) -> Result<(), Error> {
    Ok(())
}

pub(super) fn sweep(store: &Shared) {
    let queue = store.lock().unwrap().collected_scenes.clone();
    let collected = std::mem::take(&mut *queue.lock().unwrap_or_else(|e| e.into_inner()));
    if collected.is_empty() {
        return;
    }
    let mut guard = store.lock().unwrap();
    for (id, owner) in collected {
        // An attachment may have failed before publication, then been retried.
        if guard.retired_scenes.get(&id) != Some(&owner) {
            continue;
        }
        guard.retired_scenes.remove(&id);
        let Some(scene) = guard.scenes.remove(&id) else {
            continue;
        };
        for actor in scene.actors {
            let other = guard
                .scenes
                .iter()
                .find_map(|(id, s)| s.actors.contains(&actor).then_some(*id));
            if let Some(other) = other {
                if let Some(a) = guard.actors.get_mut(&actor)
                    && a.scene == id
                {
                    a.scene = other;
                }
            } else {
                guard.actors.remove(&actor);
                guard.retired_subscriptions.remove(&actor);
                guard.actor_order.retain(|candidate| *candidate != actor);
                if let Some(queued) = &mut guard.startup_queues {
                    queued.retain(|candidate| *candidate != actor);
                }
                #[cfg(feature = "test-support")]
                guard.message_ranks.remove(&actor);
            }
        }
    }
}

/// Late wrappers/native children retain the old graph and join the current
/// native registry. Its next replacement relinquishes those additional roots.
pub(super) fn retain(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
    registry: TableId,
) -> Result<(), Error> {
    let owner = store.lock().unwrap().retired_scenes.get(&scene).copied();
    if let Some(owner) = owner {
        call.raw_table_set(owner, Value::Table(actor), Value::Boolean(true))?;
        if let Some(previous) = call.table_host_state(actor)?
            && previous != owner
        {
            call.raw_table_set(owner, Value::Table(previous), Value::Boolean(true))?;
        }
        call.set_table_host_state(actor, Some(owner))?;
        call.raw_table_set(registry, Value::Table(actor), Value::Boolean(true))?;
        store.lock().unwrap().retired_subscriptions.insert(actor);
    } else {
        call.raw_table_set(registry, Value::Table(actor), Value::Boolean(true))?;
    }
    Ok(())
}

pub(super) fn retire(call: &mut HostCall<'_>, store: &Shared, id: u64) -> Result<bool, Error> {
    let (members, sounds_retired, queue) = {
        let guard = store.lock().unwrap();
        if guard.retired_scenes.contains_key(&id) {
            return Ok(false);
        }
        let Some(scene) = guard.scenes.get(&id) else {
            return Ok(false);
        };
        (
            scene.actors.clone(),
            scene.sounds_retired,
            guard.collected_scenes.clone(),
        )
    };
    lifecycle::invalidate_plans(call, store)?;
    let owner = call.try_new_table()?;
    call.with_roots(&[Value::Table(owner)], |call| {
        let token =
            call.new_host_function_with_data(lifetime, &[], CollectedScene { queue, id, owner })?;
        call.raw_table_set(owner, Value::Number(1.), token)?;
        let (exclusive, references) = {
            let guard = store.lock().unwrap();
            let exclusive: Vec<_> = members
                .iter()
                .copied()
                .filter(|actor| {
                    !guard.scenes.iter().any(|(other, s)| {
                        *other != id
                            && !guard.retired_scenes.contains_key(other)
                            && s.actors.contains(actor)
                    })
                })
                .collect();
            let mut references = members.clone();
            for actor in &exclusive {
                let a = &guard.actors[actor];
                references.extend(a.parent);
                references.extend(a.children.iter().copied());
                references.extend(a.wrappers.iter().copied());
                references.extend(a.sound);
            }
            (exclusive, references)
        };
        for value in references {
            call.raw_table_set(owner, Value::Table(value), Value::Boolean(true))?;
        }
        for &actor in &exclusive {
            if let Some(previous) = call.table_host_state(actor)? {
                call.raw_table_set(owner, Value::Table(previous), Value::Boolean(true))?;
            }
            call.set_table_host_state(actor, Some(owner))?;
        }
        // Publish only after every graph edge is traced. Registry removal below
        // cannot collect a partially transferred graph at a callback boundary.
        {
            let mut guard = store.lock().unwrap();
            guard.retired_scenes.insert(id, owner);
            guard.constructor_scenes.remove(&id);
            guard.actor_order.retain(|actor| !exclusive.contains(actor));
            if let Some(queued) = &mut guard.startup_queues {
                queued.retain(|actor| !exclusive.contains(actor));
            }
            for &actor in &members {
                let other = guard.scenes.iter().find_map(|(other, s)| {
                    (*other != id
                        && !guard.retired_scenes.contains_key(other)
                        && s.actors.contains(&actor))
                    .then_some(*other)
                });
                if let Some(other) = other
                    && guard.actors[&actor].scene == id
                {
                    guard.actors.get_mut(&actor).unwrap().scene = other;
                }
            }
        }
        let registry = table(call, call.captures()[0])?;
        for actor in exclusive {
            if !sounds_retired {
                sound::retire(call, store, actor);
            }
            call.raw_table_set(registry, Value::Table(actor), Value::Nil)?;
            store.lock().unwrap().retired_subscriptions.remove(&actor);
        }
        Ok(true)
    })
}

//! ScreenGameplay's owned base tree, before the remaining theme files load.
use super::super::managers::screen::Requests;
use super::*;
use generated_players::dummy;
use sprites::set;

#[derive(Clone)]
struct Build {
    store: Shared,
    context: crate::SongLuaCompileContext,
    statistics: Arc<Mutex<super::super::statistics::State>>,
}

impl Actors {
    pub(in crate::rust_engine) fn gameplay_screen(
        &self,
        vm: &mut Vm,
        context: &crate::SongLuaCompileContext,
        statistics: Arc<Mutex<super::super::statistics::State>>,
        catalog: Value,
        requests: Arc<Mutex<Requests>>,
    ) -> Result<(ActorScene, [Value; crate::LUA_PLAYERS]), Error> {
        underlay::ensure_helpers(vm, self.helpers)?;
        screen_parts::ensure_helpers(vm, self.helpers)?;
        let function = vm.new_host_function_with_data(
            construct,
            &[
                Value::Table(self.registry),
                Value::Table(self.helpers),
                catalog,
            ],
            Build {
                store: self.store.clone(),
                context: context.clone(),
                statistics,
            },
        )?;
        let values = vm.call(function, &[])?.to_vec();
        let Value::Number(id) = values[0] else {
            unreachable!()
        };
        let scene = ActorScene {
            owner: self.instantiate,
            id: id as u64,
        };
        let children = [values[1], values[2], values[3], values[4], values[5]];
        if let Err(error) = self.bind_top_screen(
            vm,
            catalog,
            children,
            context.players.each_ref().map(|p| p.enabled),
            requests,
        ) {
            self.release(vm, scene)?;
            return Err(error);
        }
        Ok((scene, [values[2], values[3]]))
    }
}

fn construct(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Build>().unwrap().clone();
    let scene = new_scene(call, &data.store)?;
    let previous = {
        let mut store = data.store.lock().unwrap();
        let capture = !store.clock.live.load(std::sync::atomic::Ordering::Relaxed);
        std::mem::replace(&mut store.constructing_capture, capture)
    };
    let result = assemble(call, &data, scene);
    data.store.lock().unwrap().constructing_capture = previous;
    let actors = match result {
        Ok(actors) => actors,
        Err(error) => {
            release(call, &data.store, scene)?;
            return Err(error);
        }
    };
    call.push(Value::Number(scene as f64))?;
    for actor in actors {
        call.push(Value::Table(actor))?;
    }
    Ok(())
}

fn assemble(call: &mut HostCall<'_>, data: &Build, scene: u64) -> Result<[TableId; 5], Error> {
    let store = &data.store;
    let context = &data.context;
    let top = top_screen::create(call, store, scene, context)?;
    store.lock().unwrap().scenes.get_mut(&scene).unwrap().root = Some(top);
    let builds = [0, 1].map(|index| {
        generated_players::Build::new(store.clone(), data.statistics.clone(), context, index)
    });
    // The native screen constructs both meters, then both players, even when
    // only one player is enabled. Parts are attached after screen parenting.
    let meters = [
        builds[0].create_meter(call, scene)?,
        builds[1].create_meter(call, scene)?,
    ];
    let players = [
        builds[0].create_player(call, scene)?,
        builds[1].create_player(call, scene)?,
    ];
    for (index, &player) in players.iter().enumerate() {
        native_children::adopt(call, store, player, top)?;
        set(
            call,
            player,
            "__songlua_life_meter",
            Value::Table(meters[index]),
        )?;
        player_parts::install(call, store, scene, player, index, &context.style_name)?;
    }
    for (index, &meter) in meters.iter().enumerate() {
        native_children::adopt(call, store, meter, top)?;
        set(
            call,
            meter,
            "__songlua_theme_hibernating",
            Value::Boolean(true),
        )?;
        tag(call, meter, crate::top_screen_life_meter_name(index))?;
    }
    for (index, &player) in players.iter().enumerate() {
        if context.players[index].enabled {
            native_children::insert(
                call,
                top,
                crate::top_screen_player_name(index),
                Value::Table(player),
            )?;
        }
    }
    for (index, &meter) in meters.iter().enumerate() {
        if context.players[index].enabled {
            native_children::insert(
                call,
                top,
                crate::top_screen_life_meter_name(index),
                Value::Table(meter),
            )?;
        }
    }
    for &name in crate::TOP_SCREEN_THEME_CHILD_NAMES {
        let player = crate::top_screen_score_index(name)
            .or_else(|| crate::top_screen_steps_display_index(name))
            .or_else(|| {
                ["StepsDescription", "PlayerOptions", "OniGameOver"]
                    .iter()
                    .find_map(|prefix| {
                        name.strip_prefix(prefix).and_then(|side| match side {
                            "P1" => Some(0),
                            "P2" => Some(1),
                            _ => None,
                        })
                    })
            });
        if player.is_some_and(|index| !context.players[index].enabled) {
            continue;
        }
        let child = if name == "Underlay" {
            underlay::create(call, store, scene, top)?
        } else {
            screen_parts::create(call, store, scene, name)?
        };
        underlay::set_name(call, store, child, name)?;
        underlay::copy_tags(call, top, child)?;
        native_children::adopt(call, store, child, top)?;
        tag(call, child, name)?;
        if crate::top_screen_score_index(name).is_some()
            || crate::top_screen_steps_display_index(name).is_some()
            || name.starts_with("StepsDescription")
            || matches!(name, "Header" | "Footer")
        {
            set(
                call,
                child,
                "__songlua_theme_hibernating",
                Value::Boolean(true),
            )?;
        }
        if let Some(index) = crate::top_screen_steps_display_index(name) {
            let value = call.try_intern(context.players[index].difficulty.sm_name().as_bytes())?;
            set(call, child, "__songlua_preferred_difficulty", value)?;
        }
        native_children::insert(call, top, name, Value::Table(child))?;
    }
    let registry = native_children::helper_function(call, b"native_registry")?;
    let registry = call.call(registry, &[Value::Table(top)])?[0];
    let mut ordered = call.with_roots(&[registry], |call| {
        let registry = table(call, registry)?;
        let mut ordered = Vec::new();
        for name in [
            "SongBackground",
            "Underlay",
            "PlayerP1",
            "PlayerP2",
            "LifeP1",
            "LifeP2",
            "ScoreP1",
            "ScoreP2",
            "StepsDisplayP1",
            "StepsDisplayP2",
            "Overlay",
            "SongForeground",
            "In",
            "Debug",
        ]
        .into_iter()
        .chain(crate::TOP_SCREEN_THEME_CHILD_NAMES.iter().copied())
        {
            let value = get(call, registry, name.as_bytes())?;
            if value != Value::Nil {
                let child = table(call, value)?;
                if !ordered.contains(&child) {
                    ordered.push(child);
                }
            }
        }
        Ok(ordered)
    })?;
    write_order(call, store, top, &ordered)?;
    // These native messages reach the already-constructed theme. They bypass
    // authored broadcast recording and never enter a song's startup output.
    song_capture::without_live_broadcasts(call, store, |call| {
        for (index, &meter) in meters.iter().enumerate() {
            if !context.players[index].enabled {
                continue;
            }
            let params = call.try_new_table()?;
            call.with_roots(&[Value::Table(params)], |call| {
                let player = call.try_intern(crate::player_number_name(index).as_bytes())?;
                set(call, params, "Player", player)?;
                set(call, params, "LifeMeter", Value::Table(meter))?;
                messages::dispatch(
                    call,
                    store,
                    b"LifeChanged",
                    Some(Value::Table(params)),
                    false,
                )
            })?;
        }
        Ok(())
    })?;
    let mut unnamed = Vec::new();
    for role in ["Toasty", "NextSong", "Ready", "Go", "Failed"] {
        let actor = dummy(call, store, scene, "ActorFrame", "", Some(top))?;
        set(call, actor, "__songlua_transition_state", Value::Number(0.))?;
        let value = call.try_intern(role.as_bytes())?;
        set(call, actor, "__songlua_screen_actor_role", value)?;
        if role == "Toasty" {
            screen_parts::invoke(call, actor, "visible", &[Value::Boolean(false)])?;
        }
        unnamed.push(actor);
        ordered.push(actor);
    }
    let unnamed = underlay::group(call, &unnamed)?;
    native_children::insert(call, top, "", unnamed)?;
    set(
        call,
        top,
        "__songlua_owned_child_lookup",
        Value::Boolean(true),
    )?;
    // Stable sorting first restores native construction order and then draw
    // order. In particular all players precede their OniGameOver displays.
    let construction = [
        "Underlay",
        "Overlay",
        "Header",
        "Footer",
        "In",
        "Out",
        "Cancel",
        "SongBackground",
        "SongForeground",
        "Toasty",
        "PlayerP1",
        "PlayerP2",
        "OniGameOverP1",
        "OniGameOverP2",
        "NextSong",
        "LifeP1",
        "LifeP2",
        "ScoreP1",
        "ScoreP2",
        "StepsDescriptionP1",
        "PlayerOptionsP1",
        "StepsDisplayP1",
        "StepsDescriptionP2",
        "PlayerOptionsP2",
        "StepsDisplayP2",
        "SongOptions",
        "ActiveAttackListP1",
        "ActiveAttackListP2",
        "LyricDisplay",
        "Ready",
        "Go",
        "Failed",
        "Debug",
    ];
    let mut keys = Vec::new();
    for &actor in &ordered {
        let name = actor_name(call, store, actor)?;
        let name =
            String::from_utf8(name).map_err(|error| call.error(error.to_string().as_bytes()))?;
        let role = get(call, actor, b"__songlua_screen_actor_role")?;
        let role = if role == Value::Nil {
            None
        } else {
            Some(assets::text(call, role)?)
        };
        let rank = construction
            .iter()
            .position(|known| *known == role.as_deref().unwrap_or(&name))
            .unwrap_or(construction.len());
        let order = match name.as_str() {
            "SongBackground" => -200,
            "Underlay" => -100,
            "Overlay" => 100,
            "SongForeground" => 101,
            "Debug" => 199,
            "In" | "Out" | "Cancel" => 200,
            _ if matches!(role.as_deref(), Some("NextSong" | "Failed")) => 199,
            _ => 0,
        };
        let key = call.try_intern(b"__songlua_state_draw_order")?;
        call.raw_table_set(actor, key, Value::Number(order as f64))?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .draw_order = order;
        keys.push((actor, rank, order));
    }
    keys.sort_by_key(|&(_, rank, _)| rank);
    keys.sort_by_key(|&(_, _, order)| order);
    ordered = keys.into_iter().map(|(actor, _, _)| actor).collect();
    write_order(call, store, top, &ordered)?;
    lifecycle::invalidate_plans(call, store)?;
    Ok([top, players[0], players[1], meters[0], meters[1]])
}

fn tag(call: &mut HostCall<'_>, actor: TableId, name: &str) -> Result<(), Error> {
    let value = call.try_intern(name.as_bytes())?;
    set(call, actor, "__songlua_top_screen_child_name", value)
}

fn write_order(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    ordered: &[TableId],
) -> Result<(), Error> {
    for (index, &child) in ordered.iter().enumerate() {
        call.raw_table_set(
            actor,
            Value::Number((index + 1) as f64),
            Value::Table(child),
        )?;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .children = ordered.to_vec();
    Ok(())
}

//! Generated ScreenGameplay display children, before screen ownership/On commands.
use super::*;
use generated_players::dummy;
use sprites::{field, set};

struct Build {
    store: Shared,
    name: String,
}

const LYRIC_COMMANDS: &[u8] = br#"return function()
return {
    Back = function(self) self:LyricCommand('Back') end,
    Front = function(self) self:LyricCommand('Front') end,
    SetNoReverseCommand = function(self) self:x(SCREEN_CENTER_X):y(SCREEN_CENTER_Y + 160) end,
    SetReverseCommand = function(self) self:x(SCREEN_CENTER_X):y(SCREEN_CENTER_Y - 140) end,
    SetOneReverseCommand = function(self) self:x(SCREEN_CENTER_X):y(SCREEN_CENTER_Y - 205) end,
}
end"#;
const LYRIC_INITIAL: &[u8] = br#"return function()
local allReverse, anyReverse = true, false
for _, player in ipairs(GAMESTATE:GetEnabledPlayers()) do
    local reverse = GAMESTATE:GetPlayerState(player):GetPlayerOptions('ModsLevel_Current'):Reverse() == 1
    allReverse = allReverse and reverse
    anyReverse = anyReverse or reverse
end
return allReverse and 'SetReverse' or anyReverse and 'SetOneReverse' or 'SetNoReverse'
end"#;

impl Actors {
    pub(in crate::rust_engine) fn screen_part(
        &self,
        vm: &mut Vm,
        name: &str,
    ) -> Result<ActorScene, Error> {
        ensure_helpers(vm, self.helpers)?;
        let function = vm.new_host_function_with_data(
            construct,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Build {
                store: self.store.clone(),
                name: name.to_owned(),
            },
        )?;
        let Value::Number(id) = vm.call(function, &[])?[0] else {
            unreachable!()
        };
        Ok(ActorScene {
            owner: self.instantiate,
            id: id as u64,
        })
    }
}

pub(super) fn ensure_helpers(vm: &mut Vm, helpers: TableId) -> Result<(), Error> {
    steps_displays::ensure_helpers(vm, helpers)?;
    transitions::ensure_helpers(vm, helpers)?;
    for (key, source, name) in [
        (
            "lyric_commands",
            LYRIC_COMMANDS,
            b"@theme:/metrics.ini:LyricDisplay".as_slice(),
        ),
        (
            "lyric_initial",
            LYRIC_INITIAL,
            b"@theme:/ScreenGameplay:LyricDisplayPosition".as_slice(),
        ),
    ] {
        let value = vm.try_intern(key.as_bytes())?;
        if vm.raw_table_get(helpers, value)? == Value::Nil {
            let code = compile_named(source, name)?;
            let function = vm.execute(&code)?[0];
            super::super::put(vm, helpers, key, function)?;
        }
    }
    Ok(())
}

fn construct(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Build>().unwrap();
    let store = data.store.clone();
    let name = data.name.clone();
    let id = {
        let mut guard = store.lock().unwrap();
        if guard.next >= (1u64 << 53) - 1 {
            return Err(call.error(b"actor scene identity exhausted"));
        }
        guard.next += 1;
        let id = guard.next;
        guard.scenes.insert(
            id,
            Scene {
                actors: Vec::new(),
                root: None,
                ended: false,
                sounds_retired: false,
                initial_states: None,
                song_session: None,
            },
        );
        id
    };
    let previous = {
        let mut guard = store.lock().unwrap();
        let capture = !guard.clock.live.load(std::sync::atomic::Ordering::Relaxed);
        std::mem::replace(&mut guard.constructing_capture, capture)
    };
    let result = create(call, &store, id, &name);
    store.lock().unwrap().constructing_capture = previous;
    match result {
        Ok(actor) => store.lock().unwrap().scenes.get_mut(&id).unwrap().root = Some(actor),
        Err(error) => {
            release(call, &store, id)?;
            return Err(error);
        }
    }
    call.push(Value::Number(id as f64))
}

pub(super) fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    if ["In", "Out", "Cancel"]
        .iter()
        .any(|known| name.eq_ignore_ascii_case(known))
    {
        return transitions::create(call, store, scene, name);
    }
    if name.eq_ignore_ascii_case("Timer") {
        let actor = dummy(call, store, scene, "Timer", name, None)?;
        let function = call.new_host_function(timer_seconds, &[])?;
        let bound = get(call, actor, b"__songlua_bound_methods")?;
        set(call, table(call, bound)?, "GetSeconds", function)?;
        return Ok(actor);
    }
    if let Some(index) = crate::top_screen_score_index(name) {
        return score(call, store, scene, index);
    }
    if crate::top_screen_steps_display_index(name).is_some() {
        return steps_displays::create(call, store, scene, name);
    }
    if name.eq_ignore_ascii_case("LyricDisplay") {
        return lyrics(call, store, scene, name);
    }
    if name.eq_ignore_ascii_case("SongBackground") {
        return background(call, store, scene);
    }
    if name.eq_ignore_ascii_case("Debug") {
        let actor = text(call, store, scene, name, "")?;
        let globals = table(call, helper(call, 5)?)?;
        let center = field(call, globals, "SCREEN_CENTER_X")?;
        let center = number(call, center)?;
        let bottom = field(call, globals, "SCREEN_BOTTOM")?;
        let bottom = number(call, bottom)?;
        for (method, value) in [("x", center), ("y", bottom - 116.), ("zoom", 0.75)] {
            invoke(call, actor, method, &[Value::Number(value as f64)])?;
        }
        return Ok(actor);
    }
    if ["Overlay", "Header", "Footer", "SongForeground"]
        .iter()
        .any(|part| name.eq_ignore_ascii_case(part))
    {
        return dummy(call, store, scene, "ActorFrame", name, None);
    }
    if ["StepsDescription", "PlayerOptions", "ActiveAttackList"]
        .iter()
        .any(|prefix| name.starts_with(prefix))
        || name == "SongOptions"
    {
        let actor = text(call, store, scene, name, "")?;
        invoke(call, actor, "visible", &[Value::Boolean(false)])?;
        return Ok(actor);
    }
    if name.starts_with("OniGameOver") {
        let actor = dummy(call, store, scene, "Sprite", name, None)?;
        blank_texture(call, store, actor)?;
        return Ok(actor);
    }
    Err(call.error(b"screen part is not implemented"))
}

fn timer_seconds(call: &mut HostCall<'_>) -> Result<(), Error> {
    call.push(Value::Number(0.))
}

pub(super) fn text(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
    value: &str,
) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "BitmapText", name, None)?;
    let value = call.try_intern(value.as_bytes())?;
    set(call, actor, "Text", value)?;
    Ok(actor)
}

pub(super) fn blank_texture(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let path =
        crate::blank_texture::load_native_blank_texture().map_err(|e| call.error(e.as_bytes()))?;
    let path = call.try_intern(path.as_bytes())?;
    sprites::set_texture(call, store, actor, path, false)
}

pub(super) fn append(
    call: &mut HostCall<'_>,
    store: &Shared,
    parent: TableId,
    child: TableId,
) -> Result<(), Error> {
    native_children::adopt(call, store, child, parent)?;
    call.raw_table_set(
        parent,
        Value::Number((call.raw_table_len(parent)? + 1) as f64),
        Value::Table(child),
    )?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&parent)
        .unwrap()
        .children
        .push(child);
    Ok(())
}

pub(super) fn named(
    call: &mut HostCall<'_>,
    store: &Shared,
    parent: TableId,
    name: &str,
    child: TableId,
) -> Result<(), Error> {
    native_children::adopt(call, store, child, parent)?;
    native_children::insert(call, parent, name, Value::Table(child))
}

fn score(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    index: usize,
) -> Result<TableId, Error> {
    let actor = dummy(
        call,
        store,
        scene,
        "ActorFrame",
        crate::top_screen_score_name(index),
        None,
    )?;
    let frame = dummy(call, store, scene, "Sprite", "", None)?;
    blank_texture(call, store, frame)?;
    named(call, store, actor, "", frame)?;
    let percent = dummy(
        call,
        store,
        scene,
        "PercentageDisplay",
        "ScoreDisplayPercentage Percent",
        None,
    )?;
    let name = crate::top_screen_score_percent_name(index);
    let text = text(call, store, scene, name, "0.00%")?;
    named(call, store, percent, name, text)?;
    named(
        call,
        store,
        actor,
        "ScoreDisplayPercentage Percent",
        percent,
    )?;
    Ok(actor)
}

pub(super) fn invoke(
    call: &mut HostCall<'_>,
    actor: TableId,
    name: &str,
    args: &[Value],
) -> Result<(), Error> {
    let function = field(call, actor, name)?;
    if !matches!(function, Value::Function(_) | Value::Native(_)) {
        return Err(call.error(b"actor function expected"));
    }
    let mut values = Vec::with_capacity(args.len() + 1);
    values.push(Value::Table(actor));
    values.extend_from_slice(args);
    call.call(function, &values)?;
    Ok(())
}

fn number(call: &mut HostCall<'_>, value: Value) -> Result<f32, Error> {
    sprites::number(call, value).map(|v| v as f32)
}

fn lyrics(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "ActorFrame", name, None)?;
    let factory = native_children::helper_function(call, b"lyric_commands")?;
    let commands = call.call(factory, &[])?[0];
    call.with_roots(&[commands], |call| {
        let commands = table(call, commands)?;
        for (name, side) in [("LyricBack", "Back"), ("LyricFront", "Front")] {
            let child = text(call, store, scene, name, "")?;
            let font = call.try_intern(b"Common Normal")?;
            set(call, child, "Font", font)?;
            let changed = get(call, commands, side.as_bytes())?;
            set(call, child, "ChangedCommand", changed)?;
            append(call, store, actor, child)?;
            named(call, store, actor, name, child)?;
        }
        for name in [
            "SetNoReverseCommand",
            "SetReverseCommand",
            "SetOneReverseCommand",
        ] {
            let function = get(call, commands, name.as_bytes())?;
            set(call, actor, name, function)?;
        }
        let initial = native_children::helper_function(call, b"lyric_initial")?;
        let initial = call.call(initial, &[])?[0];
        let initial = assets::text(call, initial)?;
        let function = get(call, commands, format!("{initial}Command").as_bytes())?;
        call.call(function, &[Value::Table(actor)])?;
        Ok(actor)
    })
}

fn background(call: &mut HostCall<'_>, store: &Shared, scene: u64) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "ActorFrame", "SongBackground", None)?;
    let implementation = dummy(call, store, scene, "ActorFrame", "", None)?;
    append(call, store, actor, implementation)?;
    let globals = table(call, helper(call, 5)?)?;
    let width = field(call, globals, "SCREEN_WIDTH")?;
    let width = number(call, width)?;
    let height = field(call, globals, "SCREEN_HEIGHT")?;
    let height = number(call, height)?;
    for (left, top, right, bottom) in [
        (0., 0., 0., height),
        (0., 0., width, 0.),
        (width, 0., width, height),
        (0., height, width, height),
    ] {
        let quad = dummy(call, store, scene, "Quad", "", Some(implementation))?;
        invoke(
            call,
            quad,
            "stretchto",
            &[left, top, right, bottom].map(|n| Value::Number(n as f64)),
        )?;
        invoke(call, quad, "diffuse", &[0., 0., 0., 1.].map(Value::Number))?;
        append(call, store, implementation, quad)?;
    }
    let brightness = dummy(call, store, scene, "ActorFrame", "", Some(implementation))?;
    append(call, store, implementation, brightness)?;
    let side = width / 2. - 20.;
    let prefs = get(call, globals, b"PREFSMAN")?;
    let level = call.with_roots(&[prefs], |call| {
        let function = field(call, table(call, prefs)?, "GetPreference")?;
        call.with_roots(&[function], |call| {
            if !matches!(function, Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"preference function expected"));
            }
            let key = call.try_intern(b"BGBrightness")?;
            let value = call
                .call(function, &[prefs, key])?
                .first()
                .copied()
                .unwrap_or(Value::Nil);
            number(call, value)
        })
    })?;
    for (left, right) in [(0., side), (width - side, width), (side, width - side)] {
        let quad = dummy(
            call,
            store,
            scene,
            "Quad",
            "BrightnessOverlay",
            Some(brightness),
        )?;
        invoke(
            call,
            quad,
            "stretchto",
            &[left, 0., right, height].map(|n| Value::Number(n as f64)),
        )?;
        invoke(
            call,
            quad,
            "diffuse",
            &[0., 0., 0., (1. - level) as f64].map(Value::Number),
        )?;
        append(call, store, brightness, quad)?;
    }
    // BackgroundImpl enables owned lookups recursively on its frame nodes.
    for frame in [actor, implementation, brightness] {
        set(
            call,
            frame,
            "__songlua_owned_child_lookup",
            Value::Boolean(true),
        )?;
    }
    Ok(actor)
}

//! Activation uses the loader list; the screen owns its siblings separately.
use super::super::managers::screen::Requests;
use super::super::song_activation::SongActivation;
use super::*;
use crate::{SongLuaCompileContext, SongLuaStartup};

pub(super) struct Session {
    pub roots: TableId,
    pub ready: bool,
    pub activated: bool,
    pub discovery_started: bool,
    pub locals: Option<super::super::function_snapshot::Snapshot>,
    pub queued: HashMap<TableId, super::super::SongStartupState>,
    pub messages: Option<song_messages::Capture>,
}
#[derive(Clone)]
struct Activate {
    store: Shared,
    scene: u64,
    context: SongLuaCompileContext,
    requests: Arc<Mutex<Requests>>,
    output: Arc<Mutex<Option<SongActivation>>>,
}
impl Actors {
    pub(in crate::rust_engine) fn complete_song_activation(&self, screen: ActorScene) {
        self.store
            .lock()
            .unwrap()
            .scenes
            .get_mut(&screen.id)
            .unwrap()
            .song_session
            .as_mut()
            .unwrap()
            .activated = true;
    }
    pub(in crate::rust_engine) fn discover_song_startup(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
        activation: &SongActivation,
        live: bool,
    ) -> Result<(), Error> {
        let invalid = {
            let guard = self.store.lock().unwrap();
            match &guard.scenes[&screen.id].song_session {
                None => Some(b"song layers have not been initialized".as_slice()),
                Some(session) if !session.activated || session.discovery_started => {
                    Some(b"song startup discovery requires one completed activation".as_slice())
                }
                Some(_) => None,
            }
        };
        if let Some(message) = invalid {
            return vm.with_native_stack(|stack| Err(stack.error(message)));
        }
        let (root, actors, queued) = {
            let mut guard = self.store.lock().unwrap();
            let scene = guard.scenes.get_mut(&screen.id).unwrap();
            let session = scene.song_session.as_mut().unwrap();
            session.discovery_started = true;
            let root = session.roots;
            let mut actors: Vec<_> = scene
                .initial_states
                .as_ref()
                .unwrap()
                .actors
                .keys()
                .copied()
                .collect();
            actors.extend(activation.wrapper_initials.keys().copied());
            let queued = guard.startup_queues.take().unwrap_or_default();
            if live || activation.new_screen.is_some() {
                return Ok(());
            }
            (root, actors, queued)
        };
        let has_queued = !queued.is_empty();
        let locals = if has_queued {
            Some(super::super::function_snapshot::Snapshot::capture(
                vm, root, &actors,
            )?)
        } else {
            None
        };
        // Keep the attachment reachable even if a probe removes actors from
        // the authored array or replaces the global bindings that owned them.
        let first = self.store.lock().unwrap().next;
        let result = (|| {
            if !has_queued {
                return Ok(HashMap::new());
            }
            let before = self.before_song_discovery(vm, screen)?;
            self.discover_queued(vm, queued)?;
            self.after_song_discovery(vm, screen, before)
        })();
        adopt_created(&self.store, screen.id, first);
        match result {
            Ok(queued) => {
                let mut guard = self.store.lock().unwrap();
                let session = guard
                    .scenes
                    .get_mut(&screen.id)
                    .unwrap()
                    .song_session
                    .as_mut()
                    .unwrap();
                session.locals = locals;
                session.queued = queued;
                Ok(())
            }
            Err(error) => {
                if let Some(locals) = locals {
                    locals.discard(vm)?;
                }
                Err(error)
            }
        }
    }

    pub(in crate::rust_engine) fn song_startup_queued_states(
        &self,
        screen: ActorScene,
    ) -> Option<HashMap<TableId, super::super::SongStartupState>> {
        let guard = self.store.lock().unwrap();
        Some(
            guard
                .scenes
                .get(&screen.id)?
                .song_session
                .as_ref()?
                .queued
                .clone(),
        )
    }

    pub(in crate::rust_engine) fn restore_song_startup_locals(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
    ) -> Result<(), Error> {
        let locals = self
            .store
            .lock()
            .unwrap()
            .scenes
            .get_mut(&screen.id)
            .unwrap()
            .song_session
            .as_mut()
            .and_then(|session| session.locals.take());
        if let Some(locals) = locals {
            locals.restore(vm)?;
        }
        Ok(())
    }

    #[cfg(feature = "test-support")]
    pub(in crate::rust_engine) fn song_startup_queue(&self) -> Vec<Value> {
        self.store
            .lock()
            .unwrap()
            .startup_queues
            .as_deref()
            .unwrap_or_default()
            .iter()
            .copied()
            .map(Value::Table)
            .collect()
    }

    pub(in crate::rust_engine) fn activate_song_layers(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
        context: &SongLuaCompileContext,
        requests: Arc<Mutex<Requests>>,
    ) -> Result<SongActivation, Error> {
        let output = Arc::new(Mutex::new(None));
        let function = vm.new_host_function_with_data(
            activate,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Activate {
                store: self.store.clone(),
                scene: screen.id,
                context: context.clone(),
                requests,
                output: output.clone(),
            },
        )?;
        let first = self.store.lock().unwrap().next;
        let result = vm.call(function, &[]).map(|_| ());
        adopt_created(&self.store, screen.id, first);
        result?;
        Ok(output.lock().unwrap().take().unwrap())
    }
    pub(in crate::rust_engine) fn zero_song_update(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
    ) -> Result<(), Error> {
        let function = vm.new_host_function_with_data(
            zero_update,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            (self.store.clone(), screen.id),
        )?;
        let first = self.store.lock().unwrap().next;
        let result = vm.call(function, &[]).map(|_| ());
        adopt_created(&self.store, screen.id, first);
        result
    }
}
fn zero_update(call: &mut HostCall<'_>) -> Result<(), Error> {
    let (store, id) = call.function_data::<(Shared, u64)>().unwrap().clone();
    let roots = store.lock().unwrap().scenes[&id]
        .song_session
        .as_ref()
        .unwrap()
        .roots;
    zero_node(call, &store, roots)
}
fn activate(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Activate>().unwrap().clone();
    let roots = {
        let mut guard = data.store.lock().unwrap();
        if data.context.live != guard.clock.live.load(std::sync::atomic::Ordering::Relaxed) {
            return Err(call.error(b"song activation context and runtime modes differ"));
        }
        let session = guard
            .scenes
            .get_mut(&data.scene)
            .unwrap()
            .song_session
            .as_mut()
            .ok_or_else(|| call.error(b"song layers have not been initialized"))?;
        if !session.ready {
            return Err(call.error(b"song initialization failed or activation already began"));
        }
        session.ready = false;
        session.roots
    };
    call.with_roots(&[Value::Table(roots)], |call| {
        let globals = table(call, helper(call, 5)?)?;
        let retained = call.try_new_table()?;
        call.with_roots(&[Value::Table(retained)], |call| {
            // Retain initialized globals as each typed read succeeds. A later
            // getter may collect or replace the earlier global table.
            if let Some(previous) = call.table_host_state(roots)? {
                call.raw_table_set(retained, Value::Number(5.), Value::Table(previous))?;
            }
            call.set_table_host_state(roots, Some(retained))?;
            let mut initialized = [None; 4];
            for (i, key) in ["mod_actions", "mod_perframes", "mods", "mods_ease"]
                .into_iter()
                .enumerate()
            {
                let value = sprites::field(call, globals, key)?;
                if value != Value::Nil {
                    table(call, value)?;
                    call.raw_table_set(retained, Value::Number((i + 1) as f64), value)?;
                    initialized[i] = Some(value);
                }
                if i == 0 && data.requests.lock().unwrap().next.take().is_some() {
                    log::warn!("Setting a new screen during an InitCommand is not allowed.");
                }
            }
            raw_set(
                call,
                globals,
                "__songlua_screen_loading",
                Value::Boolean(false),
            )?;
            data.store
                .lock()
                .unwrap()
                .startup_queues
                .get_or_insert_with(Vec::new);
            if let Some(capture) = &mut data.store.lock().unwrap().song_broadcasts {
                capture.overlay_started = true;
            }
            // Loader children have no native parent of their own. Begin walks
            // direct unique roots; On below follows the raw sequence including aliases.
            native_children::with_children(call, roots, |call, actor| {
                let beat = get(call, actor, b"__songlua_background_start_beat")?;
                if beat != Value::Nil {
                    sprites::number(call, beat)?;
                    return Ok(());
                }
                named_tree(call, &data.store, actor, b"Begin")
            })?;
            let top = get(call, globals, b"__songlua_top_screen")?;
            if top != Value::Nil {
                call.with_roots(&[top], |call| {
                    let children = sprites::field(call, table(call, top)?, "__songlua_children")?;
                    call.with_roots(&[children], |call| {
                        let actor = get(call, table(call, children)?, b"In")?;
                        if actor != Value::Nil {
                            call.with_roots(&[actor], |call| {
                                transitions::start(call, &data.store, table(call, actor)?)
                            })?;
                        }
                        Ok(())
                    })
                })?;
            }
            #[cfg(feature = "test-support")]
            if let Some(&[music, beat, _]) = data.context.compile_clock_inputs.first() {
                let origin = data
                    .context
                    .song_timing
                    .as_ref()
                    .map_or(0., |t| f64::from(t.get_time_for_beat_exact(0.)));
                let runtime = sprites::field(call, globals, crate::SONG_LUA_RUNTIME_KEY)?;
                call.with_roots(&[runtime], |call| {
                    let runtime = table(call, runtime)?;
                    sprites::set(
                        call,
                        runtime,
                        crate::SONG_LUA_RUNTIME_BEAT_KEY,
                        Value::Number(f64::from(beat as f32)),
                    )?;
                    sprites::set(
                        call,
                        runtime,
                        crate::SONG_LUA_RUNTIME_SECONDS_KEY,
                        Value::Number(f64::from(
                            ((music - origin) / f64::from(crate::song_music_rate(&data.context)))
                                as f32,
                        )),
                    )?;
                    Ok(())
                })?;
            }
            messages::record(call, b"ScreenChanged", false)?;
            messages::dispatch(call, &data.store, b"ScreenChanged", None, true)?;
            startup(call, &data.store, roots)?;
            let wrapper_initials = song_capture::wrapper_initials(call, &data.store, roots)?;
            let options = read_options(call, globals, &data.context)?;
            *data.output.lock().unwrap() = Some(SongActivation {
                initialized_globals: initialized,
                wrapper_initials,
                updates: HashMap::new(),
                tweens: HashMap::new(),
                broadcasts: Vec::new(),
                options,
                new_screen: None,
            });
            Ok(())
        })
    })
}
fn named_tree(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        native_children::run_command(call, store, actor, name, None)?;
        native_children::with_children(call, actor, |call, child| {
            named_tree(call, store, child, name)
        })?;
        Ok(())
    })
}
fn startup(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        if truthy(get(call, actor, b"__songlua_defer_on")?) {
            return Ok(());
        }
        if truthy(sprites::field(
            call,
            actor,
            "__songlua_startup_commands_ran",
        )?) {
            return Ok(());
        }
        sprites::set(
            call,
            actor,
            "__songlua_startup_command_started",
            Value::Boolean(true),
        )?;
        sprites::set(
            call,
            actor,
            "__songlua_startup_children_walked",
            Value::Boolean(false),
        )?;
        native_children::run_command_with_drain(call, store, actor, b"On", None, false)?;
        // Fetch each slot after the preceding child's On: callbacks may append
        // or remove children during this walk.
        let mut i = 1;
        loop {
            let child = call.raw_table_get(actor, Value::Number(i as f64))?;
            if child == Value::Nil {
                break;
            }
            if let Value::Table(child) = child {
                call.with_roots(&[Value::Table(child)], |call| {
                    native_children::adopt_declared(call, store, child, actor)?;
                    startup(call, store, child)
                })?;
            }
            i += 1;
        }
        if store.lock().unwrap().actors.contains_key(&actor)
            && let Some(stream) = song_meters::stream(call, store, actor)?
        {
            startup(call, store, stream)?;
        }
        sprites::set(
            call,
            actor,
            "__songlua_startup_children_walked",
            Value::Boolean(true),
        )?;
        if store.lock().unwrap().actors.contains_key(&actor) {
            capture::drain_commands(call, store, actor)?;
        }
        sprites::set(
            call,
            actor,
            "__songlua_startup_commands_ran",
            Value::Boolean(true),
        )?;
        if let Some(actor) = store.lock().unwrap().actors.get_mut(&actor) {
            actor.started = true;
        }
        Ok(())
    })
}
fn read_options(
    call: &mut HostCall<'_>,
    globals: TableId,
    context: &SongLuaCompileContext,
) -> Result<SongLuaStartup, Error> {
    let mut options = SongLuaStartup::default();
    for (i, key) in crate::SONG_LUA_PLAYER_OPTIONS_KEYS.iter().enumerate() {
        if !context.players[i].enabled {
            continue;
        }
        let table = sprites::field(call, globals, key)?;
        call.with_roots(&[table], |call| {
            let value = get(
                call,
                super::table(call, table)?,
                b"__songlua_noteskin_override",
            )?;
            options.noteskins[i] = initial_state::value_text(call, value)?;
            Ok(())
        })?;
    }
    let top = sprites::field(call, globals, "__songlua_top_screen")?;
    call.with_roots(&[top], |call| {
        let top = table(call, top)?;
        let value = get(call, top, b"__songlua_min_seconds_to_music")?;
        if value != Value::Nil {
            options.min_seconds_to_music = Some(sprites::number(call, value)? as f32);
        }
        let children = sprites::field(call, top, "__songlua_children")?;
        call.with_roots(&[children], |call| {
            let actor = sprites::field(call, table(call, children)?, "In")?;
            if actor != Value::Nil {
                call.with_roots(&[actor], |call| {
                    let visible = sprites::field(call, table(call, actor)?, "__songlua_visible")?;
                    options.hide_in = visible == Value::Boolean(false);
                    Ok(())
                })?;
            }
            Ok(())
        })
    })?;
    Ok(options)
}
fn raw_set(call: &mut HostCall<'_>, actor: TableId, key: &str, value: Value) -> Result<(), Error> {
    let key = call.try_intern(key.as_bytes())?;
    call.raw_table_set(actor, key, value)
}
fn truthy(value: Value) -> bool {
    !matches!(value, Value::Nil | Value::Boolean(false))
}

pub(super) fn adopt_created(store: &Shared, owner: u64, first: u64) {
    let scenes = store
        .lock()
        .unwrap()
        .scenes
        .keys()
        .copied()
        .filter(|id| *id > first)
        .collect::<Vec<_>>();
    for scene in scenes {
        gameplay_theme::adopt_owned_scene(store, owner, scene);
    }
}

// The real startup Update(0) uses dynamic raw-array traversal, not the cached
// chronological plan. It does not dispatch future queues or transition jobs.
fn zero_node(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        if truthy(get(call, actor, b"__songlua_live_inactive")?)
            || truthy(get(call, actor, b"__songlua_theme_hibernating")?)
        {
            return Ok(());
        }
        let hibernate = get(call, actor, b"__songlua_hibernate_seconds")?;
        if hibernate != Value::Nil && sprites::number(call, hibernate)? > 0. {
            return Ok(());
        }
        let owned = store.lock().unwrap().actors.contains_key(&actor);
        let wrappers = sprites::field(call, actor, "__songlua_wrappers")?;
        if wrappers == Value::Nil && owned {
            // Rust actor bindings own their default wrapper list in metadata.
            // Resolve each slot after the previous callback, as the native raw
            // sequence walker does, so appended wrappers run in this update.
            let mut index = 0;
            loop {
                let wrapper = store.lock().unwrap().actors[&actor]
                    .wrappers
                    .get(index)
                    .copied();
                let Some(wrapper) = wrapper else {
                    break;
                };
                zero_node(call, store, wrapper)?;
                index += 1;
            }
        }
        if wrappers != Value::Nil {
            call.with_roots(&[wrappers], |call| {
                let wrappers = table(call, wrappers)?;
                let mut i = 1;
                loop {
                    let wrapper = call.raw_table_get(wrappers, Value::Number(i as f64))?;
                    if wrapper == Value::Nil {
                        break;
                    }
                    zero_node(call, store, table(call, wrapper)?)?;
                    i += 1;
                }
                Ok(())
            })?;
        }
        if owned {
            let active = {
                let guard = store.lock().unwrap();
                let render = guard.actors[&actor].state.render;
                (!render.effect_timer
                    && render.effect_clock == deadlib_present::anim::EffectClock::Time)
                    || render.effect_mode != deadlib_present::anim::EffectMode::None
                    || render.rainbow
            };
            if active {
                effects::advance(call, store, actor, 0.)?;
            }
        }
        let mut i = 1;
        loop {
            let child = call.raw_table_get(actor, Value::Number(i as f64))?;
            if child == Value::Nil {
                break;
            }
            if let Value::Table(child) = child {
                call.with_roots(&[Value::Table(child)], |call| {
                    native_children::adopt_declared(call, store, child, actor)?;
                    zero_node(call, store, child)
                })?;
            }
            i += 1;
        }
        if owned && let Some(stream) = song_meters::stream(call, store, actor)? {
            zero_node(call, store, stream)?;
        }
        let key = if truthy(get(call, actor, b"__songlua_update_pending")?) {
            b"__songlua_update_previous".as_slice()
        } else {
            b"__songlua_update_function".as_slice()
        };
        let function = get(call, actor, key)?;
        if function != Value::Nil {
            if !matches!(function, Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"actor update function must be a function"));
            }
            let result = call.with_roots(&[function], |call| {
                run_actor_function(call, store, actor, function, Some(Value::Number(0.)))
            });
            let drain = capture::drain_commands(call, store, actor);
            match result {
                Err(error) if error.kind() == ErrorKind::Runtime => {
                    let mut guard = store.lock().unwrap();
                    let report = guard.actors.get_mut(&actor).is_none_or(|actor| {
                        let report = !actor.update_error_reported;
                        actor.update_error_reported = true;
                        report
                    });
                    if report {
                        guard.diagnostics.push(error.to_string());
                    }
                }
                result => result?,
            }
            drain?;
        }
        Ok(())
    })
}

//! Owned startup output; actor identities are traced by the active loader.
use super::super::song_activation::SongStartupState;
use super::*;
use crate::{SongLuaOverlayCommandBlock, SongLuaOverlayState};

#[derive(Clone, Default)]
pub(in crate::rust_engine) struct InitialUpdate {
    states: HashMap<TableId, SongLuaOverlayState>,
    prefixes: HashMap<TableId, Vec<SongLuaOverlayCommandBlock>>,
}
#[derive(Default)]
pub(super) struct Broadcasts {
    pub overlay_started: bool,
    pub zero_update: bool,
    pub events: Vec<(f32, String, bool)>,
}
#[derive(Clone)]
enum Phase {
    Before,
    After(InitialUpdate),
    QueuedBefore,
    QueuedAfter(InitialUpdate),
    Text(Vec<TableId>),
    Tweens(HashMap<TableId, SongLuaOverlayState>),
    Wrappers,
}
#[derive(Default)]
struct Output {
    before: InitialUpdate,
    updates: HashMap<TableId, SongStartupState>,
    wrappers: HashMap<TableId, SongLuaOverlayState>,
}
impl Actors {
    pub(super) fn before_song_discovery(
        &self,
        vm: &mut Vm,
        scene: ActorScene,
    ) -> Result<InitialUpdate, Error> {
        Ok(self.capture_song(vm, scene, Phase::QueuedBefore)?.before)
    }
    pub(super) fn after_song_discovery(
        &self,
        vm: &mut Vm,
        scene: ActorScene,
        before: InitialUpdate,
    ) -> Result<HashMap<TableId, SongStartupState>, Error> {
        Ok(self
            .capture_song(vm, scene, Phase::QueuedAfter(before))?
            .updates)
    }
    pub(in crate::rust_engine) fn capture_song_startup_text(
        &self,
        vm: &mut Vm,
        scene: ActorScene,
        wrappers: Vec<TableId>,
    ) -> Result<(), Error> {
        self.capture_song(vm, scene, Phase::Text(wrappers))?;
        Ok(())
    }
    pub(in crate::rust_engine) fn begin_song_capture(&self) {
        self.store.lock().unwrap().song_broadcasts = Some(Broadcasts::default());
    }
    pub(in crate::rust_engine) fn song_zero_update(&self, active: bool) {
        if let Some(capture) = &mut self.store.lock().unwrap().song_broadcasts {
            capture.zero_update = active;
        }
    }
    pub(in crate::rust_engine) fn take_song_broadcasts(&self) -> Vec<(f32, String, bool)> {
        self.store
            .lock()
            .unwrap()
            .song_broadcasts
            .as_mut()
            .map(|capture| std::mem::take(&mut capture.events))
            .unwrap_or_default()
    }
    fn capture_song(&self, vm: &mut Vm, scene: ActorScene, phase: Phase) -> Result<Output, Error> {
        let output = Arc::new(Mutex::new(Output::default()));
        let function = vm.new_host_function_with_data(
            capture,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            (self.store.clone(), scene.id, phase, output.clone()),
        )?;
        let first = self.store.lock().unwrap().next;
        let result = vm.call(function, &[]).map(|_| ());
        song_activation::adopt_created(&self.store, scene.id, first);
        result?;
        Ok(std::mem::take(&mut *output.lock().unwrap()))
    }
    pub(in crate::rust_engine) fn before_song_update(
        &self,
        vm: &mut Vm,
        scene: ActorScene,
    ) -> Result<InitialUpdate, Error> {
        Ok(self.capture_song(vm, scene, Phase::Before)?.before)
    }
    pub(in crate::rust_engine) fn after_song_update(
        &self,
        vm: &mut Vm,
        scene: ActorScene,
        before: InitialUpdate,
    ) -> Result<HashMap<TableId, SongStartupState>, Error> {
        Ok(self.capture_song(vm, scene, Phase::After(before))?.updates)
    }
    pub(in crate::rust_engine) fn song_startup_tweens(
        &self,
        vm: &mut Vm,
        scene: ActorScene,
        wrappers: HashMap<TableId, SongLuaOverlayState>,
    ) -> Result<HashMap<TableId, SongStartupState>, Error> {
        Ok(self
            .capture_song(vm, scene, Phase::Tweens(wrappers))?
            .updates)
    }
    pub(in crate::rust_engine) fn song_wrapper_initials(
        &self,
        vm: &mut Vm,
        scene: ActorScene,
    ) -> Result<HashMap<TableId, SongLuaOverlayState>, Error> {
        Ok(self.capture_song(vm, scene, Phase::Wrappers)?.wrappers)
    }
}
fn capture(call: &mut HostCall<'_>) -> Result<(), Error> {
    let (store, scene, phase, output) = call
        .function_data::<(Shared, u64, Phase, Arc<Mutex<Output>>)>()
        .unwrap()
        .clone();
    let root = store.lock().unwrap().scenes[&scene]
        .song_session
        .as_ref()
        .unwrap()
        .roots;
    call.with_roots(&[Value::Table(root)], |call| {
        let mut result = Output::default();
        match phase {
            Phase::Before => {
                let retained = retain_table(call, root)?;
                collect_initial(call, &store, root, retained, &mut result.before.states)?;
                for &actor in result.before.states.keys() {
                    result
                        .before
                        .prefixes
                        .insert(actor, command_capture(&store, actor).blocks);
                }
            }
            Phase::After(before) => result.updates = capture_states(call, &store, before)?,
            Phase::QueuedBefore => {
                let retained = retain_table(call, root)?;
                collect_queued_initial(call, &store, root, retained, &mut result.before.states)?;
            }
            Phase::QueuedAfter(before) => {
                for (actor, initial) in before.states {
                    result.updates.insert(
                        actor,
                        SongStartupState {
                            initial,
                            blocks: command_capture(&store, actor).blocks,
                            steps: Vec::new(),
                            commands: Vec::new(),
                            block_steps: Vec::new(),
                            clock_path: clock_path(call, &store, actor)?,
                        },
                    );
                }
            }
            Phase::Text(wrappers) => {
                let mut actors: Vec<_> = store.lock().unwrap().scenes[&scene]
                    .initial_states
                    .as_ref()
                    .unwrap()
                    .actors
                    .keys()
                    .copied()
                    .collect();
                actors.extend(wrappers);
                for actor in actors {
                    let kind = sprites::field(call, actor, "__songlua_actor_type")?;
                    if initial_state::value_text(call, kind)?.is_some_and(|kind| {
                        kind.eq_ignore_ascii_case("BitmapText")
                            || kind.eq_ignore_ascii_case("RollingNumbers")
                    }) {
                        let text = get(call, actor, b"Text")?;
                        raw_set(call, actor, "__songlua_startup_text", text)?;
                    }
                }
            }
            Phase::Tweens(wrappers) => {
                let mut states = store.lock().unwrap().scenes[&scene]
                    .initial_states
                    .as_ref()
                    .unwrap()
                    .actors
                    .clone();
                for (actor, state) in wrappers {
                    states.entry(actor).or_insert(state);
                }
                result.updates = capture_states(
                    call,
                    &store,
                    InitialUpdate {
                        states,
                        prefixes: HashMap::new(),
                    },
                )?;
            }
            Phase::Wrappers => result.wrappers = wrapper_initials(call, &store, root)?,
        }
        *output.lock().unwrap() = result;
        Ok(())
    })
}
fn command_capture(store: &Shared, actor: TableId) -> ActorCommandCapture {
    let mut guard = store.lock().unwrap();
    guard
        .actors
        .get_mut(&actor)
        .and_then(|actor| actor.capture.as_mut())
        .map(capture::Capture::snapshot)
        .unwrap_or_else(|| ActorCommandCapture {
            blocks: Vec::new(),
            block_steps: Vec::new(),
            steps: Vec::new(),
            queued_commands: Vec::new(),
        })
}
fn retain_table(call: &mut HostCall<'_>, root: TableId) -> Result<TableId, Error> {
    let retained = call.try_new_table()?;
    call.with_roots(&[Value::Table(retained)], |call| {
        if let Some(previous) = call.table_host_state(root)? {
            call.raw_table_set(retained, Value::Number(1.), Value::Table(previous))?;
        }
        call.set_table_host_state(root, Some(retained))?;
        Ok(retained)
    })
}
fn collect_initial(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    retained: TableId,
    states: &mut HashMap<TableId, SongLuaOverlayState>,
) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        let kind = sprites::field(call, actor, "__songlua_actor_type")?;
        if initial_state::value_text(call, kind)?.is_some() {
            let state = initial_state::read(call, store, actor)?;
            call.raw_table_set(retained, Value::Table(actor), Value::Boolean(true))?;
            states.insert(actor, state);
        }
        raw_children(call, actor, |call, child| {
            collect_initial(call, store, child, retained, states)
        })
    })
}

fn collect_queued_initial(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    retained: TableId,
    states: &mut HashMap<TableId, SongLuaOverlayState>,
) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        let kind = sprites::field(call, actor, "__songlua_actor_type")?;
        if let Some(kind) = initial_state::value_text(call, kind)? {
            states.insert(actor, initial_state::read(call, store, actor)?);
            call.raw_table_set(retained, Value::Table(actor), Value::Boolean(true))?;
            if let Some(capture) = store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .and_then(|actor| actor.capture.as_mut())
            {
                capture.begin_discovery();
            }
            if kind.eq_ignore_ascii_case("Sprite") {
                capture_sprite_binding(call, actor)?;
            }
        }
        let wrappers = sprites::field(call, actor, "__songlua_wrappers")?;
        if wrappers != Value::Nil {
            call.with_roots(&[wrappers], |call| {
                let wrappers = table(call, wrappers)?;
                for i in 1.. {
                    let value = call.raw_table_get(wrappers, Value::Number(i as f64))?;
                    if value == Value::Nil {
                        break;
                    }
                    collect_queued_initial(call, store, table(call, value)?, retained, states)?;
                }
                Ok(())
            })?;
        } else {
            let wrappers = store
                .lock()
                .unwrap()
                .actors
                .get(&actor)
                .map(|actor| actor.wrappers.clone())
                .unwrap_or_default();
            for wrapper in wrappers {
                collect_queued_initial(call, store, wrapper, retained, states)?;
            }
        }
        raw_children(call, actor, |call, child| {
            collect_queued_initial(call, store, child, retained, states)
        })
    })
}

fn capture_sprite_binding(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let binding = call.try_new_table()?;
    call.with_roots(&[Value::Table(binding)], |call| {
        let entries = call.call(helper(call, 7)?, &[Value::Table(actor)])?[0];
        call.with_roots(&[entries], |call| {
            let entries = table(call, entries)?;
            for i in 1..=call.raw_table_len(entries)? {
                let row = table(call, call.raw_table_get(entries, Value::Number(i as f64))?)?;
                let key = call.raw_table_get(row, Value::Number(1.))?;
                let Value::String(id) = key else {
                    continue;
                };
                let name = std::str::from_utf8(call.string_bytes(id).unwrap())
                    .map_err(|e| call.error(e.to_string().as_bytes()))?;
                if matches!(
                    name,
                    "Texture"
                        | "Frames"
                        | "__songlua_state_sprite_default_states"
                        | "__songlua_state_sprite_texture_epoch"
                        | "__songlua_state_sprite_frame_sheet"
                ) || name.starts_with("Frame")
                    || name.starts_with("Delay")
                {
                    let value = call.raw_table_get(row, Value::Number(2.))?;
                    let value = call.call(helper(call, 15)?, &[value])?[0];
                    call.raw_table_set(binding, key, value)?;
                }
            }
            raw_set(
                call,
                actor,
                "__songlua_startup_sprite",
                Value::Table(binding),
            )
        })
    })
}
fn raw_set(call: &mut HostCall<'_>, actor: TableId, name: &str, value: Value) -> Result<(), Error> {
    let key = call.try_intern(name.as_bytes())?;
    call.raw_table_set(actor, key, value)
}
fn raw_children(
    call: &mut HostCall<'_>,
    actor: TableId,
    mut visit: impl FnMut(&mut HostCall<'_>, TableId) -> Result<(), Error>,
) -> Result<(), Error> {
    let mut i = 1;
    loop {
        let value = call.raw_table_get(actor, Value::Number(i as f64))?;
        if value == Value::Nil {
            break;
        }
        if let Value::Table(child) = value {
            call.with_roots(&[value], |call| visit(call, child))?;
        }
        i += 1;
    }
    Ok(())
}
pub(super) fn wrapper_initials(
    call: &mut HostCall<'_>,
    store: &Shared,
    root: TableId,
) -> Result<HashMap<TableId, SongLuaOverlayState>, Error> {
    let retained = retain_table(call, root)?;
    let mut states = HashMap::new();
    collect_wrappers(call, store, root, retained, &mut states)?;
    Ok(states)
}
fn collect_wrappers(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    retained: TableId,
    states: &mut HashMap<TableId, SongLuaOverlayState>,
) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        let wrappers = sprites::field(call, actor, "__songlua_wrappers")?;
        let mut visit = |call: &mut HostCall<'_>, wrapper| {
            call.raw_table_set(retained, Value::Table(wrapper), Value::Boolean(true))?;
            states.entry(wrapper).or_default();
            collect_wrappers(call, store, wrapper, retained, states)
        };
        if wrappers != Value::Nil {
            call.with_roots(&[wrappers], |call| {
                raw_children(call, table(call, wrappers)?, &mut visit)
            })?;
        } else {
            let native = store
                .lock()
                .unwrap()
                .actors
                .get(&actor)
                .map(|a| a.wrappers.clone())
                .unwrap_or_default();
            for wrapper in native {
                visit(call, wrapper)?;
            }
        }
        raw_children(call, actor, |call, child| {
            collect_wrappers(call, store, child, retained, states)
        })
    })
}
fn clock_path(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<Vec<[f32; 2]>, Error> {
    let retained = call.try_new_table()?;
    call.with_roots(&[Value::Table(retained), Value::Table(actor)], |call| {
        let mut path = Vec::new();
        let mut next = Some(actor);
        let mut wrapper_child = false;
        let mut seen = HashSet::new();
        while let Some(actor) = next {
            if !seen.insert(actor) {
                return Err(call.error(b"cycle in actor update ancestry"));
            }
            call.raw_table_set(retained, Value::Table(actor), Value::Boolean(true))?;
            let hibernate = get(call, actor, b"__songlua_hibernate_seconds")?;
            let theme = get(call, actor, b"__songlua_theme_hibernating")?;
            let hibernate = if !matches!(theme, Value::Nil | Value::Boolean(false)) {
                f32::INFINITY
            } else if hibernate == Value::Nil {
                0.
            } else {
                sprites::number(call, hibernate)? as f32
            };
            let rate = if wrapper_child {
                1.
            } else {
                let value = get(call, actor, b"__songlua_update_rate")?;
                if value == Value::Nil {
                    store
                        .lock()
                        .unwrap()
                        .actors
                        .get(&actor)
                        .map_or(1., |actor| actor.update_rate)
                } else {
                    sprites::number(call, value)? as f32
                }
            };
            path.push([hibernate, rate]);
            let kind = sprites::field(call, actor, "__songlua_actor_type")?;
            wrapper_child = initial_state::value_text(call, kind)?
                .is_some_and(|kind| kind.eq_ignore_ascii_case("WrapperState"));
            let parent = get(call, actor, b"__songlua_parent")?;
            next = if parent == Value::Nil {
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get(&actor)
                    .and_then(|actor| actor.parent)
            } else {
                Some(table(call, parent)?)
            };
        }
        path.reverse();
        Ok(path)
    })
}
pub(super) fn broadcast(
    call: &mut HostCall<'_>,
    store: &Shared,
    message: &[u8],
    has_params: bool,
) -> Result<(), Error> {
    let active = {
        let guard = store.lock().unwrap();
        guard.song_broadcasts.as_ref().is_some_and(|capture| {
            guard.clock.live.load(std::sync::atomic::Ordering::Relaxed)
                || (capture.overlay_started
                    && (capture.zero_update || guard.startup_queues.is_none()))
        })
    };
    if store.lock().unwrap().song_broadcasts.is_none() {
        return Ok(());
    }
    let beat = effects::values(call, false).map_or(0., |values| values[0]);
    if !active {
        return Ok(());
    }
    let message =
        String::from_utf8(message.to_vec()).map_err(|e| call.error(e.to_string().as_bytes()))?;
    if let Some(capture) = &mut store.lock().unwrap().song_broadcasts {
        capture.events.push((beat, message, has_params));
    }
    Ok(())
}

// Theme construction delivers real callbacks while temporarily excluding its
// events from the live song stream, matching the two native construction scopes.
pub(super) fn without_live_broadcasts<T>(
    call: &mut HostCall<'_>,
    store: &Shared,
    action: impl FnOnce(&mut HostCall<'_>) -> Result<T, Error>,
) -> Result<T, Error> {
    let previous = {
        let mut guard = store.lock().unwrap();
        if guard.clock.live.load(std::sync::atomic::Ordering::Relaxed) {
            guard.song_broadcasts.take()
        } else {
            None
        }
    };
    let result = action(call);
    if let Some(previous) = previous {
        store.lock().unwrap().song_broadcasts = Some(previous);
    }
    result
}

fn capture_states(
    call: &mut HostCall<'_>,
    store: &Shared,
    before: InitialUpdate,
) -> Result<HashMap<TableId, SongStartupState>, Error> {
    let mut updates = HashMap::new();
    for (actor, initial) in before.states {
        let captured = command_capture(store, actor);
        let mut commands = Vec::new();
        let mut pending = captured.queued_commands.iter();
        for step in &captured.steps {
            let command = if step.is_none() {
                pending
                    .next()
                    .map(|(name, _)| {
                        String::from_utf8(name.clone())
                            .map_err(|e| call.error(e.to_string().as_bytes()))
                    })
                    .transpose()?
            } else {
                None
            };
            commands.push(command);
        }
        let prefix = before
            .prefixes
            .get(&actor)
            .filter(|prefix| captured.blocks.starts_with(prefix))
            .map_or(0, Vec::len);
        let state = SongStartupState {
            initial,
            blocks: captured.blocks.into_iter().skip(prefix).collect(),
            block_steps: captured
                .block_steps
                .into_iter()
                .skip(prefix)
                .map(|step| (step != 0).then_some(step))
                .collect(),
            steps: captured
                .steps
                .into_iter()
                .map(|step| step.unwrap_or(0.))
                .collect(),
            commands,
            clock_path: clock_path(call, store, actor)?,
        };
        updates.insert(actor, state);
    }
    Ok(updates)
}

//! Compiler-owned prediction of fallback queue clocks over canonical frames.
use super::*;

#[derive(Default)]
struct Queue {
    progress: Option<Arc<[[f32; 2]]>>,
    epoch: usize,
    frame: usize,
    remaining: f64,
    zero_frame: Option<usize>,
    steps: VecDeque<Option<f64>>,
    blocked: bool,
    dispatch: Option<(usize, f64)>,
}
#[derive(Clone, Copy)]
pub(super) struct Phase {
    pub order: usize,
    pub delta: f64,
}
#[derive(Clone, Copy)]
pub(super) struct Dispatch {
    pub actor: TableId,
    pub frame: usize,
    pub remaining: f64,
}
pub(super) struct Publication {
    pub cursor: Option<f32>,
    pub progress: Option<Arc<[[f32; 2]]>>,
    pub advance: f32,
}
pub(super) struct State {
    times: Vec<f64>,
    actor_frames: Option<Vec<[f32; 2]>>,
    pub frame: usize,
    epoch: usize,
    native: HashSet<TableId>,
    clocks: HashMap<TableId, Queue>,
    timing: HashMap<TableId, (f32, f32)>,
    recurring_frames: HashMap<TableId, usize>,
    pub orders: Arc<HashMap<TableId, usize>>,
    pub phase: Option<Phase>,
    pub dispatch: Option<Dispatch>,
}
impl State {
    pub fn new(
        frames: &[(f64, f64)],
        actor_frames: Option<&[[f32; 2]]>,
        native: HashSet<TableId>,
    ) -> Self {
        let mut seconds = 0.;
        Self {
            times: frames
                .iter()
                .map(|(_, dt)| {
                    seconds += dt;
                    seconds
                })
                .collect(),
            actor_frames: actor_frames.map(<[_]>::to_vec),
            frame: 0,
            epoch: 0,
            native,
            clocks: HashMap::new(),
            timing: HashMap::new(),
            recurring_frames: HashMap::new(),
            orders: Arc::default(),
            phase: None,
            dispatch: None,
        }
    }
    pub fn time(&self, frame: usize) -> f64 {
        self.times.get(frame).copied().unwrap_or_else(|| {
            self.times.last().copied().unwrap_or(0.)
                + frame.saturating_sub(self.times.len()).saturating_add(1) as f64 / 60.
        })
    }
    fn delta(&self, frame: usize) -> f64 {
        if let Some(delta) = self.actor_frames.as_ref().and_then(|f| f.get(frame)) {
            return f64::from(delta[0]);
        }
        if frame == 0 {
            0.
        } else {
            f64::from(self.time(frame) as f32 - self.time(frame - 1) as f32)
        }
    }
    fn global_remainder(&self, frame: usize, remaining: f64) -> f64 {
        self.actor_frames
            .as_ref()
            .and_then(|f| f.get(frame))
            .map_or(remaining, |[delta, span]| {
                if *delta > 0. {
                    remaining * f64::from(*span) / f64::from(*delta)
                } else {
                    0.
                }
            })
    }
    fn order(&self, id: TableId) -> usize {
        self.orders.get(&id).copied().unwrap_or(0)
    }
    pub fn later(&self, id: TableId) -> bool {
        self.phase.is_some_and(|phase| self.order(id) > phase.order)
    }
    pub fn enter(&mut self, order: usize, delta: f32) {
        self.phase = Some(Phase {
            order,
            delta: f64::from(delta),
        });
        self.epoch += 1;
    }
    pub fn reset(&mut self, id: TableId) {
        self.clocks.remove(&id);
        self.timing.remove(&id);
        self.recurring_frames.remove(&id);
    }

    pub fn fallback(&self, id: TableId) -> bool {
        !self.native.contains(&id)
    }
    pub fn queue_len(&self, id: TableId) -> Option<usize> {
        self.fallback(id)
            .then(|| self.clocks.get(&id).map_or(0, |c| c.steps.len()))
    }
    pub fn pending_dispatch(&self, id: TableId) -> Option<(usize, f64)> {
        self.clocks.get(&id)?.dispatch
    }
    pub fn ready(&self, id: TableId) -> bool {
        self.pending_dispatch(id)
            .is_some_and(|(frame, _)| frame <= self.frame)
            && self.phase.is_none_or(|phase| self.order(id) <= phase.order)
    }
    pub fn waiting(&self, id: TableId) -> bool {
        self.clocks.get(&id).is_some_and(|clock| clock.blocked)
            || (self.pending_dispatch(id).is_some() && !self.ready(id))
    }
    pub fn cursor(&self, id: TableId) -> f32 {
        self.timing.get(&id).map_or(0., |t| t.0)
    }
    pub fn consumed_recurring(&self, id: TableId) -> bool {
        self.recurring_frames.get(&id) == Some(&self.frame)
    }
    pub fn mark_recurring(&mut self, id: TableId) {
        if self.clocks.contains_key(&id) {
            self.recurring_frames.insert(id, self.frame);
        }
    }
    pub fn immediate_advance(&self, id: TableId) -> f32 {
        self.dispatch.map_or_else(
            || {
                self.phase
                    .filter(|phase| self.order(id) > phase.order)
                    .map_or(0., |phase| phase.delta as f32)
            },
            |d| (self.time(self.frame) - self.time(d.frame)) as f32,
        )
    }
    pub fn prime(&mut self, id: TableId) {
        if let Some(mut clock) = self.clocks.remove(&id) {
            if clock.dispatch.is_none() {
                while let Some(step) = clock.steps.pop_front() {
                    advance(self, &mut clock, step.unwrap_or(0.), None);
                    if clock.blocked {
                        break;
                    }
                    if step.is_none() {
                        clock.dispatch = Some((clock.frame, clock.remaining));
                        break;
                    }
                }
            }
            self.clocks.insert(id, clock);
        }
    }
    pub fn hurry(&mut self, id: TableId, factor: f32) {
        if let Some((cursor, duration)) = self.timing.get_mut(&id) {
            *cursor = (*cursor + duration.max(0.)) * factor;
            *duration = 0.;
        }
        if let Some(clock) = self.clocks.get_mut(&id) {
            for d in clock.steps.iter_mut().flatten() {
                *d = f64::from(*d as f32 * factor);
            }
            clock.progress = None;
        }
    }
    pub fn tween(&mut self, id: TableId, duration: Option<f64>) {
        if self.native.contains(&id) {
            return;
        }
        let (cursor, prior) = self.timing.entry(id).or_default();
        *cursor += prior.max(0.);
        *prior = 0.;
        if let Some(delay) = self.record(id, duration) {
            self.timing.get_mut(&id).unwrap().0 = delay;
        }
        if let Some(duration) = duration {
            self.timing.get_mut(&id).unwrap().1 = duration as f32;
        } else {
            self.prime(id);
        }
    }

    fn record(&mut self, id: TableId, duration: Option<f64>) -> Option<f32> {
        let phase = self.phase?;
        let later = self.order(id) > phase.order;
        let (frame, remaining) = self
            .dispatch
            .map(|d| {
                (
                    d.frame,
                    if d.actor == id {
                        d.remaining
                    } else if self.order(id) > self.order(d.actor) {
                        self.delta(d.frame)
                    } else {
                        0.
                    },
                )
            })
            .unwrap_or((self.frame, if later { phase.delta } else { 0. }));
        let mut clock = self.clocks.remove(&id).unwrap_or(Queue {
            epoch: self.epoch,
            frame,
            remaining,
            ..Default::default()
        });
        let changed = clock.epoch != self.epoch;
        if changed && clock.dispatch.is_none() {
            while let Some(step) = clock.steps.pop_front() {
                advance(self, &mut clock, step.unwrap_or(0.), None);
            }
            clock.epoch = self.epoch;
        }
        if clock.steps.is_empty()
            && (clock.frame < frame || (clock.frame == frame && clock.remaining > remaining))
        {
            clock.frame = frame;
            clock.remaining = remaining;
        }
        let delay = changed.then(|| {
            (self.time(clock.frame) - clock.remaining - (self.time(frame) - remaining)).max(0.)
                as f32
        });
        clock.steps.push_back(duration);
        clock.progress = None;
        self.clocks.insert(id, clock);
        delay
    }
    pub fn flush(&mut self, id: TableId) {
        if let Some((cursor, duration)) = self.timing.get_mut(&id) {
            *cursor += duration.max(0.);
            *duration = 0.;
        }
    }
    pub fn dispatched(&mut self, id: TableId, remaining: f32) -> Option<Dispatch> {
        let prior = self.dispatch;
        let mut time = (self.frame, f64::from(remaining));
        if !self.native.contains(&id)
            && let Some(mut clock) = self.clocks.remove(&id)
        {
            if let Some(dispatch) = clock.dispatch.take() {
                time = dispatch;
            }
            self.timing
                .insert(id, (clock.steps.iter().flatten().sum::<f64>() as f32, 0.));
            clock.epoch = self.epoch;
            self.clocks.insert(id, clock);
        }
        self.dispatch = Some(Dispatch {
            actor: id,
            frame: time.0,
            remaining: time.1,
        });
        prior
    }
    fn progress(&mut self, id: TableId) -> Option<Arc<[[f32; 2]]>> {
        let mut clock = self.clocks.remove(&id)?;
        if clock.progress.is_none() && !clock.steps.is_empty() {
            let mut sample = Queue {
                epoch: clock.epoch,
                frame: clock.frame,
                remaining: clock.remaining,
                zero_frame: clock.zero_frame,
                blocked: clock.blocked,
                ..Default::default()
            };
            let mut samples = Vec::new();
            for (index, duration) in clock.steps.iter().enumerate() {
                advance(
                    self,
                    &mut sample,
                    duration.unwrap_or(0.),
                    (index + 1 == clock.steps.len()).then_some(&mut samples),
                );
            }
            if !samples.is_empty() {
                clock.progress = Some(samples.into());
            }
        }
        let progress = clock.progress.clone();
        self.clocks.insert(id, clock);
        progress
    }
    pub fn publication(&mut self, id: TableId) -> Publication {
        let native = self.native.contains(&id);
        let (cursor, duration) = self.timing.get(&id).copied().unwrap_or_default();
        let timed = cursor.max(0.) > f32::EPSILON || duration.max(0.) > f32::EPSILON;
        let empty = self
            .clocks
            .get(&id)
            .is_some_and(|c| c.steps.back() == Some(&Some(0.)));
        let progress = if native {
            None
        } else if timed {
            self.progress(id)
        } else if empty {
            let progress = self.progress(id);
            let later = self.phase.is_some_and(|p| self.order(id) > p.order);
            progress.filter(|p| {
                later
                    || p.first()
                        .is_some_and(|s| s[0] > self.time(self.frame) as f32)
            })
        } else {
            None
        };
        let advance = if let Some(scope) = self.dispatch {
            let advance = if scope.actor == id {
                scope.remaining
            } else if self.order(id) > self.order(scope.actor) {
                self.delta(scope.frame)
            } else {
                0.
            };
            (self.time(self.frame) - self.time(scope.frame) + advance) as f32
        } else {
            self.phase
                .filter(|p| self.order(id) > p.order)
                .map_or(0., |p| p.delta as f32)
        };
        Publication {
            cursor: (!native).then_some(cursor.max(0.)),
            progress,
            advance,
        }
    }
}

fn advance(
    frames: &State,
    clock: &mut Queue,
    duration: f64,
    mut samples: Option<&mut Vec<[f32; 2]>>,
) {
    if clock.blocked || !(duration as f32).is_finite() {
        clock.blocked = true;
        return;
    }
    // Actor::UpdateTweening subtracts native floats on each frame. A double
    // clock can release a zero-time command early and change later RNG calls.
    let mut left = duration as f32;
    loop {
        while clock.remaining <= 0.0 {
            let Some(frame) = clock.frame.checked_add(1) else {
                clock.blocked = true;
                return;
            };
            clock.frame = frame;
            clock.remaining = frames.delta(clock.frame);
        }
        if duration as f32 == 0.0 {
            clock.zero_frame = Some(clock.frame);
        }
        // A callback after its child can enqueue a zero-time state on the final
        // captured frame. Its start still belongs to the next update, even when
        // that update lies beyond the replay. Omitting this sample makes the
        // pending destination look immediate and overwrites the last draw.
        if let Some(samples) = &mut samples
            && samples.is_empty()
        {
            let start = frames.time(clock.frame)
                - if left == 0.0 {
                    0.0
                } else {
                    frames.global_remainder(clock.frame, clock.remaining)
                };
            let mut start = start as f32;
            if left > 0.0 && clock.frame > 0 {
                let prior = frames.time(clock.frame - 1) as f32;
                // A tiny remainder can put the next tween strictly after the
                // prior update while both timestamps round to the same float.
                // Preserve queue order: it cannot draw on that earlier frame.
                if frames.time(clock.frame) - frames.global_remainder(clock.frame, clock.remaining)
                    > f64::from(prior)
                    && start <= prior
                {
                    start = prior.next_up();
                }
            }
            if let Some(frame) = clock.zero_frame {
                start = start.max(frames.time(frame) as f32);
            }
            samples.push([start, left]);
        }
        let elapsed = left.min(clock.remaining as f32);
        left -= elapsed;
        clock.remaining = f64::from(clock.remaining as f32 - elapsed);
        if let Some(samples) = &mut samples
            && clock.frame < frames.times.len()
            && left != duration as f32
        {
            samples.push([frames.time(clock.frame) as f32, left]);
        }
        if left == 0.0 {
            break;
        }
        if clock.frame >= frames.times.len() {
            let count = (left * 60.0).floor() as usize;
            if count > 1 {
                clock.frame = clock.frame.saturating_add(count - 1);
                left -= (count - 1) as f32 / 60.0;
            }
        }
    }
}

impl Actors {
    pub(in crate::rust_engine) fn discard_song_replay_clock(&self) {
        self.store.lock().unwrap().replay_clock = None;
    }

    pub(in crate::rust_engine) fn set_song_replay_frames(
        &self,
        screen: ActorScene,
        frames: &[(f64, f64)],
        actor_frames: Option<&[[f32; 2]]>,
    ) -> bool {
        let mut store = self.store.lock().unwrap();
        if store.replay_frame.map(|f| f.0) != Some(screen.id)
            || store.replay_advancing
            || store.clock.live.load(std::sync::atomic::Ordering::Relaxed)
        {
            return false;
        }
        let native = store
            .actors
            .iter()
            .filter(|(_, a)| a.scene == screen.id && a.capture.is_none())
            .map(|(id, _)| *id)
            .collect();
        store.replay_clock = Some(State::new(frames, actor_frames, native));
        true
    }
    pub(in crate::rust_engine) fn set_song_replay_frame(
        &self,
        screen: ActorScene,
        frame: usize,
    ) -> Option<f64> {
        let mut store = self.store.lock().unwrap();
        if store.replay_frame?.0 != screen.id {
            return None;
        }
        let clock = store.replay_clock.as_mut()?;
        clock.frame = frame;
        Some(clock.time(frame))
    }
}

//! Typed spline observations for the existing compiler's column transforms.
use super::*;
use crate::{SongLuaColumnTransformSample as Sample, SongLuaColumnTransformTarget as Target};

const POS: &str = "__songlua_pos_handler";
const ZOOM: &str = "__songlua_zoom_handler";
const ROT: &str = "__songlua_rot_handler";
const MODE: &str = "__songlua_spline_mode";
const SPLINE: &str = "__songlua_spline";
const SIZE: &str = "__songlua_spline_size";
const POINTS: &str = "__songlua_spline_points";
const DISABLED: &str = "NoteColumnSplineMode_Disabled";
const OFFSET: &str = "NoteColumnSplineMode_Offset";
const POSITION: &str = "NoteColumnSplineMode_Position";

#[derive(Clone, Copy)]
enum Numeric {
    Float,
    Integer,
    Unsigned,
}
pub(super) fn install(vm: &mut Vm, helpers: TableId) -> Result<(), Error> {
    for (name, mode) in [
        ("column_float", Numeric::Float),
        ("column_integer", Numeric::Integer),
        ("column_unsigned", Numeric::Unsigned),
    ] {
        let function = vm.new_host_function_with_data(convert, &[], mode)?;
        super::super::put(vm, helpers, name, function)?;
    }
    Ok(())
}
fn convert(call: &mut HostCall<'_>) -> Result<(), Error> {
    let mode = *call.function_data::<Numeric>().unwrap();
    let mut stack = call.native_stack()?;
    let number = match mode {
        Numeric::Float => stack
            .to_number(1)
            .ok_or_else(|| stack.error(b"column number expected"))?,
        Numeric::Integer => stack
            .to_integer(1)
            .ok_or_else(|| stack.error(b"column integer expected"))?
            as f64,
        Numeric::Unsigned => {
            let number = stack
                .to_number(1)
                .ok_or_else(|| stack.error(b"column index expected"))?;
            if matches!(stack.value(1), Some(Value::Number(_)))
                && number >= 0.
                && number < (usize::MAX as f64)
            {
                (number as usize) as f64
            } else {
                usize::try_from(
                    stack
                        .to_integer(1)
                        .ok_or_else(|| stack.error(b"column index expected"))?,
                )
                .map_err(|_| stack.error(b"column index out of range"))? as f64
            }
        }
    };
    stack.push(Value::Number(number))?;
    stack.finish(1)
}
fn numeric(call: &mut HostCall<'_>, value: Value, mode: Numeric) -> Result<f64, Error> {
    let name: &[u8] = match mode {
        Numeric::Float => b"column_float",
        Numeric::Integer => b"column_integer",
        Numeric::Unsigned => b"column_unsigned",
    };
    let function = native_children::helper_function(call, name)?;
    let Value::Number(value) = call.call(function, &[value])?[0] else {
        unreachable!()
    };
    Ok(value)
}
fn field(call: &mut HostCall<'_>, actor: TableId, key: &str) -> Result<Value, Error> {
    sprites::field(call, actor, key)
}
fn text(call: &mut HostCall<'_>, value: Value, optional: bool) -> Result<String, Error> {
    match initial_state::value_text(call, value)? {
        Some(text) => Ok(text),
        None if optional => Ok(String::new()),
        None => Err(call.error(b"column string expected")),
    }
}
fn mode(call: &mut HostCall<'_>, handler: TableId, optional: bool) -> Result<String, Error> {
    let value = field(call, handler, MODE)?;
    text(call, value, optional)
}
fn with_table<T>(
    call: &mut HostCall<'_>,
    value: Value,
    read: impl FnOnce(&mut HostCall<'_>, Option<TableId>) -> Result<T, Error>,
) -> Result<T, Error> {
    if value == Value::Nil {
        return read(call, None);
    }
    let table = table(call, value)?;
    call.with_roots(&[value], |call| read(call, Some(table)))
}
fn required_table(call: &HostCall<'_>, value: Value) -> Result<TableId, Error> {
    table(call, value)
}
fn optional_integer(call: &mut HostCall<'_>, value: Value) -> Result<Option<i64>, Error> {
    if value == Value::Nil {
        Ok(None)
    } else {
        Ok(Some(numeric(call, value, Numeric::Integer)? as i64))
    }
}
fn point(call: &mut HostCall<'_>, points: TableId, index: usize) -> Result<[f32; 3], Error> {
    let value = call.raw_table_get(points, Value::Number(index as f64))?;
    with_table(call, value, |call, point| {
        let Some(point) = point else {
            return Ok([0.; 3]);
        };
        let mut result = [0.; 3];
        for (axis, result) in result.iter_mut().enumerate() {
            let value = call.raw_table_get(point, Value::Number((axis + 1) as f64))?;
            if value != Value::Nil {
                *result = numeric(call, value, Numeric::Float)? as f32;
            }
        }
        Ok(result)
    })
}
fn spline_size(call: &mut HostCall<'_>, spline: TableId) -> Result<usize, Error> {
    let value = field(call, spline, SIZE)?;
    Ok(optional_integer(call, value)?
        .and_then(|n| usize::try_from(n).ok())
        .unwrap_or(0))
}
fn uniform(
    call: &mut HostCall<'_>,
    column: TableId,
    key: &str,
    component: usize,
    baseline: f32,
) -> Result<Option<f32>, Error> {
    let handler = field(call, column, key)?;
    with_table(call, handler, |call, handler| {
        let Some(handler) = handler else {
            return Ok(None);
        };
        let mode = mode(call, handler, true)?;
        if mode.eq_ignore_ascii_case(DISABLED) {
            return Ok(Some(baseline));
        }
        let offset = mode.eq_ignore_ascii_case(OFFSET);
        if !offset && !mode.eq_ignore_ascii_case(POSITION) {
            return Ok(None);
        }
        let spline = field(call, handler, SPLINE)?;
        with_table(call, spline, |call, spline| {
            let Some(spline) = spline else {
                return Ok(None);
            };
            let size = spline_size(call, spline)?;
            if size == 0 {
                return Ok(Some(baseline));
            }
            let points = field(call, spline, POINTS)?;
            let points = required_table(call, points)?;
            call.with_roots(&[Value::Table(points)], |call| {
                if !offset && key == ZOOM {
                    return Ok(Some(baseline));
                }
                if !offset {
                    return Ok(Some(point(call, points, 1)?[component]));
                }
                let witness = match component {
                    0 => "__songlua_nonuniform_x",
                    1 => "__songlua_nonuniform_y",
                    _ => "__songlua_nonuniform_z",
                };
                let index = field(call, spline, witness)?;
                if index != Value::Nil {
                    let index = numeric(call, index, Numeric::Unsigned)? as usize;
                    if index <= size {
                        let first = point(call, points, 1).ok().map(|p| p[component]);
                        let other = point(call, points, index).ok().map(|p| p[component]);
                        if first.zip(other).is_some_and(|(a, b)| (a - b).abs() > 0.001) {
                            return Ok(None);
                        }
                    }
                }
                let mut first = None::<f32>;
                for index in 1..=size {
                    let value = point(call, points, index)?[component];
                    if let Some(prior) = first {
                        if (value - prior).abs() > 0.001 {
                            sprites::set(call, spline, witness, Value::Number(index as f64))?;
                            return Ok(None);
                        }
                    } else {
                        first = Some(value);
                    }
                }
                Ok(Some(baseline + first.unwrap_or(0.)))
            })
        })
    })
}
fn x_offset(call: &mut HostCall<'_>, column: TableId) -> Result<Option<f32>, Error> {
    let handler = field(call, column, POS)?;
    with_table(call, handler, |call, handler| {
        let Some(handler) = handler else {
            return Ok(None);
        };
        let mode = mode(call, handler, false)?;
        if mode.eq_ignore_ascii_case(OFFSET) {
            uniform(call, column, POS, 0, 0.)
        } else {
            Ok(
                (mode.eq_ignore_ascii_case(DISABLED) || mode.eq_ignore_ascii_case(POSITION))
                    .then_some(0.),
            )
        }
    })
}
fn y_offset(call: &mut HostCall<'_>, column: TableId) -> Result<Option<f32>, Error> {
    let handler = field(call, column, POS)?;
    with_table(call, handler, |call, handler| {
        let Some(handler) = handler else {
            return Ok(None);
        };
        let mode = mode(call, handler, true)?;
        if mode.eq_ignore_ascii_case(DISABLED) {
            return Ok(Some(0.));
        }
        if !mode.eq_ignore_ascii_case(OFFSET) {
            return Ok(None);
        }
        let spline = field(call, handler, SPLINE)?;
        with_table(call, spline, |call, spline| {
            let Some(spline) = spline else {
                return Ok(None);
            };
            let size = spline_size(call, spline)?;
            if size == 0 {
                return Ok(Some(0.));
            }
            let points = field(call, spline, POINTS)?;
            let points = required_table(call, points)?;
            call.with_roots(&[Value::Table(points)], |call| {
                let mut first = None::<f32>;
                let mut valid = true;
                for index in 1..=size {
                    let [x, y, _] = point(call, points, index)?;
                    valid &= x.is_finite() && y.is_finite();
                    if let Some(first) = first {
                        valid &= (y - first).abs() <= 0.001;
                    } else {
                        first = Some(y)
                    }
                }
                Ok(if valid { first } else { None })
            })
        })
    })
}
fn position(
    call: &mut HostCall<'_>,
    column: TableId,
) -> Result<Option<[(Target, f32); 10]>, Error> {
    let handler = field(call, column, POS)?;
    with_table(call, handler, |call, handler| {
        let Some(handler) = handler else {
            return Ok(None);
        };
        if !mode(call, handler, false)?.eq_ignore_ascii_case(OFFSET) {
            return Ok(None);
        }
        let spline = field(call, handler, SPLINE)?;
        let spline = required_table(call, spline)?;
        call.with_roots(&[Value::Table(spline)], |call| {
            let size = field(call, spline, SIZE)?;
            if numeric(call, size, Numeric::Integer)? != 2. {
                return Ok(None);
            }
            let points = field(call, spline, POINTS)?;
            let points = required_table(call, points)?;
            call.with_roots(&[Value::Table(points)], |call| {
                let mut out = [(Target::PositionEnabled, 0.); 10];
                for p in 0..2u8 {
                    let values = point(call, points, usize::from(p) + 1)?;
                    for axis in 0..3u8 {
                        let value = values[usize::from(axis)];
                        if !value.is_finite() {
                            return Ok(None);
                        }
                        out[usize::from(p) * 3 + usize::from(axis)] =
                            (Target::PositionPoint { point: p, axis }, value);
                    }
                }
                let beats = field(call, handler, "__songlua_beats_per_t")?;
                let beats = numeric(call, beats, Numeric::Float)? as f32;
                let receptor = field(call, handler, "__songlua_receptor_t")?;
                let receptor = numeric(call, receptor, Numeric::Float)? as f32;
                if !beats.is_finite() || beats == 0. || !receptor.is_finite() {
                    return Ok(None);
                }
                let subtract = field(call, handler, "__songlua_subtract_song_beat")?.is_truthy();
                out[6..].copy_from_slice(&[
                    (Target::PositionEnabled, 1.),
                    (Target::PositionBeatsPerT, beats),
                    (Target::PositionReceptorT, receptor),
                    (Target::PositionSubtractBeat, if subtract { 1. } else { 0. }),
                ]);
                Ok(Some(out))
            })
        })
    })
}
fn read_field(
    call: &mut HostCall<'_>,
    field_id: TableId,
    out: &mut Vec<Sample>,
) -> Result<(), Error> {
    let columns = field(call, field_id, "__songlua_note_columns")?;
    with_table(call, columns, |call, columns| {
        let Some(columns) = columns else {
            return Ok(());
        };
        for index in 1usize.. {
            let column = call.raw_table_get(columns, Value::Number(index as f64))?;
            if column == Value::Nil {
                break;
            }
            let id = table(call, column)?;
            call.with_roots(&[column], |call| {
                let player = field(call, id, "__songlua_player_index")?;
                let Some(player) =
                    optional_integer(call, player)?.and_then(|n| usize::try_from(n).ok())
                else {
                    return Ok(());
                };
                let column = field(call, id, "__songlua_column_index")?;
                let Some(column) =
                    optional_integer(call, column)?.and_then(|n| usize::try_from(n).ok())
                else {
                    return Ok(());
                };
                let mut push = |target, value: Option<f32>| {
                    if let Some(value) = value.filter(|v| v.is_finite()) {
                        out.push(Sample {
                            player,
                            column,
                            target,
                            value,
                        })
                    }
                };
                let position = position(call, id)?;
                let handler = field(call, id, POS)?;
                let absolute = with_table(call, handler, |call, handler| {
                    Ok(handler.is_some_and(|h| {
                        mode(call, h, false).is_ok_and(|m| m.eq_ignore_ascii_case(POSITION))
                    }))
                })?;
                if position.is_some() || absolute {
                    push(Target::OffsetX, Some(0.));
                    push(Target::OffsetY, Some(0.));
                } else {
                    push(Target::OffsetX, x_offset(call, id)?);
                    push(Target::OffsetY, y_offset(call, id)?);
                }
                push(Target::Zoom, uniform(call, id, ZOOM, 0, 1.)?);
                push(Target::RotationZ, uniform(call, id, ROT, 2, 0.)?);
                if let Some(position) = position {
                    for (target, value) in position {
                        push(target, Some(value));
                    }
                } else {
                    push(Target::PositionEnabled, Some(0.));
                }
                Ok(())
            })?;
        }
        Ok(())
    })
}
fn note_field(call: &mut HostCall<'_>, index: usize) -> Result<Option<TableId>, Error> {
    let globals = helper(call, 5)?;
    let player = super::super::field(
        call,
        globals,
        if index == 0 {
            "__songlua_top_screen_player_1"
        } else {
            "__songlua_top_screen_player_2"
        },
    )?;
    with_table(call, player, |call, player| {
        let Some(player) = player else {
            return Ok(None);
        };
        let key = call.try_intern(b"__songlua_children")?;
        let children = call.raw_table_get(player, key)?;
        if call.raw_table_len(player)? == 0 && children != Value::Nil {
            return with_table(call, children, |call, children| {
                let key = call.try_intern(b"NoteField")?;
                let value = call.raw_table_get(children.unwrap(), key)?;
                if value == Value::Nil {
                    Ok(None)
                } else {
                    table(call, value).map(Some)
                }
            });
        }
        let children = native_children::named_children(call, player)?;
        call.with_roots(&[children], |call| {
            let value = super::super::field(call, children, "NoteField")?;
            if value == Value::Nil {
                Ok(None)
            } else {
                table(call, value).map(Some)
            }
        })
    })
}
fn read_pending(
    call: &mut HostCall<'_>,
    pending: TableId,
    out: &mut Vec<Sample>,
) -> Result<(), Error> {
    for i in 1usize.. {
        let key = Value::Number(i as f64);
        let value = call.raw_table_get(pending, key)?;
        if value == Value::Nil {
            break;
        }
        let field = table(call, value)?;
        call.with_roots(&[value], |call| {
            // Native consumes its Vec<Table>: retain future fields, but drop
            // each processed field before getters on the next field can run.
            call.raw_table_set(pending, key, Value::Nil)?;
            read_field(call, field, out)
        })?;
    }
    Ok(())
}
fn global_fields(call: &mut HostCall<'_>, out: &mut Vec<Sample>) -> Result<(), Error> {
    let pending = call.try_new_table()?;
    call.with_roots(&[Value::Table(pending)], |call| {
        let mut slot = 1;
        for index in 0..crate::LUA_PLAYERS {
            if let Some(field) = note_field(call, index)? {
                call.raw_table_set(pending, Value::Number(slot as f64), Value::Table(field))?;
                slot += 1;
            }
        }
        read_pending(call, pending, out)
    })
}
impl Actors {
    pub(in crate::rust_engine) fn read_column_samples(
        &self,
        vm: &mut Vm,
        fields: Option<&[Value]>,
    ) -> Result<Vec<Sample>, Error> {
        let mut pins = Vec::new();
        let mut input_pin = None;
        let output = Arc::new(Mutex::new(Vec::new()));
        let result = (|| {
            let input = if let Some(fields) = fields {
                for &field in fields {
                    pins.push(vm.pin(field)?);
                    if !matches!(field, Value::Table(_)) {
                        return vm.with_native_stack(|stack| {
                            Err(stack.error(b"note field table expected"))
                        });
                    }
                }
                let table = vm.try_new_table()?;
                input_pin = Some(vm.pin(Value::Table(table))?);
                for (i, &field) in fields.iter().enumerate() {
                    vm.raw_table_set(table, Value::Number((i + 1) as f64), field)?;
                }
                for pin in pins.drain(..) {
                    vm.unpin(pin)?;
                }
                Value::Table(table)
            } else {
                Value::Nil
            };
            let callback = vm.new_host_function_with_data(
                |call| {
                    let output = call
                        .function_data::<Arc<Mutex<Vec<Sample>>>>()
                        .unwrap()
                        .clone();
                    let mut samples = Vec::new();
                    if let Value::Table(input) = call.captures()[2] {
                        read_pending(call, input, &mut samples)?;
                    } else {
                        global_fields(call, &mut samples)?;
                    }
                    *output.lock().unwrap() = samples;
                    Ok(())
                },
                &[
                    Value::Table(self.registry),
                    Value::Table(self.helpers),
                    input,
                ],
                output.clone(),
            )?;
            vm.call(callback, &[])?;
            Ok(std::mem::take(&mut *output.lock().unwrap()))
        })();
        for pin in pins {
            vm.unpin(pin)?;
        }
        if let Some(pin) = input_pin {
            vm.unpin(pin)?;
        }
        result
    }
}

//! Compiler buffers shared by immediate and scheduled render setters.
use super::super::{SongReplayImmediateUpdates, SongReplayScheduledUpdate};
use super::*;
use crate::{SongLuaOverlayUpdateTarget as Target, SongLuaOverlayUpdateValue as UpdateValue};

// The order within compound setters matters (notably basezoom and Load's size
// and texture writes). Effects emit their own ordered sequence of writes.
pub(crate) const TARGETS: &[Target] = &[
    Target::Visible,
    Target::Hibernating,
    Target::HAlign,
    Target::VAlign,
    Target::TextAlign,
    Target::BaseZoom,
    Target::BaseZoomX,
    Target::BaseZoomY,
    Target::BaseZoomZ,
    Target::BaseAlpha,
    Target::BaseRotation,
    Target::ShadowLen,
    Target::ShadowColor,
    Target::Size,
    Target::SpriteTexture,
    Target::SpriteStateIndex,
    Target::Vibrate,
    Target::Rainbow,
    Target::EffectMode,
    Target::EffectPeriod,
    Target::EffectTiming,
    Target::EffectMagnitude,
    Target::EffectColor1,
    Target::EffectColor2,
    Target::EffectOffset,
    Target::EffectClock,
    Target::EffectNoOffset,
    Target::EffectTimer,
    Target::CullMode,
    Target::AftPreserve,
    Target::AftCreated,
];

#[derive(Clone, Copy)]
pub(super) struct Dispatch {
    pub(super) seconds: Option<f64>,
    pub(super) delay: f32,
}

#[derive(Default)]
pub(super) struct Capture {
    touched: Vec<usize>,
    pub(super) frames: HashMap<usize, SongReplayImmediateUpdates>,
    pending: HashMap<usize, Vec<(Target, UpdateValue)>>,
    pub(super) prior_positions: HashMap<usize, [f32; 3]>,
}

fn replace(values: &mut Vec<(Target, UpdateValue)>, target: Target, value: UpdateValue) {
    if let Some((_, old)) = values.iter_mut().find(|(key, _)| *key == target) {
        *old = value;
    } else {
        values.push((target, value));
    }
}

impl Capture {
    pub(super) fn touch(&mut self, index: usize) -> &mut SongReplayImmediateUpdates {
        self.frames.entry(index).or_insert_with(|| {
            self.touched.push(index);
            SongReplayImmediateUpdates {
                overlay_index: index,
                ..Default::default()
            }
        })
    }

    pub(super) fn record(
        &mut self,
        index: usize,
        target: Target,
        value: UpdateValue,
        scheduled: Option<SongReplayScheduledUpdate>,
    ) {
        let pending = self
            .pending
            .get(&index)
            .and_then(|values| values.iter().find(|(key, _)| *key == target))
            .map(|(_, value)| value.clone());
        let frame = self.touch(index);
        replace(&mut frame.final_values, target, value.clone());
        if let Some(mut update) = scheduled {
            if let Some(previous) = frame.scheduled.iter_mut().find(|prior| {
                prior.target == target
                    && prior.dispatch_seconds == update.dispatch_seconds
                    && prior.frame_advance == update.frame_advance
                    && prior.delay_seconds == update.delay_seconds
                    && prior.duration_seconds == update.duration_seconds
                    && prior.easing == update.easing
                    && prior.opt1 == update.opt1
            }) {
                previous.value = value;
            } else {
                update.initial_value = frame
                    .values
                    .iter()
                    .find(|(key, _)| *key == target)
                    .map(|(_, value)| value.clone())
                    .or(pending);
                frame.scheduled.push(update);
            }
        } else {
            replace(&mut frame.values, target, value);
        }
    }

    fn drain(&mut self) -> Vec<SongReplayImmediateUpdates> {
        self.touched
            .drain(..)
            .map(|index| self.frames.remove(&index).unwrap())
            .filter(|frame| {
                frame.tween_reset
                    || !frame.values.is_empty()
                    || !frame.scheduled.is_empty()
                    || !frame.final_values.is_empty()
            })
            .collect()
    }
}

impl Actors {
    pub(in crate::rust_engine) fn set_song_pending_overlay_updates(
        &self,
        screen: ActorScene,
        values: &[(usize, Target, UpdateValue)],
    ) -> bool {
        self.set_pending_updates(screen, values, false)
    }

    pub(in crate::rust_engine) fn set_song_pending_render_updates(
        &self,
        screen: ActorScene,
        values: &[(usize, Target, UpdateValue)],
    ) -> bool {
        self.set_pending_updates(screen, values, true)
    }

    fn set_pending_updates(
        &self,
        screen: ActorScene,
        values: &[(usize, Target, UpdateValue)],
        render_only: bool,
    ) -> bool {
        let mut store = self.store.lock().unwrap();
        if store.replay_frame.map(|f| f.0) != Some(screen.id) {
            return false;
        }
        let Some(capture) = store
            .scenes
            .get_mut(&screen.id)
            .and_then(|s| s.song_session.as_mut())
            .and_then(|s| s.messages.as_mut())
        else {
            return false;
        };
        if values.iter().any(|(index, target, _)| {
            !capture.indices.values().any(|i| i == index)
                || if render_only {
                    !song_properties::TARGETS.contains(target)
                } else {
                    !song_pose::supported(*target)
                }
        }) {
            return false;
        }
        capture.immediate.pending.clear();
        for (index, target, value) in values {
            replace(
                capture.immediate.pending.entry(*index).or_default(),
                *target,
                value.clone(),
            );
        }
        true
    }

    pub(in crate::rust_engine) fn drain_song_immediate_updates(
        &self,
        screen: ActorScene,
    ) -> Option<Vec<SongReplayImmediateUpdates>> {
        let mut frames = self.drain_song_property_updates(screen)?;
        for frame in &mut frames {
            frame.values.retain(|(target, _)| TARGETS.contains(target));
            frame
                .final_values
                .retain(|(target, _)| TARGETS.contains(target));
            frame
                .scheduled
                .retain(|update| TARGETS.contains(&update.target));
        }
        frames.retain(|f| {
            f.tween_reset
                || !f.values.is_empty()
                || !f.final_values.is_empty()
                || !f.scheduled.is_empty()
        });
        Some(frames)
    }

    pub(in crate::rust_engine) fn drain_song_property_updates(
        &self,
        screen: ActorScene,
    ) -> Option<Vec<SongReplayImmediateUpdates>> {
        let mut frames = self.drain_song_overlay_updates(screen)?;
        for frame in &mut frames {
            frame.values.retain(|(target, _)| {
                TARGETS.contains(target) || song_properties::TARGETS.contains(target)
            });
            frame.final_values.retain(|(target, _)| {
                TARGETS.contains(target) || song_properties::TARGETS.contains(target)
            });
            frame.scheduled.retain(|u| {
                TARGETS.contains(&u.target) || song_properties::TARGETS.contains(&u.target)
            });
        }
        frames.retain(|f| {
            f.tween_reset
                || !f.values.is_empty()
                || !f.final_values.is_empty()
                || !f.scheduled.is_empty()
        });
        Some(frames)
    }

    pub(in crate::rust_engine) fn drain_song_overlay_updates(
        &self,
        screen: ActorScene,
    ) -> Option<Vec<SongReplayImmediateUpdates>> {
        let mut store = self.store.lock().unwrap();
        if store.replay_frame?.0 != screen.id {
            return None;
        }
        Some(
            store
                .scenes
                .get_mut(&screen.id)?
                .song_session
                .as_mut()?
                .messages
                .as_mut()?
                .immediate
                .drain(),
        )
    }
}

// A capture's actor IDs are traced by its enclosing scene. Lookup after each Lua
// access also tolerates authored reentry without holding a Store lock across it.
pub(super) fn context(store: &Store, id: TableId) -> Option<(u64, usize)> {
    if store.clock.live.load(std::sync::atomic::Ordering::Relaxed) {
        return None;
    }
    let (owner, _) = store.replay_frame?;
    if store.retired_scenes.contains_key(&owner) {
        return None;
    }
    let capture = store
        .scenes
        .get(&owner)?
        .song_session
        .as_ref()?
        .messages
        .as_ref()?;
    Some((owner, *capture.indices.get(&id)?))
}

pub(super) fn record(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    target: Target,
    value: UpdateValue,
) {
    capture::retain_render_update(store, id, target, &value, true);
    record_frame(call, store, id, target, value);
}
fn record_frame(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    target: Target,
    value: UpdateValue,
) {
    if context(&store.lock().unwrap(), id).is_none() {
        return;
    }
    let beat = effects::values(call, false).map_or(0., |values| values[0]);
    let mut guard = store.lock().unwrap();
    let Some((owner, index)) = context(&guard, id) else {
        return;
    };
    let dispatch = guard.replay_dispatch;
    let frame_advance = guard
        .replay_clock
        .as_ref()
        .map_or(0., |clock| clock.immediate_advance(id));
    let message = guard.active_message.clone();
    let capture = guard
        .scenes
        .get_mut(&owner)
        .unwrap()
        .song_session
        .as_mut()
        .unwrap()
        .messages
        .as_mut()
        .unwrap();
    if let Some(message) = message {
        capture.write(
            message,
            crate::SongLuaStatefulMessageWrite {
                overlay_index: index,
                beat,
                target,
                value: value.clone(),
                delay_seconds: dispatch.map_or(0., |scope| scope.delay),
                duration_seconds: 0.,
                easing: None,
                opt1: None,
            },
        );
    }
    let scheduled = dispatch.map(|dispatch| SongReplayScheduledUpdate {
        progress: None,
        dispatch_seconds: dispatch.seconds,
        frame_advance,
        initial_value: None,
        delay_seconds: dispatch.delay,
        duration_seconds: 0.,
        easing: None,
        opt1: None,
        target,
        value: value.clone(),
    });
    capture.immediate.record(index, target, value, scheduled);
}

pub(super) fn delta(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    delta: &crate::SongLuaOverlayStateDelta,
    immediate: bool,
) {
    if !immediate || context(&store.lock().unwrap(), id).is_none() {
        return;
    }
    let mut state = crate::SongLuaOverlayState::default();
    crate::apply_overlay_delta(&mut state, delta);
    for &target in TARGETS {
        if delta.has_update_target(target) {
            record_frame(
                call,
                store,
                id,
                target,
                crate::perframe::overlay_state_update_value(&state, target),
            );
        }
    }
}

pub(super) fn cancel(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    finish: bool,
) -> Result<(), Error> {
    if context(&store.lock().unwrap(), id).is_none() {
        return Ok(());
    }
    let beat = effects::values(call, false).map_or(0., |values| values[0]);
    let (owner, index, message, values) = {
        let mut guard = store.lock().unwrap();
        let Some((owner, index)) = context(&guard, id) else {
            return Ok(());
        };
        let actor = &guard.actors[&id];
        let cur = actor.current;
        let position = actor
            .preparation_getters
            .unwrap_or([cur.x, cur.y, cur.z, cur.aux]);
        let message = guard.active_message.clone();
        let capture = guard
            .scenes
            .get_mut(&owner)
            .unwrap()
            .song_session
            .as_mut()
            .unwrap()
            .messages
            .as_mut()
            .unwrap();
        let pending = capture.immediate.pending.remove(&index).unwrap_or_default();
        let frame = capture.immediate.touch(index);
        frame.tween_reset = true;
        if !finish {
            let targets = frame
                .scheduled
                .iter()
                .filter(|u| crate::tween_pose::TARGETS.contains(&u.target))
                .fold(0u128, |mask, u| mask | (1u128 << u.target as usize));
            frame
                .final_values
                .retain(|(target, _)| targets & (1u128 << *target as usize) == 0);
            frame
                .scheduled
                .retain(|u| !crate::tween_pose::TARGETS.contains(&u.target));
            for (target, value) in [Target::X, Target::Y, Target::Z].into_iter().zip(position) {
                replace(&mut frame.values, target, UpdateValue::F32(value));
                replace(&mut frame.final_values, target, UpdateValue::F32(value));
            }
            return Ok(());
        }
        let mut values = pending;
        for update in std::mem::take(&mut frame.scheduled) {
            replace(&mut values, update.target, update.value);
        }
        (owner, index, message, values)
    };
    for (target, value) in values {
        if crate::tween_pose::TARGETS.contains(&target) {
            song_pose::set_getter(call, store, id, target, &value)?;
        }
        let mut guard = store.lock().unwrap();
        if song_properties::TARGETS.contains(&target) {
            let actor = guard.actors.get_mut(&id).unwrap();
            crate::perframe::set_overlay_state_update_value(
                &mut actor.state.render,
                target,
                &value,
            );
            if let (Target::DrawOrder, UpdateValue::I32(order)) = (target, &value) {
                actor.state.draw_order = *order;
            }
            if target == Target::Fov {
                actor.state.render.fov = actor.state.render.fov.filter(|fov| *fov != -1.);
            }
        }
        let Some(capture) = guard
            .scenes
            .get_mut(&owner)
            .and_then(|s| s.song_session.as_mut())
            .and_then(|s| s.messages.as_mut())
        else {
            return Ok(());
        };
        capture.immediate.record(index, target, value.clone(), None);
        if let Some(message) = &message {
            capture.write(
                message.clone(),
                crate::SongLuaStatefulMessageWrite {
                    overlay_index: index,
                    beat,
                    target,
                    value,
                    delay_seconds: 0.,
                    duration_seconds: 0.,
                    easing: None,
                    opt1: None,
                },
            );
        }
    }
    Ok(())
}

//! Existing compiler renderer kinds. Command probing and tree policy are separate.
use super::*;
use crate::{
    SongLuaCompileContext, SongLuaOverlayKind as Kind, SongLuaOverlayState, SongLuaProxyTarget,
};
use deadlib_present::actors::TextAttribute;
use std::path::PathBuf;

type PlainKind = Kind<(), (), TextAttribute>;
pub(in crate::rust_engine) enum Output {
    Ready(Option<Box<PlainKind>>),
    Model(Option<crate::lua_util::SongLuaNoteskinTapActorModel>),
}
impl Output {
    fn ready(kind: Option<PlainKind>) -> Self {
        Self::Ready(kind.map(Box::new))
    }
}
#[derive(Clone)]
struct Read {
    store: Shared,
    class: String,
    initial: SongLuaOverlayState,
    context: SongLuaCompileContext,
    aft_names: HashSet<String>,
    output: Arc<Mutex<Option<Output>>>,
}
impl Actors {
    pub(in crate::rust_engine) fn read_song_overlay_kind(
        &self,
        vm: &mut Vm,
        actor: Value,
        inputs: &super::super::SongOverlayKindInputs<'_>,
    ) -> Result<Output, Error> {
        let output = Arc::new(Mutex::new(None));
        let function = vm.new_host_function_with_data(
            read,
            &[
                Value::Table(self.registry),
                Value::Table(self.helpers),
                actor,
            ],
            Read {
                store: self.store.clone(),
                class: inputs.actor_type.to_owned(),
                initial: inputs.initial_state,
                context: inputs.context.clone(),
                aft_names: inputs.aft_capture_names.clone(),
                output: output.clone(),
            },
        )?;
        vm.call(function, &[])?;
        Ok(output.lock().unwrap().take().unwrap())
    }
}
fn resolve(call: &mut HostCall<'_>, actor: TableId, path: &str) -> Result<Option<PathBuf>, Error> {
    match assets::resolve(call, actor, path) {
        Err(error) if error.kind() == ErrorKind::Runtime => Ok(None),
        result => result,
    }
}
fn read(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Read>().unwrap().clone();
    let actor = table(call, call.captures()[2])?;
    let result = kind(call, &data, actor)?;
    *data.output.lock().unwrap() = Some(result);
    Ok(())
}
fn kind(call: &mut HostCall<'_>, data: &Read, actor: TableId) -> Result<Output, Error> {
    let class = data.class.as_str();
    let kind = if class.eq_ignore_ascii_case("Actor") {
        Kind::Actor
    } else if class.eq_ignore_ascii_case("WrapperState") {
        Kind::WrapperState
    } else if class.eq_ignore_ascii_case("ActorFrame")
        || class.eq_ignore_ascii_case("CourseContentsList")
    {
        Kind::ActorFrame
    } else if class.eq_ignore_ascii_case("ActorFrameTexture") {
        let frame = framebuffers::read(call, actor)?;
        Kind::ActorFrameTexture {
            capture_name: frame.capture_name,
            capture_size: frame.capture_size,
            alpha_buffer: frame.alpha_buffer,
            depth_buffer: frame.depth_buffer,
            float_buffer: frame.float_buffer,
        }
    } else if class.eq_ignore_ascii_case("ActorProxy") {
        Kind::ActorProxy {
            target: proxies::read(call, actor)?.unwrap_or(SongLuaProxyTarget::Actor {
                overlay_index: usize::MAX,
            }),
        }
    } else if class.eq_ignore_ascii_case("Sprite") || class.eq_ignore_ascii_case("Banner") {
        if let Some(capture_name) = assets::field(call, actor, b"__songlua_aft_capture_name")? {
            Kind::AftSprite { capture_name }
        } else {
            let binding = get(call, actor, b"__songlua_startup_sprite")?;
            let binding = if binding == Value::Nil {
                actor
            } else {
                table(call, binding)?
            };
            let kind = call.with_roots(&[Value::Table(binding)], |call| {
                let Some(texture) = assets::field(call, binding, b"Texture")? else {
                    return Ok(Some(Kind::Actor));
                };
                let capture_name = textures::collapse(&texture);
                if data.aft_names.contains(&capture_name) {
                    return Ok(Some(Kind::AftSprite { capture_name }));
                }
                let Some(texture_path) = resolve(call, actor, &texture)? else {
                    return Ok(None);
                };
                let texture_key = crate::lua_util::texture_path_key(&texture_path);
                Ok(Some(Kind::Sprite {
                    texture_path,
                    texture_key,
                    states: sprites::states(call, binding)?.into(),
                    textures: Arc::from([]),
                }))
            })?;
            return Ok(Output::ready(kind));
        }
    } else if class.eq_ignore_ascii_case("Sound") {
        let Some(file) = assets::field(call, actor, b"File")? else {
            return Ok(Output::ready(None));
        };
        let Some(sound_path) = resolve(call, actor, &file)? else {
            return Ok(Output::ready(None));
        };
        Kind::Sound { sound_path }
    } else if ["BitmapText", "RollingNumbers", "DeviceList", "InputList"]
        .iter()
        .any(|name| class.eq_ignore_ascii_case(name))
    {
        let Some((font_name, font_path)) = text::font(call, actor)? else {
            return Ok(Output::ready(None));
        };
        if class.eq_ignore_ascii_case("DeviceList") || class.eq_ignore_ascii_case("InputList") {
            Kind::BitmapText {
                font_name,
                font_path,
                text: crate::input_status_actor_text(class)
                    .unwrap_or_default()
                    .into(),
                stroke_color: None,
                attributes: Arc::from([]),
                text_changes: Arc::from([]),
                text_changes_in_seconds: false,
            }
        } else {
            let startup = get(call, actor, b"__songlua_startup_text")?;
            let startup = initial_state::value_text(call, startup)?;
            // Native Option::or evaluates the authored Text lookup even when
            // the earlier startup value is present.
            let authored = assets::field(call, actor, b"Text")?;
            Kind::BitmapText {
                font_name,
                font_path,
                text: startup.or(authored).unwrap_or_default().into(),
                stroke_color: text::stroke(call, actor)?,
                attributes: text::attributes(call, actor)?,
                text_changes: Arc::from([]),
                text_changes_in_seconds: false,
            }
        }
    } else if class.eq_ignore_ascii_case("ActorMultiVertex") {
        let vertices = match meshes::vertices(call, actor)? {
            Some(vertices) => vertices,
            None if data.context.live => Arc::from([]),
            None => return Ok(Output::ready(None)),
        };
        let texture_path = if data.context.live {
            meshes::texture_path(call, actor)?
        } else if assets::field(call, actor, b"__songlua_aft_capture_name")?.is_some() {
            None
        } else if let Some(texture) = assets::field(call, actor, b"Texture")? {
            if data.aft_names.contains(&texture) {
                None
            } else {
                resolve(call, actor, &texture)?
            }
        } else {
            None
        };
        let texture_key = texture_path
            .as_ref()
            .map(|path| crate::lua_util::texture_path_key(path));
        let capture_name = framebuffers::capture_name(call, actor)?;
        let texture =
            assets::field(call, actor, b"Texture")?.filter(|name| data.aft_names.contains(name));
        Kind::ActorMultiVertex {
            vertices,
            texture_path,
            texture_key,
            capture_name: capture_name.or(texture),
        }
    } else if class.eq_ignore_ascii_case("Model") {
        return Ok(Output::Model(models::tap_model(call, actor)?));
    } else if class.eq_ignore_ascii_case("SongMeterDisplay") {
        let Some(meter) = song_meters::read(call, &data.store, actor)? else {
            return Ok(Output::ready(None));
        };
        Kind::SongMeterDisplay {
            stream_width: meter.stream_width,
            stream_state: meter.stream_state,
            music_length_seconds: data.context.music_length_seconds.max(0.),
        }
    } else if class.eq_ignore_ascii_case("GraphDisplay") {
        let graph = graphs::read(call, &data.store, actor)?;
        Kind::GraphDisplay {
            size: crate::lua_util::read_graph_display_size(data.initial, &data.context),
            body_values: graph.body_values,
            body_state: graph.body_state,
            line_state: Box::new(graph.line_state),
        }
    } else if class.eq_ignore_ascii_case("Quad") {
        Kind::Quad
    } else {
        return Ok(Output::ready(None));
    };
    Ok(Output::ready(Some(kind)))
}

pub(in crate::rust_engine) fn typed<N, M>(kind: PlainKind) -> Kind<N, M, TextAttribute> {
    match kind {
        Kind::Actor => Kind::Actor,
        Kind::ActorFrame => Kind::ActorFrame,
        Kind::WrapperState => Kind::WrapperState,
        Kind::UpdateTracks {
            tracks,
            draw_frames,
        } => Kind::UpdateTracks {
            tracks,
            draw_frames,
        },
        Kind::ActorFrameTexture {
            capture_name,
            capture_size,
            alpha_buffer,
            depth_buffer,
            float_buffer,
        } => Kind::ActorFrameTexture {
            capture_name,
            capture_size,
            alpha_buffer,
            depth_buffer,
            float_buffer,
        },
        Kind::ActorProxy { target } => Kind::ActorProxy { target },
        Kind::AftSprite { capture_name } => Kind::AftSprite { capture_name },
        Kind::Sprite {
            texture_path,
            texture_key,
            states,
            textures,
        } => Kind::Sprite {
            texture_path,
            texture_key,
            states,
            textures,
        },
        Kind::Sound { sound_path } => Kind::Sound { sound_path },
        Kind::BitmapText {
            font_name,
            font_path,
            text,
            text_changes,
            text_changes_in_seconds,
            stroke_color,
            attributes,
        } => Kind::BitmapText {
            font_name,
            font_path,
            text,
            text_changes,
            text_changes_in_seconds,
            stroke_color,
            attributes,
        },
        Kind::ActorMultiVertex {
            vertices,
            texture_path,
            texture_key,
            capture_name,
        } => Kind::ActorMultiVertex {
            vertices,
            texture_path,
            texture_key,
            capture_name,
        },
        Kind::SongMeterDisplay {
            stream_width,
            stream_state,
            music_length_seconds,
        } => Kind::SongMeterDisplay {
            stream_width,
            stream_state,
            music_length_seconds,
        },
        Kind::GraphDisplay {
            size,
            body_values,
            body_state,
            line_state,
        } => Kind::GraphDisplay {
            size,
            body_values,
            body_state,
            line_state,
        },
        Kind::Quad => Kind::Quad,
        Kind::Model { .. } | Kind::NoteskinActor { .. } => {
            unreachable!("model resources are loaded by the runtime host")
        }
    }
}

//! The production compiler's authored file, ownership, Init and attach boundary.
use super::super::song_layers::{Entry, SongLayerPlan};
use super::*;

#[derive(Clone)]
struct Load {
    store: Shared,
    scene: u64,
    plan: SongLayerPlan,
}
impl Actors {
    pub(in crate::rust_engine) fn song_initial_states(
        &self,
        screen: ActorScene,
    ) -> Option<super::super::song_layers::SongInitialStates> {
        self.root(screen)?;
        self.store
            .lock()
            .unwrap()
            .scenes
            .get(&screen.id)?
            .initial_states
            .clone()
    }

    pub(in crate::rust_engine) fn initialize_song_layers(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
        plan: &SongLayerPlan,
    ) -> Result<Option<Value>, Error> {
        if self.root(screen).is_none() {
            return Ok(None);
        }
        for (key, source, name) in [
            (
                "layer_upper_left",
                UPPER_LEFT,
                b"@theme:/BackgroundEffects/UpperLeft.lua".as_slice(),
            ),
            (
                "layer_compose",
                COMPOSE,
                b"=song layer command merge".as_slice(),
            ),
            (
                "layer_wrap",
                WRAP,
                b"@theme:/BackgroundEffects/UpperLeft.lua".as_slice(),
            ),
        ] {
            let key_value = vm.try_intern(key.as_bytes())?;
            if vm.raw_table_get(self.helpers, key_value)? == Value::Nil {
                let code = compile_named(source, name)?;
                let function = vm.execute(&code)?[0];
                super::super::put(vm, self.helpers, key, function)?;
            }
        }
        let function = vm.new_host_function_with_data(
            load,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Load {
                store: self.store.clone(),
                scene: screen.id,
                plan: plan.clone(),
            },
        )?;
        Ok(Some(vm.call(function, &[])?[0]))
    }
}
fn load(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Load>().unwrap().clone();
    if data.plan.live
        != data
            .store
            .lock()
            .unwrap()
            .clock
            .live
            .load(std::sync::atomic::Ordering::Relaxed)
    {
        return Err(call.error(b"song layer plan and runtime modes differ"));
    }
    let top = data.store.lock().unwrap().scenes[&data.scene].root.unwrap();
    let first = data.store.lock().unwrap().next;
    let result = load_layers(call, &data, top);
    // Constructors can leave implicit templates or throw after publishing an
    // actor. Transfer every new owner even when execution/Init failed.
    let created = data
        .store
        .lock()
        .unwrap()
        .scenes
        .keys()
        .copied()
        .filter(|id| *id > first)
        .collect::<Vec<_>>();
    for scene in created {
        gameplay_theme::adopt_owned_scene(&data.store, data.scene, scene);
    }
    let roots: Vec<_> = match &result {
        Ok(value) => vec![*value],
        Err(error) => error.value().into_iter().collect(),
    };
    call.with_roots(&roots, |call| {
        lifecycle::invalidate_plans(call, &data.store)?;
        call.push(result?)
    })
}
fn load_layers(call: &mut HostCall<'_>, data: &Load, top: TableId) -> Result<Value, Error> {
    let globals = table(call, helper(call, 5)?)?;
    raw_set(
        call,
        globals,
        "__songlua_screen_loading",
        Value::Boolean(data.plan.screen_loading),
    )?;
    let roots = call.try_new_table()?;
    call.with_roots(&[Value::Table(roots)], |call| {
        // An active screen owns the scalar loader results too. Retirement keeps
        // this private edge as part of the scene graph, without an extra pin.
        let state = call.try_new_table()?;
        call.raw_table_set(state, Value::Number(1.), Value::Table(roots))?;
        if let Some(previous) = call.table_host_state(top)? {
            call.raw_table_set(state, Value::Number(2.), Value::Table(previous))?;
        }
        call.set_table_host_state(top, Some(state))?;
        let retained = call.try_new_table()?;
        call.raw_table_set(state, Value::Number(3.), Value::Table(retained))?;
        data.store.lock().unwrap().scenes.get_mut(&data.scene).unwrap().initial_states = Some(Default::default());
        data.store.lock().unwrap().scenes.get_mut(&data.scene).unwrap().song_session = Some(song_activation::Session { roots, ready: false, activated: false, discovery_started: false, locals: None, queued: HashMap::new(), messages: None });
        capture_screen(call, data, retained, globals)?;
        for (index, entry) in data.plan.entries.iter().enumerate() {
            let result = execute(call, entry);
            let definition = match result {
                Ok(value) if !data.plan.live || matches!(value, Value::Table(_)) => value,
                Ok(_) => {
                    log::warn!("Failed to load song actor '{}': must return a table; using native dummy Actor", entry.path.display());
                    Value::Table(offline::dummy(call, &data.store, "Actor")?)
                }
                Err(error) if data.plan.live => {
                    log::warn!("Failed to load song actor '{}': {error}; using native dummy Actor", entry.path.display());
                    Value::Table(offline::dummy(call, &data.store, "Actor")?)
                }
                Err(error) => return Err(call.error(format!("failed to execute '{}': {error}", entry.path.display()).as_bytes())),
            };
            let value = call.with_roots(&[definition], |call| initialize_layer(call, data, entry, index, definition, retained))?;
            call.raw_table_set(roots, Value::Number((index+1) as f64), value)?;
        }
        data.store.lock().unwrap().scenes.get_mut(&data.scene).unwrap().song_session.as_mut().unwrap().ready = true;
        Ok(Value::Table(roots))
    })
}
fn execute(call: &mut HostCall<'_>, entry: &Entry) -> Result<Value, Error> {
    let path = call.try_intern(entry.path.to_string_lossy().as_bytes())?;
    call.with_roots(&[path], |call| {
        let source = call.try_intern(entry.source.to_string_lossy().as_bytes())?;
        let loader = native_children::helper_function(call, b"source_loader")?;
        let function = call.call(loader, &[path, Value::Nil, source])?[0];
        Ok(call
            .call(function, &[])?
            .first()
            .copied()
            .unwrap_or(Value::Nil))
    })
}
fn initialize_layer(
    call: &mut HostCall<'_>,
    data: &Load,
    entry: &Entry,
    index: usize,
    value: Value,
    retained: TableId,
) -> Result<Value, Error> {
    let Value::Table(actor) = value else {
        return Ok(value);
    };
    let actor = if let Some(color) = entry.color {
        upper_left(call, actor, color)?
    } else {
        actor
    };
    call.with_roots(&[Value::Table(actor)], |call| {
        let scene = materialize(call, &data.store, actor, Materialization::Construct)?;
        let actor = data.store.lock().unwrap().scenes[&scene].root.unwrap();
        gameplay_theme::adopt_owned_scene(&data.store, data.scene, scene);
        #[cfg(feature = "test-support")]
        {
            let path = call.try_intern((index + 1).to_string().as_bytes())?;
            raw_set(call, actor, "__songlua_message_path", path)?;
        }
        #[cfg(not(feature = "test-support"))]
        let _ = index;
        let globals = table(call, helper(call, 5)?)?;
        let screen = sprites::field(call, globals, "__songlua_top_screen")?;
        let screen = table(call, screen)?;
        let children = sprites::field(call, screen, "__songlua_children")?;
        let children = table(call, children)?;
        let parent = if entry.background {
            None
        } else {
            {
                let parent = sprites::field(call, children, "SongForeground")?;
                Some(table(call, parent)?)
            }
        };
        if let Some(beat) = entry.beat {
            let key = if entry.background {
                "__songlua_background_start_beat"
            } else {
                "__songlua_foreground_start_beat"
            };
            raw_set(call, actor, key, Value::Number(f64::from(beat)))?;
            raw_set(call, actor, "__songlua_defer_on", Value::Boolean(true))?;
            raw_set(call, actor, "__songlua_live_inactive", Value::Boolean(true))?;
        }
        if let Some(parent) = parent {
            parent_scene(call, &data.store, actor, Value::Table(parent), false)?;
        }
        collect_initial(call, data, retained, Value::Table(actor))?;
        prepare_init(&data.store);
        initialize(call, &data.store, actor).map_err(|error| {
            call.error(
                format!(
                    "failed to run actor init commands for '{}': {error}",
                    entry.path.display()
                )
                .as_bytes(),
            )
        })?;
        if let Some(parent) = parent {
            // Init may change the activation flag. Read its actual post-Init value.
            let beat = get(call, actor, b"__songlua_foreground_start_beat")?;
            if beat != Value::Nil {
                sprites::number(call, beat)?;
                if let Some(name) = &entry.name {
                    let value = call.try_intern(name.as_bytes())?;
                    if get(call, actor, b"__songlua_load_name")? != Value::Nil {
                        raw_set(call, actor, "__songlua_load_name", value)?;
                    }
                    raw_set(call, actor, "__songlua_native_name", value)?;
                    raw_set(call, actor, "Name", value)?;
                    data.store
                        .lock()
                        .unwrap()
                        .actors
                        .get_mut(&actor)
                        .unwrap()
                        .state
                        .name = name.as_bytes().to_vec();
                }
                let visible = sprites::field(call, actor, "visible")?;
                call.call(visible, &[Value::Table(actor), Value::Boolean(false)])?;
            }
            parent_scene(call, &data.store, actor, Value::Table(parent), true)?;
        }
        Ok(Value::Table(actor))
    })
}
fn upper_left(call: &mut HostCall<'_>, actor: TableId, color: [f32; 4]) -> Result<TableId, Error> {
    let colors = call.try_new_table()?;
    for (i, value) in color.into_iter().enumerate() {
        call.raw_table_set(
            colors,
            Value::Number((i + 1) as f64),
            Value::Number(f64::from(value)),
        )?;
    }
    let factory = native_children::helper_function(call, b"layer_upper_left")?;
    let commands = call.call(factory, &[Value::Table(colors)])?[0];
    call.with_roots(&[commands], |call| {
        let commands = table(call, commands)?;
        for name in ["OnCommand", "GainFocusCommand", "LoseFocusCommand"] {
            let key = call.try_intern(name.as_bytes())?;
            let second = call.raw_table_get(commands, key)?;
            let first = call.raw_table_get(actor, key)?;
            let value = if matches!(first, Value::Function(_) | Value::Native(_)) {
                let compose = native_children::helper_function(call, b"layer_compose")?;
                call.call(compose, &[first, second])?[0]
            } else {
                second
            };
            call.table_set(Value::Table(actor), key, value)?;
        }
        let wrap = native_children::helper_function(call, b"layer_wrap")?;
        let value = call.call(wrap, &[Value::Table(actor)])?[0];
        table(call, value)
    })
}
const UPPER_LEFT: &[u8] = br#"
return function(color)
    return {
        OnCommand = function(self)
            self:diffuse(color):effectclock('music')
            if self.GetTexture then self:GetTexture():rate(self:GetParent():GetUpdateRate()) end
        end,
        GainFocusCommand = function(self) self:play() end,
        LoseFocusCommand = function(self) self:pause() end,
    }
end
"#;
const COMPOSE: &[u8] =
    b"return function(first, second) return function(...) first(...); return second(...) end end";
const WRAP: &[u8] = b"return function(child)\n\n\nreturn Def.ActorFrame{child}\nend";

fn raw_set(call: &mut HostCall<'_>, actor: TableId, name: &str, value: Value) -> Result<(), Error> {
    let key = call.try_intern(name.as_bytes())?;
    call.raw_table_set(actor, key, value)
}

fn save_initial(
    call: &mut HostCall<'_>,
    data: &Load,
    retained: TableId,
    actor: TableId,
    screen_layer: bool,
) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        let state = initial_state::read(call, &data.store, actor)?;
        call.raw_table_set(retained, Value::Table(actor), Value::Boolean(true))?;
        let mut guard = data.store.lock().unwrap();
        let initial = guard
            .scenes
            .get_mut(&data.scene)
            .unwrap()
            .initial_states
            .as_mut()
            .unwrap();
        if screen_layer {
            initial.screen_layers.insert(actor, state);
        } else {
            initial.actors.insert(actor, state);
        }
        Ok(())
    })
}
fn collect_initial(
    call: &mut HostCall<'_>,
    data: &Load,
    retained: TableId,
    value: Value,
) -> Result<(), Error> {
    let Value::Table(actor) = value else {
        return Ok(());
    };
    call.with_roots(&[value], |call| {
        let class = sprites::field(call, actor, "__songlua_actor_type")?;
        if initial_state::value_text(call, class)?.is_some() {
            save_initial(call, data, retained, actor, false)?;
        }
        // The compiler walks raw sequence slots: aliases are visited again,
        // holes stop the walk, and wrappers are not sequence children.
        let mut index = 1;
        loop {
            let value = call.raw_table_get(actor, Value::Number(index as f64))?;
            if value == Value::Nil {
                break;
            }
            collect_initial(call, data, retained, value)?;
            index += 1;
        }
        Ok(())
    })
}
fn capture_screen(
    call: &mut HostCall<'_>,
    data: &Load,
    retained: TableId,
    globals: TableId,
) -> Result<(), Error> {
    let screen = sprites::field(call, globals, "__songlua_top_screen")?;
    call.with_roots(&[screen], |call| {
        let children = sprites::field(call, table(call, screen)?, "__songlua_children")?;
        call.with_roots(&[children], |call| {
            let children = table(call, children)?;
            for name in ["Underlay", "Overlay", "SongBackground", "In"] {
                let actor = sprites::field(call, children, name)?;
                if actor != Value::Nil {
                    save_initial(call, data, retained, table(call, actor)?, true)?;
                }
            }
            Ok(())
        })
    })?;
    for name in [
        "__songlua_top_screen_player_1",
        "__songlua_top_screen_player_2",
    ] {
        let actor = sprites::field(call, globals, name)?;
        table(call, actor)?;
        collect_initial(call, data, retained, actor)?;
    }
    Ok(())
}

//! Existing text, mask and sprite properties published by preparation setters.
use super::*;
use crate::{SongLuaOverlayStateDelta as Delta, SongLuaOverlayUpdateTarget as Target};

pub(crate) const TARGETS: &[Target] = &[
    Target::Uppercase,
    Target::MaskSource,
    Target::MaskDest,
    Target::RainbowScroll,
    Target::TextJitter,
    Target::TextDistortion,
    Target::TextGlowMode,
    Target::MultAttrsWithDiffuse,
    Target::SpriteAnimate,
    Target::SpriteLoop,
    Target::SpritePlaybackRate,
    Target::SpriteStateDelay,
    Target::VertSpacing,
    Target::WrapWidthPixels,
    Target::MaxWidth,
    Target::MaxHeight,
    Target::MaxWPreZoom,
    Target::MaxHPreZoom,
    Target::MaxDimensionUsesZoom,
    Target::TextureWrapping,
    Target::TexcoordOffset,
    Target::CustomTextureRect,
    Target::TexcoordVelocity,
];

// Each call represents one successful setter write, including equal values.
// Compound setters call this in native order instead of comparing snapshots.
pub(super) fn record(call: &mut HostCall<'_>, store: &Shared, id: TableId, key: &str) {
    let delta = {
        let guard = store.lock().unwrap();
        let state = &guard.actors[&id].state.render;
        let mut delta = Delta::default();
        match key {
            "uppercase" => delta.uppercase = Some(state.uppercase),
            "mask_source" => delta.mask_source = Some(state.mask_source),
            "mask_dest" => delta.mask_dest = Some(state.mask_dest),
            "rainbow_scroll" => delta.rainbow_scroll = Some(state.rainbow_scroll),
            "text_jitter" => delta.text_jitter = Some(state.text_jitter),
            "text_distortion" => delta.text_distortion = Some(state.text_distortion),
            "text_glow_mode" => delta.text_glow_mode = Some(state.text_glow_mode),
            "mult_attrs_with_diffuse" => {
                delta.mult_attrs_with_diffuse = Some(state.mult_attrs_with_diffuse)
            }
            "sprite_animate" => delta.sprite_animate = Some(state.sprite_animate),
            "sprite_loop" => delta.sprite_loop = Some(state.sprite_loop),
            "sprite_playback_rate" => delta.sprite_playback_rate = Some(state.sprite_playback_rate),
            "sprite_state_delay" => delta.sprite_state_delay = Some(state.sprite_state_delay),
            "vert_spacing" => delta.vert_spacing = state.vert_spacing,
            "wrap_width_pixels" => delta.wrap_width_pixels = state.wrap_width_pixels,
            "max_width" => delta.max_width = state.max_width,
            "max_height" => delta.max_height = state.max_height,
            "max_w_pre_zoom" => delta.max_w_pre_zoom = Some(state.max_w_pre_zoom),
            "max_h_pre_zoom" => delta.max_h_pre_zoom = Some(state.max_h_pre_zoom),
            "max_dimension_uses_zoom" => {
                delta.max_dimension_uses_zoom = Some(state.max_dimension_uses_zoom)
            }
            "texture_wrapping" => delta.texture_wrapping = Some(state.texture_wrapping),
            "texcoord_offset" => delta.texcoord_offset = state.texcoord_offset,
            "custom_texture_rect" => delta.custom_texture_rect = state.custom_texture_rect,
            "texcoord_velocity" => delta.texcoord_velocity = state.texcoord_velocity,
            _ => unreachable!("unknown captured media property"),
        }
        delta
    };
    capture::write(call, store, id, delta, false);
}

pub(super) fn delta(call: &mut HostCall<'_>, store: &Shared, id: TableId, delta: &Delta) {
    if song_immediate::context(&store.lock().unwrap(), id).is_none() {
        return;
    }
    let mut state = crate::SongLuaOverlayState::default();
    crate::apply_overlay_delta(&mut state, delta);
    for &target in TARGETS {
        if delta.has_update_target(target) {
            song_properties::record(
                call,
                store,
                id,
                target,
                crate::perframe::overlay_state_update_value(&state, target),
            );
        }
    }
}

//! Chronological message provenance for properties owned by the tween queue.
use super::song_replay::raw_set;
use super::*;
use crate::{SongLuaStatefulMessageCapture, SongLuaStatefulMessageWrite};
use std::collections::{BTreeMap, BTreeSet};

pub(super) struct Capture {
    // Identities are owned by this song session's scene, never by this map.
    pub(super) indices: HashMap<TableId, usize>,
    pub(super) immediate: song_immediate::Capture,
    writes: BTreeMap<String, Vec<SongLuaStatefulMessageWrite>>,
}

impl Capture {
    pub(super) fn new(indices: impl IntoIterator<Item = (TableId, usize)>) -> Self {
        Self {
            indices: indices.into_iter().collect(),
            immediate: Default::default(),
            writes: BTreeMap::new(),
        }
    }

    pub(super) fn write(&mut self, message: String, write: SongLuaStatefulMessageWrite) {
        // A pose-only message write still establishes this actor's place in
        // the frame buffer if an immediate property follows later.
        self.immediate.touch(write.overlay_index);
        self.writes.entry(message).or_default().push(write);
    }

    pub(super) fn output(&self) -> Vec<SongLuaStatefulMessageCapture> {
        self.writes
            .iter()
            .map(|(message, writes)| {
                let mut targets: BTreeMap<usize, BTreeSet<_>> = BTreeMap::new();
                for write in writes {
                    targets
                        .entry(write.overlay_index)
                        .or_default()
                        .insert(write.target);
                }
                SongLuaStatefulMessageCapture {
                    message: message.clone(),
                    overlay_targets: targets
                        .into_iter()
                        .map(|(index, targets)| (index, targets.into_iter().collect()))
                        .collect(),
                    writes: writes.clone(),
                }
            })
            .collect()
    }
}

impl Actors {
    pub(in crate::rust_engine) fn song_replay_messages(
        &self,
        screen: ActorScene,
    ) -> Option<Vec<SongLuaStatefulMessageCapture>> {
        let store = self.store.lock().unwrap();
        if store.replay_frame?.0 != screen.id {
            return None;
        }
        Some(
            store
                .scenes
                .get(&screen.id)?
                .song_session
                .as_ref()?
                .messages
                .as_ref()?
                .output(),
        )
    }

    pub(in crate::rust_engine) fn song_replay_tween_messages(
        &self,
        screen: ActorScene,
    ) -> Option<Vec<SongLuaStatefulMessageCapture>> {
        let store = self.store.lock().unwrap();
        if store.replay_frame?.0 != screen.id {
            return None;
        }
        Some(
            store
                .scenes
                .get(&screen.id)?
                .song_session
                .as_ref()?
                .messages
                .as_ref()?
                .output()
                .into_iter()
                .filter_map(|mut capture| {
                    capture
                        .writes
                        .retain(|w| crate::tween_pose::TARGETS.contains(&w.target));
                    for (_, targets) in &mut capture.overlay_targets {
                        targets.retain(|t| crate::tween_pose::TARGETS.contains(t));
                    }
                    capture.overlay_targets.retain(|(_, t)| !t.is_empty());
                    (!capture.writes.is_empty()).then_some(capture)
                })
                .collect(),
        )
    }
}

pub(super) fn timing(
    call: &mut HostCall<'_>,
    actor: TableId,
    duration: f32,
    easing: Option<&str>,
) -> Result<(), Error> {
    raw_set(
        call,
        actor,
        "__songlua_capture_duration",
        Value::Number(f64::from(duration)),
    )?;
    let easing = easing
        .map(|text| call.try_intern(text.as_bytes()))
        .transpose()?
        .unwrap_or(Value::Nil);
    raw_set(call, actor, "__songlua_capture_easing", easing)?;
    raw_set(call, actor, "__songlua_capture_opt1", Value::Nil)
}

pub(super) fn reset_timing(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let replaying = {
        let mut guard = store.lock().unwrap();
        let replay = guard.actors.get_mut(&actor).unwrap().replay.as_mut();
        if let Some(replay) = replay {
            replay.capture_open = false;
            true
        } else {
            false
        }
    };
    if replaying {
        timing(call, actor, 0., None)?;
    }
    Ok(())
}

pub(super) fn hurry_timing(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    factor: f32,
) -> Result<(), Error> {
    let (replaying, flush, children) = {
        let mut guard = store.lock().unwrap();
        if guard.replay_frame.is_none() {
            return Ok(());
        }
        let actor = guard.actors.get_mut(&actor).unwrap();
        let flush = actor
            .replay
            .as_mut()
            .is_some_and(|r| std::mem::take(&mut r.capture_open));
        (actor.replay.is_some(), flush, actor.children.clone())
    };
    // Hurry flushes an open command block before scaling the retained queue.
    // Later pose writes still change that queue, but have no active block timing.
    if flush {
        timing(call, actor, 0., None)?;
    }
    if replaying {
        let duration = get(call, actor, b"__songlua_capture_duration")?;
        if let Some(duration) = float_scalar(call, duration, true) {
            raw_set(
                call,
                actor,
                "__songlua_capture_duration",
                Value::Number(f64::from(duration * factor)),
            )?;
        }
    }
    for child in children {
        hurry_timing(call, store, child, factor)?;
    }
    Ok(())
}

pub(super) fn record(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    delta: &crate::SongLuaOverlayStateDelta,
) {
    if !crate::tween_pose::TARGETS
        .iter()
        .any(|&target| delta.has_update_target(target))
    {
        return;
    }
    let context = {
        let guard = store.lock().unwrap();
        if guard.clock.live.load(std::sync::atomic::Ordering::Relaxed) {
            return;
        }
        let Some(message) = guard.active_message.as_ref() else {
            return;
        };
        let Some((owner, _)) = guard.replay_frame else {
            return;
        };
        if guard.retired_scenes.contains_key(&owner) {
            return;
        }
        let Some(capture) = guard
            .scenes
            .get(&owner)
            .and_then(|s| s.song_session.as_ref())
            .and_then(|s| s.messages.as_ref())
        else {
            return;
        };
        let Some(&index) = capture.indices.get(&id) else {
            return;
        };
        (owner, index, message.clone())
    };
    // Read the same per-write clock and command metadata as preparation. These
    // accesses can enter Lua, so no actor metadata borrow crosses them.
    let beat = effects::values(call, false).map_or(0., |values| values[0]);
    let duration = get(call, id, b"__songlua_capture_duration")
        .ok()
        .and_then(|v| float_scalar(call, v, true))
        .unwrap_or(0.);
    let easing = get(call, id, b"__songlua_capture_easing")
        .ok()
        .and_then(|v| render::text(call, v).map(str::to_owned));
    let opt1 = get(call, id, b"__songlua_capture_opt1")
        .ok()
        .and_then(|v| float_scalar(call, v, true));
    let mut guard = store.lock().unwrap();
    let Some(actor) = guard.actors.get(&id) else {
        return;
    };
    let delay = actor.capture.as_ref().map_or_else(
        || lifecycle::message_delay(actor, duration),
        |capture| capture.cursor().max(0.),
    );
    if guard.retired_scenes.contains_key(&context.0) {
        return;
    }
    let Some(capture) = guard
        .scenes
        .get_mut(&context.0)
        .and_then(|s| s.song_session.as_mut())
        .and_then(|s| s.messages.as_mut())
    else {
        return;
    };
    let mut state = crate::SongLuaOverlayState::default();
    crate::apply_overlay_delta(&mut state, delta);
    let pose = TweenPose::from(state);
    for target in crate::tween_pose::TARGETS {
        if delta.has_update_target(target) {
            capture.write(
                context.2.clone(),
                SongLuaStatefulMessageWrite {
                    overlay_index: context.1,
                    beat,
                    target,
                    value: pose.get(target),
                    delay_seconds: delay,
                    duration_seconds: duration,
                    easing: easing.clone(),
                    opt1,
                },
            );
        }
    }
}

//! SongMeterDisplay's stream construction, width and owned render state.
use super::*;
use sprites::{field, set};

#[derive(Clone, Debug)]
pub struct SongMeterDisplay {
    pub stream_width: f32,
    pub stream_state: crate::SongLuaOverlayState,
}

pub(super) fn install(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let methods = native_children::helper_function(call, b"meter_methods")?;
    let methods = table(call, methods)?;
    let bound = get(call, actor, b"__songlua_bound_methods")?;
    let bound = table(call, bound)?;
    for name in ["Load", "SetStreamWidth", "GetStreamWidth"] {
        let method = get(call, methods, name.as_bytes())?;
        let captures = [
            call.captures()[0],
            call.captures()[1],
            Value::Table(actor),
            method,
        ];
        let function = call.new_host_function_with_data(invoke_bound, &captures, name)?;
        set(call, bound, name, function)?;
    }
    Ok(())
}

pub(super) fn initialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
) -> Result<(), Error> {
    let width = field(call, actor, "StreamWidth")?;
    let width = float_scalar(call, width, false).unwrap_or(0.0);
    set(
        call,
        actor,
        "__songlua_stream_width",
        Value::Number(width as f64),
    )?;
    let stream = field(call, actor, "Stream")?;
    if stream == Value::Nil {
        return Ok(());
    }
    let stream = table(call, stream)?;
    if store.lock().unwrap().actors[&actor].offline_instance {
        courses::attach(call, store, scene, stream)?;
        let name = call.try_intern(b"Stream")?;
        set(call, stream, "Name", name)?;
        native_children::adopt(call, store, stream, actor)?;
        return native_children::insert(call, actor, "Stream", Value::Table(stream));
    }
    let node = call.call(helper(call, 2)?, &[Value::Table(stream)])?[0];
    let first = store.lock().unwrap().scenes[&scene].actors.len();
    let stream = call.with_roots(&[node], |call| {
        build(
            call,
            store,
            scene,
            table(call, node)?,
            Some(actor),
            false,
            false,
        )?
        .ok_or_else(|| call.error(b"SongMeterDisplay Stream must load an actor"))
    })?;
    {
        let mut store = store.lock().unwrap();
        // Unlike GraphDisplay's dummy children, this declaration subscribes
        // when its own Init traversal begins, after its meter's Init command.
        let deferred: HashSet<_> = store.scenes[&scene].actors[first..]
            .iter()
            .copied()
            .filter(|id| {
                !matches!(
                    store.actors[id].state.class,
                    "GraphDisplayBody" | "GraphDisplayLine"
                )
            })
            .collect();
        store.actor_order.retain(|id| !deferred.contains(id));
        for id in deferred {
            store.actors.get_mut(&id).unwrap().registered = false;
        }
        let stream = store.actors.get_mut(&stream).unwrap();
        stream.load_name = Some(b"Stream".to_vec());
        stream.state.name = b"Stream".to_vec();
    }
    let name = call.try_intern(b"Stream")?;
    set(call, stream, "Name", name)?;
    native_children::adopt(call, store, stream, actor)?;
    set(call, actor, "Stream", Value::Table(stream))?;
    native_children::insert(call, actor, "Stream", Value::Table(stream))
}

pub(super) fn stream(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<Option<TableId>, Error> {
    if store.lock().unwrap().actors[&actor].state.class != "SongMeterDisplay" {
        return Ok(None);
    }
    if !assets::field(call, actor, b"__songlua_actor_type")?
        .is_some_and(|s| s.eq_ignore_ascii_case("SongMeterDisplay"))
    {
        return Ok(None);
    }
    let map = native_children::named_children(call, actor)?;
    call.with_roots(&[map], |call| {
        let stream = field(call, table(call, map)?, "Stream")?;
        if stream == Value::Nil {
            return Ok(None);
        }
        let stream = table(call, stream)?;
        if !store.lock().unwrap().actors.contains_key(&stream) {
            native_children::group_members(call, stream)?;
        }
        native_children::adopt(call, store, stream, actor)?;
        Ok(Some(stream))
    })
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    match name {
        "Load" => return sprites::method(call, store, actor, name),
        "GetStreamWidth" => {
            let value = field(call, actor, "__songlua_stream_width")?;
            let width = if value == Value::Nil {
                0.0
            } else {
                sprites::number(call, value)? as f32
            };
            return call.push(Value::Number(width as f64));
        }
        _ => {
            if assets::field(call, actor, b"__songlua_actor_type")?
                .is_some_and(|s| s.eq_ignore_ascii_case("SongMeterDisplay"))
                && let Some(width) = float_scalar(call, arg(call, 1), false)
            {
                set(call, actor, "StreamWidth", Value::Number(width as f64))?;
                set(
                    call,
                    actor,
                    "__songlua_stream_width",
                    Value::Number(width as f64),
                )?;
            }
        }
    }
    call.push(Value::Table(actor))
}

pub(super) fn read(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<Option<SongMeterDisplay>, Error> {
    let width = field(call, actor, "__songlua_stream_width")?;
    let width = if width == Value::Nil {
        match field(call, actor, "StreamWidth") {
            Ok(width) => float_scalar(call, width, false).unwrap_or(0.0),
            Err(error) if error.kind() == ErrorKind::Runtime => 0.0,
            Err(error) => return Err(error),
        }
    } else {
        sprites::number(call, width)? as f32
    }
    .max(0.0);
    if width <= f32::EPSILON {
        return Ok(None);
    }
    let map = native_children::named_children(call, actor)?;
    call.with_roots(&[map], |call| {
        let stream = field(call, table(call, map)?, "Stream")?;
        if stream == Value::Nil {
            return Ok(None);
        }
        let stream = table(call, stream)?;
        let stream_state = native_children::state(call, store, stream)?;
        Ok(Some(SongMeterDisplay {
            stream_width: width,
            stream_state,
        }))
    })
}

//! Production tracked actor extraction; Lua access stays inside one host call.
use super::*;
use crate::{SongLuaCapturedActor, SongLuaTrackedActorTarget as Target};
use sprites::{field, set};

pub(in crate::rust_engine) struct Tracked {
    pub actor: SongLuaCapturedActor,
    pub target: Target,
}
#[derive(Clone)]
struct Read {
    store: Shared,
    scene: u64,
    output: Arc<Mutex<Vec<Tracked>>>,
}
impl Actors {
    pub(in crate::rust_engine) fn read_song_tracked_actors(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
    ) -> Result<(Value, Vec<Tracked>), Error> {
        let output = Arc::new(Mutex::new(Vec::new()));
        let function = vm.new_host_function_with_data(
            read,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Read {
                store: self.store.clone(),
                scene: screen.id,
                output: output.clone(),
            },
        )?;
        let values = vm.call(function, &[])?[0];
        let rows = std::mem::take(&mut *output.lock().unwrap());
        Ok((values, rows))
    }
}
fn optional_table(call: &HostCall<'_>, value: Value) -> Result<Option<TableId>, Error> {
    if value == Value::Nil {
        Ok(None)
    } else {
        table(call, value).map(Some)
    }
}
fn registry(call: &mut HostCall<'_>, actor: TableId) -> Result<TableId, Error> {
    let function = native_children::helper_function(call, b"native_registry")?;
    let value = call.call(function, &[Value::Table(actor)])?[0];
    table(call, value)
}
fn manual_hud(call: &mut HostCall<'_>, player: TableId) -> Result<bool, Error> {
    let value = field(call, player, "__songlua_children")?;
    let Some(children) = optional_table(call, value)? else {
        return Ok(false);
    };
    call.with_roots(&[value], |call| {
        for name in ["Judgment", "Combo"] {
            let value = field(call, children, name)?;
            let Some(child) = optional_table(call, value)? else {
                continue;
            };
            let present = call.with_roots(&[value], |call| {
                let value = field(call, child, "__songlua_manual_draw_state")?;
                Ok(optional_table(call, value)?.is_some())
            })?;
            if present {
                return Ok(true);
            }
        }
        Ok(false)
    })
}
fn push(
    call: &mut HostCall<'_>,
    data: &Read,
    batch: TableId,
    actor: TableId,
    target: Target,
) -> Result<(), Error> {
    // Pin the identity before any authored getter can detach it and collect.
    let index = call.raw_table_len(batch)? + 1;
    call.raw_table_set(batch, Value::Number(index as f64), Value::Table(actor))?;
    let state = if matches!(target, Target::Player(_)) {
        initial_state::read(call, &data.store, actor)?
    } else {
        let value = field(call, actor, "__songlua_manual_draw_state")?;
        if let Some(snapshot) = optional_table(call, value)? {
            call.with_roots(&[value], |call| {
                initial_state::read(call, &data.store, snapshot)
            })?
        } else {
            initial_state::read(call, &data.store, actor)?
        }
    };
    let manual_hud_draw = matches!(target, Target::Player(_)) && manual_hud(call, actor)?;
    data.output.lock().unwrap().push(Tracked {
        target,
        actor: SongLuaCapturedActor {
            initial_state: state,
            manual_hud_draw,
            ..Default::default()
        },
    });
    Ok(())
}
fn child(
    call: &mut HostCall<'_>,
    data: &Read,
    parent: TableId,
    name: &str,
) -> Result<TableId, Error> {
    let kind = assets::field(call, parent, b"__songlua_actor_type")?;
    let index = field(call, parent, "__songlua_player_index")?;
    if kind
        .as_deref()
        .is_some_and(|s| s.eq_ignore_ascii_case("PlayerActor"))
        && index != Value::Nil
    {
        let index = sprites::number(call, index)?;
        if index.fract() != 0. || !(0. ..crate::LUA_PLAYERS as f64).contains(&index) {
            return Err(call.error(b"tracked player index out of range"));
        }
        return player_parts::tracked_child(
            call,
            &data.store,
            data.scene,
            parent,
            index as usize,
            name,
        );
    }
    let top = kind
        .as_deref()
        .is_some_and(|s| s.eq_ignore_ascii_case("TopScreen"));
    let actor = if top {
        screen_parts::create(call, &data.store, data.scene, name)?
    } else {
        generated_players::dummy(call, &data.store, data.scene, "ChildActor", name, None)?
    };
    underlay::copy_tags(call, parent, actor)?;
    native_children::adopt(call, &data.store, actor, parent)?;
    if top {
        let value = call.try_intern(name.as_bytes())?;
        set(call, actor, "__songlua_top_screen_child_name", value)?;
    }
    Ok(actor)
}
fn read(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Read>().unwrap().clone();
    let batch = call.try_new_table()?;
    call.with_roots(&[Value::Table(batch)], |call| {
        let globals = table(call, helper(call, 5)?)?;
        let top = field(call, globals, "__songlua_top_screen")?;
        let top = table(call, top)?;
        call.with_roots(&[Value::Table(top)], |call| {
            let children = registry(call, top)?;
            call.with_roots(&[Value::Table(children)], |call| {
                let value = field(call, children, "SongForeground")?;
                let foreground = if let Some(actor) = optional_table(call, value)? {
                    actor
                } else {
                    let actor = child(call, &data, top, "SongForeground")?;
                    set(call, children, "SongForeground", Value::Table(actor))?;
                    actor
                };
                call.with_roots(&[Value::Table(foreground)], |call| {
                    // Native resolves both players before reading any of their state.
                    let p1 = field(call, globals, "__songlua_top_screen_player_1")?;
                    let p1 = table(call, p1)?;
                    call.with_roots(&[Value::Table(foreground), Value::Table(p1)], |call| {
                        let p2 = field(call, globals, "__songlua_top_screen_player_2")?;
                        let p2 = table(call, p2)?;
                        call.with_roots(&[Value::Table(p2)], |call| {
                            for (index, player) in [p1, p2].into_iter().enumerate() {
                                push(call, &data, batch, player, Target::Player(index))?;
                                let children = registry(call, player)?;
                                call.with_roots(&[Value::Table(children)], |call| {
                                    for (name, target) in [
                                        ("Judgment", Target::PlayerJudgment(index)),
                                        ("Combo", Target::PlayerCombo(index)),
                                    ] {
                                        let value = field(call, children, name)?;
                                        let actor =
                                            if let Some(actor) = optional_table(call, value)? {
                                                actor
                                            } else {
                                                child(call, &data, player, name)?
                                            };
                                        push(call, &data, batch, actor, target)?;
                                    }
                                    Ok(())
                                })?;
                            }
                            push(call, &data, batch, foreground, Target::SongForeground)?;
                            for (index, name) in ["Underlay", "Overlay", "SongBackground", "In"]
                                .into_iter()
                                .enumerate()
                            {
                                let value = field(call, children, name)?;
                                if let Some(actor) = optional_table(call, value)? {
                                    push(call, &data, batch, actor, Target::ScreenLayer(index))?;
                                }
                            }
                            call.push(Value::Table(batch))
                        })
                    })
                })
            })
        })
    })
}

//! Fallback pose publications and the compiler's sampled getter handoff.
use super::*;
use crate::{SongLuaOverlayUpdateTarget as Target, SongLuaOverlayUpdateValue as Update};

pub(super) fn supported(target: Target) -> bool {
    crate::tween_pose::TARGETS.contains(&target)
        || song_immediate::TARGETS.contains(&target)
        || song_properties::TARGETS.contains(&target)
        || song_media::TARGETS.contains(&target)
}
pub(super) fn mode(store: &Store, id: TableId) -> bool {
    song_immediate::context(store, id).is_some()
        && store.replay_clock.as_ref().is_some_and(|c| c.fallback(id))
}
pub(super) fn prior_position(store: &Store, id: TableId) -> Option<[f32; 3]> {
    if !store.replay_clock.as_ref()?.later(id) {
        return None;
    }
    let (owner, index) = song_immediate::context(store, id)?;
    store
        .scenes
        .get(&owner)?
        .song_session
        .as_ref()?
        .messages
        .as_ref()?
        .immediate
        .prior_positions
        .get(&index)
        .copied()
}
pub(super) fn record(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    delta: &crate::SongLuaOverlayStateDelta,
) -> bool {
    if !mode(&store.lock().unwrap(), id) {
        return false;
    }
    let mut state = crate::SongLuaOverlayState::default();
    crate::apply_overlay_delta(&mut state, delta);
    for target in crate::tween_pose::TARGETS {
        if !delta.has_update_target(target) {
            continue;
        }
        let value = crate::perframe::overlay_state_update_value(&state, target);
        let scheduled = song_properties::record_inner(call, store, id, target, value.clone());
        if scheduled == Some(false)
            && let Update::F32(value) = value
        {
            let axis = match target {
                Target::X => Some(0),
                Target::Y => Some(1),
                Target::Z => Some(2),
                Target::Aux => Some(3),
                _ => None,
            };
            if let Some(axis) = axis {
                let mut guard = store.lock().unwrap();
                let actor = guard.actors.get_mut(&id).unwrap();
                actor.current.set(target, &Update::F32(value));
                let current = actor.current;
                actor.preparation_getters.get_or_insert([
                    current.x,
                    current.y,
                    current.z,
                    current.aux,
                ])[axis] = value;
                if axis < 3 {
                    let (owner, index) = song_immediate::context(&guard, id).unwrap();
                    if let Some(position) = guard
                        .scenes
                        .get_mut(&owner)
                        .and_then(|scene| scene.song_session.as_mut())
                        .and_then(|session| session.messages.as_mut())
                        .and_then(|capture| capture.immediate.prior_positions.get_mut(&index))
                    {
                        position[axis] = value;
                    }
                }
            }
        }
    }
    true
}

pub(super) fn advance_position(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
) -> Result<(), Error> {
    let position = {
        let mut guard = store.lock().unwrap();
        if !mode(&guard, id) {
            return Ok(());
        }
        let (owner, index) = song_immediate::context(&guard, id).unwrap();
        let actor = &guard.actors[&id];
        let current = actor.current;
        let mut position =
            actor
                .preparation_getters
                .unwrap_or([current.x, current.y, current.z, current.aux]);
        let Some(frame) = guard.scenes[&owner]
            .song_session
            .as_ref()
            .unwrap()
            .messages
            .as_ref()
            .unwrap()
            .immediate
            .frames
            .get(&index)
        else {
            return Ok(());
        };
        let mut destinations = [None; 3];
        for update in &frame.scheduled {
            let axis = match update.target {
                Target::X => 0,
                Target::Y => 1,
                Target::Z => 2,
                _ => continue,
            };
            let Update::F32(to) = update.value else {
                continue;
            };
            let from = destinations[axis]
                .or(match update.initial_value {
                    Some(Update::F32(value)) => Some(value),
                    _ => None,
                })
                .unwrap_or(position[axis]);
            destinations[axis] = Some(to);
            if update.frame_advance + 1.0e-7 < update.delay_seconds {
                continue;
            }
            let factor = if update.duration_seconds <= f32::EPSILON {
                1.
            } else {
                ((update.frame_advance - update.delay_seconds) / update.duration_seconds)
                    .clamp(0., 1.)
            };
            let factor =
                crate::overlay_command_ease_factor(update.easing.as_deref(), factor, update.opt1);
            position[axis] = (to - from).mul_add(factor, from);
        }
        let actor = guard.actors.get_mut(&id).unwrap();
        actor.preparation_getters = Some(position);
        [actor.current.x, actor.current.y, actor.current.z] =
            [position[0], position[1], position[2]];
        position
    };
    for (key, value) in [
        "__songlua_current_x",
        "__songlua_current_y",
        "__songlua_current_z",
    ]
    .into_iter()
    .zip(position)
    {
        song_replay::raw_set(call, id, key, Value::Number(f64::from(value)))?;
    }
    Ok(())
}

fn scalar_key(target: Target) -> Option<&'static str> {
    Some(match target {
        Target::Aux => "aux",
        Target::X => "x",
        Target::Y => "y",
        Target::Z => "z",
        Target::Zoom => "zoom",
        Target::ZoomX => "zoom_x",
        Target::ZoomY => "zoom_y",
        Target::ZoomZ => "zoom_z",
        Target::RotationX => "rot_x_deg",
        Target::RotationY => "rot_y_deg",
        Target::RotationZ => "rot_z_deg",
        Target::SkewX => "skew_x",
        Target::SkewY => "skew_y",
        Target::CropLeft => "cropleft",
        Target::CropRight => "cropright",
        Target::CropTop => "croptop",
        Target::CropBottom => "cropbottom",
        Target::FadeLeft => "fadeleft",
        Target::FadeRight => "faderight",
        Target::FadeTop => "fadetop",
        Target::FadeBottom => "fadebottom",
        _ => return None,
    })
}

pub(super) fn set_getter(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    target: Target,
    value: &Update,
) -> Result<(), Error> {
    if matches!(
        target,
        Target::Zoom
            | Target::ZoomX
            | Target::ZoomY
            | Target::ZoomZ
            | Target::RotationX
            | Target::RotationY
            | Target::RotationZ
            | Target::SkewX
            | Target::SkewY
    ) {
        let key = call.try_intern(b"__songlua_player_index")?;
        let player = call.raw_table_get(id, key)?;
        let key = call.try_intern(b"__songlua_player_child_name")?;
        let child = call.raw_table_get(id, key)?;
        if player != Value::Nil && child == Value::Nil {
            return Ok(());
        }
    }
    let scalar = scalar_key(target);
    if !matches!(value,Update::F32(_) if scalar.is_some())
        && !matches!(
            (target, value),
            (Target::Diffuse, Update::Vec4(_)) | (_, Update::Quaternion(_))
        )
    {
        return Ok(());
    }
    {
        let mut guard = store.lock().unwrap();
        let fallback = mode(&guard, id);
        let actor = guard.actors.get_mut(&id).unwrap();
        let dest = *actor.getter_destination();
        let replay = actor.replay.get_or_insert_with(song_replay::State::default);
        let getters = replay.getters.get_or_insert(dest);
        if !matches!(target, Target::X | Target::Y | Target::Z | Target::Aux) {
            getters.set(target, value);
        }
        if fallback {
            actor.current.set(target, value);
            // Non-position samples replace the native raw destination. Relative
            // setters must read that sample even while a captured queue exists.
            if !matches!(target, Target::X | Target::Y | Target::Z | Target::Aux) {
                actor.destination_mut().set(target, value);
            }
        }
        if let Update::F32(v) = value {
            let axis = match target {
                Target::X => Some(0),
                Target::Y => Some(1),
                Target::Z => Some(2),
                Target::Aux => Some(3),
                _ => None,
            };
            if let Some(axis) = axis {
                let cur = actor.current;
                actor
                    .preparation_getters
                    .get_or_insert([cur.x, cur.y, cur.z, cur.aux])[axis] = *v;
            }
            match target {
                Target::RotationX => actor.state.rotation[0] = *v,
                Target::RotationY => actor.state.rotation[1] = *v,
                Target::RotationZ => actor.state.rotation[2] = *v,
                _ => {}
            }
        }
    }
    match value {
        Update::F32(value) => {
            let key = match target {
                Target::X => "__songlua_current_x".to_owned(),
                Target::Y => "__songlua_current_y".to_owned(),
                Target::Z => "__songlua_current_z".to_owned(),
                Target::Aux => "__songlua_aux".to_owned(),
                _ => format!("__songlua_state_{}", scalar.unwrap()),
            };
            song_replay::raw_set(call, id, &key, Value::Number(f64::from(*value)))?;
        }
        Update::Vec4(value) => {
            let value = sprites::vector_value(call, value)?;
            song_replay::raw_set(call, id, "__songlua_state_diffuse", value)?;
            song_replay::raw_set(call, id, "__songlua_diffuse", value)?;
        }
        Update::Quaternion(value) => {
            let value = sprites::vector_value(call, value)?;
            song_replay::raw_set(call, id, "__songlua_state_quaternion", value)?;
        }
        _ => {}
    }
    Ok(())
}

fn apply_getters(call: &mut HostCall<'_>) -> Result<(), Error> {
    let (store, values) = call
        .function_data::<(Shared, Vec<(TableId, Target, Update)>)>()
        .unwrap()
        .clone();
    for (id, target, value) in values {
        set_getter(call, &store, id, target, &value)?;
    }
    Ok(())
}

impl Actors {
    pub(in crate::rust_engine) fn set_song_replay_prior_positions(
        &self,
        screen: ActorScene,
        states: &[crate::SongLuaOverlayState],
    ) -> bool {
        let mut guard = self.store.lock().unwrap();
        if guard.replay_frame.map(|f| f.0) != Some(screen.id) {
            return false;
        }
        let Some(capture) = guard
            .scenes
            .get_mut(&screen.id)
            .and_then(|s| s.song_session.as_mut())
            .and_then(|s| s.messages.as_mut())
        else {
            return false;
        };
        let count = capture.indices.values().max().map_or(0, |i| i + 1);
        for (index, state) in states.iter().take(count).enumerate() {
            capture
                .immediate
                .prior_positions
                .insert(index, [state.x, state.y, state.z]);
        }
        true
    }
    pub(in crate::rust_engine) fn set_song_replay_pose_getters(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
        values: &[(usize, Target, Update)],
    ) -> Result<bool, Error> {
        let Some(values) = (|| {
            let guard = self.store.lock().unwrap();
            if guard.replay_frame?.0 != screen.id {
                return None;
            }
            let capture = guard
                .scenes
                .get(&screen.id)?
                .song_session
                .as_ref()?
                .messages
                .as_ref()?;
            values
                .iter()
                .map(|(index, target, value)| {
                    if !crate::tween_pose::TARGETS.contains(target) {
                        return None;
                    }
                    let id = capture
                        .indices
                        .iter()
                        .find_map(|(id, i)| (*i == *index).then_some(*id))?;
                    Some((id, *target, value.clone()))
                })
                .collect::<Option<Vec<_>>>()
        })() else {
            return Ok(false);
        };
        let mut captures = vec![Value::Table(self.registry), Value::Table(self.helpers)];
        captures.extend(values.iter().map(|(id, _, _)| Value::Table(*id)));
        let function =
            vm.new_host_function_with_data(apply_getters, &captures, (self.store.clone(), values))?;
        vm.call(function, &[])?;
        Ok(true)
    }
}

//! Scheduled renderer properties outside the native interpolated tween pose.
use super::*;
use crate::{SongLuaOverlayUpdateTarget as Target, SongLuaOverlayUpdateValue as Update};

pub(crate) const TARGETS: &[Target] = &[
    Target::ZBias,
    Target::DrawOrder,
    Target::DrawByZPosition,
    Target::Fov,
    Target::Vanishpoint,
    Target::Blend,
    Target::DepthTest,
    Target::DepthTestOnFail,
    Target::DepthWrite,
    Target::TextureFiltering,
];

pub(super) fn record(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    target: Target,
    value: Update,
) {
    capture::retain_render_update(store, id, target, &value, false);
    let _ = record_inner(call, store, id, target, value);
}

pub(super) fn record_inner(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    target: Target,
    value: Update,
) -> Option<bool> {
    song_immediate::context(&store.lock().unwrap(), id)?;
    let beat = effects::values(call, false).map_or(0., |values| values[0]);
    let duration = get(call, id, b"__songlua_capture_duration")
        .ok()
        .and_then(|v| float_scalar(call, v, true))
        .unwrap_or(0.)
        .max(0.);
    let easing = get(call, id, b"__songlua_capture_easing")
        .ok()
        .and_then(|v| render::text(call, v).map(str::to_owned));
    let opt1 = get(call, id, b"__songlua_capture_opt1")
        .ok()
        .and_then(|v| float_scalar(call, v, true));
    let mut guard = store.lock().unwrap();
    let (owner, index) = song_immediate::context(&guard, id)?;
    let actor = &guard.actors[&id];
    let mut delay = actor.capture.as_ref().map_or_else(
        || lifecycle::message_delay(actor, duration),
        |capture| capture.cursor().max(0.),
    );
    let (progress, frame_advance) = if let Some(publication) = guard
        .replay_clock
        .as_mut()
        .map(|clock| clock.publication(id))
    {
        delay = publication.cursor.unwrap_or(delay);
        (publication.progress, publication.advance)
    } else {
        (None, 0.)
    };
    let dispatch_seconds = guard.replay_dispatch.and_then(|scope| scope.seconds);
    let message = guard.active_message.clone();
    let capture = guard
        .scenes
        .get_mut(&owner)
        .unwrap()
        .song_session
        .as_mut()
        .unwrap()
        .messages
        .as_mut()
        .unwrap();
    if let Some(message) = message {
        capture.write(
            message,
            crate::SongLuaStatefulMessageWrite {
                overlay_index: index,
                beat,
                target,
                value: value.clone(),
                delay_seconds: delay,
                duration_seconds: duration,
                easing: easing.clone(),
                opt1,
            },
        );
    }
    let scheduled =
        (delay > f32::EPSILON || duration > f32::EPSILON || progress.is_some()).then(|| {
            super::super::SongReplayScheduledUpdate {
                progress,
                dispatch_seconds,
                frame_advance,
                initial_value: None,
                delay_seconds: delay,
                duration_seconds: duration,
                easing,
                opt1,
                target,
                value: value.clone(),
            }
        });
    let timed = scheduled.is_some();
    capture.immediate.record(index, target, value, scheduled);
    Some(timed)
}

//! Restore the compiler's chronological queue after speculative discovery.
use super::*;
use crate::{SongLuaOverlayState, rust_engine::SongStartupState};

// Before the first positive update, preparation getters still expose the
// exported frame-zero fields, while tween interpolation owns a different tail.
#[derive(Clone, Default)]
pub(super) struct State {
    pub(super) getters: Option<TweenPose>,
    pub(super) progress: Vec<Vec<[f32; 2]>>,
    pub(super) targets: u128,
    pub(super) capture_open: bool,
}

#[derive(Clone)]
struct Setup {
    store: Shared,
    scene: u64,
    overlays: Vec<(TableId, SongLuaOverlayState)>,
    startup: HashMap<TableId, SongStartupState>,
    spin: HashMap<TableId, [f32; 3]>,
}

impl Actors {
    pub(in crate::rust_engine) fn begin_song_replay(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
        overlays: &[(TableId, SongLuaOverlayState)],
        startup: &HashMap<TableId, SongStartupState>,
    ) -> Result<(), Error> {
        let invalid = {
            let store = self.store.lock().unwrap();
            if store.clock.live.load(std::sync::atomic::Ordering::Relaxed) {
                Some(b"song preparation replay is unavailable in live mode".as_slice())
            } else if store.playback {
                Some(b"song replay has already started".as_slice())
            } else if !store.scenes[&screen.id]
                .song_session
                .as_ref()
                .is_some_and(|session| session.activated && session.discovery_started)
            {
                Some(b"song replay requires startup discovery".as_slice())
            } else if overlays
                .iter()
                .map(|(id, _)| id)
                .chain(startup.keys())
                .any(|id| {
                    store
                        .actors
                        .get(id)
                        .is_none_or(|actor| actor.scene != screen.id)
                })
            {
                Some(b"song replay actor belongs to another scene".as_slice())
            } else {
                None
            }
        };
        if let Some(message) = invalid {
            return vm.with_native_stack(|stack| Err(stack.error(message)));
        }
        let spin = {
            let store = self.store.lock().unwrap();
            overlays
                .iter()
                .filter_map(|(id, _)| {
                    let actor = &store.actors[id];
                    actor.effects.spin_baked.then_some((
                        *id,
                        [
                            actor.current.rot_x_deg,
                            actor.current.rot_y_deg,
                            actor.current.rot_z_deg,
                        ],
                    ))
                })
                .collect()
        };
        self.restore_song_startup_locals(vm, screen)?;
        let mut captures = vec![Value::Table(self.registry), Value::Table(self.helpers)];
        captures.extend(overlays.iter().map(|(id, _)| Value::Table(*id)));
        captures.extend(startup.keys().map(|id| Value::Table(*id)));
        let function = vm.new_host_function_with_data(
            setup,
            &captures,
            Setup {
                store: self.store.clone(),
                scene: screen.id,
                overlays: overlays.to_vec(),
                startup: startup.clone(),
                spin,
            },
        )?;
        // General playback removes discovery queues. The saved Init/On queues
        // below are the only queues which may enter chronological preparation.
        self.begin_playback();
        vm.call(function, &[])?;
        let mut store = self.store.lock().unwrap();
        store.replay_frame = Some((screen.id, 0.));
        store
            .scenes
            .get_mut(&screen.id)
            .unwrap()
            .song_session
            .as_mut()
            .unwrap()
            .messages = Some(song_messages::Capture::new(
            overlays.iter().enumerate().map(|(i, (id, _))| (*id, i)),
        ));
        Ok(())
    }
}

fn setup(call: &mut HostCall<'_>) -> Result<(), Error> {
    let setup = call.function_data::<Setup>().unwrap().clone();
    for &(id, state) in &setup.overlays {
        for key in [
            "__songlua_capture_cursor",
            "__songlua_capture_duration",
            "__songlua_capture_tween_time_left",
        ] {
            raw_set(call, id, key, Value::Number(0.))?;
        }
        for key in [
            "__songlua_startup_queue_seconds",
            "__songlua_capture_easing",
            "__songlua_capture_opt1",
            "__songlua_capture_opt2",
            "__songlua_capture_block",
            "__songlua_capture_immediate_block",
        ] {
            raw_set(call, id, key, Value::Nil)?;
        }
        let blocks = call.try_new_table()?;
        raw_set(call, id, "__songlua_capture_blocks", Value::Table(blocks))?;
        let binding = get(call, id, b"__songlua_startup_sprite")?;
        if binding != Value::Nil {
            call.with_roots(&[binding], |call| {
                let binding = table(call, binding)?;
                for key in [
                    "Texture",
                    "Frames",
                    "__songlua_state_sprite_default_states",
                    "__songlua_state_sprite_texture_epoch",
                    "__songlua_state_sprite_frame_sheet",
                ] {
                    let value = get(call, binding, key.as_bytes())?;
                    raw_set(call, id, key, value)?;
                }
                Ok(())
            })?;
        }
        restore_getters(call, &setup.store, id, state)?;
    }
    let mut store = setup.store.lock().unwrap();
    store.replay_clock = None;
    // Native chronological queues are installed only for actors with startup
    // steps. Other actors retain command capture until frame-driven queueing.
    for actor in store.actors.values_mut().filter(|a| a.scene == setup.scene) {
        actor.capture = Some(capture::Capture::default());
    }
    for (&id, startup) in setup
        .startup
        .iter()
        .filter(|(_, state)| !state.steps.is_empty())
    {
        let mut current = setup
            .overlays
            .iter()
            .find(|(actor, _)| *actor == id)
            .map_or_else(
                || crate::overlay_state_after_blocks(startup.initial, &startup.blocks, 0.),
                |(_, state)| *state,
            );
        let mut to = current;
        let actor = store.actors.get_mut(&id).unwrap();
        actor.capture = None;
        let getters = *actor.destination();
        let replay = actor.replay.get_or_insert(State {
            getters: Some(getters),
            ..Default::default()
        });
        replay.progress = vec![Vec::new(); startup.steps.len()];
        replay.targets = 0;
        actor.queue.clear();
        for (index, &duration) in startup.steps.iter().enumerate() {
            let mut easing = None;
            let mut opt1 = None;
            for (block, step) in startup.blocks.iter().zip(&startup.block_steps) {
                if *step == Some(index + 1) {
                    crate::apply_overlay_delta(&mut to, &block.delta);
                    for target in crate::tween_pose::TARGETS {
                        if block.delta.has_update_target(target) {
                            replay.targets |= 1u128 << target as usize;
                        }
                    }
                    easing.clone_from(&block.easing);
                    opt1 = block.opt1;
                }
            }
            actor.queue.push_back(TweenStep::startup(
                index,
                duration,
                to.into(),
                easing,
                opt1,
                startup
                    .commands
                    .get(index)
                    .cloned()
                    .flatten()
                    .map(String::into_bytes),
            ));
        }
        if let Some(rotation) = setup.spin.get(&id) {
            [current.rot_x_deg, current.rot_y_deg, current.rot_z_deg] = *rotation;
        }
        actor.current = current.into();
    }
    Ok(())
}

// Match the preparation getter export, not a wholesale render-state reset:
// discovery also writes non-tween properties which the compiler keeps.
fn restore_getters(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    state: SongLuaOverlayState,
) -> Result<(), Error> {
    for (key, value) in [
        ("__songlua_visible", state.visible),
        ("__songlua_state_sprite_texture", state.sprite_texture),
        ("__songlua_state_aft_preserve", state.aft_preserve),
        ("__songlua_state_aft_created", state.aft_created),
        ("__songlua_state_effect_timer", state.effect_timer),
        ("__songlua_state_effect_no_offset", state.effect_no_offset),
    ] {
        sprites::set(call, id, key, Value::Boolean(value))?;
    }
    for (key, value) in [
        ("__songlua_state_aux", state.aux),
        ("__songlua_aux", state.aux),
        ("__songlua_state_x", state.x),
        ("__songlua_state_y", state.y),
        ("__songlua_state_z", state.z),
        ("__songlua_current_x", state.x),
        ("__songlua_current_y", state.y),
        ("__songlua_current_z", state.z),
        ("__songlua_state_zoom", state.zoom),
        ("__songlua_state_zoom_x", state.zoom_x),
        ("__songlua_state_zoom_y", state.zoom_y),
        ("__songlua_state_zoom_z", state.zoom_z),
        ("__songlua_state_basezoom", state.basezoom),
        ("__songlua_state_basezoom_x", state.basezoom_x),
        ("__songlua_state_basezoom_y", state.basezoom_y),
        ("__songlua_state_basezoom_z", state.basezoom_z),
        ("__songlua_state_base_alpha", state.base_alpha),
        ("__songlua_state_rot_x_deg", state.rot_x_deg),
        ("__songlua_state_rot_y_deg", state.rot_y_deg),
        ("__songlua_state_rot_z_deg", state.rot_z_deg),
        ("__songlua_state_halign", state.halign),
        ("__songlua_state_valign", state.valign),
        ("__songlua_state_effect_period", state.effect_period),
    ] {
        sprites::set(call, id, key, Value::Number(f64::from(value)))?;
    }
    for (key, values) in [
        ("__songlua_state_quaternion", state.quaternion.as_slice()),
        (
            "__songlua_state_base_rotation",
            state.base_rotation.as_slice(),
        ),
        ("__songlua_state_glow", state.glow.as_slice()),
        (
            "__songlua_state_effect_magnitude",
            state.effect_magnitude.as_slice(),
        ),
    ]
    .into_iter()
    .chain(
        state
            .size
            .as_ref()
            .map(|size| ("__songlua_state_size", size.as_slice())),
    )
    .chain(
        state
            .stretch_rect
            .as_ref()
            .map(|rect| ("__songlua_state_stretch_rect", rect.as_slice())),
    ) {
        let value = sprites::vector_value(call, values)?;
        call.with_roots(&[value], |call| sprites::set(call, id, key, value))?;
    }
    let diffuse = sprites::vector_value(call, &state.diffuse)?;
    call.with_roots(&[diffuse], |call| {
        sprites::set(call, id, "__songlua_state_diffuse", diffuse)?;
        sprites::set(call, id, "__songlua_diffuse", diffuse)
    })?;
    for (key, label) in [
        (
            "__songlua_state_effect_mode",
            crate::effect_mode_label(state.effect_mode),
        ),
        (
            "__songlua_state_effect_clock",
            crate::effect_clock_label(state.effect_clock),
        ),
    ] {
        let value = call.try_intern(label.as_bytes())?;
        call.with_roots(&[value], |call| sprites::set(call, id, key, value))?;
    }
    let mut store = store.lock().unwrap();
    let actor = store.actors.get_mut(&id).unwrap();
    actor.current.x = state.x;
    actor.current.y = state.y;
    actor.current.z = state.z;
    actor.current.aux = state.aux;
    actor.current.zoom = state.zoom;
    actor.current.zoom_x = state.zoom_x;
    actor.current.zoom_y = state.zoom_y;
    actor.current.zoom_z = state.zoom_z;
    actor.current.rot_x_deg = state.rot_x_deg;
    actor.current.rot_y_deg = state.rot_y_deg;
    actor.current.rot_z_deg = state.rot_z_deg;
    actor.current.quaternion = state.quaternion;
    actor.current.diffuse = state.diffuse;
    actor.current.glow = state.glow;
    actor.replay = Some(State {
        getters: Some(actor.current),
        ..Default::default()
    });
    actor.preparation_getters = Some([state.x, state.y, state.z, state.aux]);
    actor.state.rotation = [state.rot_x_deg, state.rot_y_deg, state.rot_z_deg];
    actor.state.visible = state.visible;
    let render = &mut actor.state.render;
    render.sprite_texture = state.sprite_texture;
    render.aft_preserve = state.aft_preserve;
    render.aft_created = state.aft_created;
    render.basezoom = state.basezoom;
    render.basezoom_x = state.basezoom_x;
    render.basezoom_y = state.basezoom_y;
    render.basezoom_z = state.basezoom_z;
    render.base_alpha = state.base_alpha;
    render.base_rotation = state.base_rotation;
    render.halign = state.halign;
    render.valign = state.valign;
    render.effect_mode = state.effect_mode;
    render.effect_clock = state.effect_clock;
    render.effect_timer = state.effect_timer;
    render.effect_no_offset = state.effect_no_offset;
    render.effect_period = state.effect_period;
    render.effect_magnitude = state.effect_magnitude;
    if let Some(size) = state.size {
        actor.state.size = size;
        render.size = Some(size);
    }
    if state.stretch_rect.is_some() {
        render.stretch_rect = state.stretch_rect;
    }
    Ok(())
}

pub(super) fn raw_set(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &str,
    value: Value,
) -> Result<(), Error> {
    call.with_roots(&[value], |call| {
        let key = call.try_intern(key.as_bytes())?;
        call.raw_table_set(actor, key, value)
    })
}

/// Preparation exports the sampled current pose and queued destination to
/// Lua. No metadata lock survives allocation or a host API operation.
pub(super) fn sync_getters(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
) -> Result<(), Error> {
    let poses = {
        let mut store = store.lock().unwrap();
        let fallback = song_pose::mode(&store, id);
        let actor = store.actors.get_mut(&id).unwrap();
        if actor.replay.is_some() {
            actor.sync_rotation_getters();
            let dest = if fallback {
                *actor.getter_destination()
            } else {
                *actor.destination()
            };
            if fallback {
                actor.state.rotation = [dest.rot_x_deg, dest.rot_y_deg, dest.rot_z_deg];
            }
            Some((actor.current, dest))
        } else {
            None
        }
    };
    let Some((current, dest)) = poses else {
        return Ok(());
    };
    for (key, value) in [
        ("aux", dest.aux),
        ("x", dest.x),
        ("y", dest.y),
        ("z", dest.z),
        ("zoom", dest.zoom),
        ("zoom_x", dest.zoom_x),
        ("zoom_y", dest.zoom_y),
        ("zoom_z", dest.zoom_z),
        ("rot_x_deg", dest.rot_x_deg),
        ("rot_y_deg", dest.rot_y_deg),
        ("rot_z_deg", dest.rot_z_deg),
        ("skew_x", dest.skew_x),
        ("skew_y", dest.skew_y),
        ("cropleft", dest.cropleft),
        ("cropright", dest.cropright),
        ("croptop", dest.croptop),
        ("cropbottom", dest.cropbottom),
        ("fadeleft", dest.fadeleft),
        ("faderight", dest.faderight),
        ("fadetop", dest.fadetop),
        ("fadebottom", dest.fadebottom),
    ] {
        raw_set(
            call,
            id,
            &format!("__songlua_state_{key}"),
            Value::Number(f64::from(value)),
        )?;
    }
    for (key, values) in [
        ("__songlua_diffuse", dest.diffuse),
        ("__songlua_state_diffuse", dest.diffuse),
        ("__songlua_state_glow", dest.glow),
        ("__songlua_state_quaternion", dest.quaternion),
    ] {
        let value = sprites::vector_value(call, &values)?;
        raw_set(call, id, key, value)?;
    }
    let colors = if let Some(colors) = dest.vertex_colors {
        let table = call.try_new_table()?;
        call.with_roots(&[Value::Table(table)], |call| {
            for (i, color) in colors.iter().enumerate() {
                let value = sprites::vector_value(call, color)?;
                call.raw_table_set(table, Value::Number((i + 1) as f64), value)?;
            }
            raw_set(
                call,
                id,
                "__songlua_state_vertex_colors",
                Value::Table(table),
            )
        })?;
        true
    } else {
        false
    };
    if !colors {
        raw_set(call, id, "__songlua_state_vertex_colors", Value::Nil)?;
    }
    for (key, value) in [
        ("__songlua_aux", current.aux),
        ("__songlua_current_x", current.x),
        ("__songlua_current_y", current.y),
        ("__songlua_current_z", current.z),
    ] {
        raw_set(call, id, key, Value::Number(f64::from(value)))?;
    }
    Ok(())
}

// Scalar setters export the fields they wrote, without synchronizing unrelated
// destinations. Current XYZ/aux still come from the replay's current pose.
pub(super) fn publish_scalar(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    name: &str,
) -> Result<(), Error> {
    let poses = {
        let store = store.lock().unwrap();
        let actor = &store.actors[&id];
        actor
            .replay
            .as_ref()
            .map(|_| (actor.current, *actor.getter_destination(), actor.state.size))
    };
    let Some((current, dest, size)) = poses else {
        return Ok(());
    };
    let keys: &[(&str, f32)] = match name {
        "x" | "addx" => &[("x", dest.x)],
        "y" | "addy" => &[("y", dest.y)],
        "z" | "addz" => &[("z", dest.z)],
        "xy" => &[("x", dest.x), ("y", dest.y)],
        "aux" => &[("aux", dest.aux)],
        "zoom" => &[
            ("zoom", dest.zoom),
            ("zoom_x", dest.zoom_x),
            ("zoom_y", dest.zoom_y),
            ("zoom_z", dest.zoom_z),
        ],
        "zoomx" => &[("zoom_x", dest.zoom_x)],
        "zoomy" => &[("zoom_y", dest.zoom_y)],
        "zoomz" => &[("zoom_z", dest.zoom_z)],
        "rotationx" | "addrotationx" => &[("rot_x_deg", dest.rot_x_deg)],
        "rotationy" | "addrotationy" => &[("rot_y_deg", dest.rot_y_deg)],
        "rotationz" | "addrotationz" => &[("rot_z_deg", dest.rot_z_deg)],
        _ => &[],
    };
    for &(key, value) in keys {
        raw_set(
            call,
            id,
            &format!("__songlua_state_{key}"),
            Value::Number(f64::from(value)),
        )?;
        let current = match key {
            "x" => Some(("__songlua_current_x", current.x)),
            "y" => Some(("__songlua_current_y", current.y)),
            "z" => Some(("__songlua_current_z", current.z)),
            "aux" => Some(("__songlua_aux", current.aux)),
            _ => None,
        };
        if let Some((key, value)) = current {
            raw_set(call, id, key, Value::Number(f64::from(value)))?;
        }
    }
    if matches!(name, "SetWidth" | "SetHeight" | "setsize") {
        let value = sprites::vector_value(call, &size)?;
        raw_set(call, id, "__songlua_state_size", value)?;
    }
    Ok(())
}

impl Actors {
    pub(in crate::rust_engine) fn advance_song_replay(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
        seconds: f64,
        delta: f64,
    ) -> Result<bool, Error> {
        let first = {
            let mut store = self.store.lock().unwrap();
            if store
                .replay_frame
                .is_none_or(|(owner, _)| owner != screen.id)
            {
                drop(store);
                return vm.with_native_stack(|stack| {
                    Err(stack.error(b"song preparation replay has not started"))
                });
            }
            store.replay_frame = Some((screen.id, seconds));
            store.next
        };
        let previous = std::mem::replace(&mut self.store.lock().unwrap().replay_advancing, true);
        let result = self.advance(vm, screen, delta);
        self.store.lock().unwrap().replay_advancing = previous;
        song_activation::adopt_created(&self.store, screen.id, first);
        result
    }

    pub(in crate::rust_engine) fn capture_song_tween_replay(
        &self,
        screen: ActorScene,
    ) -> Option<HashMap<TableId, super::super::SongTweenReplay>> {
        let mut store = self.store.lock().unwrap();
        let (owner, time) = store.replay_frame?;
        if owner != screen.id {
            return None;
        }
        let ids = store.scenes.get(&screen.id)?.actors.clone();
        let mut result = HashMap::new();
        for id in ids {
            let actor = store.actors.get_mut(&id).unwrap();
            lifecycle::sample_replay(actor, time as f32);
            let Some(replay) = &actor.replay else {
                continue;
            };
            let values = crate::tween_pose::TARGETS
                .into_iter()
                .filter(|target| replay.targets & (1u128 << *target as usize) != 0)
                .map(|target| (target, actor.current.get(target)))
                .collect();
            result.insert(
                id,
                super::super::SongTweenReplay {
                    progress: replay.progress.clone(),
                    values,
                },
            );
        }
        Some(result)
    }
}

//! Lua observations for the existing overlay draw-tree collector.
use super::*;
use crate::SongLuaOverlayState;

#[derive(Clone)]
pub(in crate::rust_engine) enum Query {
    AftNames,
    References,
    Wrappers,
    Index(usize, bool),
    Header,
    Name,
    Draw,
    Wrapper,
}
pub(in crate::rust_engine) enum Answer {
    Names(HashSet<String>),
    References(HashSet<TableId>),
    Wrappers(Option<(Value, usize)>),
    Value(Value),
    Header(Option<Box<(String, SongLuaOverlayState, usize)>>),
    Name(Option<String>),
    Flag(bool),
}
pub(in crate::rust_engine) struct Observation {
    pub answer: Answer,
    pin: Option<Root>,
}
impl Observation {
    pub fn release(self, vm: &mut Vm) -> Result<(), Error> {
        if let Some(pin) = self.pin {
            vm.unpin(pin)?;
        }
        Ok(())
    }
}
type Output = Arc<Mutex<Option<Answer>>>;
#[derive(Clone)]
struct Read {
    store: Shared,
    query: Query,
    output: Output,
}
pub(in crate::rust_engine) struct Tree {
    registry: TableId,
    helpers: TableId,
    store: Shared,
}
impl Actors {
    pub(in crate::rust_engine) fn overlay_tree(&self) -> Tree {
        Tree {
            registry: self.registry,
            helpers: self.helpers,
            store: self.store.clone(),
        }
    }
}
impl Tree {
    pub fn query(&self, vm: &mut Vm, actor: Value, query: Query) -> Result<Observation, Error> {
        let output = Arc::new(Mutex::new(None));
        let function = vm.new_host_function_with_data(
            read,
            &[
                Value::Table(self.registry),
                Value::Table(self.helpers),
                actor,
            ],
            Read {
                store: self.store.clone(),
                query,
                output: output.clone(),
            },
        )?;
        let value = vm.call(function, &[])?[0];
        let answer = output.lock().unwrap().take().unwrap();
        // The callback returns a cursor handle on the VM stack. Pin it before
        // any subsequent Lua operation, then release at the native cursor scope.
        let pin = if matches!(answer, Answer::Value(_) | Answer::Wrappers(Some(_))) {
            Some(vm.pin(value)?)
        } else {
            None
        };
        Ok(Observation { answer, pin })
    }
    pub fn deferred(&self, actor: Value) -> bool {
        self.store
            .lock()
            .unwrap()
            .deferred_messages
            .iter()
            .any(|r| Value::Table(r.actor) == actor)
    }
}
fn text(call: &mut HostCall<'_>, actor: TableId, key: &str) -> Result<Option<String>, Error> {
    let value = sprites::field(call, actor, key)?;
    initial_state::value_text(call, value)
}
fn aft_names(
    call: &mut HostCall<'_>,
    actor: TableId,
    out: &mut HashSet<String>,
) -> Result<(), Error> {
    if text(call, actor, "__songlua_actor_type")?
        .is_some_and(|c| c.eq_ignore_ascii_case("ActorFrameTexture"))
    {
        let allocation = get(call, actor, b"__songlua_aft_allocation")?;
        if allocation != Value::Nil {
            table(call, allocation)?;
            if let Some(name) = framebuffers::capture_name(call, actor)? {
                out.insert(name);
            }
        }
    }
    let mut i = 1;
    loop {
        let value = call.raw_table_get(actor, Value::Number(i as f64))?;
        if value == Value::Nil {
            break;
        }
        if let Value::Table(child) = value {
            call.with_roots(&[value], |call| aft_names(call, child, out))?;
        }
        i += 1;
    }
    Ok(())
}
fn references(call: &mut HostCall<'_>, data: &Read) -> Result<HashSet<TableId>, Error> {
    let globals = helper(call, 5)?;
    let public_registry = sprites::field(call, table(call, globals)?, "__songlua_actor_registry")?;
    let known = if public_registry == Value::Nil {
        data.store
            .lock()
            .unwrap()
            .actor_order
            .iter()
            .copied()
            .collect::<HashSet<_>>()
    } else {
        let registry = table(call, public_registry)?;
        let mut known = HashSet::new();
        let mut index = 1;
        loop {
            let value = call.raw_table_get(registry, Value::Number(index as f64))?;
            if value == Value::Nil {
                break;
            }
            known.insert(table(call, value)?);
            index += 1;
        }
        known
    };
    let mut stack = call.native_stack()?;
    stack.push(globals)?;
    let outer = stack.top_offset();
    stack.push(Value::Nil)?;
    let mut referenced = HashSet::new();
    while stack.next_table(outer)? {
        if let Some(value @ Value::Table(id)) = stack.value(-1) {
            if known.contains(&id) {
                referenced.insert(id);
            } else if value != globals && value != public_registry {
                stack.push(value)?;
                let inner = stack.top_offset();
                stack.push(Value::Nil)?;
                while stack.next_table(inner)? {
                    if let Some(Value::Table(id)) = stack.value(-1)
                        && known.contains(&id)
                    {
                        referenced.insert(id);
                    }
                    stack.set_top(stack.top() - 1)?;
                }
                stack.set_top(stack.top() - 1)?;
            }
        }
        stack.set_top(stack.top() - 1)?;
    }
    Ok(referenced)
}
fn read(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Read>().unwrap().clone();
    let actor = table(call, call.captures()[2])?;
    let answer = match data.query {
        Query::AftNames => {
            let mut names = HashSet::new();
            aft_names(call, actor, &mut names)?;
            Answer::Names(names)
        }
        Query::References => Answer::References(references(call, &data)?),
        Query::Wrappers => {
            let raw = get(call, actor, b"__songlua_wrappers")?;
            let owned = if raw == Value::Nil {
                data.store
                    .lock()
                    .unwrap()
                    .actors
                    .get(&actor)
                    .map(|a| a.wrappers.clone())
                    .unwrap_or_default()
            } else {
                Vec::new()
            };
            let value = if !owned.is_empty() {
                // The Rust binding keeps the native default wrapper list in
                // actor metadata. An authored Lua list still takes precedence.
                let array = call.try_new_table()?;
                call.with_roots(&[Value::Table(array)], |call| {
                    for (i, wrapper) in owned.into_iter().enumerate() {
                        call.raw_table_set(
                            array,
                            Value::Number((i + 1) as f64),
                            Value::Table(wrapper),
                        )?;
                    }
                    Ok(())
                })?;
                Value::Table(array)
            } else {
                sprites::field(call, actor, "__songlua_wrappers")?
            };
            let value = if value == Value::Nil {
                None
            } else {
                let wrappers = table(call, value)?;
                Some((value, call.raw_table_len(wrappers)?))
            };
            Answer::Wrappers(value)
        }
        Query::Index(i, required) => {
            let value = call.raw_table_get(actor, Value::Number(i as f64))?;
            if required {
                table(call, value)?;
            }
            Answer::Value(value)
        }
        Query::Header => {
            let class = text(call, actor, "__songlua_actor_type")?;
            Answer::Header(if let Some(class) = class {
                let initial = initial_state::read(call, &data.store, actor)?;
                let initial = crate::overlay_state_after_blocks(initial, &[], 0.);
                let identity = call.object_pointer(Value::Table(actor)).unwrap();
                Some(Box::new((class, initial, identity)))
            } else {
                None
            })
        }
        Query::Name => Answer::Name(text(call, actor, "Name")?),
        Query::Draw => {
            let value = sprites::field(call, actor, "__songlua_draw_function")?;
            if !matches!(value, Value::Nil | Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"draw function expected"));
            }
            Answer::Flag(value != Value::Nil)
        }
        Query::Wrapper => Answer::Flag(
            text(call, actor, "__songlua_actor_type")?
                .is_some_and(|c| c.eq_ignore_ascii_case("WrapperState")),
        ),
    };
    let returned = match &answer {
        Answer::Value(value) => *value,
        Answer::Wrappers(Some((value, _))) => *value,
        _ => Value::Nil,
    };
    *data.output.lock().unwrap() = Some(answer);
    call.push(returned)
}

//! Sound actors emit immediate host events; their RageSound handles retain
//! independent parameters and cached metadata through ordinary traced captures.
use super::*;
use crate::{SongLuaActorSound, SongLuaSoundEvent};
use std::sync::atomic::Ordering;

type LengthCache = Arc<Mutex<Option<(Option<String>, f32)>>>;
fn parameter(call: &HostCall<'_>) -> Value {
    arg(
        call,
        usize::from(matches!(call.arguments().first(), Some(Value::Table(_)))),
    )
}
#[derive(Clone)]
struct SoundBinding {
    store: Shared,
    name: &'static str,
    length: LengthCache,
}

pub(super) fn install(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let sound = call.try_new_table()?;
    let methods = call.try_new_table()?;
    let registry = table(call, call.captures()[0])?;
    // The actor's registry value traces the handle even if authored fields are
    // replaced. Its methods in turn retain the actor after scene retirement.
    let scene = store.lock().unwrap().actors[&actor].scene;
    let retired = store.lock().unwrap().retired_scenes.get(&scene).copied();
    if let Some(owner) = retired {
        call.raw_table_set(owner, Value::Table(sound), Value::Boolean(true))?;
    } else {
        call.raw_table_set(registry, Value::Table(actor), Value::Table(sound))?;
    }
    let key = call.try_intern(b"__songlua_bound_methods")?;
    call.raw_table_set(actor, key, Value::Table(methods))?;
    for name in [b"__songlua_volume".as_slice(), b"__songlua_pitch"] {
        let key = call.try_intern(name)?;
        call.raw_table_set(sound, key, Value::Number(1.0))?;
    }
    let captures = [
        call.captures()[0],
        call.captures()[1],
        Value::Table(actor),
        Value::Table(sound),
    ];
    let length = Arc::new(Mutex::new(None));
    for (target, names) in [
        (methods, &["Load", "get", "stop", "playforplayer"][..]),
        (sound, &["pitch", "volume", "get_length", "SetProperty"][..]),
    ] {
        for &name in names {
            let function = call.new_host_function_with_data(
                bound,
                &captures,
                SoundBinding {
                    store: store.clone(),
                    name,
                    length: length.clone(),
                },
            )?;
            let key = call.try_intern(name.as_bytes())?;
            call.raw_table_set(target, key, function)?;
        }
    }
    store.lock().unwrap().actors.get_mut(&actor).unwrap().sound = Some(sound);
    Ok(())
}

fn path(
    call: &mut HostCall<'_>,
    actor: TableId,
    file: &str,
) -> Result<Option<std::path::PathBuf>, Error> {
    match assets::resolve(call, actor, file) {
        Err(error) if error.kind() == ErrorKind::Runtime => Ok(None),
        result => result,
    }
}

fn owner(call: &mut HostCall<'_>, actor: TableId) -> u64 {
    call.object_pointer(Value::Table(actor))
        .expect("captured actor") as u64
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let (is_sound, live) = {
        let store = store.lock().unwrap();
        (
            store.actors[&actor].state.class == "Sound",
            store.clock.live.load(Ordering::Relaxed),
        )
    };
    if !is_sound {
        if !matches!(name, "play" | "pause") {
            return call.push(Value::Table(actor));
        }
        action_capture::prepare(call, store, actor)?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .render
            .sprite_animate = name == "play";
        sprites::set(
            call,
            actor,
            "__songlua_state_sprite_animate",
            Value::Boolean(name == "play"),
        )?;
        song_media::record(call, store, actor, "sprite_animate");
        return call.push(Value::Table(actor));
    }
    match name {
        "play" | "playforplayer" => {
            if let Some(file) = assets::field(call, actor, b"File")?
                && let Some(path) = path(call, actor, &file)?
            {
                if live {
                    let owner = owner(call, actor);
                    store
                        .lock()
                        .unwrap()
                        .sounds
                        .push(SongLuaActorSound::Play { owner, path });
                } else {
                    let beat = match effects::values(call, false) {
                        Ok(values) => values[0],
                        Err(error) if error.kind() == ErrorKind::Runtime => 0.0,
                        Err(error) => return Err(error),
                    };
                    {
                        let mut store = store.lock().unwrap();
                        if let Some(queued_startup) = store.sound_capture {
                            let source_message = store.active_message.clone();
                            store.prepared_sounds.push(SongLuaSoundEvent {
                                beat,
                                path: path.clone(),
                                source_message,
                                queued_startup,
                            });
                        }
                    }
                    let key = call.try_intern(crate::SONG_LUA_SOUND_CALLS_KEY.as_bytes())?;
                    let calls = call.table_get(helper(call, 5)?, key)?;
                    if calls != Value::Nil {
                        let calls = table(call, calls)?;
                        let value = call.try_intern(path.to_string_lossy().as_bytes())?;
                        let index = Value::Number((call.raw_table_len(calls)? + 1) as f64);
                        call.raw_table_set(calls, index, value)?;
                    }
                }
            }
        }
        "pause" | "stop" if live => {
            let owner = owner(call, actor);
            let event = if name == "pause" {
                SongLuaActorSound::Pause {
                    owner,
                    paused: boolish(call, arg(call, 1)).unwrap_or(false),
                }
            } else {
                SongLuaActorSound::Stop { owner }
            };
            store.lock().unwrap().sounds.push(event);
        }
        _ => {}
    }
    call.push(Value::Table(actor))
}

fn bound(call: &mut HostCall<'_>) -> Result<(), Error> {
    let SoundBinding {
        store,
        name,
        length,
    } = call.function_data::<SoundBinding>().unwrap().clone();
    let actor = table(call, call.captures()[2])?;
    let sound = table(call, call.captures()[3])?;
    match name {
        "volume" | "pitch" => {
            let value = float_scalar(call, parameter(call), false)
                .ok_or_else(|| call.error(b"sound parameter must be a number"))?;
            let key = call.try_intern(if name == "volume" {
                b"__songlua_volume"
            } else {
                b"__songlua_pitch"
            })?;
            call.raw_table_set(sound, key, Value::Number(value as f64))?;
            call.push(Value::Table(sound))
        }
        "SetProperty" => call.push(Value::Boolean(false)),
        "get_length" => {
            // Read authored File before consulting the cache. Neither metadata
            // lookup nor decoder I/O holds a lock across reentrant Lua calls.
            let file = assets::field(call, actor, b"File")?;
            let cached = length
                .lock()
                .unwrap()
                .as_ref()
                .filter(|(previous, _)| previous == &file)
                .map(|(_, value)| *value);
            let value = if let Some(value) = cached {
                value
            } else {
                let path = match file.as_deref() {
                    Some(file) => path(call, actor, file)?,
                    None => None,
                };
                let value = path
                    .and_then(|path| {
                        deadlib_audio_decode::file_length_seconds(&path, Default::default()).ok()
                    })
                    .map(|seconds| (seconds * 1000.0).trunc() / 1000.0)
                    .unwrap_or(-1.0);
                *length.lock().unwrap() = Some((file, value));
                value
            };
            call.push(Value::Number(value as f64))
        }
        _ => {
            if !store.lock().unwrap().actors.contains_key(&actor) {
                return Err(call.error(b"sound actor has been released"));
            }
            match name {
                "get" => call.push(Value::Table(sound)),
                "Load" => {
                    let value = parameter(call);
                    if matches!(value, Value::String(_) | Value::Nil) {
                        if value != Value::Nil {
                            assets::text(call, value)?;
                        }
                        let key = call.try_intern(b"File")?;
                        call.table_set(Value::Table(actor), key, value)?;
                    }
                    call.push(Value::Table(actor))
                }
                _ => method(call, &store, actor, name),
            }
        }
    }
}

pub(super) fn retire(call: &mut HostCall<'_>, store: &Shared, actor: TableId) {
    let mut store = store.lock().unwrap();
    if store.actors[&actor].sound.is_some() && store.clock.live.load(Ordering::Relaxed) {
        store.sounds.push(SongLuaActorSound::Stop {
            owner: owner(call, actor),
        });
    }
}

//! Existing global SOUND stubs, resource discovery and runtime sound capture.
use super::*;
use std::path::{Path, PathBuf};

#[derive(Clone, Copy)]
enum Operation {
    Effect,
    Path(bool),
    Balance,
    Delayed,
}
#[derive(Clone)]
struct Binding {
    store: Shared,
    song_dir: PathBuf,
    operation: Operation,
}
impl Actors {
    pub(in crate::rust_engine) fn install_sound_manager(
        &self,
        vm: &mut Vm,
        song_dir: &Path,
    ) -> Result<(), Error> {
        let globals = vm.get_global(b"_G")?;
        let tonumber = vm.get_global(b"tonumber")?;
        let sound = vm.try_new_table()?;
        let pin = vm.pin(Value::Table(sound))?;
        let result = (|| {
            let paths = vm.try_new_table()?;
            vm.set_global(
                crate::SONG_LUA_SOUND_PATHS_KEY.as_bytes(),
                Value::Table(paths),
            )?;
            vm.set_global(crate::SONG_LUA_SOUND_CALLS_KEY.as_bytes(), Value::Nil)?;
            for (name, operation) in [
                ("DimMusic", Operation::Effect),
                ("StopMusic", Operation::Effect),
                ("PlayMusicPart", Operation::Path(false)),
                ("PlayOnce", Operation::Path(true)),
                ("PlayAnnouncer", Operation::Effect),
                ("GetPlayerBalance", Operation::Balance),
                ("IsTimingDelayed", Operation::Delayed),
            ] {
                let function = vm.new_host_function_with_data(
                    dispatch,
                    &[globals, tonumber, Value::Table(sound)],
                    Binding {
                        store: self.store.clone(),
                        song_dir: song_dir.to_owned(),
                        operation,
                    },
                )?;
                super::super::put(vm, sound, name, function)?;
            }
            vm.set_global(b"SOUND", Value::Table(sound))
        })();
        vm.unpin(pin)?;
        result
    }
}
fn field(call: &mut HostCall<'_>, target: Value, name: &str) -> Result<Value, Error> {
    let key = call.try_intern(name.as_bytes())?;
    call.table_get(target, key)
}
fn text(call: &mut HostCall<'_>, value: Value) -> Result<String, Error> {
    let id = call
        .coerce_string(value)?
        .ok_or_else(|| call.error(b"sound string expected"))?;
    std::str::from_utf8(call.string_bytes(id).unwrap())
        .map(str::to_owned)
        .map_err(|e| call.error(e.to_string().as_bytes()))
}
fn dispatch(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Binding>().unwrap().clone();
    match data.operation {
        Operation::Balance => return call.push(Value::Number(0.)),
        Operation::Delayed => return call.push(Value::Boolean(false)),
        _ => {}
    }
    super::super::managers::side_effect(call, call.captures()[0], call.captures()[1])?;
    if let Operation::Path(capture) = data.operation {
        let offset = usize::from(matches!(call.arguments().first(), Some(Value::Table(_))));
        let value = arg(call, offset);
        // The native read_string helper ignores non-string inputs
        // and invalid UTF-8; path-resolution runtime errors are also ignored.
        if matches!(value, Value::String(_)) {
            let raw = text(call, value);
            if let Ok(raw) = raw {
                match resolve(call, &data.song_dir, &raw) {
                    Ok(Some(path)) => record(call, &data.store, path, capture)?,
                    Ok(None) => {}
                    Err(error) if error.kind() == ErrorKind::Runtime => {}
                    Err(error) => return Err(error),
                }
            } else if let Err(error) = raw
                && error.kind() != ErrorKind::Runtime
            {
                return Err(error);
            }
        }
    }
    call.push(call.captures()[2])
}
fn resolve(call: &mut HostCall<'_>, song_dir: &Path, raw: &str) -> Result<Option<PathBuf>, Error> {
    let path = Path::new(raw);
    let resolved = if path.is_absolute() && path.exists() {
        Some(path.to_owned())
    } else {
        let current = field(call, call.captures()[0], "__songlua_script_dir")?;
        let current = if current == Value::Nil {
            None
        } else {
            Some(text(call, current)?)
        };
        current
            .filter(|dir| !dir.trim().is_empty())
            .map(|dir| Path::new(&dir).join(raw))
            .filter(|path| path.exists())
            .or_else(|| {
                let candidate = song_dir.join(raw);
                candidate.exists().then_some(candidate)
            })
            .or_else(|| path.exists().then(|| path.to_owned()))
    };
    Ok(resolved.filter(|path| path.is_file() && crate::is_song_lua_audio_path(path)))
}
fn beat(call: &mut HostCall<'_>) -> Result<f32, Error> {
    let runtime = field(call, call.captures()[0], crate::SONG_LUA_RUNTIME_KEY)?;
    call.with_roots(&[runtime], |call| {
        let mut result = 0.;
        for (i, key) in [
            crate::SONG_LUA_RUNTIME_BEAT_KEY,
            crate::SONG_LUA_RUNTIME_SECONDS_KEY,
        ]
        .into_iter()
        .enumerate()
        {
            let value = field(call, runtime, key)?;
            let value = call.call(call.captures()[1], &[value])?[0];
            let Value::Number(value) = value else {
                return Err(call.error(b"sound clock number expected"));
            };
            if i == 0 {
                result = value as f32;
            }
        }
        Ok(result)
    })
}
fn record(
    call: &mut HostCall<'_>,
    store: &Shared,
    path: PathBuf,
    capture: bool,
) -> Result<(), Error> {
    let globals = call.captures()[0];
    if capture {
        let beat = match beat(call) {
            Ok(beat) => beat,
            Err(e) if e.kind() == ErrorKind::Runtime => 0.,
            Err(e) => return Err(e),
        };
        {
            let mut store = store.lock().unwrap();
            if let Some(queued_startup) = store.sound_capture {
                let source_message = store.active_message.clone();
                store.prepared_sounds.push(crate::SongLuaSoundEvent {
                    beat,
                    path: path.clone(),
                    source_message,
                    queued_startup,
                });
            }
        }
        let calls = field(call, globals, crate::SONG_LUA_SOUND_CALLS_KEY)?;
        if calls != Value::Nil {
            call.with_roots(&[calls], |call| {
                let calls = table(call, calls)?;
                let key = call.try_intern(path.to_string_lossy().as_bytes())?;
                call.raw_table_set(
                    calls,
                    Value::Number((call.raw_table_len(calls)? + 1) as f64),
                    key,
                )
            })?;
        }
    }
    let paths = field(call, globals, crate::SONG_LUA_SOUND_PATHS_KEY)?;
    let paths = if paths == Value::Nil {
        let paths = Value::Table(call.try_new_table()?);
        call.with_roots(&[paths], |call| {
            let key = call.try_intern(crate::SONG_LUA_SOUND_PATHS_KEY.as_bytes())?;
            call.table_set(globals, key, paths)
        })?;
        paths
    } else {
        paths
    };
    call.with_roots(&[paths], |call| {
        let paths = table(call, paths)?;
        let key = path.to_string_lossy();
        let mut i = 1;
        loop {
            let value = call.raw_table_get(paths, Value::Number(i as f64))?;
            if value == Value::Nil {
                break;
            }
            if text(call, value)? == key {
                return Ok(());
            }
            i += 1;
        }
        let key = call.try_intern(key.as_bytes())?;
        call.raw_table_set(
            paths,
            Value::Number((call.raw_table_len(paths)? + 1) as f64),
            key,
        )
    })
}

//! The existing three-axis NoteColumn spline API and shared gameplay solver.
use super::*;
use deadlib_lua::NativeStack;
use sprites::set;

pub(super) fn handler(call: &mut HostCall<'_>) -> Result<TableId, Error> {
    let owner = call.try_new_table()?;
    call.with_roots(&[Value::Table(owner)], |call| {
        let spline = spline(call)?;
        set(call, owner, "__songlua_spline", Value::Table(spline))?;
        let mode = call.try_intern(b"NoteColumnSplineMode_Disabled")?;
        set(call, owner, "__songlua_spline_mode", mode)?;
        set(
            call,
            owner,
            "__songlua_subtract_song_beat",
            Value::Boolean(true),
        )?;
        set(call, owner, "__songlua_receptor_t", Value::Number(0.))?;
        set(call, owner, "__songlua_beats_per_t", Value::Number(1.))?;
        let getter = call.new_host_function(
            |call| call.push(call.captures()[0]),
            &[Value::Table(spline)],
        )?;
        set(call, owner, "GetSpline", getter)?;
        set(call, owner, "get_spline", getter)?;
        for (name, alias) in [
            ("SetSplineMode", "set_spline_mode"),
            ("SetSubtractSongBeat", "set_subtract_song_beat"),
            ("SetReceptorT", "set_receptor_t"),
            ("SetBeatsPerT", "set_beats_per_t"),
        ] {
            let function =
                call.new_host_function_with_data(handler_method, &[Value::Table(owner)], name)?;
            set(call, owner, name, function)?;
            set(call, owner, alias, function)?;
        }
        Ok(owner)
    })
}

// read_f32 differs from numeric coercion: finite numeric values, but ordinary
// Rust float strings (including inf/nan), and no Lua hexadecimal string syntax.
pub(super) fn optional_float(call: &HostCall<'_>, value: Value) -> Option<f32> {
    match value {
        Value::Number(value) => (value as f32).is_finite().then_some(value as f32),
        Value::String(id) => std::str::from_utf8(call.string_bytes(id)?)
            .ok()?
            .trim()
            .parse()
            .ok(),
        _ => None,
    }
}
fn handler_method(call: &mut HostCall<'_>) -> Result<(), Error> {
    let owner = table(call, call.captures()[0])?;
    let name = *call.function_data::<&'static str>().unwrap();
    let value = arg(call, 1);
    match name {
        "SetSplineMode" => {
            if let Value::String(id) = value
                && call
                    .string_bytes(id)
                    .is_some_and(|s| std::str::from_utf8(s).is_ok())
            {
                set(call, owner, "__songlua_spline_mode", value)?;
            }
        }
        "SetSubtractSongBeat" => set(
            call,
            owner,
            "__songlua_subtract_song_beat",
            Value::Boolean(!matches!(value, Value::Nil | Value::Boolean(false))),
        )?,
        "SetReceptorT" | "SetBeatsPerT" => {
            if let Some(value) = optional_float(call, value) {
                set(
                    call,
                    owner,
                    if name == "SetReceptorT" {
                        "__songlua_receptor_t"
                    } else {
                        "__songlua_beats_per_t"
                    },
                    Value::Number(value as f64),
                )?;
            }
        }
        _ => unreachable!(),
    }
    call.push(Value::Table(owner))
}

fn spline(call: &mut HostCall<'_>) -> Result<TableId, Error> {
    let owner = call.try_new_table()?;
    call.with_roots(&[Value::Table(owner)], |call| {
        set(call, owner, "__songlua_spline_size", Value::Number(0.))?;
        set(call, owner, "__songlua_spline_loop", Value::Boolean(false))?;
        for key in ["__songlua_spline_points", "__songlua_spline_coefficients"] {
            let values = call.try_new_table()?;
            set(call, owner, key, Value::Table(values))?;
        }
        for (name, alias) in [
            ("evaluate", "Evaluate"),
            ("SetSize", "set_size"),
            ("GetSize", "get_size"),
            ("SetPoint", "set_point"),
            ("Solve", "solve"),
            ("SetPolygonal", "set_polygonal"),
            ("SetLoop", "set_loop"),
            ("get_loop", "get_loop"),
        ] {
            let function =
                call.new_host_function_with_data(spline_method, &[Value::Table(owner)], name)?;
            set(call, owner, name, function)?;
            if alias != name {
                set(call, owner, alias, function)?;
            }
        }
        Ok(owner)
    })
}

fn table_at(stack: &NativeStack<'_, '_>, index: isize) -> Result<(), Error> {
    if matches!(stack.value(index), Some(Value::Table(_))) {
        Ok(())
    } else {
        Err(stack.error(b"spline table expected"))
    }
}
fn integer(stack: &NativeStack<'_, '_>, index: isize, unsigned: bool) -> Result<f64, Error> {
    let n = stack.number(index)?.trunc();
    let valid = if unsigned {
        (0.0..(usize::MAX as f64)).contains(&n)
    } else {
        (i64::MIN as f64..-(i64::MIN as f64)).contains(&n)
    };
    if valid {
        Ok(n)
    } else {
        Err(stack.error(b"spline integer is out of range"))
    }
}
fn assign(
    stack: &mut NativeStack<'_, '_>,
    owner: usize,
    key: &[u8],
    value: Value,
) -> Result<(), Error> {
    stack.push_bytes(key)?;
    stack.push(value)?;
    stack.set_table(owner as isize, false)
}
fn raw_index(stack: &mut NativeStack<'_, '_>, owner: usize, index: usize) -> Result<(), Error> {
    stack.push(Value::Number(index as f64))?;
    stack.get_table(owner as isize, true)
}
fn raw_assign(
    stack: &mut NativeStack<'_, '_>,
    owner: usize,
    index: usize,
    value: Value,
) -> Result<(), Error> {
    stack.push(Value::Number(index as f64))?;
    stack.push(value)?;
    stack.set_table(owner as isize, true)
}
fn point(stack: &mut NativeStack<'_, '_>, owner: usize, index: usize) -> Result<[f32; 3], Error> {
    let base = stack.top();
    raw_index(stack, owner, index)?;
    let mut out = [0.; 3];
    if stack.value(-1) != Some(Value::Nil) {
        table_at(stack, -1)?;
        let point = stack.top();
        for (axis, value) in out.iter_mut().enumerate() {
            raw_index(stack, point, axis + 1)?;
            if stack.value(-1) != Some(Value::Nil) {
                *value = stack.number(-1)? as f32;
            }
            stack.set_top(point)?;
        }
    }
    stack.set_top(base)?;
    Ok(out)
}
fn push_vector(stack: &mut NativeStack<'_, '_>, values: &[f32]) -> Result<(), Error> {
    stack.create_table(values.len(), 0)?;
    let table = stack.top();
    for (i, value) in values.iter().enumerate() {
        raw_assign(stack, table, i + 1, Value::Number(*value as f64))?;
    }
    Ok(())
}

fn spline_method(call: &mut HostCall<'_>) -> Result<(), Error> {
    let name = *call.function_data::<&'static str>().unwrap();
    let owner = call.captures()[0];
    // Reserve argument slots before adding temporaries. Native spline methods
    // always use argument two, even for detached or non-table receiver calls.
    let mut stack = call.native_stack()?;
    stack.set_top(stack.top().max(3))?;
    stack.push(owner)?;
    let target = stack.top();
    match name {
        "GetSize" => {
            stack.get_field(target as isize, b"__songlua_spline_size")?;
            let value = integer(&stack, -1, false)?;
            stack.push(Value::Number(value))?;
            return stack.finish(1);
        }
        "get_loop" => {
            stack.get_field(target as isize, b"__songlua_spline_loop")?;
            let value = stack.to_boolean(-1);
            stack.push(Value::Boolean(value))?;
            return stack.finish(1);
        }
        "SetLoop" => {
            let value = stack.to_boolean(2);
            assign(
                &mut stack,
                target,
                b"__songlua_spline_loop",
                Value::Boolean(value),
            )?;
        }
        "SetPolygonal" => (),
        "SetSize" => {
            let size = stack
                .to_number(2)
                .filter(|n| n.is_finite())
                .ok_or_else(|| stack.error(b"Spline size must be a number"))?
                .trunc();
            if size < 0. {
                return Err(stack.error(b"A spline cannot have less than 0 points."));
            }
            if size > 65536. {
                return Err(stack.error(b"Spline exceeds 65536 points"));
            }
            stack.get_field(target as isize, b"__songlua_spline_size")?;
            let prior = integer(&stack, -1, false)? as i64;
            stack.get_field(target as isize, b"__songlua_spline_points")?;
            table_at(&stack, -1)?;
            let points = stack.top();
            stack.get_field(target as isize, b"__songlua_spline_coefficients")?;
            table_at(&stack, -1)?;
            let coefficients = stack.top();
            for index in size as i64 + 1..=prior {
                raw_assign(&mut stack, points, index as usize, Value::Nil)?;
                raw_assign(&mut stack, coefficients, index as usize, Value::Nil)?;
            }
            assign(
                &mut stack,
                target,
                b"__songlua_spline_size",
                Value::Number(size),
            )?;
        }
        "SetPoint" => {
            let index = stack
                .to_number(2)
                .filter(|n| n.is_finite())
                .ok_or_else(|| stack.error(b"Spline point index must be a number"))?
                .trunc();
            stack.get_field(target as isize, b"__songlua_spline_size")?;
            let size = integer(&stack, -1, false)?;
            if index < 1. || index > size {
                return Err(stack.error(b"Spline point index out of range."));
            }
            if !matches!(stack.value(3), Some(Value::Table(_))) {
                return Err(stack.error(b"Spline point must be a table."));
            }
            stack.create_table(3, 0)?;
            let point = stack.top();
            for axis in 1..=stack.object_len(3)?.max(3) {
                let value = if axis <= stack.object_len(3)? {
                    raw_index(&mut stack, 3, axis)?;
                    let n = stack
                        .to_number(-1)
                        .ok_or_else(|| stack.error(b"Spline coordinate must be a number"))?
                        as f32;
                    stack.set_top(point)?;
                    n
                } else {
                    0.
                };
                if axis <= 3 {
                    raw_assign(&mut stack, point, axis, Value::Number(value as f64))?;
                }
            }
            stack.get_field(target as isize, b"__songlua_spline_points")?;
            table_at(&stack, -1)?;
            let points = stack.top();
            let value = stack.value(point as isize).unwrap();
            raw_assign(&mut stack, points, index as usize, value)?;
        }
        "Solve" => solve(&mut stack, target)?,
        "evaluate" => {
            let t = stack
                .to_number(2)
                .ok_or_else(|| stack.error(b"Spline evaluation requires a number"))?
                as f32;
            let value = evaluate(&mut stack, target, t)?;
            push_vector(&mut stack, &value)?;
            return stack.finish(1);
        }
        _ => unreachable!(),
    }
    stack.push(owner)?;
    stack.finish(1)
}

fn solve(stack: &mut NativeStack<'_, '_>, owner: usize) -> Result<(), Error> {
    stack.get_field(owner as isize, b"__songlua_spline_size")?;
    let size = integer(stack, -1, true)? as usize;
    stack.get_field(owner as isize, b"__songlua_spline_points")?;
    table_at(stack, -1)?;
    let table = stack.top();
    let mut points = Vec::new();
    points
        .try_reserve_exact(size)
        .map_err(|_| stack.error(b"spline point allocation failed"))?;
    for index in 1..=size {
        points.push(point(stack, table, index)?);
    }
    stack.get_field(owner as isize, b"__songlua_spline_loop")?;
    let looping = stack.to_boolean(-1);
    let mut solver = deadsync_gameplay::SongLuaSplineSolver::default();
    let coefficients = solver.solve_with_loop(&points, looping);
    stack.create_table(coefficients.len(), 0)?;
    let result = stack.top();
    for (index, point) in coefficients.iter().enumerate() {
        stack.create_table(3, 0)?;
        let axes = stack.top();
        for (axis, values) in point.iter().enumerate() {
            push_vector(stack, &values[1..])?;
            let value = stack.value(-1).unwrap();
            raw_assign(stack, axes, axis + 1, value)?;
            stack.set_top(axes)?;
        }
        let value = stack.value(axes as isize).unwrap();
        raw_assign(stack, result, index + 1, value)?;
        stack.set_top(result)?;
    }
    let value = stack.value(result as isize).unwrap();
    assign(stack, owner, b"__songlua_spline_coefficients", value)
}
fn evaluate(stack: &mut NativeStack<'_, '_>, owner: usize, t: f32) -> Result<[f32; 3], Error> {
    stack.get_field(owner as isize, b"__songlua_spline_size")?;
    let size = integer(stack, -1, true)? as usize;
    if size == 0 {
        return Ok([0.; 3]);
    }
    let index = t as i32;
    stack.get_field(owner as isize, b"__songlua_spline_loop")?;
    let (index, fraction) = if stack.to_boolean(-1) {
        let mut wrapped = t % size as f32;
        if wrapped < 0. {
            wrapped += size as f32;
        }
        (wrapped as usize, wrapped - wrapped.trunc())
    } else if index < 0 {
        (0, 0.)
    } else if index as usize >= size - 1 {
        (size - 1, 0.)
    } else {
        (index as usize, t - index as f32)
    };
    let square = fraction * fraction;
    let cube = square * fraction;
    stack.get_field(owner as isize, b"__songlua_spline_points")?;
    table_at(stack, -1)?;
    let table = stack.top();
    let mut values = point(stack, table, index + 1)?;
    stack.get_field(owner as isize, b"__songlua_spline_coefficients")?;
    table_at(stack, -1)?;
    let table = stack.top();
    raw_index(stack, table, index + 1)?;
    if stack.value(-1) != Some(Value::Nil) {
        table_at(stack, -1)?;
        let coefficients = stack.top();
        for (axis, value) in values.iter_mut().enumerate() {
            let [b, c, d] = point(stack, coefficients, axis + 1)?;
            *value = *value + b * fraction + c * square + d * cube;
        }
    }
    Ok(values)
}

