const COPY: &[u8] = br#"
local type,next,rawget,rawset,sub,error = type,next,rawget,rawset,string.sub,error
local exact={__songlua_visible=true,__songlua_native_name=true,__songlua_wrappers=true,
 __songlua_hibernate_seconds=true,__songlua_theme_hibernating=true,__songlua_update_rate=true,
 __songlua_current_x=true,__songlua_current_y=true,__songlua_current_z=true,
 __songlua_diffuse=true,__songlua_text_attributes=true,__songlua_stroke_color=true,
 __songlua_aux=true,__songlua_stream_width=true,__songlua_sprite_animation_length_seconds=true,
 __songlua_sprite_effect_mode=true,Text=true,Texture=true,File=true,StreamWidth=true}
local function clone(v)
 if type(v)~='table' then return v end
 local out={};for k,x in next,v do rawset(out,clone(k),clone(x)) end;return out
end
return function(actor,mutable)
 local out={}
 for k,v in next,actor do
  if type(k)=='string' and (exact[k] or sub(k,1,16)=='__songlua_state_' or
   sub(k,1,24)=='__songlua_graph_display_' or sub(k,1,19)=='__songlua_scroller_' or
   sub(k,1,14)=='__songlua_aft_' or sub(k,1,23)=='__songlua_command_queue' or
   sub(k,1,27)=='__songlua_recurring_update_' or
   (mutable and sub(k,1,18)=='__songlua_capture_')) then
    if k=='__songlua_wrappers' and type(v)=='table' then
     local copy={};local i=1;while rawget(v,i)~=nil do
      local w=rawget(v,i);if type(w)~='table'then error('wrapper table expected')end
      copy[i]=w;i=i+1
     end;rawset(out,k,copy)
    else rawset(out,k,clone(v)) end
  end
 end
 return out
end
"#;
pub(super) fn install(vm: &mut Vm, helpers: TableId) -> Result<(), Error> {
    let code = compile_named(COPY, b"=manual actor draw snapshot")?;
    let function = vm.execute(&code)?[0];
    super::super::put(vm, helpers, "manual_state_snapshot", function)
}
pub(super) fn write(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    state: &SongLuaOverlayState,
) -> Result<TableId, Error> {
    validate_keys(call, actor)?;
    let snapshot = copy_validated(call, actor)?;
    let value = Value::Table(snapshot);
    let live = store
        .lock()
        .unwrap()
        .clock
        .live
        .load(std::sync::atomic::Ordering::Relaxed);
    call.with_roots(&[value], |call| {
        let default = SongLuaOverlayState::default();
        for &(target, key) in FIELDS {
            // The constructor infers an unbound Sprite in Rust metadata, but
            // native semantic snapshots omit that inferred flag. With no actor
            // type on the snapshot, its later reader defaults to a bound texture.
            // Explicit texture setters publish the flag into the raw table.
            if target == Target::SpriteTexture && get(call, snapshot, key.as_bytes())? == Value::Nil
            {
                continue;
            }
            let value = crate::perframe::overlay_state_update_value(state, target);
            let overrides = live && live_override(target);
            if !overrides
                && (get(call, snapshot, key.as_bytes())? != Value::Nil
                    || value == crate::perframe::overlay_state_update_value(&default, target))
            {
                continue;
            }
            let value = encode(call, &value)?;
            song_replay::raw_set(call, snapshot, key, value)?;
        }
        for (key, value, changed) in [
            (
                "__songlua_visible",
                Value::Boolean(state.visible),
                !state.visible,
            ),
            (
                "__songlua_hibernate_seconds",
                Value::Number(if state.hibernating { 1. } else { 0. }),
                state.hibernating,
            ),
            (
                "__songlua_state_decode_movie",
                Value::Boolean(state.decode_movie),
                state.decode_movie,
            ),
        ] {
            if changed && get(call, snapshot, key.as_bytes())? == Value::Nil {
                song_replay::raw_set(call, snapshot, key, value)?;
            }
        }
        Ok(snapshot)
    })
}
fn validate_keys(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    // Native snapshot iteration validates string keys but never calls authored
    // property getters. Preserve that boundary before copying raw semantic data.
    {
        let mut stack = call.native_stack()?;
        let base = stack.top();
        stack.push(Value::Table(actor))?;
        let table = stack.top_offset();
        stack.push(Value::Nil)?;
        while stack.next_table(table)? {
            if matches!(stack.value(-2), Some(Value::String(_))) {
                let valid = std::str::from_utf8(stack.to_bytes(-2)?.unwrap()).is_ok();
                if !valid {
                    return Err(stack.error(b"actor snapshot key is not UTF-8"));
                }
            }
            stack.set_top(stack.top() - 1)?;
        }
        stack.set_top(base)?;
    }
    Ok(())
}

/// Copy only native semantic fields; inferred Rust defaults are kept separately.
pub(super) fn raw_copy(call: &mut HostCall<'_>, actor: TableId) -> Result<TableId, Error> {
    copy_selected(call, actor, false)
}
pub(super) fn raw_copy_mutable(call: &mut HostCall<'_>, actor: TableId) -> Result<TableId, Error> {
    copy_selected(call, actor, true)
}
fn copy_selected(call: &mut HostCall<'_>, actor: TableId, mutable: bool) -> Result<TableId, Error> {
    let validate = call.new_host_function(
        |call| {
            let actor = table(call, call.captures()[0])?;
            validate_keys(call, actor)
        },
        &[Value::Table(actor)],
    )?;
    call.call(validate, &[])?;
    let function = native_children::helper_function(call, b"manual_state_snapshot")?;
    let value = call.call(function, &[Value::Table(actor), Value::Boolean(mutable)])?[0];
    table(call, value)
}
fn copy_validated(call: &mut HostCall<'_>, actor: TableId) -> Result<TableId, Error> {
    let function = native_children::helper_function(call, b"manual_state_snapshot")?;
    let value = call.call(function, &[Value::Table(actor)])?[0];
    table(call, value)
}
fn semantic(key: &str) -> bool {
    [
        "__songlua_state_",
        "__songlua_graph_display_",
        "__songlua_scroller_",
        "__songlua_aft_",
        "__songlua_command_queue",
        "__songlua_recurring_update_",
    ]
    .iter()
    .any(|prefix| key.starts_with(prefix))
        || matches!(
            key,
            "__songlua_visible"
                | "__songlua_native_name"
                | "__songlua_wrappers"
                | "__songlua_hibernate_seconds"
                | "__songlua_theme_hibernating"
                | "__songlua_update_rate"
                | "__songlua_current_x"
                | "__songlua_current_y"
                | "__songlua_current_z"
                | "__songlua_diffuse"
                | "__songlua_text_attributes"
                | "__songlua_stroke_color"
                | "__songlua_aux"
                | "__songlua_stream_width"
                | "__songlua_sprite_animation_length_seconds"
                | "__songlua_sprite_effect_mode"
                | "Text"
                | "Texture"
                | "File"
                | "StreamWidth"
        )
}
/// Raw writes also permit cleanup after an execution limit. Ordinary rewinds
/// retain native __newindex callbacks and their ordering/error behavior.
pub(super) fn restore_raw(
    call: &mut HostCall<'_>,
    actor: TableId,
    saved: TableId,
    raw: bool,
) -> Result<(), Error> {
    restore_selected(call, actor, saved, raw, false)
}
pub(super) fn restore_mutable(
    call: &mut HostCall<'_>,
    actor: TableId,
    saved: TableId,
    raw: bool,
) -> Result<(), Error> {
    restore_selected(call, actor, saved, raw, true)
}
fn restore_selected(
    call: &mut HostCall<'_>,
    actor: TableId,
    saved: TableId,
    raw: bool,
    mutable: bool,
) -> Result<(), Error> {
    let output = Arc::new(Mutex::new(None::<RestoreEntries>));
    let scan = call.new_host_function_with_data(
        scan_restore,
        &[Value::Table(actor), Value::Table(saved)],
        (output.clone(), mutable),
    )?;
    call.call(scan, &[])?;
    let (keys, entries) = output.lock().unwrap().take().unwrap();
    for (key, value) in keys.into_iter().map(|key| (key, Value::Nil)).chain(entries) {
        if raw {
            call.raw_table_set(actor, key, value)?
        } else {
            call.table_set(Value::Table(actor), key, value)?
        }
    }
    Ok(())
}

type RestoreEntries = (Vec<Value>, Vec<(Value, Value)>);
fn scan_restore(call: &mut HostCall<'_>) -> Result<(), Error> {
    let actor = table(call, call.captures()[0])?;
    let saved = table(call, call.captures()[1])?;
    let (output, mutable) = call
        .function_data::<(Arc<Mutex<Option<RestoreEntries>>>, bool)>()
        .unwrap()
        .clone();
    let entries = {
        let mut stack = call.native_stack()?;
        let base = stack.top();
        let mut keys = Vec::new();
        let mut entries = Vec::new();
        stack.push(Value::Table(actor))?;
        let actor_index = stack.top_offset();
        stack.push(Value::Nil)?;
        while stack.next_table(actor_index)? {
            if matches!(stack.value(-2), Some(Value::String(_))) {
                let selected = std::str::from_utf8(stack.to_bytes(-2)?.unwrap())
                    .map(|key| semantic(key) || mutable && key.starts_with("__songlua_capture_"));
                match selected {
                    Ok(true) => keys.push(stack.value(-2).unwrap()),
                    Ok(false) => {}
                    Err(error) => return Err(stack.error(error.to_string().as_bytes())),
                }
            }
            stack.set_top(stack.top() - 1)?;
        }
        stack.set_top(base)?;
        stack.push(Value::Table(saved))?;
        let saved_index = stack.top_offset();
        stack.push(Value::Nil)?;
        while stack.next_table(saved_index)? {
            entries.push((stack.value(-2).unwrap(), stack.value(-1).unwrap()));
            stack.set_top(stack.top() - 1)?;
        }
        stack.set_top(base)?;
        (keys, entries)
    };
    *output.lock().unwrap() = Some(entries);
    Ok(())
}

fn live_override(target: Target) -> bool {
    matches!(
        target,
        Target::Aux
            | Target::X
            | Target::Y
            | Target::Z
            | Target::Zoom
            | Target::ZoomX
            | Target::ZoomY
            | Target::ZoomZ
            | Target::SkewX
            | Target::SkewY
            | Target::CropLeft
            | Target::CropRight
            | Target::CropTop
            | Target::CropBottom
            | Target::FadeLeft
            | Target::FadeRight
            | Target::FadeTop
            | Target::FadeBottom
            | Target::Diffuse
            | Target::Glow
            | Target::VertexColors
            | Target::DrawByZPosition
            | Target::MaskSource
            | Target::MaskDest
            | Target::DepthTest
            | Target::DepthWrite
            | Target::DepthTestOnFail
            | Target::TextureFiltering
            | Target::TextureWrapping
            | Target::BaseZoom
            | Target::BaseZoomX
            | Target::BaseZoomY
            | Target::BaseZoomZ
            | Target::HAlign
            | Target::VAlign
    )
}
fn encode(call: &mut HostCall<'_>, value: &Update) -> Result<Value, Error> {
    Ok(match value {
        Update::None => Value::Nil,
        Update::F32(n) => Value::Number(f64::from(*n)),
        Update::I32(n) => Value::Number(f64::from(*n)),
        Update::U32(n) => Value::Number(f64::from(*n)),
        Update::Bool(b) => Value::Boolean(*b),
        Update::Vec2(v) => sprites::vector_value(call, v)?,
        Update::Vec3(v) => sprites::vector_value(call, v)?,
        Update::Vec4(v) | Update::Quaternion(v) => sprites::vector_value(call, v)?,
        Update::Vec5(v) => sprites::vector_value(call, v)?,
        Update::VertexColors(v) => {
            let rows = call.try_new_table()?;
            call.with_roots(&[Value::Table(rows)], |call| {
                for (i, v) in v.iter().enumerate() {
                    let value = sprites::vector_value(call, v)?;
                    call.raw_table_set(rows, Value::Number((i + 1) as f64), value)?;
                }
                Ok(Value::Table(rows))
            })?
        }
        Update::CullMode(mode) => Value::Number(match mode {
            deadlib_render_core::CullMode::None => 0.,
            deadlib_render_core::CullMode::Back => 1.,
            deadlib_render_core::CullMode::Front => 2.,
        }),
        Update::TextAlign(v) => call.try_intern(crate::overlay_text_align_label(*v).as_bytes())?,
        Update::EffectClock(v) => call.try_intern(crate::effect_clock_label(*v).as_bytes())?,
        Update::EffectMode(v) => call.try_intern(crate::effect_mode_label(*v).as_bytes())?,
        Update::TextGlowMode(v) => call.try_intern(crate::text_glow_mode_label(*v).as_bytes())?,
        Update::Blend(v) => call.try_intern(format!("{v:?}").as_bytes())?,
    })
}

//! Existing StepsDisplay children, SetInternal ordering and gameplay metrics.
use super::*;
use native_children::{run_command, with_children};
use sprites::field;

const COMMANDS: &[u8] = br#"return function()
return {
    FrameLoadCommand = function(self,param) local bFlip = param.PlayerState and param.PlayerState:GetPlayerNumber() ~= PLAYER_1; self:zoomx(bFlip and -1 or 1); end,
    FrameSetCommand = function(self,param) if param.CustomDifficulty and param.CustomDifficulty ~= "" then self:diffuse(CustomDifficultyToColor(param.CustomDifficulty)) end end,
    MeterOnCommand = function(self) self:visible(false) end,
    MeterSetCommand = function(self,param) MESSAGEMAN:Broadcast("MeterSet") end,
    DescriptionOnCommand = function(self) self:zoom(0.8):horizalign("left"):vertspacing(-9):_wrapwidthpixels(345) end,
    DescriptionSetCommand = function(self,params) self:visible(params.Steps ~= nil and params.Steps:GetDifficulty()=="Difficulty_Edit") end,
}
end"#;

#[derive(Clone)]
struct Binding {
    store: Shared,
    method: &'static str,
}

impl Actors {
    pub(in crate::rust_engine) fn initialize_steps_displays(
        &self,
        vm: &mut Vm,
        screen: Value,
    ) -> Result<(), Error> {
        ensure_helpers(vm, self.helpers)?;
        let function = vm.new_host_function_with_data(
            initialize_callback,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            self.store.clone(),
        )?;
        vm.call(function, &[screen]).map(|_| ())
    }
}

pub(super) fn ensure_helpers(vm: &mut Vm, helpers: TableId) -> Result<(), Error> {
    let key = vm.try_intern(b"steps_display_commands")?;
    if vm.raw_table_get(helpers, key)? == Value::Nil {
        let code = compile_named(COMMANDS, b"@theme:/metrics.ini:StepsDisplayGameplay")?;
        let factory = vm.execute(&code)?[0];
        super::super::put(vm, helpers, "steps_display_commands", factory)?;
    }
    Ok(())
}

fn raw(call: &mut HostCall<'_>, actor: TableId, name: &str, value: Value) -> Result<(), Error> {
    let key = call.try_intern(name.as_bytes())?;
    call.raw_table_set(actor, key, value)
}

pub(super) fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    let actor = generated_players::dummy(call, store, scene, "StepsDisplay", name, None)?;
    raw(
        call,
        actor,
        "__songlua_owned_child_lookup",
        Value::Boolean(true),
    )?;
    for (name, kind) in [
        ("Frame", "Sprite"),
        ("Meter", "BitmapText"),
        ("Description", "BitmapText"),
        ("Autogen", "Sprite"),
    ] {
        let child = generated_players::dummy(call, store, scene, kind, name, Some(actor))?;
        if kind == "Sprite" {
            screen_parts::blank_texture(call, store, child)?;
        } else {
            let font = call.try_intern(b"Common Normal")?;
            raw(call, child, "Font", font)?;
            let empty = call.try_intern(b"")?;
            raw(call, child, "Text", empty)?;
        }
        screen_parts::append(call, store, actor, child)?;
        screen_parts::named(call, store, actor, name, child)?;
    }
    let bound = get(call, actor, b"__songlua_bound_methods")?;
    let bound = table(call, bound)?;
    for method in ["SetFromSteps", "SetFromTrail", "SetFromGameState"] {
        let function = call.new_host_function_with_data(
            invoke,
            &[call.captures()[0], call.captures()[1]],
            Binding {
                store: store.clone(),
                method,
            },
        )?;
        raw(call, bound, method, function)?;
    }
    Ok(actor)
}

fn value_call(
    call: &mut HostCall<'_>,
    receiver: TableId,
    method: &str,
    arguments: &[Value],
) -> Result<Value, Error> {
    let function = field(call, receiver, method)?;
    if !matches!(function, Value::Function(_) | Value::Native(_)) {
        return Err(call.error(b"function expected"));
    }
    let mut args = Vec::with_capacity(arguments.len() + 1);
    args.push(Value::Table(receiver));
    args.extend_from_slice(arguments);
    Ok(call
        .call(function, &args)?
        .first()
        .copied()
        .unwrap_or(Value::Nil))
}

fn truthy(value: Value) -> bool {
    !matches!(value, Value::Nil | Value::Boolean(false))
}

fn optional_table(call: &HostCall<'_>, value: Value) -> Result<Option<TableId>, Error> {
    if value == Value::Nil {
        Ok(None)
    } else {
        table(call, value).map(Some)
    }
}

fn visibility(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    visible: bool,
) -> Result<(), Error> {
    raw(call, actor, "__songlua_visible", Value::Boolean(visible))?;
    if let Some(actor) = store.lock().unwrap().actors.get_mut(&actor) {
        actor.state.visible = visible;
    }
    Ok(())
}

fn registry(call: &mut HostCall<'_>, actor: TableId) -> Result<Value, Error> {
    let function = native_children::helper_function(call, b"native_registry")?;
    Ok(call.call(function, &[Value::Table(actor)])?[0])
}

fn child(call: &mut HostCall<'_>, registry: TableId, name: &str) -> Result<TableId, Error> {
    let value = get(call, registry, name.as_bytes())?;
    table(call, value)
}

fn direct_message(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Value,
) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor), params], |call| {
        run_command(call, store, actor, name, Some(params))?;
        let kind = assets::field(call, actor, b"__songlua_actor_type")?.unwrap_or_default();
        if ["ActorFrame", "ActorFrameTexture", "TopScreen"]
            .iter()
            .any(|k| kind.eq_ignore_ascii_case(k))
        {
            with_children(call, actor, |call, child| {
                direct_message(call, store, child, name, params)
            })?;
        }
        Ok(())
    })
}

fn set_value(
    call: &mut HostCall<'_>,
    store: &Shared,
    display: TableId,
    value: Option<TableId>,
    trail: bool,
) -> Result<(), Error> {
    call.with_roots(&[value.map_or(Value::Nil, Value::Table)], |call| {
        let (difficulty, steps_type, meter) = if let Some(value) = value {
            let difficulty = value_call(call, value, "GetDifficulty", &[])?;
            let difficulty = assets::text(call, difficulty)?;
            let steps_type = value_call(call, value, "GetStepsType", &[])?;
            let steps_type = assets::text(call, steps_type)?;
            let meter = value_call(call, value, "GetMeter", &[])?;
            let meter = sprites::number(call, meter)?.trunc();
            if !(i32::MIN as f64..=i32::MAX as f64).contains(&meter) {
                return Err(call.error(b"steps meter is out of range"));
            }
            (difficulty, steps_type, meter as i32)
        } else {
            let difficulty = get(call, display, b"__songlua_preferred_difficulty")?;
            (
                assets::text(call, difficulty)?,
                "StepsType_Invalid".into(),
                0,
            )
        };
        let short = difficulty
            .strip_prefix("Difficulty_")
            .unwrap_or(&difficulty);
        let custom = match (steps_type.as_str(), short) {
            ("StepsType_Pump_Single", "Hard") => "Crazy",
            ("StepsType_Pump_Double", "Medium") => "Freestyle",
            ("StepsType_Pump_Double", "Hard") => "Nightmare",
            ("StepsType_Pump_Halfdouble", "Medium") => "HalfDouble",
            (_, "Invalid") => "",
            _ => short,
        };
        let description = if !trail
            && short == "Edit"
            && let Some(value) = value
        {
            let text = value_call(call, value, "GetDescription", &[])?;
            assets::text(call, text)?
        } else {
            match custom {
                "Beginner" => "Novice",
                "Challenge" => "Expert",
                _ => custom,
            }
            .into()
        };
        let params = call.try_new_table()?;
        call.with_roots(&[Value::Table(params)], |call| {
            for (key, text) in [
                ("CustomDifficulty", custom),
                ("DisplayDescription", description.as_str()),
                ("StepsType", steps_type.as_str()),
            ] {
                let value = call.try_intern(text.as_bytes())?;
                raw(call, params, key, value)?;
            }
            raw(call, params, "Meter", Value::Number(meter as f64))?;
            if let Some(value) = value {
                raw(
                    call,
                    params,
                    if trail { "Trail" } else { "Steps" },
                    Value::Table(value),
                )?;
            }
            let params = Value::Table(params);
            visibility(call, store, display, true)?;
            let children = registry(call, display)?;
            call.with_roots(&[children], |call| {
                let children = table(call, children)?;
                // Native Table handles keep every selected child alive until
                // SetInternal returns, even after callbacks replace its registry.
                let held = call.try_new_table()?;
                call.with_roots(&[Value::Table(held)], |call| {
                    let frame = child(call, children, "Frame")?;
                    call.raw_table_set(held, Value::Number(1.), Value::Table(frame))?;
                    direct_message(call, store, frame, b"Set", params)?;
                    let text = child(call, children, "Meter")?;
                    call.raw_table_set(held, Value::Number(2.), Value::Table(text))?;
                    let meter_text = if meter == 0 {
                        "?".into()
                    } else {
                        meter.to_string()
                    };
                    let meter_text = call.try_intern(meter_text.as_bytes())?;
                    raw(call, text, "Text", meter_text)?;
                    if meter != 0 {
                        direct_message(call, store, text, b"Set", params)?;
                    }
                    let text = child(call, children, "Description")?;
                    call.raw_table_set(held, Value::Number(3.), Value::Table(text))?;
                    let description = call.try_intern(description.as_bytes())?;
                    raw(call, text, "Text", description)?;
                    direct_message(call, store, text, b"Set", params)?;
                    let autogen = child(call, children, "Autogen")?;
                    call.raw_table_set(held, Value::Number(4.), Value::Table(autogen))?;
                    call.with_roots(&[Value::Table(autogen)], |call| {
                        direct_message(call, store, autogen, b"Set", params)?;
                        let autogen_value = if !trail && let Some(value) = value {
                            truthy(value_call(call, value, "IsAutogen", &[])?)
                        } else {
                            false
                        };
                        visibility(call, store, autogen, autogen_value)
                    })?;
                    run_command(call, store, display, b"Set", Some(params))?;
                    with_children(call, display, |call, child| {
                        direct_message(call, store, child, b"Set", params)
                    })
                })
            })
        })
    })
}

fn invoke(call: &mut HostCall<'_>) -> Result<(), Error> {
    let Binding { store, method } = call.function_data::<Binding>().unwrap().clone();
    let display = table(call, arg(call, 0))?;
    let value = arg(call, 1);
    if method == "SetFromGameState" {
        let globals = table(call, helper(call, 5)?)?;
        let game = field(call, globals, "GAMESTATE")?;
        call.with_roots(&[game], |call| {
            let game = table(call, game)?;
            let trail = truthy(value_call(call, game, "IsCourseMode", &[])?);
            let value = value_call(
                call,
                game,
                if trail {
                    "GetCurrentTrail"
                } else {
                    "GetCurrentSteps"
                },
                &[value],
            )?;
            set_value(call, &store, display, optional_table(call, value)?, trail)
        })?;
    } else if let Some(value) = optional_table(call, value)? {
        set_value(call, &store, display, Some(value), method == "SetFromTrail")?;
    } else {
        visibility(call, &store, display, false)?;
    }
    // The typed counter conversion and increment happen only after all callbacks.
    let globals = table(call, helper(call, 5)?)?;
    let count = field(call, globals, crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY)?;
    let count = if count == Value::Nil {
        0
    } else {
        let count = sprites::number(call, count)?;
        if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&count) {
            return Err(call.error(b"side effect count is out of range"));
        }
        count as i64
    };
    sprites::set(
        call,
        globals,
        crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY,
        Value::Number(count.saturating_add(1) as f64),
    )?;
    call.push(Value::Table(display))
}

fn initialize_callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let store = call.function_data::<Shared>().unwrap().clone();
    let screen = table(call, arg(call, 0))?;
    initialize(call, &store, screen)
}

pub(super) fn initialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    screen: TableId,
) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let game = field(call, globals, "GAMESTATE")?;
    call.with_roots(&[game], |call| {
        let game = table(call, game)?;
        let factory = native_children::helper_function(call, b"steps_display_commands")?;
        let commands = call.call(factory, &[])?[0];
        call.with_roots(&[commands], |call| {
            let commands = table(call, commands)?;
            for index in 0..crate::LUA_PLAYERS {
                let children = registry(call, screen)?;
                let display = call.with_roots(&[children], |call| {
                    let value = get(
                        call,
                        table(call, children)?,
                        format!("StepsDisplayP{}", index + 1).as_bytes(),
                    )?;
                    optional_table(call, value)
                })?;
                let Some(display) = display else { continue };
                for (name, x) in [
                    ("Frame", 0.),
                    ("Meter", 30.),
                    ("Description", -265.),
                    ("Autogen", 40.),
                ] {
                    let children = registry(call, display)?;
                    let actor = call.with_roots(&[children], |call| {
                        child(call, table(call, children)?, name)
                    })?;
                    {
                        let mut guard = store.lock().unwrap();
                        let actor = guard.actors.get_mut(&actor).ok_or_else(|| {
                            call.error(b"steps display child is not owned by this runtime")
                        })?;
                        let pose = actor.destination_mut();
                        pose.x = x;
                        pose.y = 0.;
                    }
                    for command in ["Load", "On", "Set"] {
                        let callback =
                            get(call, commands, format!("{name}{command}Command").as_bytes())?;
                        if callback != Value::Nil {
                            raw(call, actor, &format!("{command}Command"), callback)?;
                        }
                    }
                    run_named(call, store, actor, b"On", None)?;
                }
                let player = call.try_intern(crate::player_number_name(index).as_bytes())?;
                let params = Value::Table(call.try_new_table()?);
                call.with_roots(&[player, params], |call| {
                    let state = value_call(call, game, "GetPlayerState", &[player])?;
                    table(call, state)?;
                    raw(call, table(call, params)?, "PlayerState", state)?;
                    with_children(call, display, |call, child| {
                        direct_message(call, store, child, b"Load", params)
                    })?;
                    visibility(call, store, display, false)?;
                    let steps = value_call(call, game, "GetCurrentSteps", &[player])?;
                    if let Some(steps) = optional_table(call, steps)? {
                        set_value(call, store, display, Some(steps), false)?;
                    }
                    Ok(())
                })?;
            }
            Ok(())
        })
    })
}

//! BitmapText bindings and immutable renderer payloads over the Rust host API.
use super::action_capture;
use super::{
    Shared, arg, assets, boolish, float_scalar, get, helper, integer_scalar, render, song_media,
    sprites, table,
};
use deadlib_lua::{Error, ErrorKind, HostCall, TableId, Value};
use deadlib_present::actors::TextAttribute;
use sprites::{field, set, vector, vector_value};
use std::{path::PathBuf, sync::Arc};

#[derive(Clone, Debug)]
pub struct BitmapText {
    pub font: Option<(&'static str, PathBuf)>,
    pub text: Arc<str>,
    pub stroke_color: Option<[f32; 4]>,
    pub attributes: Arc<[TextAttribute]>,
}

pub(super) const METHODS: &[&str] = &[
    "wrapwidthpixels",
    "maxwidth",
    "maxheight",
    "max_dimension_use_zoom",
    "vertspacing",
    "settext",
    "rainbowscroll",
    "jitter",
    "distort",
    "undistort",
    "GetText",
    "AddAttribute",
    "ClearAttributes",
    "strokecolor",
    "getstrokecolor",
    "uppercase",
    "textglowmode",
    "get_mult_attrs_with_diffuse",
    "set_mult_attrs_with_diffuse",
];
const ATTRIBUTES: &str = "__songlua_text_attributes";

pub(super) fn text_value(call: &mut HostCall<'_>, value: Value) -> Result<String, Error> {
    match value {
        Value::String(_) => assets::text(call, value),
        Value::Number(n) => Ok(n.to_string()),
        Value::Boolean(b) => Ok(b.to_string()),
        _ => Ok(String::new()),
    }
}
pub(super) fn content(call: &mut HostCall<'_>, actor: TableId) -> Result<String, Error> {
    let value = field(call, actor, "Text")?;
    text_value(call, value)
}

pub(super) fn global_color(call: &mut HostCall<'_>) -> Result<(), Error> {
    let value = match render::color_at(call, 0)? {
        Some(color) => vector_value(call, &color)?,
        None => Value::Nil,
    };
    call.push(value)
}

fn color_value(call: &mut HostCall<'_>, value: Value) -> Result<Option<[f32; 4]>, Error> {
    match value {
        Value::String(_) => {
            Ok(render::text(call, value).map(|v| crate::parse_color_text(v).unwrap_or([1.; 4])))
        }
        Value::Table(t) => call.with_roots(&[value], |call| {
            let mut color = [1.; 4];
            for (i, component) in color.iter_mut().enumerate() {
                let value = call.raw_table_get(t, Value::Number((i + 1) as f64))?;
                if i == 3 && value == Value::Nil {
                    continue;
                }
                let Value::Number(n) = call.call(helper(call, 6)?, &[value])?[0] else {
                    return Ok(None);
                };
                *component = n as f32;
            }
            Ok(Some(color))
        }),
        _ => Ok(None),
    }
}

fn colors(
    call: &mut HostCall<'_>,
    value: Value,
    permissive: bool,
) -> Result<Option<[[f32; 4]; 4]>, Error> {
    let Value::Table(t) = value else {
        return Ok(None);
    };
    call.with_roots(&[value], |call| {
        let mut colors = [[1.; 4]; 4];
        let mut saw = false;
        for (i, color) in colors.iter_mut().enumerate() {
            let value = call.raw_table_get(t, Value::Number((i + 1) as f64))?;
            let read = if permissive {
                color_value(call, value)?
            } else if matches!(value, Value::Table(_)) {
                vector(call, value)?
            } else {
                None
            };
            if let Some(read) = read {
                *color = read;
                saw = true;
            } else if !permissive {
                return Ok(None);
            }
        }
        Ok(saw.then_some(colors))
    })
}

fn first(call: &mut HostCall<'_>, params: TableId, keys: &[&str]) -> Result<Value, Error> {
    for key in keys {
        let value = field(call, params, key)?;
        if value != Value::Nil {
            return Ok(value);
        }
    }
    Ok(Value::Nil)
}
fn optional_table(call: &HostCall<'_>, value: Value) -> Result<Option<TableId>, Error> {
    if value == Value::Nil {
        Ok(None)
    } else {
        table(call, value).map(Some)
    }
}
fn raw_color(
    call: &mut HostCall<'_>,
    entry: TableId,
    key: &[u8],
    strict: bool,
) -> Result<Option<[f32; 4]>, Error> {
    let value = get(call, entry, key)?;
    if strict || matches!(value, Value::Table(_)) {
        vector(call, value)
    } else {
        Ok(None)
    }
}
fn strict_integer(
    call: &mut HostCall<'_>,
    entry: TableId,
    key: &[u8],
    default: i32,
) -> Result<i32, Error> {
    let value = get(call, entry, key)?;
    if value == Value::Nil {
        return Ok(default);
    }
    let n = sprites::number(call, value)?.trunc();
    if n >= i32::MIN as f64 && n <= i32::MAX as f64 {
        Ok(n as i32)
    } else {
        Err(call.error(b"integer out of range"))
    }
}

fn add_attribute(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let Some(start) = integer_scalar(call, arg(call, 1)).map(|n| n.max(0)) else {
        return Ok(());
    };
    let Value::Table(params) = arg(call, 2) else {
        return Ok(());
    };
    let value = first(call, params, &["Length", "length"])?;
    let length = integer_scalar(call, value).unwrap_or(1);
    if length == 0 {
        return Ok(());
    }
    let value = first(call, params, &["Diffuses", "diffuses"])?;
    let mut vertex_colors = colors(call, value, true)?.unwrap_or([[1.; 4]; 4]);
    let value = first(
        call,
        params,
        &[
            "Diffuse",
            "diffuse",
            "DiffuseColor",
            "diffusecolor",
            "Color",
            "color",
        ],
    )?;
    if let Some(color) = color_value(call, value)? {
        vertex_colors = [color; 4];
    }
    let color = vertex_colors[0];
    let value = first(call, params, &["Glow", "glow"])?;
    let glow = color_value(call, value)?;
    let attr = call.try_new_table()?;
    call.with_roots(&[Value::Table(attr)], |call| {
        set(call, attr, "start", Value::Number(start as f64))?;
        set(call, attr, "length", Value::Number(length as f64))?;
        let value = vector_value(call, &color)?;
        set(call, attr, "color", value)?;
        if vertex_colors != [color; 4] {
            let rows = call.try_new_table()?;
            set(call, attr, "vertex_colors", Value::Table(rows))?;
            for (i, color) in vertex_colors.iter().enumerate() {
                let value = vector_value(call, color)?;
                call.raw_table_set(rows, Value::Number((i + 1) as f64), value)?;
            }
        }
        if let Some(glow) = glow {
            let value = vector_value(call, &glow)?;
            set(call, attr, "glow", value)?;
        }
        let value = field(call, actor, ATTRIBUTES)?;
        let attrs = match optional_table(call, value)? {
            Some(t) => t,
            None => {
                let t = call.try_new_table()?;
                call.with_roots(&[Value::Table(t)], |call| {
                    set(call, actor, ATTRIBUTES, Value::Table(t))
                })?;
                t
            }
        };
        call.with_roots(&[Value::Table(attrs)], |call| {
            let mut i = 1;
            loop {
                let value = call.raw_table_get(attrs, Value::Number(i as f64))?;
                if value == Value::Nil {
                    break;
                }
                let old = table(call, value)?;
                if strict_integer(call, old, b"start", -1)? == start
                    && strict_integer(call, old, b"length", 0)? == length
                {
                    let old_color = raw_color(call, old, b"color", true)?.unwrap_or([1.; 4]);
                    let value = get(call, old, b"vertex_colors")?;
                    optional_table(call, value)?;
                    let old_colors = colors(call, value, false)?.unwrap_or([old_color; 4]);
                    let old_glow = raw_color(call, old, b"glow", true)?;
                    if old_color == color && old_colors == vertex_colors && old_glow == glow {
                        return Ok(());
                    }
                }
                i += 1;
            }
            let end = call.raw_table_len(attrs)? + 1;
            call.raw_table_set(attrs, Value::Number(end as f64), Value::Table(attr))
        })
    })
}

pub(super) fn attributes(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Arc<[TextAttribute]>, Error> {
    let value = field(call, actor, ATTRIBUTES)?;
    let Some(attrs) = optional_table(call, value)? else {
        return Ok(Arc::from([]));
    };
    call.with_roots(&[value], |call| {
        let mut out = Vec::new();
        let mut i = 1;
        loop {
            let value = call.raw_table_get(attrs, Value::Number(i as f64))?;
            if value == Value::Nil {
                break;
            }
            let entry = table(call, value)?;
            let value = get(call, entry, b"start")?;
            let start = integer_scalar(call, value).unwrap_or(0).max(0) as usize;
            let value = get(call, entry, b"length")?;
            let length = integer_scalar(call, value).unwrap_or(1);
            if length != 0 {
                let color = raw_color(call, entry, b"color", false)?.unwrap_or([1.; 4]);
                let value = get(call, entry, b"vertex_colors")?;
                let vertex_colors = colors(call, value, false)?;
                let glow = raw_color(call, entry, b"glow", false)?;
                out.push(TextAttribute {
                    start,
                    length: if length < 0 {
                        usize::MAX
                    } else {
                        length as usize
                    },
                    color,
                    vertex_colors,
                    glow,
                });
            }
            i += 1;
        }
        Ok(out.into())
    })
}

pub(super) fn stroke(call: &mut HostCall<'_>, actor: TableId) -> Result<Option<[f32; 4]>, Error> {
    let value = field(call, actor, "__songlua_stroke_color")?;
    if let Some(color) = vector(call, value)? {
        return Ok(Some(color));
    }
    let fallback = field(call, actor, "StrokeColor").and_then(|v| vector(call, v));
    match fallback {
        Err(e) if e.kind() == ErrorKind::Runtime => Ok(None),
        result => result,
    }
}
pub(super) fn font(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Option<(&'static str, PathBuf)>, Error> {
    let mut font = None;
    if let Some(name) = assets::field(call, actor, b"Font")? {
        let resolved = match assets::resolve(call, actor, &name) {
            Err(e) if e.kind() == ErrorKind::Runtime => None,
            result => result?,
        };
        font = if let Some(path) = resolved {
            Some((crate::bitmap_font::song_lua_font_name(&path), path))
        } else if crate::bitmap_font::song_lua_uses_builtin_theme_font(&name) {
            Some(("miso", PathBuf::from("assets/fonts/miso/_miso light.ini")))
        } else {
            None
        };
    }
    Ok(font)
}
pub(super) fn read(call: &mut HostCall<'_>, actor: TableId) -> Result<BitmapText, Error> {
    let font = font(call, actor)?;
    let kind = assets::field(call, actor, b"__songlua_actor_type")?.unwrap_or_default();
    if let Some(text) = crate::input_status_actor_text(&kind) {
        return Ok(BitmapText {
            font,
            text: text.into(),
            stroke_color: None,
            attributes: Arc::from([]),
        });
    }
    Ok(BitmapText {
        font,
        text: content(call, actor)?.into(),
        stroke_color: stroke(call, actor)?,
        attributes: attributes(call, actor)?,
    })
}

fn flag(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    key: &str,
    value: bool,
) -> Result<(), Error> {
    action_capture::prepare(call, store, actor)?;
    {
        let mut guard = store.lock().unwrap();
        let state = &mut guard.actors.get_mut(&actor).unwrap().state.render;
        match key {
            "rainbow_scroll" => state.rainbow_scroll = value,
            "text_jitter" => state.text_jitter = value,
            "uppercase" => state.uppercase = value,
            "mult_attrs_with_diffuse" => state.mult_attrs_with_diffuse = value,
            "max_w_pre_zoom" => state.max_w_pre_zoom = value,
            "max_h_pre_zoom" => state.max_h_pre_zoom = value,
            "max_dimension_uses_zoom" => state.max_dimension_uses_zoom = value,
            _ => unreachable!(),
        }
    }
    set(
        call,
        actor,
        &format!("__songlua_state_{key}"),
        Value::Boolean(value),
    )?;
    song_media::record(call, store, actor, key);
    Ok(())
}
pub(super) fn pre_zoom(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    width: bool,
    height: bool,
) -> Result<(), Error> {
    if !super::text_displays::is_text(store.lock().unwrap().actors[&actor].state.class) {
        return Ok(());
    }
    for (enabled, saw, key) in [
        (width, "__songlua_text_saw_max_width", "max_w_pre_zoom"),
        (height, "__songlua_text_saw_max_height", "max_h_pre_zoom"),
    ] {
        if enabled && !matches!(field(call, actor, saw)?, Value::Nil | Value::Boolean(false)) {
            flag(call, store, actor, key, true)?;
        }
    }
    Ok(())
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    match name {
        "settext" => {
            let text = text_value(call, arg(call, 1))?;
            let value = call.try_intern(text.as_bytes())?;
            set(call, actor, "Text", value)?;
        }
        "GetText" => {
            let text = content(call, actor)?;
            let value = call.try_intern(text.as_bytes())?;
            return call.push(value);
        }
        "AddAttribute" => add_attribute(call, actor)?,
        "ClearAttributes" => {
            let t = call.try_new_table()?;
            call.with_roots(&[Value::Table(t)], |call| {
                set(call, actor, ATTRIBUTES, Value::Table(t))
            })?;
        }
        "strokecolor" => {
            if let Some(color) = render::color(call)? {
                let value = vector_value(call, &color)?;
                call.with_roots(&[value], |call| {
                    set(call, actor, "__songlua_stroke_color", value)
                })?;
            }
        }
        "getstrokecolor" => {
            let color = stroke(call, actor)?.unwrap_or([0.; 4]);
            let value = vector_value(call, &color)?;
            return call.push(value);
        }
        "rainbowscroll" | "jitter" | "uppercase" => {
            let Value::Boolean(value) = arg(call, 1) else {
                return Err(call.error(format!("{name}: boolean expected").as_bytes()));
            };
            flag(
                call,
                store,
                actor,
                match name {
                    "rainbowscroll" => "rainbow_scroll",
                    "jitter" => "text_jitter",
                    _ => name,
                },
                value,
            )?;
        }
        "set_mult_attrs_with_diffuse" => flag(
            call,
            store,
            actor,
            "mult_attrs_with_diffuse",
            !matches!(arg(call, 1), Value::Nil | Value::Boolean(false)),
        )?,
        "get_mult_attrs_with_diffuse" => {
            let value = field(call, actor, "__songlua_state_mult_attrs_with_diffuse")?;
            return call.push(Value::Boolean(!matches!(
                value,
                Value::Nil | Value::Boolean(false)
            )));
        }
        "max_dimension_use_zoom" => flag(
            call,
            store,
            actor,
            "max_dimension_uses_zoom",
            boolish(call, arg(call, 1)).unwrap_or(true),
        )?,
        "distort" | "undistort" => {
            let n = if name == "undistort" {
                0.
            } else {
                float_scalar(call, arg(call, 1), false)
                    .unwrap_or(0.)
                    .max(0.)
            };
            action_capture::prepare(call, store, actor)?;
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .render
                .text_distortion = n;
            set(
                call,
                actor,
                "__songlua_state_text_distortion",
                Value::Number(n as f64),
            )?;
            song_media::record(call, store, actor, "text_distortion");
        }
        "wrapwidthpixels" | "vertspacing" => {
            if let Some(n) = float_scalar(call, arg(call, 1), false) {
                let n = if name == "vertspacing" {
                    n.round() as i32
                } else {
                    n as i32
                };
                if name == "vertspacing" || n >= 0 {
                    action_capture::prepare(call, store, actor)?;
                    let key = if name == "vertspacing" {
                        "vert_spacing"
                    } else {
                        "wrap_width_pixels"
                    };
                    {
                        let mut guard = store.lock().unwrap();
                        let s = &mut guard.actors.get_mut(&actor).unwrap().state.render;
                        if name == "vertspacing" {
                            s.vert_spacing = Some(n)
                        } else {
                            s.wrap_width_pixels = Some(n)
                        }
                    }
                    set(
                        call,
                        actor,
                        &format!("__songlua_state_{key}"),
                        Value::Number(n as f64),
                    )?;
                    song_media::record(call, store, actor, key);
                }
            }
        }
        "maxwidth" | "maxheight" => {
            if let Some(n) = float_scalar(call, arg(call, 1), false) {
                let width = name == "maxwidth";
                action_capture::prepare(call, store, actor)?;
                {
                    let mut guard = store.lock().unwrap();
                    let s = &mut guard.actors.get_mut(&actor).unwrap().state.render;
                    if width {
                        s.max_width = Some(n)
                    } else {
                        s.max_height = Some(n)
                    }
                }
                set(
                    call,
                    actor,
                    if width {
                        "__songlua_state_max_width"
                    } else {
                        "__songlua_state_max_height"
                    },
                    Value::Number(n as f64),
                )?;
                song_media::record(
                    call,
                    store,
                    actor,
                    if width { "max_width" } else { "max_height" },
                );
                flag(
                    call,
                    store,
                    actor,
                    if width {
                        "max_w_pre_zoom"
                    } else {
                        "max_h_pre_zoom"
                    },
                    false,
                )?;
                set(
                    call,
                    actor,
                    if width {
                        "__songlua_text_saw_max_width"
                    } else {
                        "__songlua_text_saw_max_height"
                    },
                    Value::Boolean(true),
                )?;
            }
        }
        "textglowmode" => {
            if let Some(mode) =
                render::text(call, arg(call, 1)).and_then(crate::parse_overlay_text_glow_mode)
            {
                action_capture::prepare(call, store, actor)?;
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .state
                    .render
                    .text_glow_mode = mode;
                let value = call.try_intern(crate::text_glow_mode_label(mode).as_bytes())?;
                set(call, actor, "__songlua_state_text_glow_mode", value)?;
                song_media::record(call, store, actor, "text_glow_mode");
            }
        }
        _ => unreachable!(),
    }
    call.push(Value::Table(actor))
}

// LoadFont creates a live, reusable template, including the current directory;
// declaration concatenation clones its native state without running Init.
pub(super) fn load_font(call: &mut HostCall<'_>, store: &Shared) -> Result<(), Error> {
    let font = render::text(call, arg(call, 0))
        .unwrap_or_default()
        .to_owned();
    if store.lock().unwrap().offline_definitions {
        let actor = super::offline::dummy(call, store, "BitmapText")?;
        let font = call.try_intern(font.as_bytes())?;
        set(call, actor, "Font", font)?;
        return call.push(Value::Table(actor));
    }
    let declaration = call.try_new_table()?;
    call.with_roots(&[Value::Table(declaration)], |call| {
        let class = call.try_intern(b"BitmapText")?;
        set(call, declaration, "Class", class)?;
        let globals = table(call, helper(call, 5)?)?;
        for key in ["__songlua_script_dir", "__songlua_song_dir"] {
            if let Some(directory) = assets::field(call, globals, key.as_bytes())? {
                let value = call.try_intern(directory.as_bytes())?;
                set(call, declaration, key, value)?;
            }
        }
        let id = super::materialize(call, store, declaration, super::Materialization::Template)?;
        let actor = store.lock().unwrap().scenes[&id]
            .root
            .expect("font template");
        let key = call.try_intern(b"Class")?;
        call.raw_table_set(actor, key, Value::Nil)?;
        let value = call.try_intern(font.as_bytes())?;
        set(call, actor, "Font", value)?;
        call.push(Value::Table(actor))
    })
}

// Before replay is installed, LoadFont template setters publish a preparation
// capture block. Production relative position setters consult that block even
// after the final instance owns replay, until playback starts. Preserve this
// existing boundary (including authored getters) rather than replacing it with
// the newer destination unconditionally.
pub(super) fn captured_position(
    call: &mut HostCall<'_>,
    actor: TableId,
    axis: &str,
) -> Result<Option<f32>, Error> {
    let value = field(call, actor, "__songlua_capture_block")?;
    let Some(block) = optional_table(call, value)? else {
        return Ok(None);
    };
    call.with_roots(&[value], |call| {
        let value = field(call, block, axis)?;
        if value == Value::Nil {
            Ok(None)
        } else {
            sprites::number(call, value).map(|n| Some(n as f32))
        }
    })
}
pub(super) fn capture_template_position(
    call: &mut HostCall<'_>,
    actor: TableId,
    axis: &str,
    value: f32,
) -> Result<(), Error> {
    let block = field(call, actor, "__songlua_capture_block")?;
    let block = match optional_table(call, block)? {
        Some(t) => t,
        None => {
            let t = call.try_new_table()?;
            call.with_roots(&[Value::Table(t)], |call| {
                set(call, actor, "__songlua_capture_block", Value::Table(t))
            })?;
            t
        }
    };
    call.with_roots(&[Value::Table(block)], |call| {
        set(call, block, axis, Value::Number(value as f64))
    })
}

//! Existing text-display adapters whose methods are private instance bindings.
//! These classes inherit the public Actor table, not BitmapText's theme helpers.
use super::{Shared, arg, assets, float_scalar, get, helper, render, sprites, table, text};
use deadlib_lua::{Error, HostCall, TableId, Value};
use sprites::{field, set};

pub(super) const METHODS: &[&str] = &[
    "Load",
    "targetnumber",
    "SetTargetNumber",
    "GetTargetNumber",
    "settextf",
    "mult_attrs_with_diffuse",
];

pub(super) fn is_display(kind: &str) -> bool {
    matches!(
        kind,
        "RollingNumbers" | "BPMDisplay" | "DeviceList" | "InputList"
    )
}
pub(super) fn is_text(kind: &str) -> bool {
    kind == "BitmapText" || is_display(kind)
}

pub(super) fn install(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let bound = get(call, actor, b"__songlua_bound_methods")?;
    let bound = table(call, bound)?;
    let helpers = table(call, call.captures()[1])?;
    let methods = get(call, helpers, b"text_display_methods")?;
    let methods = table(call, methods)?;
    for &name in text::METHODS.iter().chain(METHODS) {
        let method = get(call, methods, name.as_bytes())?;
        let captures = [
            call.captures()[0],
            call.captures()[1],
            Value::Table(actor),
            method,
        ];
        let function = call.new_host_function_with_data(super::invoke_bound, &captures, name)?;
        let key = call.try_intern(name.as_bytes())?;
        call.raw_table_set(bound, key, function)?;
    }
    Ok(())
}

fn formatted(call: &mut HostCall<'_>) -> Result<String, Error> {
    if call.arguments().len() <= 1 {
        return Ok(String::new());
    }
    let globals = table(call, helper(call, 5)?)?;
    let string = field(call, globals, "string")?;
    call.with_roots(&[string], |call| {
        let string = table(call, string)?;
        let function = field(call, string, "format")?;
        if !matches!(function, Value::Function(_) | Value::Native(_)) {
            return Err(call.error(b"string.format must be a function"));
        }
        let arguments = call.arguments()[1..].to_vec();
        let result = call
            .call(function, &arguments)?
            .first()
            .copied()
            .unwrap_or(Value::Nil);
        text::text_value(call, result)
    })
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    match name {
        "Load" => {
            let kind = assets::field(call, actor, b"__songlua_actor_type")?;
            if kind
                .as_deref()
                .is_some_and(|s| s.eq_ignore_ascii_case("RollingNumbers"))
            {
                if let Some(metric) = render::text(call, arg(call, 1)).map(str::to_owned) {
                    let value = call.try_intern(metric.as_bytes())?;
                    set(call, actor, "__songlua_rolling_numbers_metric", value)?;
                    let format =
                        call.try_intern(crate::rolling_numbers_format(&metric).as_bytes())?;
                    set(call, actor, "__songlua_rolling_numbers_format", format)?;
                }
            } else {
                return sprites::method(call, store, actor, "Load");
            }
        }
        "targetnumber" | "SetTargetNumber" => {
            if let Some(number) = float_scalar(call, arg(call, 1), false) {
                // Publish the target first. A failing format getter leaves that
                // new target in place while the previous Text is preserved.
                set(
                    call,
                    actor,
                    "__songlua_target_number",
                    Value::Number(number as f64),
                )?;
                let format = assets::field(call, actor, b"__songlua_rolling_numbers_format")?
                    .unwrap_or_else(|| "%.0f".into());
                let text = crate::format_rolling_number(&format, number);
                let value = call.try_intern(text.as_bytes())?;
                set(call, actor, "Text", value)?;
            }
        }
        "GetTargetNumber" => {
            let value = field(call, actor, "__songlua_target_number")?;
            let n = if value == Value::Nil {
                0.
            } else {
                sprites::number(call, value)? as f32
            };
            return call.push(Value::Number(n as f64));
        }
        "settextf" => {
            let text = formatted(call)?;
            let value = call.try_intern(text.as_bytes())?;
            set(call, actor, "Text", value)?;
        }
        "mult_attrs_with_diffuse" => {
            return text::method(call, store, actor, "set_mult_attrs_with_diffuse");
        }
        _ => unreachable!(),
    }
    call.push(Value::Table(actor))
}

//! Retained texture metadata and owner-directed movie parameters.
use super::*;
use sprites::{field, number};
use std::path::Path;

pub(super) struct Info {
    pub(super) path: String,
    pub(super) source: [f32; 2],
    pub(super) image: [f32; 2],
    pub(super) allocation: [f32; 2],
    pub(super) frames: u32,
}
#[derive(Clone)]
struct Binding {
    store: Shared,
    info: Arc<Info>,
    name: &'static str,
}

pub(super) fn install_getter(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let methods = super::get(call, actor, b"__songlua_bound_methods")?;
    let methods = table(call, methods)?;
    let captures = [call.captures()[0], call.captures()[1], Value::Table(actor)];
    // Native instances own this getter even when their public class hides it.
    // Internal screen kinds expose it through the existing bound-method fallback.
    let getter = call.new_host_function_with_data(bound_getter, &captures, store.clone())?;
    let key = call.try_intern(b"GetTexture")?;
    call.raw_table_set(methods, key, getter)
}

fn bound_getter(call: &mut HostCall<'_>) -> Result<(), Error> {
    // The legacy callback requires a table receiver but reads its captured owner.
    table(call, arg(call, 0))?;
    let actor = table(call, call.captures()[2])?;
    let store = call.function_data::<Shared>().unwrap().clone();
    if !store.lock().unwrap().actors.contains_key(&actor) {
        return Err(call.error(b"actor instance is not owned by this runtime or has been released"));
    }
    if assets::field(call, actor, b"__songlua_actor_type")?
        .is_some_and(|kind| kind.eq_ignore_ascii_case("ActorFrameTexture"))
    {
        framebuffers::method(call, &store, actor, "GetTexture")
    } else {
        get(call, &store, actor)
    }
}

// RageTextureID collapses only slash-terminated components, retaining leading
// ./ and trailing .. just like the existing song resource adapter.
pub(super) fn collapse(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    for part in name.split_inclusive('/') {
        if (part == "/" || part == "./") && !out.is_empty() {
            continue;
        }
        if part == "../" && !out.is_empty() && out != "/" {
            let start = out[..out.len() - 1].rfind('/').map_or(0, |i| i + 1);
            if &out[start..] != "../" {
                out.truncate(start);
                continue;
            }
        }
        out.push_str(part);
    }
    out
}
pub(super) fn get(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let default = sprites::default_texture(call, actor)?;
    if !default && field(call, actor, "Texture")? == Value::Nil {
        return call.push(Value::Nil);
    }
    // Each ordinary GetTexture creates a fresh metadata handle. Retaining one
    // must not make its getters observe later loads or authored field changes.
    let texture = call.try_new_table()?;
    call.with_roots(&[Value::Table(texture)], |call| {
        let kind = call.try_intern(b"RageTexture")?;
        sprites::set(call, texture, "__songlua_native_type", kind)?;
        let (info, sheet) = if default {
            sprites::set(
                call,
                texture,
                "__songlua_default_texture",
                Value::Boolean(true),
            )?;
            (
                Info {
                    path: String::new(),
                    source: [1.0; 2],
                    image: [1.0; 2],
                    allocation: [1.0; 2],
                    frames: 1,
                },
                (1, 1),
            )
        } else {
            let frames = crate::sprite_frame_count(sprites::sheet(call, actor)?);
            let raw = assets::field(call, actor, b"Texture")?.unwrap_or_default();
            let resolved = assets::texture_path(call, actor)?;
            let path = resolved
                .as_deref()
                .map(crate::file_path_string)
                .unwrap_or_else(|| raw.clone());
            let source_path = resolved.as_deref().unwrap_or_else(|| Path::new(&raw));
            let source = if let Some(size) = sprites::image_size(source_path, true) {
                size
            } else if crate::is_song_lua_video_path(source_path) {
                if let Some(size) = sprites::movie_size(call, actor)? {
                    size
                } else {
                    let globals = table(call, helper(call, 5)?)?;
                    let mut size = [640.0, 480.0];
                    for (i, name) in ["SCREEN_WIDTH", "SCREEN_HEIGHT"].into_iter().enumerate() {
                        let value = field(call, globals, name)?;
                        if value != Value::Nil {
                            let value = number(call, value)?;
                            if !value.is_finite()
                                || value < i32::MIN as f64
                                || value >= i32::MAX as f64 + 1.0
                            {
                                return Err(call.error(b"screen dimension out of range"));
                            }
                            size[i] = (value as i32) as f32;
                        }
                    }
                    size
                }
            } else {
                sprites::refresh_size(call, store, actor)?;
                store.lock().unwrap().actors[&actor]
                    .state
                    .size
                    .map(f32::abs)
            };
            let upload = sprites::actor_upload_size(call, actor)?;
            let (image, allocation) = upload.map_or((source, source), |image| {
                let allocation = image.map(|n| {
                    (n as u32)
                        .checked_next_power_of_two()
                        .unwrap_or(u32::MAX)
                        .max(8) as f32
                });
                (image, allocation)
            });
            let sheet = sprites::sheet(call, actor)?.unwrap_or((1, 1));
            (
                Info {
                    path: collapse(&path),
                    source,
                    image,
                    allocation,
                    frames,
                },
                sheet,
            )
        };
        install(call, store, actor, texture, info, sheet)?;
        call.push(Value::Table(texture))
    })
}
pub(super) fn install(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    texture: TableId,
    info: Info,
    sheet: (u32, u32),
) -> Result<(), Error> {
    let path = call.try_intern(info.path.as_bytes())?;
    sprites::set(call, texture, "__songlua_texture_path", path)?;
    let frame = [
        (info.source[0] / sheet.0.max(1) as f32).floor(),
        (info.source[1] / sheet.1.max(1) as f32).floor(),
    ];
    let frame = sprites::vector_value(call, &frame)?;
    sprites::set(call, texture, "__songlua_source_frame_size", frame)?;
    let info = Arc::new(info);
    let captures = [
        call.captures()[0],
        call.captures()[1],
        Value::Table(actor),
        Value::Table(texture),
    ];
    for name in [
        "GetPath",
        "GetSourceWidth",
        "GetSourceHeight",
        "GetTextureWidth",
        "GetTextureHeight",
        "GetImageWidth",
        "GetImageHeight",
        "GetNumFrames",
        "loop",
        "rate",
    ] {
        let function = call.new_host_function_with_data(
            callback,
            &captures,
            Binding {
                store: store.clone(),
                info: info.clone(),
                name,
            },
        )?;
        sprites::set(call, texture, name, function)?;
    }
    Ok(())
}
fn callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let Binding { store, info, name } = call.function_data::<Binding>().unwrap().clone();
    let value = match name {
        "GetPath" => {
            return call
                .try_intern(info.path.as_bytes())
                .and_then(|value| call.push(value));
        }
        "GetSourceWidth" => info.source[0],
        "GetSourceHeight" => info.source[1],
        "GetTextureWidth" => info.allocation[0],
        "GetTextureHeight" => info.allocation[1],
        "GetImageWidth" => info.image[0],
        "GetImageHeight" => info.image[1],
        "GetNumFrames" => return call.push(Value::Number(info.frames as f64)),
        "loop" | "rate" => {
            let actor = table(call, call.captures()[2])?;
            let offset = usize::from(matches!(arg(call, 0), Value::Table(_)));
            sprites::texture_parameter(call, &store, actor, name, arg(call, offset))?;
            return call.push(call.captures()[3]);
        }
        _ => unreachable!(),
    };
    call.push(Value::Number(value as f64))
}

//! ScreenGameplay controls, installed on the screen after its children exist.
use super::super::managers::screen::{Requests, capture};
use super::*;
use deadlib_lua::NativeStack;
use generated_players::dummy;
use sprites::set;

#[derive(Clone)]
struct Binding {
    store: Shared,
    requests: Arc<Mutex<Requests>>,
    enabled: [bool; crate::LUA_PLAYERS],
    method: &'static str,
}

impl Actors {
    // Screen allocation precedes generated player/theme adoption and controls.
    pub(in crate::rust_engine) fn top_screen_base(
        &self,
        vm: &mut Vm,
        context: &crate::SongLuaCompileContext,
    ) -> Result<ActorScene, Error> {
        let function = vm.new_host_function_with_data(
            create_base,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            (self.store.clone(), context.clone()),
        )?;
        let Value::Number(id) = vm.call(function, &[])?[0] else {
            unreachable!()
        };
        Ok(ActorScene {
            owner: self.instantiate,
            id: id as u64,
        })
    }

    pub(in crate::rust_engine) fn bind_top_screen(
        &self,
        vm: &mut Vm,
        catalog: Value,
        screen_and_children: [Value; 5],
        enabled: [bool; crate::LUA_PLAYERS],
        requests: Arc<Mutex<Requests>>,
    ) -> Result<(), Error> {
        let mut captures = vec![
            Value::Table(self.registry),
            Value::Table(self.helpers),
            catalog,
        ];
        captures.extend(screen_and_children);
        let function = vm.new_host_function_with_data(
            install,
            &captures,
            Binding {
                store: self.store.clone(),
                requests,
                enabled,
                method: "",
            },
        )?;
        vm.call(function, &[]).map(|_| ())
    }
}

fn create_base(call: &mut HostCall<'_>) -> Result<(), Error> {
    let (store, context) = call
        .function_data::<(Shared, crate::SongLuaCompileContext)>()
        .unwrap()
        .clone();
    let scene = new_scene(call, &store)?;
    let previous = {
        let mut guard = store.lock().unwrap();
        let capture = !guard.clock.live.load(std::sync::atomic::Ordering::Relaxed);
        std::mem::replace(&mut guard.constructing_capture, capture)
    };
    let result = (|| {
        let actor = create(call, &store, scene, &context)?;
        store.lock().unwrap().scenes.get_mut(&scene).unwrap().root = Some(actor);
        Ok(())
    })();
    store.lock().unwrap().constructing_capture = previous;
    if let Err(error) = result {
        release(call, &store, scene)?;
        return Err(error);
    }
    call.push(Value::Number(scene as f64))
}

pub(super) fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    context: &crate::SongLuaCompileContext,
) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "TopScreen", "ScreenGameplay", None)?;
    for (key, value) in [
        ("__songlua_player1_enabled", context.players[0].enabled),
        ("__songlua_player2_enabled", context.players[1].enabled),
    ] {
        set(call, actor, key, Value::Boolean(value))?;
    }
    let title = call.try_intern(context.main_title.as_bytes())?;
    set(call, actor, "__songlua_main_title", title)?;
    let bpm = crate::display_bpms_text(context.song_display_bpms, crate::song_music_rate(context));
    let bpm = call.try_intern(bpm.as_bytes())?;
    set(call, actor, "__songlua_bpm_text", bpm)?;
    Ok(actor)
}

// Bound methods retain the original screen, enabled players and backing slots.
// Replacing the published screen or GAMESTATE does not retarget saved methods.
fn install(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Binding>().unwrap().clone();
    let catalog = table(call, call.captures()[2])?;
    let slots = get(call, catalog, b"game_state_slots")?;
    let screen = table(call, call.captures()[3])?;
    let mut captures = call.captures().to_vec();
    captures[2] = slots;
    let wheel = call.try_new_table()?;
    call.with_roots(&[Value::Table(wheel)], |call| {
        captures.push(Value::Table(wheel));
        captures.push(helper(call, 5)?);
        for method in [
            "IsLocked",
            "GetSelectedSection",
            "GetSelectedSong",
            "GetSelectedType",
            "GetSortOrder",
            "ChangeSort",
            "SetOpenSection",
            "Move",
        ] {
            let method_captures = method_captures(call, &captures, method)?;
            let function = call.new_host_function_with_data(
                callback,
                &method_captures,
                Binding {
                    method,
                    ..data.clone()
                },
            )?;
            set(call, wheel, method, function)?;
        }
        for method in [
            "GetScreenType",
            "SetMinSecondsToMusic",
            "GetChild",
            "GetLifeMeter",
            "StartTransitioningScreen",
            "SetNextScreenName",
            "SetPrevScreenName",
            "GetNextScreenName",
            "GetPrevScreenName",
            "GetGoToOptions",
            "GetEditState",
            "GetCurrentRowIndex",
            "GetNumRows",
            "GetOptionRow",
            "SetOptionRowIndex",
            "RedrawOptions",
            "IsPaused",
            "PauseGame",
            "AllAreOnLastRow",
            "GetMusicWheel",
            "GetNextCourseSong",
            "PostScreenMessage",
            "SetProfileIndex",
            "Cancel",
            "Continue",
            "Finish",
            "Load",
            "begin_backing_out",
        ] {
            let method_captures = method_captures(call, &captures, method)?;
            let function = call.new_host_function_with_data(
                callback,
                &method_captures,
                Binding {
                    method,
                    ..data.clone()
                },
            )?;
            let bound = get(call, screen, b"__songlua_bound_methods")?;
            set(call, table(call, bound)?, method, function)?;
        }
        Ok(())
    })
}

fn argument(call: &HostCall<'_>, index: usize) -> Value {
    let offset = usize::from(matches!(call.arguments().first(), Some(Value::Table(_))));
    arg(call, index + offset)
}
fn string(call: &HostCall<'_>, value: Value) -> Option<String> {
    let Value::String(id) = value else {
        return None;
    };
    std::str::from_utf8(call.string_bytes(id)?)
        .ok()
        .map(str::to_owned)
}
fn integer(call: &HostCall<'_>, value: Value) -> Option<i32> {
    match value {
        Value::Number(value) if value.is_finite() => {
            Some(value.round().clamp(i32::MIN as f64, i32::MAX as f64) as i32)
        }
        Value::String(_) => {
            let value = string(call, value)?;
            value
                .trim()
                .parse()
                .ok()
                .or_else(|| value.trim().parse::<f32>().ok().map(|n| n.round() as i32))
        }
        _ => None,
    }
}

fn callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Binding>().unwrap().clone();
    let screen_value = call.captures()[3];
    let first = argument(call, 0);
    match data.method {
        "SetMinSecondsToMusic" => {
            let receiver = table(call, arg(call, 0))?;
            let seconds = call.number(1)? as f32;
            if !seconds.is_finite() || !(0.0..=60.0).contains(&seconds) {
                return Err(call.error(b"music lead-in must be between 0 and 60 seconds"));
            }
            let key = call.try_intern(b"__songlua_min_seconds_to_music")?;
            call.raw_table_set(receiver, key, Value::Number(seconds as f64))?;
            return call.push(Value::Table(receiver));
        }
        "GetOptionRow" => {
            let name = if matches!(first, Value::String(_)) {
                string(call, first).unwrap_or_default()
            } else {
                integer(call, first)
                    .and_then(crate::top_screen_option_row_name_at)
                    .unwrap_or(crate::SONG_LUA_TOP_SCREEN_OPTION_ROWS[0])
                    .to_owned()
            };
            let scene = new_scene(call, &data.store)?;
            data.store.lock().unwrap().constructor_scenes.insert(scene);
            let previous = {
                let mut guard = data.store.lock().unwrap();
                let capture = !guard.clock.live.load(std::sync::atomic::Ordering::Relaxed);
                std::mem::replace(&mut guard.constructing_capture, capture)
            };
            let row = option_row(call, &data.store, scene, &name);
            data.store.lock().unwrap().constructing_capture = previous;
            let row = match row {
                Ok(row) => row,
                Err(error) => {
                    release(call, &data.store, scene)?;
                    return Err(error);
                }
            };
            data.store
                .lock()
                .unwrap()
                .scenes
                .get_mut(&scene)
                .unwrap()
                .root = Some(row);
            return call.push(Value::Table(row));
        }
        "GetChild" => {
            let screen = table(call, screen_value)?;
            let Some(name) = string(call, first) else {
                return call.push(Value::Nil);
            };
            let player = crate::top_screen_player_index(&name)
                .map(|i| (i, 4 + i))
                .or_else(|| crate::top_screen_life_meter_index(&name).map(|i| (i, 6 + i)));
            if let Some((index, slot)) = player {
                return call.push(if data.enabled[index] {
                    call.captures()[slot]
                } else {
                    Value::Nil
                });
            }
            let named = registry(call, screen)?;
            return call.with_roots(&[named], |call| {
                let key = call.try_intern(name.as_bytes())?;
                let value = call.table_get(named, key)?;
                if !matches!(value, Value::Nil | Value::Table(_)) {
                    return Err(call.error(b"screen child table expected"));
                }
                call.push(value)
            });
        }
        "GetLifeMeter" => {
            let index = match first {
                Value::Number(n) if n >= 0. && n < crate::LUA_PLAYERS as f64 && n.fract() == 0. => {
                    Some(n as usize)
                }
                Value::String(id) => call.string_bytes(id).and_then(|s| {
                    if s.eq_ignore_ascii_case(b"P1") || s.eq_ignore_ascii_case(b"PlayerNumber_P1") {
                        Some(0)
                    } else if s.eq_ignore_ascii_case(b"P2")
                        || s.eq_ignore_ascii_case(b"PlayerNumber_P2")
                    {
                        Some(1)
                    } else {
                        None
                    }
                }),
                _ => None,
            };
            return call.push(
                index
                    .filter(|&i| data.enabled[i])
                    .map_or(Value::Nil, |i| call.captures()[6 + i]),
            );
        }
        "StartTransitioningScreen" => {
            let screen = table(call, screen_value)?;
            let globals = call.captures()[9];
            let live = data
                .store
                .lock()
                .unwrap()
                .clock
                .live
                .load(std::sync::atomic::Ordering::Relaxed);
            let message = string(call, first);
            {
                let mut stack = call.native_stack()?;
                stack.push(globals)?;
                let globals_index = stack.top();
                side_effect(&mut stack, globals_index)?;
                if live {
                    let message = message
                        .as_ref()
                        .ok_or_else(|| stack.error(b"expected a screen transition message"))?;
                    capture(
                        &mut stack,
                        &data.requests,
                        globals_index,
                        crate::SongLuaLiveRequest::Transition(message.clone()),
                    )?;
                }
            }
            if live {
                for child in children(call, &data.store, screen)? {
                    play(call, &data.store, child, b"Off", None, true)?;
                }
                let named = registry(call, screen)?;
                let out =
                    call.with_roots(&[named], |call| get(call, table(call, named)?, b"Out"))?;
                if out != Value::Nil {
                    transitions::start(call, &data.store, table(call, out)?)?;
                }
                data.requests.lock().unwrap().transition = message;
            }
            return call.push(screen_value);
        }
        _ => (),
    }
    let second = argument(call, 1);
    let arg_count = call.arguments().len()
        - usize::from(matches!(call.arguments().first(), Some(Value::Table(_))));
    let first_text = string(call, first);
    let row = integer(call, if arg_count > 1 { second } else { first });
    let slots = call.captures()[2];
    let wheel = call.captures()[8];
    let globals = call.captures()[9];
    let mut stack = call.native_stack()?;
    stack.push(screen_value)?;
    let owner = stack.top();
    let mut result = screen_value;
    let mut effect = false;
    match data.method {
        "GetScreenType" => stack.push_bytes(b"ScreenType_Gameplay")?,
        "GetGoToOptions" | "AllAreOnLastRow" | "IsLocked" => stack.push(Value::Boolean(false))?,
        "GetEditState" => stack.push_bytes(b"EditState_Playing")?,
        "GetSelectedType" => stack.push_bytes(b"WheelItemDataType_Song")?,
        "GetSelectedSection" => stack.push_bytes(b"")?,
        "GetSelectedSong" => stack.push(Value::Nil)?,
        "GetMusicWheel" => stack.push(wheel)?,
        "GetNumRows" => stack.push(Value::Number(
            crate::SONG_LUA_TOP_SCREEN_OPTION_ROWS.len() as f64
        ))?,
        "GetNextScreenName" | "GetPrevScreenName" | "GetCurrentRowIndex" | "IsPaused" => {
            let key = match data.method {
                "GetNextScreenName" => b"__songlua_next_screen_name".as_slice(),
                "GetPrevScreenName" => b"__songlua_prev_screen_name",
                "GetCurrentRowIndex" => b"__songlua_current_row_index",
                _ => b"__songlua_paused",
            };
            stack.get_field(owner as isize, key)?;
            if data.method == "IsPaused" {
                stack.push(Value::Boolean(stack.to_boolean(-1)))?;
            } else if data.method == "GetCurrentRowIndex" {
                let n = if stack.value(-1) == Some(Value::Nil) {
                    0
                } else {
                    checked_i64(&stack, -1)?
                };
                stack.push(Value::Number(n as f64))?;
            } else if stack.value(-1) == Some(Value::Nil) {
                stack.push_bytes(b"")?;
            } else {
                let text = string_bytes(&mut stack, -1)?;
                stack.push_bytes(&text)?;
            }
        }
        "SetNextScreenName" | "SetPrevScreenName" | "PauseGame" | "SetOptionRowIndex" => {
            let key = match data.method {
                "SetNextScreenName" => b"__songlua_next_screen_name".as_slice(),
                "SetPrevScreenName" => b"__songlua_prev_screen_name",
                "PauseGame" => b"__songlua_paused",
                _ => b"__songlua_current_row_index",
            };
            if data.method != "SetOptionRowIndex" || row.is_some() {
                stack.push_bytes(key)?;
                match data.method {
                    "PauseGame" => stack.push(Value::Boolean(!matches!(
                        first,
                        Value::Nil | Value::Boolean(false)
                    )))?,
                    "SetOptionRowIndex" => stack.push(Value::Number(row.unwrap().max(0) as f64))?,
                    _ => stack.push_bytes(first_text.as_deref().unwrap_or_default().as_bytes())?,
                }
                stack.set_table(owner as isize, false)?;
            }
            effect = true;
        }
        "GetSortOrder" | "GetNextCourseSong" | "ChangeSort" => {
            stack.push(slots)?;
            let slot = stack.top();
            if data.method == "ChangeSort" {
                if let Some(name) = first_text {
                    stack.push(Value::Number(1.))?;
                    stack.push_bytes(name.as_bytes())?;
                    stack.set_table(slot as isize, true)?;
                }
                effect = true;
                result = wheel;
            } else {
                stack.push(Value::Number(1.))?;
                stack.get_table(slot as isize, true)?;
                if data.method == "GetSortOrder" {
                    if stack.value(-1) == Some(Value::Nil) {
                        stack.push_bytes(b"SortOrder_Group")?;
                    } else {
                        let bytes = string_bytes(&mut stack, -1)?;
                        stack.push_bytes(&bytes)?;
                    }
                } else if !matches!(stack.value(-1), Some(Value::Nil | Value::Table(_))) {
                    return Err(stack.error(b"song table expected"));
                }
            }
        }
        "SetOpenSection" | "Move" => {
            effect = true;
            result = wheel;
        }
        "RedrawOptions" | "PostScreenMessage" | "SetProfileIndex" | "Cancel" | "Continue"
        | "Finish" | "Load" | "begin_backing_out" => effect = true,
        _ => unreachable!(),
    }
    if effect {
        stack.push(globals)?;
        let index = stack.top();
        side_effect(&mut stack, index)?;
        stack.push(result)?;
    }
    stack.finish(1)
}

fn string_bytes(stack: &mut NativeStack<'_, '_>, index: isize) -> Result<Vec<u8>, Error> {
    let value = match stack.to_bytes(index)? {
        Some(bytes) => bytes.to_vec(),
        None => return Err(stack.error(b"string expected")),
    };
    if std::str::from_utf8(&value).is_err() {
        return Err(stack.error(b"UTF-8 string expected"));
    }
    Ok(value)
}

fn checked_i64(stack: &NativeStack<'_, '_>, index: isize) -> Result<i64, Error> {
    let value = stack.number(index)?;
    if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&value) {
        return Err(stack.error(b"integer out of range"));
    }
    Ok(value as i64)
}
fn side_effect(stack: &mut NativeStack<'_, '_>, globals: usize) -> Result<(), Error> {
    stack.get_field(
        globals as isize,
        crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes(),
    )?;
    let count = if stack.value(-1) == Some(Value::Nil) {
        0
    } else {
        checked_i64(stack, -1)?
    };
    stack.push_bytes(crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY.as_bytes())?;
    stack.push(Value::Number(count.saturating_add(1) as f64))?;
    stack.set_table(globals as isize, false)
}

fn option_row(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    let row = dummy(call, store, scene, "OptionRow", name, None)?;
    let name_value = call.try_intern(name.as_bytes())?;
    let get_name = call.new_host_function(|call| call.push(call.captures()[0]), &[name_value])?;
    let bound = get(call, row, b"__songlua_bound_methods")?;
    set(call, table(call, bound)?, "GetName", get_name)?;
    bind_queries(call, row)?;
    let focus = call.new_host_function(|call| call.push(Value::Number(1.)), &[])?;
    set(call, table(call, bound)?, "GetChoiceInRowWithFocus", focus)?;
    let frame = dummy(call, store, scene, "OptionRowFrame", "", Some(row))?;
    bind_queries(call, frame)?;
    native_children::insert(call, row, "", Value::Table(frame))?;
    let title = screen_parts::text(call, store, scene, "Title", name)?;
    screen_parts::named(call, store, frame, "Title", title)?;
    let members = call.try_new_table()?;
    let group = call.with_roots(&[Value::Table(members)], |call| {
        Ok(call.call(helper(call, 3)?, &[Value::Table(members)])?[0])
    })?;
    call.with_roots(&[group], |call| {
        let text = crate::option_row_default_text(name);
        for index in 1..=crate::LUA_PLAYERS {
            let item = screen_parts::text(call, store, scene, "Item", &text)?;
            native_children::adopt(call, store, item, frame)?;
            call.raw_table_set(
                table(call, group)?,
                Value::Number(index as f64),
                Value::Table(item),
            )?;
        }
        native_children::insert(call, frame, "Item", group)
    })?;
    Ok(row)
}

fn registry(call: &mut HostCall<'_>, actor: TableId) -> Result<Value, Error> {
    let registry = native_children::helper_function(call, b"native_registry")?;
    Ok(call.call(registry, &[Value::Table(actor)])?[0])
}
pub(super) fn bind_queries(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let methods = native_children::helper_function(call, b"model_methods")?;
    let bound = get(call, actor, b"__songlua_bound_methods")?;
    for name in ["GetChild", "GetChildren", "GetNumChildren"] {
        let method = get(call, table(call, methods)?, name.as_bytes())?;
        let captures = [
            call.captures()[0],
            call.captures()[1],
            Value::Table(actor),
            method,
        ];
        let function = call.new_host_function_with_data(invoke_bound, &captures, name)?;
        set(call, table(call, bound)?, name, function)?;
    }
    Ok(())
}
fn method_captures(
    call: &mut HostCall<'_>,
    source: &[Value],
    method: &str,
) -> Result<[Value; 10], Error> {
    let mut captures = [Value::Nil; 10];
    let indices: &[usize] = match method {
        "GetScreenType"
        | "GetGoToOptions"
        | "GetEditState"
        | "GetNumRows"
        | "AllAreOnLastRow"
        | "SetMinSecondsToMusic"
        | "IsLocked"
        | "GetSelectedSection"
        | "GetSelectedSong"
        | "GetSelectedType" => &[],
        "GetOptionRow" => &[0, 1],
        "GetChild" => &[0, 1, 3, 4, 5, 6, 7],
        "GetLifeMeter" => &[6, 7],
        "StartTransitioningScreen" => &[0, 1, 3, 9],
        "GetMusicWheel" => &[8],
        "GetSortOrder" | "GetNextCourseSong" => &[],
        "ChangeSort" | "SetOpenSection" | "Move" => &[8, 9],
        "GetNextScreenName" | "GetPrevScreenName" | "GetCurrentRowIndex" | "IsPaused" => &[3],
        _ => &[3, 9],
    };
    for &i in indices {
        captures[i] = source[i];
    }
    if matches!(method, "GetSortOrder" | "ChangeSort" | "GetNextCourseSong") {
        captures[2] = get(
            call,
            table(call, source[2])?,
            if method == "GetNextCourseSong" {
                b"song"
            } else {
                b"sort"
            },
        )?;
    }
    Ok(captures)
}

