			end
			if IsRoutine() then
				local routineStats = STATSMAN:GetCurStageStats():GetRoutineStageStats()
				local bestWhites = totalWhites
				if PROFILEMAN:IsPersistentProfile(GAMESTATE:GetMasterPlayerNumber()) then
					local steps = GAMESTATE:GetCurrentSteps(GAMESTATE:GetMasterPlayerNumber())
					local scores = PROFILEMAN:GetProfile(GAMESTATE:GetMasterPlayerNumber()):GetHighScoreList(song, steps):GetHighScores()
					for hs in ivalues(scores) do
						-- If the player previously quadded the song, retain the better white count.
						-- Technically this is a workaround because the date would be wrong, but
						-- it's still worth to keep the score around
						if (routineStats:GetPercentDancePoints() == hs:GetPercentDP() and hs:GetPercentDP() == 1.0) then
							bestWhites = math.min(bestWhites, hs:GetScore())
						end
					end
				end
				routineStats:SetScore(bestWhites)
			end
		end
	end
}
end"#;

impl Actors {
    pub(in crate::rust_engine) fn start_transition(
        &self,
        vm: &mut Vm,
        actor: Value,
    ) -> Result<(), Error> {
        let function = vm.new_host_function_with_data(
            start_callback,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            self.store.clone(),
        )?;
        vm.call(function, &[actor]).map(|_| ())
    }
}

pub(super) fn ensure_helpers(vm: &mut Vm, helpers: TableId) -> Result<(), Error> {
    for (key, source, name) in [
        (
            "transition_in_commands",
            IN_COMMANDS,
            "@theme:/BGAnimations/ScreenGameplay in/default.lua",
        ),
        (
            "transition_stage_text",
            STAGE_TEXT,
            "@theme:/BGAnimations/ScreenGameplay in/default.lua",
        ),
        (
            "transition_out_commands",
            OUT_COMMANDS,
            "@theme:/BGAnimations/ScreenGameplay out.lua",
        ),
    ] {
        let field = vm.try_intern(key.as_bytes())?;
        if vm.raw_table_get(helpers, field)? == Value::Nil {
            let code = compile_named(source, name.as_bytes())?;
            let function = vm.execute(&code)?[0];
            super::super::put(vm, helpers, key, function)?;
        }
    }
    Ok(())
}

pub(super) fn state(call: &mut HostCall<'_>, actor: TableId) -> Result<Option<u8>, Error> {
    let value = get(call, actor, b"__songlua_transition_state")?;
    if value == Value::Nil {
        return Ok(None);
    }
    let number = sprites::number(call, value)?.trunc();
    if !(0.0..256.0).contains(&number) {
        return Err(call.error(b"transition state out of range"));
    }
    Ok(Some(number as u8))
}

pub(super) fn child(call: &mut HostCall<'_>, actor: TableId) -> Result<Option<TableId>, Error> {
    let value = get(call, actor, b"__songlua_transition_child")?;
    if value == Value::Nil {
        Ok(None)
    } else {
        table(call, value).map(Some)
    }
}

pub(super) fn start(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    if state(call, actor)? != Some(0) {
        return Ok(());
    }
    if let Some(child) = child(call, actor)? {
        // The AutoActor survives replacement/removal of the raw child field by
        // its own callback. Start's state write follows the complete traversal.
        call.with_roots(&[Value::Table(child)], |call| {
            start_commands(call, store, child)
        })?;
        set(call, actor, "__songlua_transition_state", Value::Number(1.))?;
    }
    Ok(())
}

fn start_callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let store = call.function_data::<Shared>().unwrap().clone();
    start(call, &store, table(call, arg(call, 0))?)
}

fn global_table(call: &mut HostCall<'_>, name: &str) -> Result<TableId, Error> {
    let globals = table(call, helper(call, 5)?)?;
    let value = field(call, globals, name)?;
    table(call, value)
}
fn global_call(call: &mut HostCall<'_>, name: &str, args: &[Value]) -> Result<Value, Error> {
    let globals = table(call, helper(call, 5)?)?;
    let function = field(call, globals, name)?;
    function_call(call, function, args)
}
fn function_call(call: &mut HostCall<'_>, function: Value, args: &[Value]) -> Result<Value, Error> {
    if !matches!(function, Value::Function(_) | Value::Native(_)) {
        return Err(call.error(b"function expected"));
    }
    Ok(call
        .call(function, args)?
        .first()
        .copied()
        .unwrap_or(Value::Nil))
}
fn reload(call: &mut HostCall<'_>, value: bool) -> Result<(), Error> {
    let sl = global_table(call, "SL")?;
    let global = field(call, sl, "Global")?;
    set(
        call,
        table(call, global)?,
        "GameplayReloadCheck",
        Value::Boolean(value),
    )
}
fn hide(call: &mut HostCall<'_>) -> Result<(), Error> {
    let actor = table(call, arg(call, 0))?;
    invoke(call, actor, "visible", &[Value::Boolean(false)])?;
    reload(call, true)
}
fn off(call: &mut HostCall<'_>) -> Result<(), Error> {
    table(call, arg(call, 0))?;
    reload(call, false)
}
fn cancel(call: &mut HostCall<'_>) -> Result<(), Error> {
    let actor = table(call, arg(call, 0))?;
    invoke(call, actor, "sleep", &[Value::Number(0.1)])?;
    invoke(call, actor, "linear", &[Value::Number(0.4)])?;
    invoke(call, actor, "diffusealpha", &[Value::Number(1.)])
}

fn attach(
    call: &mut HostCall<'_>,
    store: &Shared,
    owner: TableId,
    child: TableId,
) -> Result<(), Error> {
    set(
        call,
        owner,
        "__songlua_transition_child",
        Value::Table(child),
    )?;
    append(call, store, owner, child)
}
fn commands(
    call: &mut HostCall<'_>,
    actor: TableId,
    handlers: TableId,
    names: &[&str],
) -> Result<(), Error> {
    for name in names {
        let function = get(call, handlers, name.as_bytes())?;
        if !matches!(function, Value::Function(_) | Value::Native(_)) {
            return Err(call.error(b"function expected"));
        }
        set(call, actor, name, function)?;
    }
    Ok(())
}

pub(super) fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "ActorFrame", name, None)?;
    set(call, actor, "__songlua_transition_state", Value::Number(0.))?;
    if name.eq_ignore_ascii_case("In") {
        create_in(call, store, scene, actor)?;
    } else {
        let quad = dummy(call, store, scene, "Quad", "", Some(actor))?;
        if name.eq_ignore_ascii_case("Out") {
            let factory = native_children::helper_function(call, b"transition_out_commands")?;
            let handlers = call.call(factory, &[])?[0];
            call.with_roots(&[handlers], |call| {
                commands(
                    call,
                    quad,
                    table(call, handlers)?,
                    &["InitCommand", "OnCommand", "OffCommand"],
                )
            })?;
        }
        invoke(call, quad, "FullScreen", &[])?;
        invoke(call, quad, "diffuse", &[Value::Number(0.); 4])?;
        if name.eq_ignore_ascii_case("Out") {
            invoke(call, quad, "sleep", &[Value::Number(0.5)])?;
            invoke(call, quad, "linear", &[Value::Number(1.)])?;
            invoke(call, quad, "diffusealpha", &[Value::Number(1.)])?;
        } else {
            let function = call.new_host_function(cancel, &[])?;
            set(call, quad, "StartTransitioningCommand", function)?;
        }
        attach(call, store, actor, quad)?;
    }
    Ok(actor)
}

fn create_in(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
) -> Result<(), Error> {
    let child = dummy(call, store, scene, "ActorFrame", "", Some(actor))?;
    attach(call, store, actor, child)?;
    let visuals = dummy(call, store, scene, "ActorFrame", "", Some(child))?;
    append(call, store, child, visuals)?;
    let sl = global_table(call, "SL")?;
    let global = field(call, sl, "Global")?;
    let reload = field(call, table(call, global)?, "GameplayReloadCheck")?;
    let reload = !matches!(reload, Value::Nil | Value::Boolean(false));
    for (name, body) in [
        (
            "HideCommand",
            hide as fn(&mut HostCall<'_>) -> Result<(), Error>,
        ),
        ("OffCommand", off),
    ] {
        let function = call.new_host_function(body, &[call.captures()[0], call.captures()[1]])?;
        set(call, visuals, name, function)?;
    }
    if reload {
        let name = call.try_intern(b"Hide")?;
        return invoke(call, visuals, "playcommand", &[name]);
    }
    invoke(call, visuals, "sleep", &[Value::Number(2.)])?;
    let name = call.try_intern(b"Hide")?;
    invoke(call, visuals, "queuecommand", &[name])?;
    let factory = native_children::helper_function(call, b"transition_in_commands")?;
    let handlers = call.call(factory, &[])?[0];
    call.with_roots(&[handlers], |call| {
        let handlers = table(call, handlers)?;
        let prefs = global_table(call, "ThemePrefs")?;
        let getter = field(call, prefs, "Get")?;
        let key = call.try_intern(b"VisualStyle")?;
        let style = function_call(call, getter, &[key])?;
        let style = assets::text(call, style)?;
        let spooky = global_call(call, "IsSpooky", &[])?;
        let spooky = !matches!(spooky, Value::Nil | Value::Boolean(false));
        let color = global_call(call, "GetCurrentColor", &[Value::Boolean(true)])?;
        table(call, color)?;
        call.with_roots(&[color], |call| {
            for index in 0..4 {
                let sprite = dummy(
                    call,
                    store,
                    scene,
                    if index == 0 { "Quad" } else { "Sprite" },
                    "",
                    Some(visuals),
                )?;
                let handler = call.raw_table_get(handlers, Value::Number((index + 1) as f64))?;
                commands(
                    call,
                    sprite,
                    table(call, handler)?,
                    &["InitCommand", "OnCommand"],
                )?;
                invoke(call, sprite, "Center", &[])?;
                if index == 0 {
                    invoke(call, sprite, "FullScreen", &[])?;
                    invoke(
                        call,
                        sprite,
                        "diffuse",
                        &[
                            Value::Number(0.),
                            Value::Number(0.),
                            Value::Number(0.),
                            Value::Number(1.),
                        ],
                    )?;
                    invoke(call, sprite, "sleep", &[Value::Number(1.4)])?;
                    invoke(call, sprite, "accelerate", &[Value::Number(0.6)])?;
                } else {
                    let asset = if spooky {
                        "_VisualStyles/Spooky/ExtraSpooky/Bats".into()
                    } else {
                        format!(
                            "_VisualStyles/{style}/GameplayIn {}",
                            if index == 3 { "minisplode" } else { "splode" }
                        )
                    };
                    let path =
                        gameplay_bitmaps::load(&asset).map_err(|e| call.error(e.as_bytes()))?;
                    let path = call.try_intern(path.as_bytes())?;
                    sprites::set_texture(call, store, sprite, path, false)?;
                    invoke(call, sprite, "diffuse", &[color])?;
                    invoke(
                        call,
                        sprite,
                        "rotationz",
                        &[Value::Number(if index == 2 { -10. } else { 10. })],
                    )?;
                    if index == 2 {
                        invoke(call, sprite, "rotationy", &[Value::Number(180.)])?;
                    }
                    invoke(call, sprite, "zoom", &[Value::Number(0.)])?;
                    if index != 3 {
                        invoke(
                            call,
                            sprite,
                            "diffusealpha",
                            &[Value::Number(if index == 1 { 0.9 } else { 0.8 })],
                        )?;
                    }
                    invoke(call, sprite, "sleep", &[Value::Number(0.4)])?;
                    invoke(
                        call,
                        sprite,
                        if index == 1 { "linear" } else { "decelerate" },
                        &[Value::Number(if index == 3 { 0.8 } else { 0.6 })],
                    )?;
                    invoke(call, sprite, "rotationz", &[Value::Number(0.)])?;
                    invoke(
                        call,
                        sprite,
                        "zoom",
                        &[Value::Number([0., 1.1, 1.3, 0.9][index])],
                    )?;
                }
                invoke(call, sprite, "diffusealpha", &[Value::Number(0.)])?;
                append(call, store, visuals, sprite)?;
            }
            Ok(())
        })
    })?;
    let factory = native_children::helper_function(call, b"transition_stage_text")?;
    let stage = call.call(factory, &[])?[0];
    let stage = assets::text(call, stage)?;
    let label = text(call, store, scene, "", &stage)?;
    native_children::adopt(call, store, label, child)?;
    invoke(call, label, "accelerate", &[Value::Number(0.5)])?;
    invoke(call, label, "diffusealpha", &[Value::Number(1.)])?;
    invoke(call, label, "sleep", &[Value::Number(0.66)])?;
    invoke(call, label, "accelerate", &[Value::Number(0.33)])?;
    append(call, store, child, label)
}

fn start_commands(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    native_children::run_command(call, store, actor, b"StartTransitioning", None)?;
    native_children::with_children(call, actor, |call, child| {
        start_commands(call, store, child)
    })
}

//! The existing pre-song underlay constructor, before original theme files load.
use super::*;
use generated_players::dummy;
use screen_parts::{append, invoke, named};
use sprites::set;
use std::sync::OnceLock;

pub(super) fn ensure_helpers(vm: &mut Vm, helpers: TableId) -> Result<(), Error> {
    for (key, source, name) in [
        (
            "underlay_header",
            include_bytes!("underlay/header.lua").as_slice(),
            "Shared/Header.lua",
        ),
        (
            "underlay_filter",
            include_bytes!("underlay/filter.lua").as_slice(),
            "PerPlayer/BackgroundFilter.lua",
        ),
        (
            "underlay_difficulty",
            include_bytes!("underlay/difficulty.lua").as_slice(),
            "PerPlayer/DifficultyMeter.lua",
        ),
        (
            "underlay_life",
            include_bytes!("underlay/life.lua").as_slice(),
            "PerPlayer/LifeMeter/Standard.lua",
        ),
        (
            "underlay_bpm",
            include_bytes!("underlay/bpm.lua").as_slice(),
            "Shared/BPMDisplay.lua",
        ),
    ] {
        let key_value = vm.try_intern(key.as_bytes())?;
        if vm.raw_table_get(helpers, key_value)? == Value::Nil {
            let name = format!("@theme:/BGAnimations/ScreenGameplay underlay/{name}");
            let code = compile_named(source, name.as_bytes())?;
            let function = Value::Function(vm.try_load_program(&code)?);
            let root = vm.pin(function)?;
            let result = super::super::put(vm, helpers, key, function);
            vm.unpin(root)?;
            result?;
        }
    }
    Ok(())
}

fn global(call: &mut HostCall<'_>, name: &str) -> Result<Value, Error> {
    field(call, table(call, helper(call, 5)?)?, name)
}

fn source(call: &mut HostCall<'_>, name: &str, args: &[Value]) -> Result<Value, Error> {
    let function = native_children::helper_function(call, name.as_bytes())?;
    Ok(call
        .call(function, args)?
        .first()
        .copied()
        .unwrap_or(Value::Nil))
}

fn field(call: &mut HostCall<'_>, owner: TableId, name: &str) -> Result<Value, Error> {
    call.with_roots(&[Value::Table(owner)], |call| {
        sprites::field(call, owner, name)
    })
}

fn member(call: &mut HostCall<'_>, owner: TableId, name: &str) -> Result<TableId, Error> {
    let value = field(call, owner, name)?;
    table(call, value)
}

fn mods(call: &mut HostCall<'_>, player: usize) -> Result<TableId, Error> {
    let sl = global(call, "SL")?;
    let player = member(call, table(call, sl)?, &format!("P{}", player + 1))?;
    member(call, player, "ActiveModifiers")
}

fn number(call: &mut HostCall<'_>, value: Value) -> Result<f32, Error> {
    sprites::number(call, value).map(|value| value as f32)
}

fn commands(
    call: &mut HostCall<'_>,
    actor: TableId,
    definition: TableId,
    names: &[&str],
    required: bool,
) -> Result<(), Error> {
    for name in names {
        let value = get(call, definition, name.as_bytes())?;
        if value == Value::Nil && !required {
            continue;
        }
        if !matches!(value, Value::Function(_) | Value::Native(_)) {
            return Err(call.error(b"theme command function expected"));
        }
        let key = call.try_intern(name.as_bytes())?;
        call.raw_table_set(actor, key, value)?;
    }
    Ok(())
}

fn run(call: &mut HostCall<'_>, actor: TableId, name: &str) -> Result<(), Error> {
    let function = get(call, actor, name.as_bytes())?;
    if function != Value::Nil {
        call.call(function, &[Value::Table(actor)])?;
    }
    Ok(())
}

pub(super) fn group(call: &mut HostCall<'_>, members: &[TableId]) -> Result<Value, Error> {
    let values = call.try_new_table()?;
    call.with_roots(&[Value::Table(values)], |call| {
        for (i, &actor) in members.iter().enumerate() {
            call.raw_table_set(values, Value::Number((i + 1) as f64), Value::Table(actor))?;
        }
        Ok(call.call(helper(call, 3)?, &[Value::Table(values)])?[0])
    })
}

fn unnamed(
    call: &mut HostCall<'_>,
    actor: TableId,
    members: &[TableId],
    always_group: bool,
) -> Result<(), Error> {
    let value = match members {
        [] if !always_group => return Ok(()),
        [actor] if !always_group => Value::Table(*actor),
        _ => group(call, members)?,
    };
    native_children::insert(call, actor, "", value)
}

// Same tags as create_named_child_actor. Internal unnamed actors do not inherit
// these tags; they acquire only their explicit role and parent references.
pub(super) fn copy_tags(
    call: &mut HostCall<'_>,
    from: TableId,
    into: TableId,
) -> Result<(), Error> {
    for key in ["__songlua_player1_enabled", "__songlua_player2_enabled"] {
        let value = get(call, from, key.as_bytes())?;
        if value != Value::Nil {
            let key = call.try_intern(key.as_bytes())?;
            call.raw_table_set(into, key, Value::Boolean(value != Value::Boolean(false)))?;
        }
    }
    for key in ["__songlua_player_index", "__songlua_compile_layer"] {
        let value = field(call, from, key)?;
        if value != Value::Nil {
            let value = sprites::number(call, value)?;
            if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&value) {
                return Err(call.error(b"integer out of range"));
            }
            set(call, into, key, Value::Number(value as i64 as f64))?;
        }
    }
    for key in [
        "__songlua_player_child_name",
        "__songlua_top_screen_child_name",
        "__songlua_main_title",
        "__songlua_bpm_text",
        "__songlua_style_name",
    ] {
        let value = field(call, from, key)?;
        if value != Value::Nil {
            let text = assets::text(call, value)?;
            let text = call.try_intern(text.as_bytes())?;
            set(call, into, key, text)?;
        }
    }
    Ok(())
}

pub(super) fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    parent: TableId,
) -> Result<TableId, Error> {
    let underlay = dummy(call, store, scene, "ActorFrame", "Underlay", None)?;
    copy_tags(call, parent, underlay)?;
    let name = call.try_intern(b"Underlay")?;
    set(call, underlay, "__songlua_top_screen_child_name", name)?;
    let mut unnamed_parts = Vec::new();
    for &name in crate::UNDERLAY_THEME_CHILD_NAMES {
        let player = crate::underlay_score_index(name)
            .or_else(|| crate::top_screen_step_stats_pane_index(name))
            .or_else(|| crate::top_screen_danger_index(name))
            .or_else(|| {
                name.strip_prefix("NoteFieldContainerP")
                    .and_then(|s| s.parse::<usize>().ok())
                    .map(|i| i - 1)
            });
        if let Some(player) = player {
            let key = ["__songlua_player1_enabled", "__songlua_player2_enabled"][player];
            if get(call, underlay, key.as_bytes())? == Value::Boolean(false) {
                continue;
            }
        }
        if let Some(player) = crate::top_screen_step_stats_pane_index(name) {
            if let Some(actor) = filter(call, store, scene, underlay, player)? {
                role(call, actor, &format!("filter{player}"))?;
                append(call, store, underlay, actor)?;
                unnamed_parts.push(actor);
            }
            continue;
        }
        // The original StepStatistics, Danger, NoteField and SongMeter files
        // load in the later theme phase, after their complete host is installed.
        if crate::top_screen_danger_index(name).is_some()
            || name == "SongMeter"
            || name.starts_with("NoteFieldContainerP")
        {
            continue;
        }
        let actor = if name == "Header" {
            let actor = dummy(call, store, scene, "Quad", name, Some(underlay))?;
            let definition = source(call, "underlay_header", &[])?;
            call.with_roots(&[definition], |call| {
                commands(
                    call,
                    actor,
                    table(call, definition)?,
                    &["InitCommand"],
                    true,
                )?;
                run(call, actor, "InitCommand")
            })?;
            actor
        } else {
            screen_parts::text(call, store, scene, name, "0.00%")?
        };
        set_name(call, store, actor, name)?;
        copy_tags(call, underlay, actor)?;
        let tag = call.try_intern(name.as_bytes())?;
        set(call, actor, "__songlua_top_screen_child_name", tag)?;
        named(call, store, underlay, name, actor)?;
        if let Some(player) = crate::underlay_score_index(name) {
            let actor = difficulty(call, store, scene, underlay, player)?;
            role(call, actor, &format!("difficulty{player}"))?;
            append(call, store, underlay, actor)?;
            unnamed_parts.push(actor);
            if let Some(actor) = life(call, store, scene, underlay, player)? {
                role(call, actor, &format!("life{player}"))?;
                append(call, store, underlay, actor)?;
                unnamed_parts.push(actor);
            }
        }
    }
    let definition = source(call, "underlay_bpm", &[])?;
    let bpm = call.with_roots(&[definition], |call| {
        bpm_node(call, store, scene, underlay, table(call, definition)?)
    })?;
    role(call, bpm, "bpm")?;
    append(call, store, underlay, bpm)?;
    unnamed_parts.push(bpm);
    unnamed(call, underlay, &unnamed_parts, false)?;
    Ok(underlay)
}

fn role(call: &mut HostCall<'_>, actor: TableId, role: &str) -> Result<(), Error> {
    let value = call.try_intern(role.as_bytes())?;
    set(call, actor, "__songlua_underlay_role", value)
}

fn filter(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    underlay: TableId,
    player: usize,
) -> Result<Option<TableId>, Error> {
    let pn = call.try_intern(crate::player_number_name(player).as_bytes())?;
    let definition = source(call, "underlay_filter", &[pn])?;
    if definition == Value::Nil {
        return Ok(None);
    }
    call.with_roots(&[definition, pn], |call| {
        let definition = table(call, definition)?;
        let mods = mods(call, player)?;
        let filter = field(call, mods, "BackgroundFilter")?;
        let alpha = match filter {
            Value::Number(value) => value as f32 / 100.,
            Value::String(_) => call.with_roots(&[filter], |call| {
                let function = global(call, "BackgroundFilterValues")?;
                let values = call.call(function, &[])?[0];
                let value = call.with_roots(&[values], |call| call.table_get(values, filter))?;
                Ok(number(call, value)? / 100.)
            })?,
            _ => return Err(call.error(b"invalid initial BackgroundFilter")),
        };
        let actor = dummy(call, store, scene, "Quad", "", Some(underlay))?;
        commands(
            call,
            actor,
            definition,
            &["InitCommand", "OffCommand", "ComboFlashCommand"],
            true,
        )?;
        let function = global(call, "GetNotefieldX")?;
        let value = call.call(function, &[pn])?[0];
        let x = number(call, value)?;
        let function = global(call, "GetNotefieldWidth")?;
        let value = call.call(function, &[])?[0];
        let width = number(call, value)?;
        let value = global(call, "SCREEN_HEIGHT")?;
        let height = number(call, value)?;
        invoke(
            call,
            actor,
            "xy",
            &[
                Value::Number(x as f64),
                Value::Number((height * 0.5) as f64),
            ],
        )?;
        invoke(
            call,
            actor,
            "diffuse",
            &[
                Value::Number(0.),
                Value::Number(0.),
                Value::Number(0.),
                Value::Number(alpha as f64),
            ],
        )?;
        invoke(
            call,
            actor,
            "zoomto",
            &[Value::Number(width as f64), Value::Number(height as f64)],
        )?;
        Ok(Some(actor))
    })
}

fn difficulty(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    underlay: TableId,
    player: usize,
) -> Result<TableId, Error> {
    let pn = call.try_intern(crate::player_number_name(player).as_bytes())?;
    let definition = source(call, "underlay_difficulty", &[pn])?;
    call.with_roots(&[definition, pn], |call| {
        let definition = table(call, definition)?;
        let frame = dummy(call, store, scene, "ActorFrame", "", Some(underlay))?;
        commands(call, frame, definition, &["InitCommand"], true)?;
        run(call, frame, "InitCommand")?;
        let quad = dummy(call, store, scene, "Quad", "", None)?;
        let text = screen_parts::text(call, store, scene, "", "")?;
        let font = call.try_intern(b"Common Bold")?;
        set(call, text, "Font", font)?;
        for (i, actor) in [quad, text].into_iter().enumerate() {
            let part = call.raw_table_get(definition, Value::Number((i + 1) as f64))?;
            commands(
                call,
                actor,
                table(call, part)?,
                &[
                    "InitCommand",
                    "BeginCommand",
                    "CurrentSongChangedMessageCommand",
                ],
                true,
            )?;
            native_children::adopt(call, store, actor, frame)?;
            run(call, actor, "InitCommand")?;
            append(call, store, frame, actor)?;
        }
        unnamed(call, frame, &[quad, text], true)?;
        let game = global(call, "GAMESTATE")?;
        let function = field(call, table(call, game)?, "GetCurrentSteps")?;
        let steps = call.call(function, &[game, pn])?[0];
        if steps != Value::Nil {
            call.with_roots(&[steps], |call| {
                let function = field(call, table(call, steps)?, "GetDifficulty")?;
                let value = call.call(function, &[steps])?[0];
                let text_value = assets::text(call, value)?;
                let value = call.try_intern(text_value.as_bytes())?;
                let color = call.with_roots(&[value], |call| {
                    let function = global(call, "DifficultyColor")?;
                    Ok(call.call(function, &[value])?[0])
                })?;
                call.with_roots(&[color], |call| invoke(call, quad, "diffuse", &[color]))?;
                let function = field(call, table(call, steps)?, "GetMeter")?;
                let value = call.call(function, &[steps])?[0];
                let value = sprites::number(call, value)?;
                if !(0.0..=(u32::MAX as f64)).contains(&value) {
                    return Err(call.error(b"meter out of range"));
                }
                invoke(call, text, "settext", &[Value::Number(value as u32 as f64)])
            })?;
        }
        Ok(frame)
    })
}

fn swoosh() -> Result<String, String> {
    static PREPARED: OnceLock<Result<String, String>> = OnceLock::new();
    PREPARED.get_or_init(|| {
        let bytes = include_bytes!("../../../assets/simply-love/BGAnimations/ScreenGameplay underlay/PerPlayer/LifeMeter/swoosh.png");
        let decoded = image::load_from_memory_with_format(bytes, image::ImageFormat::Png).map_err(|error| error.to_string())?;
        let mut image = decoded.into_rgba8();
        let source_size = [image.width(), image.height()];
        let hints = deadlib_assets::parse_texture_hints("swoosh.png");
        deadlib_assets::apply_texture_hints(&mut image, &hints);
        deadlib_assets::fix_hidden_alpha(&mut image);
        let path = format!("{}B/ScreenGameplay underlay/PerPlayer/LifeMeter/swoosh.png", crate::SONG_LUA_THEME_PATH_PREFIX);
        deadlib_assets::register_prepared_generated_texture(&path, image, source_size, hints.sampler_desc());
        Ok(path)
    }).clone()
}

fn life(
