    })
}

fn life_inner(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    underlay: TableId,
    player: usize,
    mods: TableId,
) -> Result<Option<TableId>, Error> {
    if !matches!(
        field(call, mods, "HideLifebar")?,
        Value::Nil | Value::Boolean(false)
    ) {
        return Ok(None);
    }
    let sl = global(call, "SL")?;
    let globals = member(call, table(call, sl)?, "Global")?;
    let value = field(call, globals, "GameMode")?;
    if assets::text(call, value)? != "ITG" {
        return Ok(None);
    }
    let value = field(call, mods, "LifeMeterType")?;
    if assets::text(call, value)? != "Standard" {
        return Ok(None);
    }
    let pn = call.try_intern(crate::player_number_name(player).as_bytes())?;
    let game = global(call, "GAMESTATE")?;
    let function = field(call, table(call, game)?, "GetPlayerState")?;
    let state = call.call(function, &[game, pn])?[0];
    let position = call.with_roots(&[state], |call| {
        let function = field(call, table(call, state)?, "GetSongPosition")?;
        Ok(call.call(function, &[state])?[0])
    })?;
    let definition = call.with_roots(&[position], |call| {
        source(call, "underlay_life", &[pn, position])
    })?;
    call.with_roots(&[definition], |call| {
        let definition = table(call, definition)?;
        let meter = dummy(call, store, scene, "ActorFrame", "", Some(underlay))?;
        commands(call, meter, definition, &["InitCommand", "OnCommand"], true)?;
        run(call, meter, "InitCommand")?;
        let mut unnamed_parts = Vec::new();
        for (i, kind, name) in [
            (1, "Quad", ""),
            (2, "Quad", ""),
            (3, "Quad", "MeterFill"),
            (4, "Sprite", "MeterSwoosh"),
        ] {
            let actor = dummy(call, store, scene, kind, name, Some(meter))?;
            if kind == "Sprite" {
                let path = swoosh().map_err(|error| call.error(error.as_bytes()))?;
                let path = call.try_intern(path.as_bytes())?;
                sprites::set_texture(call, store, actor, path, false)?;
            }
            let part = call.raw_table_get(definition, Value::Number(i as f64))?;
            commands(
                call,
                actor,
                table(call, part)?,
                &[
                    "InitCommand",
                    "OnCommand",
                    "LifeChangedMessageCommand",
                    "HealthStateChangedMessageCommand",
                ],
                false,
            )?;
            run(call, actor, "InitCommand")?;
            run(call, actor, "OnCommand")?;
            append(call, store, meter, actor)?;
            if name.is_empty() {
                unnamed_parts.push(actor);
            } else {
                named(call, store, meter, name, actor)?;
            }
        }
        unnamed(call, meter, &unnamed_parts, true)?;
        set(
            call,
            meter,
            "__songlua_owned_child_lookup",
            Value::Boolean(true),
        )?;
        run(call, meter, "OnCommand")?;
        Ok(Some(meter))
    })
}

fn bpm_node(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    parent: TableId,
    definition: TableId,
) -> Result<TableId, Error> {
    let kind = get(call, definition, b"__songlua_builtin_kind")?;
    let kind = assets::text(call, kind)?;
    let name = get(call, definition, b"Name")?;
    let name = if name == Value::Nil {
        String::new()
    } else {
        assets::text(call, name)?
    };
    let actor = if kind == "BitmapText" {
        let text = get(call, definition, b"Text")?;
        let text = if text == Value::Nil {
            String::new()
        } else {
            assets::text(call, text)?
        };
        let actor = screen_parts::text(call, store, scene, &name, &text)?;
        let font = get(call, definition, b"Font")?;
        let font = assets::text(call, font)?;
        let font = call.try_intern(font.as_bytes())?;
        set(call, actor, "Font", font)?;
        actor
    } else {
        dummy(call, store, scene, "ActorFrame", &name, None)?
    };
    native_children::adopt(call, store, actor, parent)?;
    // These unchanged definitions contain only Init commands. Their update
    // closures are installed by those commands and retain their own displays.
    commands(call, actor, definition, &["InitCommand"], false)?;
    run(call, actor, "InitCommand")?;
    let mut unnamed_parts = Vec::new();
    for index in 1..=call.raw_table_len(definition)? {
        let part = call.raw_table_get(definition, Value::Number(index as f64))?;
        let child = call.with_roots(&[part], |call| {
            bpm_node(call, store, scene, actor, table(call, part)?)
        })?;
        let name = actor_name(call, store, child)?;
        let name =
            String::from_utf8(name).map_err(|error| call.error(error.to_string().as_bytes()))?;
        append(call, store, actor, child)?;
        if name.is_empty() {
            unnamed_parts.push(child);
        } else {
            named(call, store, actor, &name, child)?;
        }
    }
    unnamed(call, actor, &unnamed_parts, false)?;
    if kind == "ActorFrame" {
        set(
            call,
            actor,
            "__songlua_owned_child_lookup",
            Value::Boolean(true),
        )?;
    }
    Ok(actor)
}

pub(super) fn set_name(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = call.try_intern(name.as_bytes())?;
    let key = call.try_intern(b"__songlua_load_name")?;
    if call.raw_table_get(actor, key)? != Value::Nil {
        call.raw_table_set(actor, key, value)?;
    }
    let key = call.try_intern(b"__songlua_native_name")?;
    call.raw_table_set(actor, key, value)?;
    set(call, actor, "Name", value)?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .state
        .name = name.as_bytes().to_vec();
    Ok(())
}

//! Wrapper actors are owned with their scene, but are not ordinary children.
use super::*;

fn text_value(call: &mut HostCall<'_>, value: Value) -> Result<Value, Error> {
    let bytes = bytes(call, value)?;
    if std::str::from_utf8(&bytes).is_err() {
        return Err(call.error(b"actor directory or tag must be valid UTF-8"));
    }
    call.try_intern(&bytes)
}

fn copy_tags(call: &mut HostCall<'_>, owner: TableId, wrapper: TableId) -> Result<(), Error> {
    for key in ["__songlua_player1_enabled", "__songlua_player2_enabled"] {
        let key = call.try_intern(key.as_bytes())?;
        let value = call.raw_table_get(owner, key)?;
        if value != Value::Nil {
            call.raw_table_set(wrapper, key, Value::Boolean(value != Value::Boolean(false)))?;
        }
    }
    for key in [
        "__songlua_player_index",
        "__songlua_compile_layer",
        "__songlua_player_child_name",
        "__songlua_top_screen_child_name",
        "__songlua_main_title",
        "__songlua_bpm_text",
        "__songlua_style_name",
    ] {
        let field = call.try_intern(key.as_bytes())?;
        let value = call.table_get(Value::Table(owner), field)?;
        if value == Value::Nil {
            continue;
        }
        let value = if matches!(key, "__songlua_player_index" | "__songlua_compile_layer") {
            let value = call.call(helper(call, 6)?, &[value])?[0];
            let Value::Number(value) = value else {
                return Err(call.error(b"integer tag expected"));
            };
            if !(-9223372036854775808.0..9223372036854775808.0).contains(&value) {
                return Err(call.error(b"integer tag out of range"));
            }
            Value::Number((value as i64) as f64)
        } else {
            text_value(call, value)?
        };
        // Lookup/coercion may have collected the old temporary field string.
        let field = call.try_intern(key.as_bytes())?;
        call.raw_table_set(wrapper, field, value)?;
    }
    Ok(())
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    match name {
        "GetNumWrapperStates" => call.push(Value::Number(
            store.lock().unwrap().actors[&actor].wrappers.len() as f64,
        )),
        "GetWrapperState" => {
            // Production accepts numeric values, truncating fractions; numeric
            // strings are not indices. Wrapper indices start at one.
            let value = if let Value::Number(index) = arg(call, 1) {
                let index = index as i64;
                usize::try_from(index)
                    .ok()
                    .and_then(|index| index.checked_sub(1))
                    .and_then(|index| {
                        store.lock().unwrap().actors[&actor]
                            .wrappers
                            .get(index)
                            .copied()
                    })
                    .map_or(Value::Nil, Value::Table)
            } else {
                Value::Nil
            };
            call.push(value)
        }
        "AddWrapperState" => {
            action_capture::prepare(call, store, actor)?;
            let scene = store.lock().unwrap().actors[&actor].scene;
            let attrs = call.try_new_table()?;
            let key = call.try_intern(b"Class")?;
            let kind = call.try_intern(b"WrapperState")?;
            call.raw_table_set(attrs, key, kind)?;
            let wrapper = call.with_roots(&[Value::Table(attrs)], |call| {
                // Native dummy actors inherit the current scope, which may
                // differ from their owner's original declaration directory.
                for key in ["__songlua_script_dir", "__songlua_song_dir"] {
                    let field = call.try_intern(key.as_bytes())?;
                    let value = call.table_get(helper(call, 5)?, field)?;
                    if value != Value::Nil {
                        let value = text_value(call, value)?;
                        let field = call.try_intern(key.as_bytes())?;
                        call.raw_table_set(attrs, field, value)?;
                    }
                }
                let node = call.try_new_table()?;
                call.raw_table_set(node, Value::Number(1.0), Value::Table(attrs))?;
                let empty = call.try_new_table()?;
                call.raw_table_set(node, Value::Number(2.0), Value::Table(empty))?;
                call.with_roots(&[Value::Table(node)], |call| {
                    Ok(build(call, store, scene, node, None, true, false)?
                        .expect("wrapper class exists"))
                })
            })?;
            courses::share_child(call, store, actor, wrapper)?;
            // The registry already roots the new actor before tag lookups can
            // reenter Lua, detach fields or collect. No metadata lock crosses Lua.
            copy_tags(call, actor, wrapper)?;
            {
                let mut store = store.lock().unwrap();
                // A tag failure leaves the registered actor unattached, matching
                // the production constructor's partial state and cleanup lifetime.
                store.actors.get_mut(&wrapper).unwrap().parent = Some(actor);
                store.actors.get_mut(&actor).unwrap().wrappers.push(wrapper);
            }
            lifecycle::invalidate_plans(call, store)?;
            call.push(Value::Table(wrapper))
        }
        _ => unreachable!(),
    }
}

//! Endpoint capture for the existing compiler's function easing entries.
use super::*;

impl RustSongRuntime {
    /// Probe the existing from/to endpoints. Known actor identities use indexed
    /// capture; an empty or unknown selection uses lazy touched capture. Shared
    /// script state belongs to the caller's outer compiler snapshot, as native.
    pub fn capture_song_overlay_function_eases(
        &mut self,
        overlays: &[(usize, Value)],
        function: Value,
        params: crate::SongLuaOverlayEaseBuildParams,
        endpoints: [f32; 2],
        probe_actors: &[Value],
    ) -> Result<Vec<crate::SongLuaOverlayEase>, String> {
        let mut pins = Vec::new();
        let result = (|| {
            for value in std::iter::once(function)
                .chain(overlays.iter().map(|r| r.1))
                .chain(probe_actors.iter().copied())
            {
                pins.push(self.vm.pin(value).map_err(|e| e.to_string())?);
            }
            let selected = overlays
                .iter()
                .filter(|(_, actor)| {
                    matches!(actor, Value::Table(_)) && probe_actors.contains(actor)
                })
                .copied()
                .collect::<Vec<_>>();
            let end = crate::song_lua_span_end(params.start, params.limit, params.span_mode)
                .max(params.start);
            let capture = |runtime: &mut Self, value, beat| {
                if selected.is_empty() {
                    runtime.capture_song_touched_actor_function(
                        overlays,
                        function,
                        Some(value),
                        Some(beat),
                    )
                } else {
                    runtime.capture_song_actor_function(
                        &selected,
                        function,
                        Some(value),
                        Some(beat),
                    )
                }
            };
            let from = capture(self, endpoints[0], params.start)?;
            let to = capture(self, endpoints[1], end)?;
            Ok(crate::overlay_eases_from_captures(
                overlays.len(),
                &from,
                &to,
                params,
            ))
        })();
        for pin in pins {
            self.vm.unpin(pin).map_err(|e| e.to_string())?;
        }
        result
    }
}

