        setmetatable(handler,{__newindex=function(t,k,v)
            if k=='__songlua_spline_mode' then
                collectgarbage();collectgarbage();assert(weak[1].marker=='first' and weak[2]==nil)
                assert(saved.a:GetX()==91)
                restored=restored+1
